module smbus_pec_mon (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire scl_low,
    input wire wvalid,
    input wire [127:0] wdata
);
    localparam [5:0] TMAX = 6'd50;

    reg [5:0]   low_cnt      = 6'd0;
    reg         timeout_flag = 1'b0;
    reg         before_to    = 1'b1;
    reg [127:0] wbuf         = 128'd0;
    reg         pend         = 1'b0;
    reg         pend_cnt     = 1'b0;
    reg [7:0]   pec_acc      = 8'h00;
    reg [6:0]   wcnt         = 7'd0;
    reg [7:0]   pec_snap     = 8'h00;
    reg         pv           = 1'b0;

    function [7:0] crc8_128;
        input [7:0] c;
        input [127:0] d;
        integer i;
        reg [7:0] r;
        reg fb;
        begin
            r = c;
            for (i = 127; i >= 0; i = i - 1) begin
                fb = r[7] ^ d[i];
                r = {r[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            end
            crc8_128 = r;
        end
    endfunction

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (!rst_n) begin
            low_cnt      <= 6'd0;
            timeout_flag <= 1'b0;
            before_to    <= 1'b1;
            wbuf         <= 128'd0;
            pend         <= 1'b0;
            pend_cnt     <= 1'b0;
            pec_acc      <= 8'h00;
            wcnt         <= 7'd0;
            pec_snap     <= 8'h00;
        end else if (en) begin
            if (!scl_low)
                low_cnt <= 6'd0;
            else if (low_cnt < TMAX)
                low_cnt <= low_cnt + 6'd1;

            if (low_cnt == TMAX - 6'd1 && scl_low) begin
                timeout_flag <= 1'b1;
                before_to    <= 1'b0;
            end

            if (wvalid)
                wbuf <= wdata;

            if (wvalid)
                pend <= 1'b1;
            else if (pend)
                pend <= 1'b0;

            if (wvalid)
                pend_cnt <= 1'b1;
            else if (pend_cnt)
                pend_cnt <= 1'b0;

            if (pend)
                pec_acc <= crc8_128(pec_acc, wbuf);

            if (pend_cnt) begin
                wcnt     <= wcnt + 7'd1;
                pec_snap <= crc8_128(pec_acc, wbuf);
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(rst_n) && before_to && $past(before_to) && $stable(wcnt))
            assert ($stable(pec_acc));
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
    output wire [31:0] o_x3
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
                if (start && armed && step == 32'd0)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
                if (start && armed && !clr) begin
                    step <= 32'd1;
                    mode <= sel_add;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module cdc_line_edge_fifo (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [127:0] din,
    input  wire         rd_en,
    input  wire         cfg_set,
    output wire [127:0] dout,
    output reg          full,
    output reg          empty
);
    reg [127:0] prev;
    reg [127:0] mem [0:15];
    reg [3:0]   wr_ptr;
    reg [3:0]   rd_ptr;
    reg [4:0]   count;
    reg         armed;
    reg         pv;
    integer i;

    initial begin
        prev   = 128'd0;
        wr_ptr = 4'd0;
        rd_ptr = 4'd0;
        count  = 5'd0;
        full   = 1'b0;
        empty  = 1'b1;
        armed  = 1'b0;
        pv     = 1'b0;
        for (i = 0; i < 16; i = i + 1) mem[i] = 128'd0;
    end

    wire edge_seen = en && (din != prev);
    wire push = edge_seen && !full;
    wire pop  = en && rd_en && !empty;
    wire [4:0] count_next = count + {4'd0, push} - {4'd0, pop};

    assign dout = mem[rd_ptr];

    always @(posedge clk) begin
        if (!rst_n) begin
            prev   <= 128'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count  <= 5'd0;
            full   <= 1'b0;
            empty  <= 1'b1;
            armed  <= 1'b0;
        end else if (en) begin
            prev <= din;
            if (push) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (pop)
                rd_ptr <= rd_ptr + 4'd1;
            count <= count_next;
            full  <= (count_next == 5'd16);
            empty <= (count_next == 5'd0);
            armed <= armed | cfg_set;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && armed && $rose(edge_seen))
            assert (!(full && empty));
endmodule

module lssd_scan_dump (
    input  wire        clk,
    input  wire        en,
    input  wire        scan_req,
    input  wire        tdi,
    input  wire        cap,
    input  wire [63:0] sys_d0,
    input  wire [63:0] sys_d1,
    output wire        tdo,
    output wire        busy_o
);
    reg [63:0] l1_0 = 64'd0;
    reg [63:0] l1_1 = 64'd0;
    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

    assign tdo    = l2_1[63];
    assign busy_o = busy;

    always @(posedge clk) begin
        if (en) begin
            if (!busy) begin
                if (scan_req) begin
                    busy <= 1'b1;
                    cd   <= 8'd128;
                    sc   <= 7'd0;
                    ph   <= 1'b0;
                end else begin
                    if (cap) begin
                        l1_0 <= sys_d0;
                        l1_1 <= sys_d1;
                    end
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                end
            end else begin
                cd <= cd - 8'd1;
                if (!ph) begin
                    l1_0 <= {l2_0[62:0], tdi};
                    l1_1 <= {l2_1[62:0], l2_0[63]};
                    ph   <= 1'b1;
                end else begin
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                    ph   <= 1'b0;
                    if (sc == 7'd63) begin
                        busy <= 1'b0;
                        sc   <= 7'd0;
                    end else begin
                        sc   <= sc + 7'd1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (busy)
            assert (cd != 8'd0);
        else
            assert (cd == 8'd0);
    end
endmodule

module mips_wb_scoreboard (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [15:0] req_vec,
    input wire q_open,
    input wire r_close,
    output wire wb_valid,
    output reg [3:0] wb_idx
);
    reg [15:0] pend = 16'd0;
    reg busy = 1'b0;
    reg [7:0] cnt = 8'd0;
    reg win = 1'b0;

    wire [15:0] low = pend & (~pend + 16'd1);
    wire [15:0] pend_next = pend & ~low;

    reg [4:0] pc;
    integer i;
    always @(*) begin
        wb_idx = 4'd0;
        for (i = 15; i >= 0; i = i - 1)
            if (pend[i]) wb_idx = i[3:0];
    end

    integer j;
    always @(*) begin
        pc = 5'd0;
        for (j = 0; j < 16; j = j + 1)
            pc = pc + {4'd0, pend[j]};
    end

    assign wb_valid = en && busy;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                pend <= 16'd0;
                busy <= 1'b0;
                cnt <= 8'd0;
                win <= 1'b0;
            end else begin
                if (q_open)
                    win <= 1'b1;
                else if (r_close)
                    win <= 1'b0;
                if (!busy && req && req_vec != 16'd0) begin
                    pend <= req_vec;
                    busy <= 1'b1;
                    cnt <= 8'd16;
                end else if (busy) begin
                    pend <= pend_next;
                    cnt <= cnt - 8'd1;
                    if (pend_next == 16'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    always @(*) assert (!(win && busy) || cnt != 8'd0);
endmodule

module relo_belt (
    input wire clk,
    input wire rst,
    input wire en,
    input wire drop,
    input wire [63:0] din,
    input wire [4:0] rd_pos,
    input wire ckpt_open,
    input wire ckpt_close,
    output wire [63:0] dout
);
    reg [63:0] slot [0:31];
    reg [4:0] head;
    reg [63:0] drops;
    reg [63:0] win_cnt;
    reg win;
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            slot[i] = 64'd0;
        head = 5'd0;
        drops = 64'd0;
        win_cnt = 64'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 32; i = i + 1)
                slot[i] <= 64'd0;
            head <= 5'd0;
            drops <= 64'd0;
            win_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (drop) begin
                slot[head] <= din;
                head <= head + 5'd1;
                drops <= drops + 64'd1;
                if (win)
                    win_cnt <= win_cnt + 64'd1;
            end
            if (ckpt_close) begin
                win <= 1'b0;
            end else if (ckpt_open) begin
                win <= 1'b1;
                win_cnt <= 64'd0;
            end
        end
    end

    assign dout = slot[head - 5'd1 - rd_pos];

    always @(posedge clk)
        if (win && !rst)
            assert (head == drops[4:0]);
endmodule

module rdf_lockstep_wl (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] wl_in,
    input wire close_in,
    input wire eco_in
);
    reg [63:0] acc_a = 64'd0;
    reg [63:0] acc_b = 64'd0;
    reg [63:0] step_cnt = 64'd0;
    reg mism_q = 1'b0;
    reg err_q = 1'b0;
    reg ok_q = 1'b0;
    reg pre_eco = 1'b1;

    wire [63:0] nxt_a = acc_a + wl_in;
    wire [63:0] nxt_b = acc_b + wl_in;

    always @(posedge clk) begin
        if (rst) begin
            acc_a <= 64'd0;
            acc_b <= 64'd0;
            step_cnt <= 64'd0;
            mism_q <= 1'b0;
            err_q <= 1'b0;
            ok_q <= 1'b0;
            pre_eco <= 1'b1;
        end else if (en) begin
            acc_a <= nxt_a;
            acc_b <= nxt_b;
            step_cnt <= step_cnt + 64'd1;
            mism_q <= (nxt_a != nxt_b);
            err_q <= err_q | mism_q;
            ok_q <= ok_q | close_in;
            pre_eco <= pre_eco & ~eco_in;
        end
    end

    always @(posedge clk) assert (!pre_eco || !(mism_q && ok_q));
endmodule

module hdmi_agc (
    input wire clk,
    input wire rst,
    input wire en,
    input wire vsync_rise,
    input wire frame_end,
    input wire pix_valid,
    input wire [31:0] luma,
    output wire [31:0] o_pix,
    output wire [31:0] o_gain
);
    localparam [1:0] IDLE  = 2'd0;
    localparam [1:0] ARMED = 2'd1;
    localparam [1:0] ADAPT = 2'd2;
    localparam [1:0] DONE  = 2'd3;
    localparam [31:0] ARM_TH     = 32'd1000;
    localparam [31:0] TARGET     = 32'd50000;
    localparam [31:0] GSTEP      = 32'd16;
    localparam [31:0] ADAPT_LAST = 32'd63;

    reg [31:0] amp_est;
    reg [31:0] gain;
    reg [31:0] hist [0:63];
    reg [5:0]  wr_ptr;
    reg [31:0] adapt_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done_flag;
    reg        win;

    integer i;
    initial begin
        amp_est    = 32'd0;
        gain       = 32'h00010000;
        wr_ptr     = 6'd0;
        adapt_cnt  = 32'd0;
        phase      = IDLE;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        done_flag  = 1'b0;
        win        = 1'b0;
        for (i = 0; i < 64; i = i + 1)
            hist[i] = 32'd0;
    end

    wire [31:0] abs_luma = luma[31] ? (~luma + 32'd1) : luma;
    wire [31:0] scaled   = luma * {16'd0, gain[31:16]};
    wire [31:0] amp_next = (abs_luma > amp_est) ? abs_luma : (amp_est - (amp_est >> 4));

    always @(posedge clk) begin
        if (rst) begin
            amp_est    <= 32'd0;
            gain       <= 32'h00010000;
            wr_ptr     <= 6'd0;
            adapt_cnt  <= 32'd0;
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            done_flag  <= 1'b0;
            win        <= 1'b0;
        end else if (en) begin
            if (vsync_rise) begin
                win        <= 1'b1;
                phase      <= IDLE;
                arm_seen   <= 1'b0;
                start_seen <= 1'b0;
                done_flag  <= 1'b0;
                adapt_cnt  <= 32'd0;
            end else if (frame_end) begin
                win <= 1'b0;
            end else if (win && pix_valid) begin
                hist[wr_ptr] <= scaled;
                wr_ptr       <= wr_ptr + 6'd1;
                amp_est      <= amp_next;
                case (phase)
                    IDLE: begin
                        if (amp_est > ARM_TH) begin
                            phase    <= ARMED;
                            arm_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (wr_ptr == 6'd63) begin
                            phase      <= ADAPT;
                            start_seen <= 1'b1;
                        end
                    end
                    ADAPT: begin
                        if (amp_est < TARGET)
                            gain <= gain + GSTEP;
                        else if ((amp_est > TARGET) && (gain > GSTEP))
                            gain <= gain - GSTEP;
                        if (adapt_cnt == ADAPT_LAST) begin
                            phase     <= DONE;
                            done_flag <= 1'b1;
                        end else begin
                            adapt_cnt <= adapt_cnt + 32'd1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_pix  = hist[wr_ptr];
    assign o_gain = gain;

    always @(*) assert (!(win && done_flag) || start_seen);
    always @(*) assert (!(win && start_seen) || arm_seen);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module wrapped_quad_dec (
    input  wire        clk,
    input  wire        rst,
    input  wire        proj_en,
    input  wire        enc_a,
    input  wire        enc_b,
    input  wire        wbs_stb_i,
    input  wire        wbs_cyc_i,
    input  wire        wbs_we_i,
    input  wire [3:0]  wbs_adr_i,
    output wire [31:0] wbs_dat_o,
    output wire        wbs_ack_o
);
    reg        a_q = 1'b0;
    reg        b_q = 1'b0;
    reg [15:0] pos = 16'd0;
    reg [15:0] err_cnt = 16'd0;
    reg        seen_step = 1'b0;
    reg        armed = 1'b0;
    reg        ack_q = 1'b0;

    wire da   = enc_a ^ a_q;
    wire db   = enc_b ^ b_q;
    wire step = da ^ db;
    wire dbl  = da & db;
    wire up   = a_q ^ enc_b;
    wire rd0  = proj_en && wbs_stb_i && wbs_cyc_i && !wbs_we_i && (wbs_adr_i == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            a_q       <= 1'b0;
            b_q       <= 1'b0;
            pos       <= 16'd0;
            err_cnt   <= 16'd0;
            seen_step <= 1'b0;
            armed     <= 1'b0;
            ack_q     <= 1'b0;
        end else if (proj_en) begin
            a_q <= enc_a;
            b_q <= enc_b;
            if (step) begin
                seen_step <= 1'b1;
                if (up)
                    pos <= pos + 16'd1;
                else
                    pos <= pos - 16'd1;
            end else if (dbl) begin
                err_cnt <= err_cnt + 16'd1;
            end
            if (rd0)
                armed <= 1'b1;
            ack_q <= wbs_stb_i && wbs_cyc_i && !ack_q;
        end
    end

    assign wbs_ack_o = ack_q;
    assign wbs_dat_o = (wbs_adr_i == 4'd0) ? {{16{pos[15]}}, pos} : {16'd0, err_cnt};

    assert property (!(armed && (pos != 16'd0)) || seen_step);
endmodule

module tcu_useq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [2:0]  op,
    input  wire        cond,
    input  wire [1:0]  sel,
    input  wire        tw_en,
    input  wire [1:0]  tw_idx,
    input  wire [15:0] tw_data,
    output wire [15:0] upc_o,
    output wire        ret_valid_o
);
    localparam [2:0] OP_INC  = 3'd0;
    localparam [2:0] OP_JMP  = 3'd1;
    localparam [2:0] OP_BR   = 3'd2;
    localparam [2:0] OP_CALL = 3'd3;
    localparam [2:0] OP_RET  = 3'd4;

    reg [15:0] upc;
    reg [15:0] jt0, jt1, jt2, jt3;
    reg [15:0] ret_reg;
    reg        ret_valid;
    reg [15:0] shadow_ret;
    reg        pv;

    initial upc = 16'h0000;
    initial jt0 = 16'h0000;
    initial jt1 = 16'h0000;
    initial jt2 = 16'h0000;
    initial jt3 = 16'h0000;
    initial ret_reg = 16'h0000;
    initial ret_valid = 1'b0;
    initial shadow_ret = 16'h0000;
    initial pv = 1'b0;

    reg [15:0] tgt;
    always @(*) begin
        case (sel)
            2'd0: tgt = jt0;
            2'd1: tgt = jt1;
            2'd2: tgt = jt2;
            default: tgt = jt3;
        endcase
    end

    wire [15:0] upc_inc = upc + 16'h0001;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            upc        <= 16'h0000;
            jt0        <= 16'h0000;
            jt1        <= 16'h0000;
            jt2        <= 16'h0000;
            jt3        <= 16'h0000;
            ret_reg    <= 16'h0000;
            ret_valid  <= 1'b0;
            shadow_ret <= 16'h0000;
        end else if (en) begin
            if (tw_en) begin
                case (tw_idx)
                    2'd0: jt0 <= tw_data;
                    2'd1: jt1 <= tw_data;
                    2'd2: jt2 <= tw_data;
                    default: jt3 <= tw_data;
                endcase
            end
            case (op)
                OP_INC:  upc <= upc_inc;
                OP_JMP:  upc <= tgt;
                OP_BR:   upc <= cond ? tgt : upc_inc;
                OP_CALL: begin
                    ret_reg    <= upc_inc;
                    shadow_ret <= upc_inc;
                    ret_valid  <= 1'b1;
                    upc        <= tgt;
                end
                OP_RET: begin
                    if (ret_valid) begin
                        upc       <= ret_reg;
                        ret_valid <= 1'b0;
                    end else begin
                        upc <= upc_inc;
                    end
                end
                default: upc <= upc_inc;
            endcase
        end
    end

    assign upc_o = upc;
    assign ret_valid_o = ret_valid;

    always @(posedge clk)
        if (pv && $past(en) && !$past(rst) && ($past(op) == 3'd4) && $past(ret_valid))
            assert (upc == $past(shadow_ret));
endmodule

module nfc_rst_escalator (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire rx_fault,
    output wire sub_rst,
    output wire chip_rst
);
    localparam [63:0] T1 = 64'd4;
    localparam [63:0] T2 = 64'd8;
    localparam [63:0] DECAY = 64'd1000;
    localparam [63:0] CNT_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] fault_cnt = 64'd0;
    reg [63:0] decay_tmr = 64'd0;
    reg sub_rst_q = 1'b0;
    reg chip_rst_q = 1'b0;
    reg armed = 1'b0;

    wire [63:0] inc = fault_cnt + 64'd1;
    wire [63:0] dec = fault_cnt - 64'd1;

    always @(posedge clk) begin
        if (!rst_n) begin
            fault_cnt <= 64'd0;
            decay_tmr <= 64'd0;
            sub_rst_q <= 1'b0;
            chip_rst_q <= 1'b0;
            armed <= 1'b0;
        end else if (en) begin
            armed <= armed | sub_rst_q;
            if (rx_fault) begin
                if (fault_cnt != CNT_MAX) begin
                    fault_cnt <= inc;
                    if (inc == T1)
                        sub_rst_q <= 1'b1;
                    if (inc == T2) begin
                        chip_rst_q <= 1'b1;
                        sub_rst_q <= 1'b0;
                    end
                end
            end else begin
                if (decay_tmr == DECAY) begin
                    decay_tmr <= 64'd0;
                    if (fault_cnt != 64'd0) begin
                        fault_cnt <= dec;
                        if (dec == T2 - 64'd1) begin
                            chip_rst_q <= 1'b0;
                            sub_rst_q <= 1'b1;
                        end
                        if (dec == T1 - 64'd1)
                            sub_rst_q <= 1'b0;
                    end
                end else begin
                    decay_tmr <= decay_tmr + 64'd1;
                end
            end
        end
    end

    assign sub_rst = sub_rst_q;
    assign chip_rst = chip_rst_q;

    always @(*)
        if (armed)
            assert (!(sub_rst_q && chip_rst_q));
endmodule

module pix_palette_bimap (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] din_a,
    input wire [7:0] din_b,
    output wire hit,
    output wire [5:0] addr,
    output wire [7:0] partner
);
    // 48 entries x 8 bits, flattened: entry i lives at [i*8 +: 8]
    reg [383:0] key_mem = 384'd0;
    reg [383:0] val_mem = 384'd0;
    reg [47:0]  valid = 48'd0;
    reg [5:0]   wr_ptr = 6'd0;
    reg         hit_q = 1'b0;
    reg [5:0]   addr_q = 6'd0;
    reg [7:0]   partner_q = 8'd0;
    reg         ever_ins = 1'b0;
    reg         pre_flush = 1'b1;

    assign hit = hit_q;
    assign addr = addr_q;
    assign partner = partner_q;

    // parallel search, lowest matching index wins
    reg       m_hit;
    reg [5:0] m_addr;
    reg [7:0] m_partner;
    reg [7:0] sel;
    integer i;
    always @(*) begin
        m_hit = 1'b0;
        m_addr = 6'd0;
        m_partner = 8'd0;
        sel = 8'd0;
        for (i = 47; i >= 0; i = i - 1) begin
            sel = (op == 2'b01) ? val_mem[i*8 +: 8] : key_mem[i*8 +: 8];
            if (valid[i] && (sel == din_a)) begin
                m_hit = 1'b1;
                m_addr = i;
                m_partner = (op == 2'b01) ? key_mem[i*8 +: 8] : val_mem[i*8 +: 8];
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 48'd0;
            hit_q <= 1'b0;
            addr_q <= 6'd0;
            partner_q <= 8'd0;
            ever_ins <= 1'b0;
            pre_flush <= 1'b1;
            wr_ptr <= 6'd0;
        end else if (en) begin
            case (op)
                2'b00, 2'b01: begin
                    hit_q <= m_hit;
                    addr_q <= m_addr;
                    partner_q <= m_partner;
                end
                2'b10: begin
                    key_mem[wr_ptr*8 +: 8] <= din_a;
                    val_mem[wr_ptr*8 +: 8] <= din_b;
                    valid[wr_ptr] <= 1'b1;
                    ever_ins <= 1'b1;
                    wr_ptr <= (wr_ptr == 6'd47) ? 6'd0 : wr_ptr + 6'd1;
                end
                default: begin
                    valid <= 48'd0;
                    hit_q <= 1'b0;
                    ever_ins <= 1'b0;
                    pre_flush <= 1'b0;
                end
            endcase
        end
    end

    // Precedence: before the first flush, a registered hit requires a prior insert
    always @(posedge clk)
        assert (!(pre_flush && hit_q) || ever_ins);
endmodule

module cam_key_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [7:0]  col_in,
    output reg  [31:0] row_n,
    output wire [7:0]  key_map_out
);
    localparam [7:0] DWELL = 8'd200;

    reg [7:0] row_idx;
    reg [7:0] scan_tmr;
    reg [7:0] key_map [0:31];
    integer i;

    initial begin
        row_idx  = 8'd0;
        scan_tmr = 8'd0;
        row_n    = 32'hFFFF_FFFE;
        for (i = 0; i < 32; i = i + 1) key_map[i] = 8'd0;
    end

    wire [7:0] nxt = (row_idx == 8'd31) ? 8'd0 : (row_idx + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            row_idx  <= 8'd0;
            scan_tmr <= 8'd0;
            row_n    <= 32'hFFFF_FFFE;
        end else if (en) begin
            if (scan_tmr == DWELL - 8'd1) begin
                scan_tmr <= 8'd0;
                key_map[row_idx[4:0]] <= ~col_in;
                row_idx  <= nxt;
                row_n    <= ~(32'b1 << nxt);
            end else begin
                scan_tmr <= scan_tmr + 8'd1;
            end
        end
    end

    assign key_map_out = key_map[row_idx[4:0]];

    reg pv = 1'b0;
    reg rst_q = 1'b1;
    always @(posedge clk) begin
        pv    <= 1'b1;
        rst_q <= rst;
    end

    always @(posedge clk)
        if (pv && !rst_q)
            assert (row_n == $past(row_n) || row_n == {$past(row_n[30:0]), $past(row_n[31])});
endmodule

module qpsk_mw_cfg (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cs,
    input wire di,
    output wire dout,
    output reg do_oe
);
    localparam [2:0] IDLE = 3'd0, START = 3'd1, OPCODE = 3'd2, ADDR = 3'd3, DATA = 3'd4;

    reg [2:0]  phase;
    reg [63:0] cnt;
    reg [7:0]  oa_sr;
    reg [63:0] dat_sr;
    reg [63:0] mem [0:63];
    reg [63:0] wr_cnt;
    reg        pre_commit;
    integer i;

    initial begin
        phase = IDLE; cnt = 64'd0; oa_sr = 8'd0; dat_sr = 64'd0;
        do_oe = 1'b0; wr_cnt = 64'd0; pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) mem[i] = 64'd0;
    end

    wire [7:0]  oa_next  = {oa_sr[6:0], di};
    wire        is_read  = (oa_sr[7:6] == 2'b10);
    wire [63:0] dat_next = {dat_sr[62:0], di};

    assign dout = do_oe & dat_sr[63];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; cnt <= 64'd0; oa_sr <= 8'd0; dat_sr <= 64'd0;
            do_oe <= 1'b0; wr_cnt <= 64'd0; pre_commit <= 1'b1;
        end else if (en) begin
            if (!cs) begin
                phase <= IDLE;
                do_oe <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (di) phase <= START;
                    end
                    START: begin
                        phase <= OPCODE;
                        cnt <= 64'd2;
                    end
                    OPCODE: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= ADDR;
                            cnt <= 64'd6;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    ADDR: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= DATA;
                            cnt <= 64'd64;
                            do_oe <= (oa_next[7:6] == 2'b10);
                            if (oa_next[7:6] == 2'b10)
                                dat_sr <= mem[oa_next[5:0]];
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    DATA: begin
                        if (is_read)
                            dat_sr <= {dat_sr[62:0], 1'b0};
                        else
                            dat_sr <= dat_next;
                        if (cnt == 64'd1) begin
                            if (!is_read) begin
                                mem[oa_sr[5:0]] <= dat_next;
                                wr_cnt <= wr_cnt + 64'd1;
                                pre_commit <= 1'b0;
                            end
                            phase <= IDLE;
                            do_oe <= 1'b0;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    default: begin
                        phase <= IDLE;
                    end
                endcase
            end
        end
    end

    always @(*)
        if (pre_commit)
            assert (!(phase == 3'd3 && do_oe));
endmodule

module vcd_mac_learn (
    input wire clk,
    input wire rst,
    input wire en,
    input wire learn_v,
    input wire [31:0] src_mac,
    input wire [3:0] src_port,
    input wire look_v,
    input wire [31:0] dst_mac,
    input wire age_tick,
    input wire win_open,
    input wire win_close,
    output wire o_hit,
    output wire [3:0] o_port,
    output wire o_win
);
    reg [383:0] key_flat;
    reg [47:0]  port_flat;
    reg [11:0]  valid;
    reg [11:0]  age;
    reg [3:0]   rr_ptr;
    reg [31:0]  learn_cnt;
    reg         hit_q;
    reg [3:0]   out_port;
    reg         win;

    initial key_flat = 384'd0;
    initial port_flat = 48'd0;
    initial valid = 12'd0;
    initial age = 12'd0;
    initial rr_ptr = 4'd0;
    initial learn_cnt = 32'd0;
    initial hit_q = 1'b0;
    initial out_port = 4'd0;
    initial win = 1'b0;

    assign o_hit = hit_q;
    assign o_port = out_port;
    assign o_win = win;

    integer i;
    reg match_any;
    reg [3:0] match_idx;
    reg free_any;
    reg [3:0] free_idx;
    reg look_hit;
    reg [3:0] look_idx;
    always @(*) begin
        match_any = 1'b0; match_idx = 4'd0;
        free_any = 1'b0;  free_idx = 4'd0;
        look_hit = 1'b0;  look_idx = 4'd0;
        for (i = 11; i >= 0; i = i - 1) begin
            if (valid[i] && (key_flat[i*32 +: 32] == src_mac)) begin
                match_any = 1'b1; match_idx = i;
            end
            if (!valid[i]) begin
                free_any = 1'b1; free_idx = i;
            end
            if (valid[i] && (key_flat[i*32 +: 32] == dst_mac)) begin
                look_hit = 1'b1; look_idx = i;
            end
        end
    end

    wire [3:0] tgt = match_any ? match_idx : (free_any ? free_idx : rr_ptr);

    reg [11:0] valid_n;
    reg [11:0] age_n;
    always @(*) begin
        valid_n = valid;
        age_n = age;
        if (age_tick) begin
            valid_n = valid & age;
            age_n = 12'd0;
        end
        if (look_v && look_hit)
            age_n[look_idx] = 1'b1;
        if (learn_v) begin
            valid_n[tgt] = 1'b1;
            age_n[tgt] = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            key_flat <= 384'd0;
            port_flat <= 48'd0;
            valid <= 12'd0;
            age <= 12'd0;
            rr_ptr <= 4'd0;
            learn_cnt <= 32'd0;
            hit_q <= 1'b0;
            out_port <= 4'd0;
            win <= 1'b0;
        end else if (en) begin
            valid <= valid_n;
            age <= age_n;
            hit_q <= look_v & look_hit;
            if (look_v && look_hit)
                out_port <= port_flat[look_idx*4 +: 4];
            if (learn_v) begin
                key_flat[tgt*32 +: 32] <= src_mac;
                port_flat[tgt*4 +: 4] <= src_port;
                if (!match_any)
                    rr_ptr <= (rr_ptr >= 4'd11) ? 4'd0 : rr_ptr + 4'd1;
                if (learn_cnt != 32'hFFFFFFFF)
                    learn_cnt <= learn_cnt + 32'd1;
            end
            if (win_close)
                win <= 1'b0;
            else if (win_open)
                win <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && win && $rose(hit_q))
            assert (learn_cnt != 32'd0);
endmodule

module wal_quad_probe (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    input  wire        cap_req,
    input  wire        stop,
    output reg         done,
    output wire [63:0] i_out,
    output wire [63:0] q
);
    reg [63:0] d0, d1, d2, d3;
    reg [63:0] i_dly;
    reg [63:0] q_out;
    reg [63:0] cnt;
    reg [2:0]  fill;
    reg        pending;
    reg        win;

    initial begin
        d0 = 64'd0; d1 = 64'd0; d2 = 64'd0; d3 = 64'd0;
        i_dly = 64'd0; q_out = 64'd0; cnt = 64'd0;
        fill = 3'd0; pending = 1'b0; win = 1'b0; done = 1'b0;
    end

    assign i_out = i_dly;
    assign q = q_out;

    always @(posedge clk) begin
        if (rst) begin
            d0 <= 64'd0; d1 <= 64'd0; d2 <= 64'd0; d3 <= 64'd0;
            i_dly <= 64'd0; q_out <= 64'd0; cnt <= 64'd0;
            fill <= 3'd0; pending <= 1'b0; win <= 1'b0; done <= 1'b0;
        end else if (en) begin
            d0 <= x_in;
            d1 <= d0;
            d2 <= d1;
            d3 <= d2;
            i_dly <= d1;
            q_out <= (d0 - d3) + 64'd3 * (d1 - d2);
            done <= 1'b0;
            if (cap_req && !pending) begin
                pending <= 1'b1;
                fill    <= 3'd0;
                cnt     <= 64'd5;
                win     <= 1'b1;
            end else begin
                if (stop)
                    win <= 1'b0;
                if (pending) begin
                    if (fill + 3'd1 == 3'd4) begin
                        pending <= 1'b0;
                        cnt     <= 64'd0;
                        fill    <= 3'd4;
                        done    <= 1'b1;
                    end else begin
                        fill <= fill + 3'd1;
                        cnt  <= cnt - 64'd1;
                    end
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && (cnt == 64'd0) && !$past(cnt == 64'd0))
            assert (!pending);
endmodule

module femto_trace_ser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire ack,
    input wire flush,
    input wire [31:0] data_in,
    output wire sout
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, SHIFT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] load_reg;
    reg [31:0] shift_reg;
    reg [31:0] bit_cnt;
    reg armed_f, started_f, finished_f;
    reg win;

    initial begin
        phase = IDLE;
        load_reg = 32'd0;
        shift_reg = 32'd0;
        bit_cnt = 32'd0;
        armed_f = 1'b0;
        started_f = 1'b0;
        finished_f = 1'b0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            load_reg <= 32'd0;
            shift_reg <= 32'd0;
            bit_cnt <= 32'd0;
            armed_f <= 1'b0;
            started_f <= 1'b0;
            finished_f <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            if (flush) begin
                win <= 1'b0;
                armed_f <= 1'b0;
                started_f <= 1'b0;
                finished_f <= 1'b0;
                phase <= IDLE;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            load_reg <= data_in;
                            armed_f <= 1'b1;
                            phase <= ARMED;
                            win <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            shift_reg <= load_reg;
                            bit_cnt <= 32'd0;
                            started_f <= 1'b1;
                            phase <= SHIFT;
                        end
                    end
                    SHIFT: begin
                        shift_reg <= {shift_reg[30:0], 1'b0};
                        bit_cnt <= bit_cnt + 32'd1;
                        if (bit_cnt == 32'd31) begin
                            finished_f <= 1'b1;
                            phase <= DONE;
                        end
                    end
                    DONE: begin
                        if (ack) begin
                            armed_f <= 1'b0;
                            started_f <= 1'b0;
                            finished_f <= 1'b0;
                            phase <= IDLE;
                        end
                    end
                endcase
            end
        end
    end

    assign sout = shift_reg[31];

    always @(posedge clk)
        if (win && finished_f)
            assert (started_f);

    always @(posedge clk)
        if (win && started_f)
            assert (armed_f);
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
endmodule

module atalanta_ca_retry (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_valid,
    input wire [63:0] cmd_addr,
    input wire alert_n,
    output reg [63:0] ca_out,
    output reg ca_par
);
    reg [63:0] hist [0:31];
    reg hist_par [0:31];
    reg [4:0] wr_ptr;
    reg [4:0] replay_ptr;
    reg replaying;
    reg [63:0] issue_cnt;
    reg [63:0] log_cnt;
    reg [63:0] err_status;
    reg no_alert_yet;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            hist[i] = 64'd0;
            hist_par[i] = 1'b0;
        end
        wr_ptr = 5'd0;
        replay_ptr = 5'd0;
        replaying = 1'b0;
        issue_cnt = 64'd0;
        log_cnt = 64'd0;
        err_status = 64'd0;
        no_alert_yet = 1'b1;
        ca_out = 64'd0;
        ca_par = 1'b0;
    end

    wire alert = !alert_n;
    wire do_issue = cmd_valid && !replaying;
    wire [4:0] replay_next = replay_ptr + 5'd1;

    wire [63:0] err_next;
    assign err_next[0] = err_status[0] | (issue_cnt != log_cnt);
    assign err_next[1] = err_status[1] | alert;
    assign err_next[31:2] = err_status[31:2];
    assign err_next[63:32] = replaying ? (err_status[63:32] + 32'd1) : err_status[63:32];

    always @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 5'd0;
            replay_ptr <= 5'd0;
            replaying <= 1'b0;
            issue_cnt <= 64'd0;
            log_cnt <= 64'd0;
            err_status <= 64'd0;
            no_alert_yet <= 1'b1;
            ca_out <= 64'd0;
            ca_par <= 1'b0;
        end else if (en) begin
            err_status <= err_next;
            if (do_issue) begin
                ca_out <= cmd_addr;
                ca_par <= ^cmd_addr;
                hist[wr_ptr] <= cmd_addr;
                hist_par[wr_ptr] <= ^cmd_addr;
                wr_ptr <= wr_ptr + 5'd1;
                issue_cnt <= issue_cnt + 64'd1;
                log_cnt <= log_cnt + 64'd1;
            end
            if (replaying) begin
                ca_out <= hist[replay_ptr];
                ca_par <= hist_par[replay_ptr];
                replay_ptr <= replay_next;
                if (replay_next == wr_ptr)
                    replaying <= 1'b0;
            end
            if (alert) begin
                replaying <= 1'b1;
                replay_ptr <= wr_ptr - 5'd1;
                no_alert_yet <= 1'b0;
            end
        end
    end

    always @(*) assert (!no_alert_yet || err_status == 64'd0);
endmodule

module sc_park_alu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire uni_bit,
    input wire util_bit,
    input wire vis_bit,
    input wire win_bit,
    output wire [1:0] o_phase,
    output wire [15:0] o_ones,
    output wire [15:0] o_log0
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_seen, start_seen, done_seen;
    reg [15:0] len_cnt;
    reg [15:0] ones_cnt;
    reg [15:0] log_q [0:7];
    reg [2:0] log_ptr;
    integer i;

    initial begin
        phase = IDLE;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        done_seen = 1'b0;
        len_cnt = 16'd0;
        ones_cnt = 16'd0;
        log_ptr = 3'd0;
        for (i = 0; i < 8; i = i + 1) log_q[i] = 16'd0;
    end

    wire m = uni_bit & util_bit;
    wire s = win_bit ? vis_bit : m;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
            len_cnt <= 16'd0;
            ones_cnt <= 16'd0;
            log_ptr <= 3'd0;
            for (i = 0; i < 8; i = i + 1) log_q[i] <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm_req) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start_req) begin
                        phase <= RUN;
                        start_seen <= 1'b1;
                        len_cnt <= 16'd0;
                        ones_cnt <= 16'd0;
                    end
                end
                RUN: begin
                    len_cnt <= len_cnt + 16'd1;
                    ones_cnt <= ones_cnt + {15'd0, s};
                    if (len_cnt == 16'd699) begin
                        phase <= DONE;
                        done_seen <= 1'b1;
                        log_q[log_ptr] <= ones_cnt;
                        log_ptr <= log_ptr + 3'd1;
                    end
                end
                DONE: begin
                    if (arm_req) phase <= ARMED;
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_ones = ones_cnt;
    assign o_log0 = log_q[0];

    always @(posedge clk)
        assert ((!done_seen || start_seen) && (!start_seen || arm_seen));
endmodule

module metron_trace_latch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [5:0] s,
    input wire [5:0] r,
    input wire trace_on,
    input wire trace_off,
    output wire [5:0] q_out,
    output wire [31:0] cnt_out
);
    reg [5:0] q;
    reg [31:0] live_cnt;
    reg win;
    initial q = 6'b000000;
    initial live_cnt = 32'd0;
    initial win = 1'b0;

    function [31:0] pc6;
        input [5:0] v;
        begin
            pc6 = {31'd0, v[0]} + {31'd0, v[1]} + {31'd0, v[2]}
                + {31'd0, v[3]} + {31'd0, v[4]} + {31'd0, v[5]};
        end
    endfunction

    wire [5:0] q_n = s | (~r & q);
    wire [5:0] rises = q_n & ~q;
    wire [5:0] falls = q & ~q_n;

    always @(posedge clk) begin
        if (rst) begin
            q <= 6'b000000;
            live_cnt <= 32'd0;
            win <= 1'b0;
        end else if (en) begin
            q <= q_n;
            live_cnt <= live_cnt + pc6(rises) - pc6(falls);
            win <= trace_on ? 1'b1 : (trace_off ? 1'b0 : win);
        end
    end

    assign q_out = q;
    assign cnt_out = live_cnt;

    assert property (!win || live_cnt <= 32'd6);
endmodule

module mips_i2c_deglitch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire scl_in,
    input wire sda_in,
    input wire cfg_we,
    input wire [7:0] cfg_din,
    output wire scl_o,
    output wire sda_o
);
    reg [3:0] sh_scl = 4'b1111;
    reg [3:0] sh_sda = 4'b1111;
    reg st_scl = 1'b1;
    reg st_sda = 1'b1;
    reg [7:0] cnt_scl = 8'd0;
    reg [7:0] cnt_sda = 8'd0;
    reg [7:0] flen = 8'd3;
    reg armed = 1'b0;
    reg pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            sh_scl <= 4'b1111;
            sh_sda <= 4'b1111;
            st_scl <= 1'b1;
            st_sda <= 1'b1;
            cnt_scl <= 8'd0;
            cnt_sda <= 8'd0;
            flen <= 8'd3;
            armed <= 1'b0;
        end else if (en) begin
            sh_scl <= {sh_scl[2:0], scl_in};
            sh_sda <= {sh_sda[2:0], sda_in};
            if (cfg_we) begin
                flen <= (cfg_din > 8'd12) ? 8'd12 : cfg_din;
                cnt_scl <= 8'd0;
                cnt_sda <= 8'd0;
            end else begin
                if (sh_scl[3] != st_scl) begin
                    if (cnt_scl >= flen) begin
                        st_scl <= sh_scl[3];
                        cnt_scl <= 8'd0;
                        if (st_scl && !sh_scl[3])
                            armed <= 1'b1;
                    end else begin
                        cnt_scl <= cnt_scl + 8'd1;
                    end
                end else begin
                    cnt_scl <= 8'd0;
                end
                if (sh_sda[3] != st_sda) begin
                    if (cnt_sda >= flen) begin
                        st_sda <= sh_sda[3];
                        cnt_sda <= 8'd0;
                    end else begin
                        cnt_sda <= cnt_sda + 8'd1;
                    end
                end else begin
                    cnt_sda <= 8'd0;
                end
            end
        end
    end

    assign scl_o = st_scl;
    assign sda_o = st_sda;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(cnt_scl) <= 8'd12 && $past(cnt_sda) <= 8'd12);
endmodule

module LispDebugBridge (
    input wire clk,
    input wire en,
    input wire start,
    input wire wr_in,
    input wire [3:0] addr_in,
    input wire [63:0] wdata_in,
    output wire busy_o,
    output wire [63:0] rdata_o,
    output wire [63:0] txn_o
);
    // host side
    reg busy = 1'b0;
    reg req_tgl = 1'b0;
    reg ack_s1 = 1'b0;
    reg ack_s2 = 1'b0;
    reg [3:0] addr_q = 4'd0;
    reg wr_q = 1'b0;
    reg [63:0] wdata_q = 64'd0;
    reg [63:0] rdata_q = 64'd0;
    reg [63:0] txn_cnt = 64'd0;
    // core side
    reg req_s1 = 1'b0;
    reg req_s2 = 1'b0;
    reg tgt_seen = 1'b0;
    reg ack_tgl = 1'b0;
    reg [63:0] regs [0:15];
    // verification shadow
    reg [3:0] shadow_addr = 4'd0;
    reg [63:0] shadow_wdata = 64'd0;
    reg win = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            regs[i] = 64'd0;
    end

    wire tgt_fire = (req_s2 != tgt_seen);
    wire launch = start && !busy;

    // host side: launch and completion
    always @(posedge clk) begin
        if (en) begin
            ack_s1 <= ack_tgl;
            ack_s2 <= ack_s1;
            if (launch) begin
                addr_q       <= addr_in;
                wr_q         <= wr_in;
                wdata_q      <= wdata_in;
                req_tgl      <= ~req_tgl;
                busy         <= 1'b1;
                shadow_addr  <= addr_in;
                shadow_wdata <= wdata_in;
                win          <= 1'b1;
            end else if (busy && (ack_s2 == req_tgl)) begin
                busy    <= 1'b0;
                win     <= 1'b0;
                txn_cnt <= txn_cnt + 64'd1;
            end
        end
    end

    // core side: synchronizer and target access
    always @(posedge clk) begin
        if (en) begin
            req_s1 <= req_tgl;
            req_s2 <= req_s1;
            if (tgt_fire) begin
                if (wr_q)
                    regs[addr_q] <= wdata_q;
                else
                    rdata_q <= regs[addr_q];
                tgt_seen <= req_s2;
                ack_tgl  <= ~ack_tgl;
            end
        end
    end

    assign busy_o  = busy;
    assign rdata_o = rdata_q;
    assign txn_o   = txn_cnt;

    // A1: core acts only on the address the host launched
    always @(*) assert (!(win && tgt_fire) || (addr_q == shadow_addr));
    // A2: core writes only the data the host launched
    always @(*) assert (!(win && tgt_fire && wr_q) || (wdata_q == shadow_wdata));
endmodule

module fletcher_seg_offload (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire in_valid,
    input wire in_last,
    input wire [127:0] in_data,
    output wire chk_valid,
    output wire [31:0] checksum
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0]  phase = IDLE;
    reg        armed_seen = 1'b0;
    reg        started_seen = 1'b0;
    reg        fin_q = 1'b0;
    reg [4:0]  cnt = 5'd0;
    reg [15:0] sumA = 16'd0;
    reg [15:0] sumB = 16'd0;

    assign chk_valid = fin_q;
    assign checksum = {sumB, sumA};

    function [31:0] fold;
        input [15:0] a;
        input [15:0] b;
        input [127:0] d;
        reg [16:0] ta;
        reg [16:0] tb;
        integer i;
        begin
            ta = {1'b0, a};
            tb = {1'b0, b};
            for (i = 0; i < 8; i = i + 1) begin
                ta = ta + {1'b0, d[i*16 +: 16]};
                if (ta >= 17'd65535) ta = ta - 17'd65535;
                tb = tb + ta;
                if (tb >= 17'd65535) tb = tb - 17'd65535;
            end
            fold = {tb[15:0], ta[15:0]};
        end
    endfunction

    wire [31:0] fold_run   = fold(sumA, sumB, in_data);
    wire [31:0] fold_first = fold(16'd0, 16'd0, in_data);

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            fin_q <= 1'b0;
            cnt <= 5'd0;
            sumA <= 16'd0;
            sumB <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (in_valid) begin
                        phase <= RUN;
                        started_seen <= 1'b1;
                        cnt <= 5'd1;
                        sumA <= fold_first[15:0];
                        sumB <= fold_first[31:16];
                    end
                end
                RUN: begin
                    if (in_valid) begin
                        sumA <= fold_run[15:0];
                        sumB <= fold_run[31:16];
                        cnt <= cnt + 5'd1;
                        if (in_last || cnt == 5'd23) begin
                            phase <= DONE;
                            fin_q <= 1'b1;
                        end
                    end
                end
                DONE: begin
                    phase <= IDLE;
                    armed_seen <= 1'b0;
                    started_seen <= 1'b0;
                    fin_q <= 1'b0;
                    cnt <= 5'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (fin_q) assert (armed_seen && started_seen);
endmodule

module ol_flow_perfmon (
    input  wire        clk,
    input  wire        en,
    input  wire [7:0]  ev,
    input  wire        cfg_we,
    input  wire [1:0]  cfg_idx,
    input  wire [2:0]  cfg_sel,
    input  wire        rd_en,
    input  wire        clr_all,
    output wire [15:0] rd_data,
    output wire        empty,
    output wire        full
);
    reg [15:0] ctr0, ctr1, ctr2, ctr3;
    reg [2:0]  sel0, sel1, sel2, sel3;
    reg [13:0] stamp;
    reg [15:0] mem [0:63];
    reg [6:0]  wr_ptr, rd_ptr, occ;
    reg        pre_clr;
    reg        pv;

    integer i;
    initial begin
        ctr0 = 16'd0; ctr1 = 16'd0; ctr2 = 16'd0; ctr3 = 16'd0;
        sel0 = 3'd0; sel1 = 3'd1; sel2 = 3'd2; sel3 = 3'd3;
        stamp = 14'd0;
        wr_ptr = 7'd0; rd_ptr = 7'd0; occ = 7'd0;
        pre_clr = 1'b1;
        pv = 1'b0;
        for (i = 0; i < 64; i = i + 1) mem[i] = 16'd0;
    end

    assign empty = (occ == 7'd0);
    wire [6:0] ptr_diff = wr_ptr - rd_ptr;
    assign full  = (ptr_diff == 7'd64);
    assign rd_data = mem[rd_ptr[5:0]];

    wire inc0 = ev[sel0];
    wire inc1 = ev[sel1];
    wire inc2 = ev[sel2];
    wire inc3 = ev[sel3];
    wire wrap0 = inc0 && (ctr0 == 16'hFFFF);
    wire wrap1 = inc1 && (ctr1 == 16'hFFFF);
    wire wrap2 = inc2 && (ctr2 == 16'hFFFF);
    wire wrap3 = inc3 && (ctr3 == 16'hFFFF);
    wire any_wrap = wrap0 | wrap1 | wrap2 | wrap3;
    wire [1:0] wid = wrap0 ? 2'd0 : (wrap1 ? 2'd1 : (wrap2 ? 2'd2 : 2'd3));

    wire do_push = en && !clr_all && any_wrap && !full;
    wire do_pop  = en && !clr_all && rd_en && !empty;

    integer j;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            stamp <= stamp + 14'd1;
            if (cfg_we) begin
                case (cfg_idx)
                    2'd0: sel0 <= cfg_sel;
                    2'd1: sel1 <= cfg_sel;
                    2'd2: sel2 <= cfg_sel;
                    default: sel3 <= cfg_sel;
                endcase
            end
            if (clr_all) begin
                ctr0 <= 16'd0; ctr1 <= 16'd0; ctr2 <= 16'd0; ctr3 <= 16'd0;
                wr_ptr <= 7'd0; rd_ptr <= 7'd0; occ <= 7'd0;
                pre_clr <= 1'b0;
                for (j = 0; j < 64; j = j + 1) mem[j] <= 16'd0;
            end else begin
                if (inc0) ctr0 <= ctr0 + 16'd1;
                if (inc1) ctr1 <= ctr1 + 16'd1;
                if (inc2) ctr2 <= ctr2 + 16'd1;
                if (inc3) ctr3 <= ctr3 + 16'd1;
                if (do_push) begin
                    mem[wr_ptr[5:0]] <= {wid, stamp};
                    wr_ptr <= wr_ptr + 7'd1;
                end
                if (do_pop) rd_ptr <= rd_ptr + 7'd1;
                case ({do_push, do_pop})
                    2'b10:   occ <= occ + 7'd1;
                    2'b01:   occ <= occ - 7'd1;
                    default: occ <= occ;
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(pre_clr))
            assert (!($past(full) && $past(empty)));
endmodule

module lfsr_gpio (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_out,
    input wire wr_dir,
    input wire wr_lock,
    input wire wr_unlock,
    input wire [31:0] wdata,
    input wire [31:0] pins_in,
    input wire sample,
    output reg [31:0] pin_drive,
    output reg [33:0] box_sum
);
    reg [31:0] out_data;
    reg [31:0] dir;
    reg [31:0] cap0;
    reg [31:0] cap1;
    reg [31:0] cap2;
    reg        lock_win;
    reg        pv;

    initial out_data  = 32'h0000_0000;
    initial dir       = 32'h0000_0000;
    initial pin_drive = 32'h0000_0000;
    initial cap0      = 32'h0000_0000;
    initial cap1      = 32'h0000_0000;
    initial cap2      = 32'h0000_0000;
    initial box_sum   = 34'h0_0000_0000;
    initial lock_win  = 1'b0;
    initial pv        = 1'b0;

    wire [31:0] nxt_out = wr_out ? wdata : out_data;
    wire [31:0] nxt_dir = wr_dir ? wdata : dir;
    wire [31:0] new_cap = pins_in & ~dir;

    always @(posedge clk) begin
        if (rst) begin
            out_data  <= 32'h0000_0000;
            dir       <= 32'h0000_0000;
            pin_drive <= 32'h0000_0000;
            cap0      <= 32'h0000_0000;
            cap1      <= 32'h0000_0000;
            cap2      <= 32'h0000_0000;
            box_sum   <= 34'h0_0000_0000;
            lock_win  <= 1'b0;
        end else if (en) begin
            out_data  <= nxt_out;
            dir       <= nxt_dir;
            pin_drive <= nxt_out & nxt_dir;
            if (sample) begin
                cap0    <= new_cap;
                cap1    <= cap0;
                cap2    <= cap1;
                box_sum <= box_sum + {2'b00, new_cap} - {2'b00, cap2};
            end
            if (wr_unlock)
                lock_win <= 1'b0;
            else if (wr_lock)
                lock_win <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && lock_win && $past(lock_win) && $stable(out_data) && $stable(dir))
            assert ($stable(pin_drive));
endmodule

module hls_pixclk_swallow (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [7:0] N,
    input wire [7:0] S,
    output wire strobe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, DONE = 2'd3;

    reg [3:0] pre_cnt = 4'd0;
    reg [7:0] p_cnt = 8'd0;
    reg [7:0] s_cnt = 8'd0;
    reg [7:0] n_reg = 8'd0;
    reg [7:0] s_reg = 8'd0;
    reg [1:0] phase = 2'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg q_seen = 1'b0;

    wire tc = (s_cnt != 8'd0) ? (pre_cnt == 4'd8) : (pre_cnt == 4'd7);
    wire hit = tc && (p_cnt <= 8'd1);
    assign strobe = en && !load && hit;

    always @(posedge clk) begin
        if (rst) begin
            pre_cnt <= 4'd0;
            p_cnt <= 8'd0;
            s_cnt <= 8'd0;
            n_reg <= 8'd0;
            s_reg <= 8'd0;
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            q_seen <= 1'b0;
        end else if (en) begin
            if (load) begin
                n_reg <= N;
                s_reg <= S;
                p_cnt <= N;
                s_cnt <= S;
                pre_cnt <= 4'd0;
                phase <= ARMED;
                armed_seen <= 1'b1;
                started_seen <= 1'b0;
                q_seen <= 1'b1;
            end else begin
                if (tc) begin
                    pre_cnt <= 4'd0;
                    if (p_cnt <= 8'd1) begin
                        p_cnt <= n_reg;
                        s_cnt <= s_reg;
                    end else begin
                        p_cnt <= p_cnt - 8'd1;
                        if (s_cnt != 8'd0)
                            s_cnt <= s_cnt - 8'd1;
                    end
                    case (phase)
                        ARMED: begin
                            phase <= STARTED;
                            started_seen <= 1'b1;
                        end
                        STARTED: begin
                            if (p_cnt <= 8'd1)
                                phase <= DONE;
                        end
                        default: phase <= phase;
                    endcase
                end else begin
                    pre_cnt <= pre_cnt + 4'd1;
                end
            end
        end
    end

    always @(*) assert (!(q_seen && phase == 2'd3) || (started_seen && armed_seen));
endmodule

module dnn_wfuse_ctrl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire prog_req,
    input wire [2:0] prog_addr,
    input wire [31:0] prog_data,
    input wire lock_req,
    input wire sense_req,
    output wire [31:0] o_rd_data,
    output wire o_locked
);
    localparam [1:0] S_IDLE = 2'd0, S_BURN = 2'd1, S_SENSE = 2'd2;

    reg [31:0] fuse_shadow [0:7];
    reg [7:0]  prog_done;
    reg [31:0] prog_cnt;
    reg [1:0]  fsm;
    reg        pre_lock;
    reg [2:0]  burn_addr;
    reg [31:0] burn_data;
    reg [31:0] rd_data;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) fuse_shadow[i] = 32'd0;
        prog_done = 8'd0;
        prog_cnt  = 32'd0;
        fsm       = S_IDLE;
        pre_lock  = 1'b1;
        burn_addr = 3'd0;
        burn_data = 32'd0;
        rd_data   = 32'd0;
    end

    wire [3:0] done_pop = prog_done[0] + prog_done[1] + prog_done[2] + prog_done[3]
                        + prog_done[4] + prog_done[5] + prog_done[6] + prog_done[7];

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) fuse_shadow[i] <= 32'd0;
            prog_done <= 8'd0;
            prog_cnt  <= 32'd0;
            fsm       <= S_IDLE;
            pre_lock  <= 1'b1;
            burn_addr <= 3'd0;
            burn_data <= 32'd0;
            rd_data   <= 32'd0;
        end else if (en) begin
            if (lock_req)
                pre_lock <= 1'b0;
            case (fsm)
                S_IDLE: begin
                    if (pre_lock && prog_req && !prog_done[prog_addr]) begin
                        burn_addr <= prog_addr;
                        burn_data <= prog_data;
                        fsm       <= S_BURN;
                    end else if (!pre_lock && sense_req) begin
                        burn_addr <= prog_addr;
                        fsm       <= S_SENSE;
                    end
                end
                S_BURN: begin
                    fuse_shadow[burn_addr] <= burn_data;
                    prog_done[burn_addr]   <= 1'b1;
                    prog_cnt               <= prog_cnt + 32'd1;
                    fsm                    <= S_IDLE;
                end
                S_SENSE: begin
                    rd_data  <= fuse_shadow[burn_addr];
                    prog_cnt <= prog_cnt + 32'd1;
                    fsm      <= S_IDLE;
                end
                default: fsm <= S_IDLE;
            endcase
        end
    end

    assign o_rd_data = rd_data;
    assign o_locked  = !pre_lock;

    always @(posedge clk)
        assert (!pre_lock || prog_cnt <= 32'd8);
endmodule

module issie_dbi_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [63:0] wdata,
    input  wire        q_start,
    input  wire        r_stop,
    output wire [63:0] rdata,
    output wire [63:0] beat_count
);
    reg [63:0] bus_q;
    reg [7:0]  dbi_q;
    reg [63:0] plain_q;
    reg [63:0] beat_cnt;
    reg        win;
    reg        pv;
    initial begin
        bus_q = 64'd0; dbi_q = 8'd0; plain_q = 64'd0;
        beat_cnt = 64'd0; win = 1'b0; pv = 1'b0;
    end

    function [3:0] pop8;
        input [7:0] b;
        integer k;
        begin
            pop8 = 4'd0;
            for (k = 0; k < 8; k = k + 1)
                pop8 = pop8 + {3'd0, b[k]};
        end
    endfunction

    wire [7:0]  f;
    wire [63:0] enc;
    wire [63:0] xdbi;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : g_lane
            assign f[i] = ((4'd8 - pop8(wdata[8*i +: 8])) > 4'd4);
            assign enc[8*i +: 8]  = wdata[8*i +: 8] ^ {8{f[i]}};
            assign xdbi[8*i +: 8] = {8{dbi_q[i]}};
        end
    endgenerate

    assign rdata = bus_q ^ xdbi;
    assign beat_count = beat_cnt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            bus_q <= 64'd0;
            dbi_q <= 8'd0;
            plain_q <= 64'd0;
            beat_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (wr) begin
                bus_q <= enc;
                dbi_q <= f;
                plain_q <= wdata;
                beat_cnt <= beat_cnt + 64'd1;
            end
            if (q_start)
                win <= 1'b1;
            else if (r_stop)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && $past(win) && $stable(bus_q) && $stable(dbi_q))
            assert ($stable(plain_q));
endmodule

module zkr_seed_unit (
    input wire clk,
    input wire rst,
    input wire en,
    input wire raw,
    input wire q_open,
    input wire r_close,
    output wire [7:0] o_seed,
    output wire o_win
);
    reg half = 1'b0;
    reg first_bit = 1'b0;
    reg out_valid = 1'b0;
    reg out_bit = 1'b0;
    reg [7:0] pair_cnt = 8'd0;
    reg [7:0] emit_cnt = 8'd0;
    reg [63:0] pool = 64'd0;
    reg [5:0] wr_ptr = 6'd0;
    reg win = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            half <= 1'b0;
            first_bit <= 1'b0;
            out_valid <= 1'b0;
            out_bit <= 1'b0;
            pair_cnt <= 8'd0;
            emit_cnt <= 8'd0;
            pool <= 64'd0;
            wr_ptr <= 6'd0;
            win <= 1'b0;
        end else if (en) begin
            if (!half) begin
                first_bit <= raw;
                half <= 1'b1;
                pair_cnt <= pair_cnt + 8'd1;
                if (out_valid) begin
                    pool[wr_ptr] <= out_bit;
                    wr_ptr <= wr_ptr + 6'd1;
                    out_valid <= 1'b0;
                end
            end else begin
                half <= 1'b0;
                if (raw != first_bit) begin
                    out_bit <= first_bit;
                    out_valid <= 1'b1;
                end
            end
            if (out_valid)
                emit_cnt <= emit_cnt + 8'd1;
            if (q_open)
                win <= 1'b1;
            else if (r_close)
                win <= 1'b0;
        end
    end

    assign o_seed = pool[7:0];
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(pair_cnt))
            assert ($stable(emit_cnt));
endmodule

module lane_deskew4 (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [255:0] din,
    input  wire [3:0]   mk,
    output wire [255:0] dout,
    output wire         aligned_o,
    output wire         timeout_o
);
    reg [63:0] fifo [0:31];
    reg [11:0] wptr;
    reg [11:0] rptr;
    reg [3:0]  seen;
    reg        aligned;
    reg        win;
    reg [63:0] cd;
    reg        timeout;

    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) fifo[k] = 64'd0;
        wptr = 12'd0; rptr = 12'd0; seen = 4'd0;
        aligned = 1'b0; win = 1'b0; cd = 64'd0; timeout = 1'b0;
    end

    wire       q        = !win && !aligned && (|mk);
    wire       force_mk = win && !aligned && (cd == 64'd1);
    wire [3:0] seen_n   = force_mk ? 4'hF : (seen | mk);

    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            wptr <= 12'd0; rptr <= 12'd0; seen <= 4'd0;
            aligned <= 1'b0; win <= 1'b0; cd <= 64'd0; timeout <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 4; i = i + 1) begin
                fifo[i*8 + wptr[i*3 +: 3]] <= din[i*64 +: 64];
                wptr[i*3 +: 3] <= wptr[i*3 +: 3] + 3'd1;
                if (aligned) rptr[i*3 +: 3] <= rptr[i*3 +: 3] + 3'd1;
            end
            seen    <= seen_n;
            timeout <= timeout | (win && !aligned && (cd == 64'd0));
            if (seen_n == 4'hF) begin
                aligned <= 1'b1;
                win     <= 1'b0;
                cd      <= 64'd0;
            end else if (q) begin
                win <= 1'b1;
                cd  <= 64'd8;
            end else if (win && !aligned) begin
                cd <= cd - 64'd1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            assign dout[g*64 +: 64] = fifo[g*8 + rptr[g*3 +: 3]];
        end
    endgenerate

    assign aligned_o = aligned;
    assign timeout_o = timeout;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && !aligned && $stable(aligned))
            assert ($stable(timeout));
endmodule

module tia_pll_seq (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire band_ok,
    input wire lock_in,
    output wire pll_pwr,
    output wire cal_active,
    output wire loop_closed,
    output wire clk_release,
    output reg [3:0] band
);
    localparam [2:0] S_OFF      = 3'd0;
    localparam [2:0] S_PWRUP    = 3'd1;
    localparam [2:0] S_BANDCAL  = 3'd2;
    localparam [2:0] S_CLOSE    = 3'd3;
    localparam [2:0] S_LOCKWAIT = 3'd4;
    localparam [2:0] S_RUN      = 3'd5;

    reg [2:0]  state;
    reg [15:0] cnt;

    initial state = S_OFF;
    initial cnt   = 16'd0;
    initial band  = 4'd0;

    assign pll_pwr     = (state != S_OFF);
    assign cal_active  = (state == S_BANDCAL);
    assign loop_closed = (state == S_CLOSE) || (state == S_LOCKWAIT) || (state == S_RUN);
    assign clk_release = (state == S_RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S_OFF;
            cnt   <= 16'd0;
            band  <= 4'd0;
        end else if (en) begin
            case (state)
                S_OFF: begin
                    state <= S_PWRUP;
                    cnt   <= 16'd0;
                end
                S_PWRUP: begin
                    if (cnt >= 16'd511) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
                end
                S_LOCKWAIT: begin
                    if (!lock_in) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else if (cnt >= 16'd1200) begin
                        state <= S_RUN;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_RUN: begin
                    cnt <= 16'd0;
                    if (!lock_in)
                        state <= S_BANDCAL;
                end
                default: begin
                    state <= S_OFF;
                    cnt   <= 16'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (state == 3'd4) assert (cnt <= 16'd1200);
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
    input wire [4:0]  issue_idx
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

    wire alloc_fire = alloc && !full;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
    wire [31:0] new_deps   = alloc_deps & valid & ~clr_mask;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module arrow_bound_cmp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire mode_in,
    input wire [7:0] cnt_in,
    input wire [7:0] len_in,
    output wire o_lt,
    output wire o_eq,
    output wire o_gt
);
    reg mode_r;
    reg [7:0] cnt_r;
    reg [7:0] len_r;
    reg lt_r, eq_r, gt_r;
    reg gt_q;
    initial mode_r = 1'b0;
    initial cnt_r = 8'd0;
    initial len_r = 8'd0;
    initial lt_r = 1'b0;
    initial eq_r = 1'b1;
    initial gt_r = 1'b0;
    initial gt_q = 1'b0;

    wire in_lt = mode_in ? ($signed(cnt_in) < $signed(len_in)) : (cnt_in < len_in);
    wire in_eq = (cnt_in == len_in);
    wire in_gt = !in_lt && !in_eq;

    wire cur_lt = mode_r ? ($signed(cnt_r) < $signed(len_r)) : (cnt_r < len_r);
    wire cur_eq = (cnt_r == len_r);

    wire [7:0] cnt_nx = cnt_r + 8'd1;

    always @(posedge clk) begin
        if (rst) begin
            mode_r <= 1'b0;
            cnt_r <= 8'd0;
            len_r <= 8'd0;
            lt_r <= 1'b0;
            eq_r <= 1'b1;
            gt_r <= 1'b0;
            gt_q <= 1'b0;
        end else if (en) begin
            gt_q <= gt_r;
            if (load) begin
                cnt_r <= cnt_in;
                len_r <= len_in;
                mode_r <= mode_in;
                lt_r <= in_lt;
                eq_r <= in_eq;
                gt_r <= in_gt;
            end else if (eq_r) begin
                eq_r <= 1'b0;
                gt_r <= 1'b1;
            end else if (lt_r) begin
                cnt_r <= cnt_nx;
                if (cnt_nx == len_r) begin
                    lt_r <= 1'b0;
                    eq_r <= 1'b1;
                end
            end
        end
    end

    assign o_lt = lt_r;
    assign o_eq = eq_r;
    assign o_gt = gt_r;

    always @(posedge clk)
        if (gt_r && !gt_q)
            assert (!lt_r && !eq_r);
endmodule

module rvx_dma2d (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire [63:0] cfg_row_len,
    input  wire [63:0] cfg_row_cnt,
    input  wire [63:0] cfg_src_base,
    input  wire [63:0] cfg_dst_base,
    input  wire [63:0] cfg_src_stride,
    input  wire [63:0] cfg_dst_stride,
    input  wire [63:0] rd_data,
    input  wire        dst_ready,
    output wire [63:0] rd_addr,
    output wire        rd_req,
    output wire [63:0] wr_addr,
    output wire [63:0] wr_data,
    output wire        wr_valid,
    output wire        busy
);
    reg [63:0] row_len, row_cnt, src_stride, dst_stride;
    reg [63:0] rcol, rrow, src_addr;
    reg [63:0] wcol, wrow, dst_addr;
    reg        active;
    reg [63:0] fifo_mem [0:7];
    reg [2:0]  wr_ptr, rd_ptr;
    reg        wr_lap, rd_lap;
    reg [3:0]  fifo_count;
    reg        pre_done;
    integer i;

    initial begin
        row_len = 64'd0; row_cnt = 64'd0; src_stride = 64'd0; dst_stride = 64'd0;
        rcol = 64'd0; rrow = 64'd0; src_addr = 64'd0;
        wcol = 64'd0; wrow = 64'd0; dst_addr = 64'd0;
        active = 1'b0;
        wr_ptr = 3'd0; rd_ptr = 3'd0; wr_lap = 1'b0; rd_lap = 1'b0;
        fifo_count = 4'd0;
        pre_done = 1'b1;
        for (i = 0; i < 8; i = i + 1) fifo_mem[i] = 64'd0;
    end

    wire fifo_full  = (fifo_count == 4'd8);
    wire fifo_empty = (wr_ptr == rd_ptr) && (wr_lap == rd_lap);

    wire rows_left = (rrow < row_cnt);
    wire do_push   = active && rows_left && (fifo_count < 4'd8);
    wire do_pop    = !fifo_empty && dst_ready;
    wire rd_row_end = (rcol == row_len - 64'd1);
    wire wr_row_end = (wcol == row_len - 64'd1);
    wire last_pop  = do_pop && wr_row_end && (wrow == row_cnt - 64'd1);

    assign rd_addr  = src_addr;
    assign rd_req   = do_push;
    assign wr_addr  = dst_addr;
    assign wr_data  = fifo_mem[rd_ptr];
    assign wr_valid = !fifo_empty;
    assign busy     = active;

    always @(posedge clk) begin
        if (rst) begin
            active <= 1'b0;
            rcol <= 64'd0; rrow <= 64'd0; src_addr <= 64'd0;
            wcol <= 64'd0; wrow <= 64'd0; dst_addr <= 64'd0;
            wr_ptr <= 3'd0; rd_ptr <= 3'd0; wr_lap <= 1'b0; rd_lap <= 1'b0;
            fifo_count <= 4'd0;
            pre_done <= 1'b1;
        end else if (en) begin
            if (do_push) begin
                fifo_mem[wr_ptr] <= rd_data;
                {wr_lap, wr_ptr} <= {wr_lap, wr_ptr} + 4'd1;
                if (rd_row_end) begin
                    rcol     <= 64'd0;
                    rrow     <= rrow + 64'd1;
                    src_addr <= src_addr + 64'd8 + src_stride;
                end else begin
                    rcol     <= rcol + 64'd1;
                    src_addr <= src_addr + 64'd8;
                end
            end
            if (do_pop) begin
                {rd_lap, rd_ptr} <= {rd_lap, rd_ptr} + 4'd1;
                if (wr_row_end) begin
                    wcol     <= 64'd0;
                    wrow     <= wrow + 64'd1;
                    dst_addr <= dst_addr + 64'd8 + dst_stride;
                end else begin
                    wcol     <= wcol + 64'd1;
                    dst_addr <= dst_addr + 64'd8;
                end
            end
            case ({do_push, do_pop})
                2'b10:   fifo_count <= fifo_count + 4'd1;
                2'b01:   fifo_count <= fifo_count - 4'd1;
                default: fifo_count <= fifo_count;
            endcase
            if (last_pop) begin
                active   <= 1'b0;
                pre_done <= 1'b0;
            end
            if (start && !active) begin
                row_len    <= cfg_row_len;
                row_cnt    <= cfg_row_cnt;
                src_stride <= cfg_src_stride;
                dst_stride <= cfg_dst_stride;
                src_addr   <= cfg_src_base;
                dst_addr   <= cfg_dst_base;
                rcol <= 64'd0; rrow <= 64'd0;
                wcol <= 64'd0; wrow <= 64'd0;
                active <= 1'b1;
            end
        end
    end

    always @(*) assert (!pre_done || !(fifo_full && fifo_empty));
endmodule

module ras_walker (
    input wire clk,
    input wire rst,
    input wire en,
    input wire call,
    input wire ret,
    input wire [63:0] call_addr,
    output reg [63:0] ret_addr,
    output reg ret_valid
);
    reg [63:0] ras0, ras1;
    reg [1:0]  tos;
    reg        pend;
    reg [63:0] stg;
    reg [63:0] cnt;
    reg        win;
    reg        pv;

    initial ras0 = 64'd0;
    initial ras1 = 64'd0;
    initial tos = 2'd0;
    initial pend = 1'b0;
    initial stg = 64'd0;
    initial cnt = 64'd0;
    initial win = 1'b0;
    initial ret_addr = 64'd0;
    initial ret_valid = 1'b0;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            ras0 <= 64'd0;
            ras1 <= 64'd0;
            tos <= 2'd0;
            pend <= 1'b0;
            stg <= 64'd0;
            cnt <= 64'd0;
            win <= 1'b0;
            ret_addr <= 64'd0;
            ret_valid <= 1'b0;
        end else if (en) begin
            ret_valid <= 1'b0;
            if (pend) begin
                if (stg == 64'd3) begin
                    ret_addr <= tos[0] ? ras1 : ras0;
                    ret_valid <= 1'b1;
                    pend <= 1'b0;
                    win <= 1'b0;
                    stg <= 64'd0;
                end else begin
                    stg <= stg + 64'd1;
                    cnt <= cnt - 64'd1;
                end
            end else if (ret && tos != 2'd0) begin
                tos <= tos - 2'd1;
                pend <= 1'b1;
                stg <= 64'd0;
                cnt <= 64'd4;
                win <= 1'b1;
            end else if (call && tos < 2'd2) begin
                if (tos == 2'd0) ras0 <= call_addr;
                else ras1 <= call_addr;
                tos <= tos + 2'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(en) && $past(win) && $past(pend))
            assert ($past(cnt) != 64'd0);
endmodule

module vcd_tstamp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire snap_req,
    input wire rd_hi,
    output wire [31:0] rdata
);
    reg [31:0] cnt_lo, cnt_hi, snap_lo, snap_hi;
    reg        busy;
    reg [3:0]  cd;
    reg        win;
    reg        latched;

    initial begin
        cnt_lo = 32'd0; cnt_hi = 32'd0;
        snap_lo = 32'd0; snap_hi = 32'd0;
        busy = 1'b0; cd = 4'd0; win = 1'b0; latched = 1'b0;
    end

    wire accept = snap_req && (cd == 4'd0);

    assign rdata = rd_hi ? snap_hi : snap_lo;

    always @(posedge clk) begin
        if (rst) begin
            cnt_lo <= 32'd0; cnt_hi <= 32'd0;
            snap_lo <= 32'd0; snap_hi <= 32'd0;
            busy <= 1'b0; cd <= 4'd0; win <= 1'b0; latched <= 1'b0;
        end else if (en) begin
            cnt_lo <= cnt_lo + 32'd1;
            if (cnt_lo == 32'hFFFFFFFF)
                cnt_hi <= cnt_hi + 32'd1;

            if (accept) begin
                busy    <= 1'b1;
                cd      <= 4'd8;
                latched <= 1'b0;
            end else begin
                if (cd != 4'd0)
                    cd <= cd - 4'd1;
                if (busy && cd == 4'd5) begin
                    snap_lo <= cnt_lo;
                    snap_hi <= cnt_hi;
                    latched <= 1'b1;
                end
                if (busy && cd == 4'd1 && latched) begin
                    busy    <= 1'b0;
                    latched <= 1'b0;
                end
            end

            if (accept)
                win <= 1'b1;
            else if (rd_hi)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy)
            assert (cd != 4'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cd <= 4'd8);
endmodule

module awesome_frame_sync (
    input wire clk,
    input wire rst,
    input wire en,
    input wire hdr_ok,
    input wire win_clr,
    output reg [1:0] state
);
    localparam [1:0] HUNT = 2'd0, PRESYNC = 2'd1, SYNC = 2'd2;
    reg [31:0] good_cnt;
    reg [31:0] bad_cnt;
    reg [3:0]  bad_hist;
    reg        win;
    initial begin
        state = HUNT; good_cnt = 32'd0; bad_cnt = 32'd0; bad_hist = 4'd0; win = 1'b0;
    end

    wire q_evt = en && (state == PRESYNC) && hdr_ok && (good_cnt == 32'd2);

    always @(posedge clk) begin
        if (rst) begin
            state <= HUNT; good_cnt <= 32'd0; bad_cnt <= 32'd0; bad_hist <= 4'd0; win <= 1'b0;
        end else if (en) begin
            if (win_clr) win <= 1'b0;
            else if (q_evt) win <= 1'b1;
            case (state)
                HUNT: begin
                    if (hdr_ok) begin
                        state <= PRESYNC;
                        good_cnt <= 32'd1;
                    end
                end
                PRESYNC: begin
                    if (hdr_ok) begin
                        if (good_cnt == 32'd2) begin
                            state <= SYNC;
                            good_cnt <= 32'd0;
                            bad_cnt <= 32'd0;
                            bad_hist <= 4'd0;
                        end else begin
                            good_cnt <= good_cnt + 32'd1;
                        end
                    end else begin
                        state <= HUNT;
                        good_cnt <= 32'd0;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end
                end
                SYNC: begin
                    if (hdr_ok) begin
                        bad_cnt <= 32'd0;
                        bad_hist <= {bad_hist[2:0], 1'b0};
                    end else if (bad_hist[2:0] == 3'b111) begin
                        state <= HUNT;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end else begin
                        bad_cnt <= bad_cnt + 32'd1;
                        bad_hist <= {bad_hist[2:0], 1'b1};
                    end
                end
                default: begin
                    state <= HUNT;
                    good_cnt <= 32'd0;
                    bad_cnt <= 32'd0;
                    bad_hist <= 4'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && state == 2'd2)
            assert (bad_cnt <= 32'd3);
endmodule

module farrow_apb_bridge (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire hwr,
    input wire [31:0] hwdata,
    input wire hmu_wr,
    input wire [31:0] hmu,
    input wire pread,
    output wire [31:0] prdata
);
    reg [31:0] x0, x1, x2, x3;
    reg [31:0] c0, c1, c2, c3;
    reg [31:0] mu;
    reg [31:0] fill_cnt;
    reg out_valid;
    reg [31:0] y;
    reg hist_wr;

    initial begin
        x0 = 32'd0; x1 = 32'd0; x2 = 32'd0; x3 = 32'd0;
        c0 = 32'd0; c1 = 32'd0; c2 = 32'd0; c3 = 32'd0;
        mu = 32'd0; fill_cnt = 32'd0; out_valid = 1'b0;
        y = 32'd0; hist_wr = 1'b0;
    end

    // cubic Lagrange sub-filter taps (truncated arithmetic)
    wire [31:0] d02  = x0 - x2;
    wire [31:0] t1   = $signed(d02) >>> 1;
    wire [31:0] x1m5 = x1 * 32'd5;
    wire [31:0] t2   = x2 - ($signed(x1m5) >>> 1) + (x0 << 1);
    wire [31:0] s3   = (x3 - x0) + ((x1 - x2) * 32'd3);
    wire [31:0] t3   = $signed(s3) >>> 1;

    // Horner evaluation in Q0.32 mu
    wire [63:0] p3 = {32'd0, c3} * {32'd0, mu};
    wire [31:0] h3 = p3[63:32] + c2;
    wire [63:0] p2 = {32'd0, h3} * {32'd0, mu};
    wire [31:0] h2 = p2[63:32] + c1;
    wire [63:0] p1 = {32'd0, h2} * {32'd0, mu};
    wire [31:0] y_next = p1[63:32] + c0;

    wire rd_done = pread && (fill_cnt == 32'd4);

    always @(posedge clk) begin
        if (!rst_n) begin
            x0 <= 32'd0; x1 <= 32'd0; x2 <= 32'd0; x3 <= 32'd0;
            c0 <= 32'd0; c1 <= 32'd0; c2 <= 32'd0; c3 <= 32'd0;
            mu <= 32'd0; fill_cnt <= 32'd0; out_valid <= 1'b0;
            y <= 32'd0; hist_wr <= 1'b0;
        end else if (en) begin
            if (hwr) begin
                x3 <= x2;
                x2 <= x1;
                x1 <= x0;
                x0 <= hwdata;
                fill_cnt <= (fill_cnt >= 32'd4) ? 32'd4 : fill_cnt + 32'd1;
                hist_wr <= 1'b1;
            end
            c0 <= x1;
            c1 <= t1;
            c2 <= t2;
            c3 <= t3;
            if (hmu_wr)
                mu <= hmu;
            out_valid <= rd_done;
            if (rd_done)
                y <= y_next;
        end
    end

    assign prdata = y;

    always @(posedge clk)
        if (out_valid)
            assert (hist_wr);
endmodule

module bayer_tile_demosaic (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire [63:0] pix_in,
    output reg [63:0] rgb_r,
    output reg [63:0] rgb_g,
    output reg [63:0] rgb_b,
    output reg done
);
    reg [63:0] tile [0:15];
    reg [63:0] idx;
    reg [63:0] cd;
    reg busy;
    reg [1:0] phase;
    reg win;
    reg pv;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1) tile[k] = 64'd0;
        idx = 64'd0;
        cd = 64'd0;
        busy = 1'b0;
        phase = 2'b00;
        win = 1'b0;
        pv = 1'b0;
        rgb_r = 64'd0;
        rgb_g = 64'd0;
        rgb_b = 64'd0;
        done = 1'b0;
    end

    wire [3:0] i0 = idx[3:0];
    wire [3:0] im = i0 - 4'd1;
    wire [3:0] ip = i0 + 4'd1;
    wire [63:0] c_px = tile[i0];
    wire [63:0] l_px = tile[im];
    wire [63:0] r_px = tile[ip];
    wire [63:0] avg = (l_px >> 1) + (r_px >> 1);
    wire [63:0] diag = (l_px >> 2) + (r_px >> 2) + (c_px >> 1);

    reg [63:0] nr, ng, nb;
    always @(*) begin
        case (phase)
            2'b00: begin nr = c_px; ng = avg;  nb = diag; end
            2'b01: begin nr = avg;  ng = c_px; nb = diag; end
            2'b10: begin nr = diag; ng = c_px; nb = avg;  end
            default: begin nr = diag; ng = avg; nb = c_px; end
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1) tile[k] <= 64'd0;
            idx <= 64'd0;
            cd <= 64'd0;
            busy <= 1'b0;
            phase <= 2'b00;
            win <= 1'b0;
            rgb_r <= 64'd0;
            rgb_g <= 64'd0;
            rgb_b <= 64'd0;
            done <= 1'b0;
        end else if (en) begin
            if (start && !busy) begin
                busy <= 1'b1;
                win <= 1'b1;
                idx <= 64'd0;
                cd <= 64'd16;
                phase <= 2'b00;
                done <= 1'b0;
            end else if (busy) begin
                tile[i0] <= pix_in;
                rgb_r <= nr;
                rgb_g <= ng;
                rgb_b <= nb;
                idx <= idx + 64'd1;
                cd <= cd - 64'd1;
                phase[0] <= ~phase[0];
                if (i0[1:0] == 2'b11) phase[1] <= ~phase[1];
                if (idx == 64'd15) begin
                    busy <= 1'b0;
                    win <= 1'b0;
                    done <= 1'b1;
                end else begin
                    done <= 1'b0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(win) && $past(busy))
            assert ($past(cd) != 64'd0);
endmodule

module round_disp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [34:0] din,
    input wire [1:0] mode_in,
    output reg [6:0] seg
);
    reg [31:0] trunc = 32'd0;
    reg [2:0]  grs = 3'b000;
    reg [1:0]  mode = 2'd0;
    reg [31:0] rounded = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    function inc_f;
        input [1:0] m;
        input [2:0] g;
        input lsb;
        begin
            case (m)
                2'd0: inc_f = g[2] & (g[1] | g[0] | lsb);
                2'd1: inc_f = 1'b0;
                2'd2: inc_f = g[2] | g[1] | g[0];
                default: inc_f = g[2];
            endcase
        end
    endfunction

    wire ld_inc = inc_f(mode_in, din[2:0], din[3]);
    wire rf_inc = inc_f(mode, grs, trunc[0]);

    always @(posedge clk) begin
        if (rst) begin
            trunc   <= 32'd0;
            grs     <= 3'b000;
            mode    <= 2'd0;
            rounded <= 32'd0;
            armed   <= 1'b0;
        end else if (en) begin
            if (load) begin
                trunc   <= din[34:3];
                grs     <= din[2:0];
                mode    <= mode_in;
                rounded <= din[34:3] + {31'd0, ld_inc};
                armed   <= 1'b1;
            end else begin
                rounded <= trunc + {31'd0, rf_inc};
            end
        end
    end

    always @(*) begin
        case (rounded[3:0])
            4'h0: seg = 7'b1111110;
            4'h1: seg = 7'b0110000;
            4'h2: seg = 7'b1101101;
            4'h3: seg = 7'b1111001;
            4'h4: seg = 7'b0110011;
            4'h5: seg = 7'b1011011;
            4'h6: seg = 7'b1011111;
            4'h7: seg = 7'b1110000;
            4'h8: seg = 7'b1111111;
            4'h9: seg = 7'b1111011;
            4'hA: seg = 7'b1110111;
            4'hB: seg = 7'b0011111;
            4'hC: seg = 7'b1001110;
            4'hD: seg = 7'b0111101;
            4'hE: seg = 7'b1001111;
            default: seg = 7'b1000111;
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && !$past(rst) && armed && $stable(trunc) && $stable(grs) && $stable(mode))
            assert ($stable(rounded));
endmodule

module sd_host_blk (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_start,
    input wire [63:0] cmd_arg,
    input wire resp_valid,
    input wire [63:0] resp_in,
    input wire data_valid,
    input wire [63:0] data_in,
    input wire [1:0] rd_idx,
    output wire o_busy,
    output wire [63:0] o_resp,
    output wire [63:0] o_arg,
    output wire [63:0] o_data,
    output wire [63:0] o_words_done
);
    localparam [63:0] BLK_WORDS = 64'd8;

    reg [63:0] arg_reg;
    reg [63:0] resp_reg;
    reg        busy;
    reg [63:0] words_done;
    reg [63:0] words_left;
    reg [63:0] fifo [0:3];
    reg        armed;
    reg        pv;

    initial begin
        arg_reg = 64'd0;
        resp_reg = 64'd0;
        busy = 1'b0;
        words_done = 64'd0;
        words_left = BLK_WORDS;
        fifo[0] = 64'd0;
        fifo[1] = 64'd0;
        fifo[2] = 64'd0;
        fifo[3] = 64'd0;
        armed = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (en) begin
            pv <= 1'b1;
            if (rst) begin
                words_done <= 64'd0;
                words_left <= BLK_WORDS;
                busy <= 1'b0;
                armed <= 1'b0;
            end else begin
                if (resp_valid) begin
                    resp_reg <= resp_in;
                    armed <= 1'b1;
                end
                if (cmd_start && !busy) begin
                    arg_reg <= cmd_arg;
                    words_done <= 64'd0;
                    words_left <= BLK_WORDS;
                    busy <= 1'b1;
                end else if (busy) begin
                    if (data_valid && words_left != 64'd0) begin
                        fifo[words_done[1:0]] <= data_in;
                        words_done <= words_done + 64'd1;
                        words_left <= words_left - 64'd1;
                    end
                    if (words_left == 64'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_resp = resp_reg;
    assign o_arg = arg_reg;
    assign o_data = fifo[rd_idx];
    assign o_words_done = words_done;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(words_done) <= 64'd8);
endmodule

module udp_hamming_tx (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         req,
    input  wire [127:0] data_i,
    input  wire         link_down,
    output wire [136:0] code_o,
    output wire         valid_o
);
    reg [127:0] data_q;
    reg [8:0]   chk_q;
    reg [1:0]   step;
    reg [2:0]   cd;
    reg         busy;
    reg [136:0] code_q;
    reg         valid_q;
    reg         pre_r;

    initial begin
        data_q  = 128'd0;
        chk_q   = 9'd0;
        step    = 2'd0;
        cd      = 3'd0;
        busy    = 1'b0;
        code_q  = 137'd0;
        valid_q = 1'b0;
        pre_r   = 1'b1;
    end

    assign code_o  = code_q;
    assign valid_o = valid_q;

    // current 32-bit beat
    wire [31:0] beat = data_q[{step, 5'b00000} +: 32];

    // Hamming contribution of this beat: data bit idx sits at position 129+idx
    reg [8:0] beat_chk;
    reg [5:0] j;
    always @(*) begin
        beat_chk = 9'd0;
        for (j = 6'd0; j < 6'd32; j = j + 6'd1) begin
            if (beat[j[4:0]]) begin
                beat_chk[7:0] = beat_chk[7:0] ^ (8'd129 + {1'b0, step, j[4:0]});
                beat_chk[8]   = ~beat_chk[8];
            end
        end
    end

    wire [8:0] chk_next  = chk_q ^ beat_chk;
    wire       par_final = chk_next[8] ^ (^chk_next[7:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            data_q  <= 128'd0;
            chk_q   <= 9'd0;
            step    <= 2'd0;
            cd      <= 3'd0;
            busy    <= 1'b0;
            code_q  <= 137'd0;
            valid_q <= 1'b0;
        end else if (en) begin
            if (busy) begin
                chk_q <= chk_next;
                step  <= step + 2'd1;
                cd    <= cd - 3'd1;
                if (step == 2'd3) begin
                    code_q  <= {par_final, chk_next[7:0], data_q};
                    valid_q <= 1'b1;
                    busy    <= 1'b0;
                end
            end else if (req) begin
                data_q  <= data_i;
                chk_q   <= 9'd0;
                step    <= 2'd0;
                cd      <= 3'd4;
                busy    <= 1'b1;
                valid_q <= 1'b0;
            end
        end
    end

    // scope register: ignores en
    always @(posedge clk) begin
        if (!rst_n)
            pre_r <= 1'b1;
        else if (link_down)
            pre_r <= 1'b0;
    end

    always @(posedge clk)
        if (pre_r) assert (!(busy && cd == 3'd0));
endmodule

module pin_bist (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    output wire busy,
    output reg fail
);
    localparam [127:0] PAT = "PIN_UART_A15____";

    reg [127:0] mem [0:15];
    reg [3:0] addr = 4'd0;
    reg [1:0] phase = 2'd0;
    reg [6:0] countdown = 7'd0;
    reg win = 1'b0;
    initial fail = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 128'd0;
    end

    assign busy = win;

    wire [5:0] pa = {phase, addr};
    wire [127:0] rd = mem[addr];
    wire [127:0] exp_rd = (phase == 2'd2) ? ~PAT : PAT;
    wire [127:0] wr = (phase == 2'd1) ? ~PAT : PAT;
    wire do_read = (phase != 2'd0);
    wire do_write = (phase != 2'd3);

    always @(posedge clk) begin
        if (!rst && en && win && do_write)
            mem[addr] <= wr;
    end

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            countdown <= 7'd0;
            addr <= 4'd0;
            phase <= 2'd0;
            fail <= 1'b0;
        end else if (en) begin
            if (!win) begin
                if (start) begin
                    win <= 1'b1;
                    countdown <= 7'd64;
                    addr <= 4'd0;
                    phase <= 2'd0;
                    fail <= 1'b0;
                end
            end else begin
                if (do_read && (rd != exp_rd))
                    fail <= 1'b1;
                {phase, addr} <= pa + 6'd1;
                if (pa == 6'd63) begin
                    win <= 1'b0;
                    countdown <= 7'd0;
                end else begin
                    countdown <= countdown - 7'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire cd_zero = (countdown == 7'd0);

    always @(posedge clk) begin
        if (pv && !rst && win && $stable(win))
            assert ($stable(cd_zero));
    end
endmodule

module axi_goertzel_bin (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire b_ready,
    input wire clr,
    input wire [15:0] sample,
    input wire [15:0] coef_in,
    output reg done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUNNING = 2'd2, DONE = 2'd3;

    reg [1:0] phase = 2'd0;
    reg signed [15:0] s1 = 16'sd0;
    reg signed [15:0] s2 = 16'sd0;
    reg [15:0] cnt = 16'd0;
    reg [15:0] coef = 16'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg before_clr = 1'b1;
    initial done = 1'b0;

    wire signed [31:0] prod = $signed(coef) * s1;
    wire signed [31:0] fb = prod >>> 14;
    wire signed [15:0] s1_next = $signed(sample) + fb[15:0] - s2;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            s1 <= 16'sd0;
            s2 <= 16'sd0;
            cnt <= 16'd0;
            coef <= 16'd0;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            before_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        coef <= coef_in;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase <= RUNNING;
                        started_seen <= 1'b1;
                        cnt <= 16'd0;
                        s1 <= 16'sd0;
                        s2 <= 16'sd0;
                    end
                end
                RUNNING: begin
                    s1 <= s1_next;
                    s2 <= s1;
                    if (cnt == 16'd23) begin
                        phase <= DONE;
                        done <= 1'b1;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                DONE: begin
                    if (b_ready) begin
                        phase <= IDLE;
                        done <= 1'b0;
                    end
                end
            endcase
            if (clr) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                before_clr <= 1'b0;
            end
        end
    end

    always @(*) assert (!before_clr || !done || (started_seen && armed_seen));
endmodule

module kaze_gust_meter (
    input wire clk,
    input wire rst,
    input wire en,
    input wire inc,
    input wire q_open,
    input wire r_close,
    output wire calm,
    output wire storm
);
    reg [63:0] b;
    reg [63:0] g;
    reg        win;
    initial b = 64'd0;
    initial g = 64'd0;
    initial win = 1'b0;

    wire [63:0] b_nxt = b + 64'd1;

    always @(posedge clk) begin
        if (rst) begin
            b   <= 64'd0;
            g   <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (inc) begin
                b <= b_nxt;
                g <= b_nxt ^ (b_nxt >> 1);
            end
            win <= q_open ? 1'b1 : (r_close ? 1'b0 : win);
        end
    end

    // stateless prefix-XOR Gray-to-binary network, MSB down
    wire [63:0] conv;
    assign conv[63] = g[63];
    genvar i;
    generate
        for (i = 62; i >= 0; i = i - 1) begin : g2b
            assign conv[i] = conv[i+1] ^ g[i];
        end
    endgenerate

    assign calm  = (b == 64'd0);
    assign storm = (conv == 64'hFFFF_FFFF_FFFF_FFFF);

    always @(posedge clk)
        if (win) assert (!((b == 64'd0) && (conv == 64'hFFFF_FFFF_FFFF_FFFF)));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module camsi_line_energy_acc (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sol,
    input wire [31:0] px,
    output wire [31:0] o_energy,
    output wire o_sat
);
    localparam [31:0] LIMIT = 32'h00FF_FFFF;

    reg [31:0] acc;
    reg [31:0] headroom;
    reg        sat_flag;
    initial acc = 32'd0;
    initial headroom = LIMIT;
    initial sat_flag = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            acc      <= 32'd0;
            headroom <= LIMIT;
            sat_flag <= 1'b0;
        end else if (en) begin
            if (sol) begin
                acc      <= 32'd0;
                headroom <= LIMIT;
                sat_flag <= 1'b0;
            end else if (px > headroom) begin
                acc      <= LIMIT;
                headroom <= 32'd0;
                sat_flag <= 1'b1;
            end else begin
                acc      <= acc + px;
                headroom <= headroom - px;
            end
        end
    end

    assign o_energy = acc;
    assign o_sat = sat_flag;

    always @(posedge clk)
        if (!sat_flag) assert (acc <= LIMIT);
endmodule

module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
endmodule

module tta_loop_fu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [31:0] bus,
    input wire tick,
    output reg [31:0] cnt,
    output reg [31:0] rem
);
    localparam [31:0] LIMIT = 32'd1000;

    initial cnt = 32'd0;
    initial rem = LIMIT;

    wire [31:0] v = (bus > LIMIT) ? LIMIT : bus;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                cnt <= 32'd0;
                rem <= LIMIT;
            end else if (load) begin
                cnt <= v;
                rem <= LIMIT - v;
            end else if (tick && rem != 32'd0) begin
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
            end
        end
    end

    always @(*) assert (cnt <= 32'd1000);
endmodule

module pmod_simd_div (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       req,
    input  wire       req_mode,
    input  wire [7:0] dividend,
    input  wire [7:0] divisor,
    input  wire       cfg_wr,
    output reg        resp_valid,
    output wire [7:0] quotient,
    output wire [7:0] remainder,
    output wire       busy_o
);
    reg       busy = 1'b0;
    reg       mode = 1'b0;
    reg [7:0] prem = 8'd0;
    reg [7:0] dvs  = 8'd0;
    reg [7:0] quo  = 8'd0;
    reg [7:0] cnt  = 8'd0;
    reg [7:0] dl   = 8'd0;
    reg       pre  = 1'b1;
    initial resp_valid = 1'b0;

    assign quotient  = quo;
    assign remainder = prem;
    assign busy_o    = busy;

    wire [7:0] w_cur = mode     ? 8'd4 : 8'd8;
    wire [7:0] w_req = req_mode ? 8'd4 : 8'd8;
    wire       last  = (cnt == (w_cur - 8'd1));

    // 8-bit lane
    wire [8:0] r8  = {prem, quo[7]};
    wire       ge8 = (r8 >= {1'b0, dvs});
    wire [8:0] s8  = r8 - {1'b0, dvs};

    // two 4-bit lanes
    wire [4:0] rlo  = {prem[3:0], quo[3]};
    wire       gelo = (rlo >= {1'b0, dvs[3:0]});
    wire [4:0] slo  = rlo - {1'b0, dvs[3:0]};
    wire [4:0] rhi  = {prem[7:4], quo[7]};
    wire       gehi = (rhi >= {1'b0, dvs[7:4]});
    wire [4:0] shi  = rhi - {1'b0, dvs[7:4]};

    wire [7:0] prem_n = mode ? {(gehi ? shi[3:0] : rhi[3:0]), (gelo ? slo[3:0] : rlo[3:0])}
                             : (ge8 ? s8[7:0] : r8[7:0]);
    wire [7:0] quo_n  = mode ? {quo[6:4], gehi, quo[2:0], gelo}
                             : {quo[6:0], ge8};

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                busy <= 1'b0;
                cnt  <= 8'd0;
                dl   <= 8'd0;
                mode <= 1'b0;
                pre  <= 1'b1;
                resp_valid <= 1'b0;
            end else begin
                resp_valid <= 1'b0;
                if (!busy) begin
                    if (cfg_wr)
                        pre <= 1'b0;
                    if (req) begin
                        prem <= 8'd0;
                        quo  <= dividend;
                        dvs  <= divisor;
                        mode <= req_mode;
                        cnt  <= 8'd0;
                        dl   <= w_req;
                        busy <= 1'b1;
                    end
                end else begin
                    prem <= prem_n;
                    quo  <= quo_n;
                    cnt  <= cnt + 8'd1;
                    dl   <= dl - 8'd1;
                    if (last) begin
                        busy <= 1'b0;
                        resp_valid <= 1'b1;
                    end
                end
            end
        end
    end

    // A1: countdown never expires while an operation is outstanding
    always @(*)
        if (pre && busy)
            assert (dl != 8'd0);

    // A2: deadline and completion coincide
    always @(*)
        if (pre && busy && dl == 8'd1)
            assert (cnt == (mode ? 8'd3 : 8'd7));
endmodule

module acc_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        load,
    input  wire        shift,
    input  wire [63:0] din,
    output wire [63:0] norm_out,
    output wire [6:0]  exp_adj,
    output wire        done
);
    function [6:0] lzc_tree;
        input [63:0] x;
        reg [31:0] y32;
        reg [15:0] y16;
        reg [7:0]  y8;
        reg [3:0]  y4;
        reg [1:0]  y2;
        reg b5, b4, b3, b2, b1, b0;
        begin
            b5  = ~|x[63:32];
            y32 = b5 ? x[31:0] : x[63:32];
            b4  = ~|y32[31:16];
            y16 = b4 ? y32[15:0] : y32[31:16];
            b3  = ~|y16[15:8];
            y8  = b3 ? y16[7:0] : y16[15:8];
            b2  = ~|y8[7:4];
            y4  = b2 ? y8[3:0] : y8[7:4];
            b1  = ~|y4[3:2];
            y2  = b1 ? y4[1:0] : y4[3:2];
            b0  = ~y2[1];
            if (x == 64'd0)
                lzc_tree = 7'd64;
            else
                lzc_tree = {1'b0, b5, b4, b3, b2, b1, b0};
        end
    endfunction

    reg [63:0] data_r;
    reg [6:0]  lz_r;
    reg        armed_r;
    initial data_r  = 64'd0;
    initial lz_r    = 7'd64;
    initial armed_r = 1'b0;

    wire [6:0] lzc_din = lzc_tree(din);
    wire [6:0] lzc_cur = lzc_tree(data_r);

    always @(posedge clk) begin
        if (rst) begin
            data_r  <= 64'd0;
            lz_r    <= 7'd64;
            armed_r <= 1'b0;
        end else if (en) begin
            if (load) begin
                data_r  <= din;
                lz_r    <= lzc_din;
                armed_r <= 1'b1;
            end else if (shift && lz_r != 7'd0 && lz_r != 7'd64) begin
                data_r <= {data_r[62:0], 1'b0};
                lz_r   <= lz_r - 7'd1;
            end
        end
    end

    assign norm_out = data_r;
    assign exp_adj  = lz_r;
    assign done     = (lz_r == 7'd0);

    always @(*) if (armed_r) assert (!(done && !data_r[63]));
    always @(*) if (armed_r) assert (!(data_r[63] && lz_r != 7'd0));
endmodule

module kv_vault (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        wr_en,
    input  wire [2:0]  wr_slot,
    input  wire [63:0] wr_key,
    input  wire        perm_set,
    input  wire [2:0]  perm_slot,
    input  wire        lock_req,
    input  wire [2:0]  lock_slot,
    input  wire        use_req,
    input  wire [2:0]  use_slot,
    output reg  [63:0] cipher_key,
    output reg         use_gnt
);
    reg [511:0] key;
    reg [7:0]   perm;
    reg [7:0]   lock;
    reg [63:0]  use_cnt;
    reg         armed;

    initial key        = 512'd0;
    initial perm       = 8'd0;
    initial lock       = 8'd0;
    initial use_cnt    = 64'd0;
    initial armed      = 1'b0;
    initial cipher_key = 64'd0;
    initial use_gnt    = 1'b0;

    wire grant = use_req && perm[use_slot] && lock[use_slot];

    always @(posedge clk) begin
        if (!rst_n) begin
            key        <= 512'd0;
            perm       <= 8'd0;
            lock       <= 8'd0;
            use_cnt    <= 64'd0;
            armed      <= 1'b0;
            cipher_key <= 64'd0;
            use_gnt    <= 1'b0;
        end else if (en) begin
            if (wr_en && !lock[wr_slot])
                key[{wr_slot, 6'd0} +: 64] <= wr_key;
            if (perm_set && !lock[perm_slot])
                perm[perm_slot] <= 1'b1;
            if (lock_req) begin
                lock[lock_slot] <= 1'b1;
                if (lock_slot == 3'd0)
                    armed <= 1'b1;
            end
            use_gnt <= grant;
            if (grant) begin
                cipher_key <= key[{use_slot, 6'd0} +: 64];
                use_cnt    <= use_cnt + 64'd1;
            end else begin
                cipher_key <= 64'd0;
            end
        end
    end

    wire [63:0] key0 = key[63:0];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $past(armed) && $stable(use_cnt))
            assert ($stable(key0));
endmodule

module darki2s_tx (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] smp_l,
    input wire [63:0] smp_r,
    input wire start,
    input wire stop,
    output wire sd,
    output wire o_ws
);
    localparam [63:0] SLOT_END = 64'd63;
    reg [63:0] sh_l, sh_r, bit_cnt;
    reg ws, own_l, own_r, win;
    initial begin
        sh_l = 64'd0; sh_r = 64'd0; bit_cnt = 64'd0;
        ws = 1'b0; own_l = 1'b1; own_r = 1'b0; win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            sh_l <= 64'd0;
            sh_r <= 64'd0;
            bit_cnt <= 64'd0;
            ws <= 1'b0;
            own_l <= 1'b1;
            own_r <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            win <= start ? 1'b1 : (stop ? 1'b0 : win);
            if (bit_cnt == SLOT_END) begin
                bit_cnt <= 64'd0;
                ws <= ~ws;
                own_l <= own_r;
                own_r <= ~ws;
                if (~ws) begin
                    sh_r <= smp_r;
                    if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                end else begin
                    sh_l <= smp_l;
                    if (own_r) sh_r <= {sh_r[62:0], 1'b0};
                end
            end else begin
                bit_cnt <= bit_cnt + 64'd1;
                if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                if (own_r) sh_r <= {sh_r[62:0], 1'b0};
            end
        end
    end

    assign sd = ws ? sh_r[63] : sh_l[63];
    assign o_ws = ws;

    always @(posedge clk)
        if (win)
            assert (!(own_l && own_r));
endmodule

module lim_mod_fold (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire vld,
    input wire [63:0] chunk,
    output wire [15:0] res,
    output wire done
);
    localparam [63:0] M = 64'd65521;

    function [63:0] two64;
        input [31:0] dummy;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < 64; i = i + 1)
                r = (r * 64'd2) % M;
            two64 = r;
        end
    endfunction

    localparam [63:0] K = two64(0);

    function [63:0] kpow;
        input [31:0] n;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < n; i = i + 1)
                r = (r * K) % M;
            kpow = r;
        end
    endfunction

    localparam [63:0] C = kpow(256);

    reg [63:0] acc;
    reg [63:0] wreg;
    reg [8:0]  idx;
    reg        armed;
    initial acc = 64'd0;
    initial wreg = 64'd1;
    initial idx = 9'd0;
    initial armed = 1'b0;

    wire [64*257-1:0] wflat;
    genvar g;
    generate
        for (g = 0; g < 257; g = g + 1) begin : G_ROM
            localparam [63:0] WV = kpow(g);
            assign wflat[g*64 +: 64] = WV;
        end
    endgenerate

    wire [63:0] wexp = wflat[idx*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            acc   <= 64'd0;
            wreg  <= 64'd1;
            idx   <= 9'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (start) begin
                acc   <= 64'd0;
                wreg  <= 64'd1;
                idx   <= 9'd0;
                armed <= 1'b1;
            end else if (vld && (idx < 9'd256)) begin
                acc  <= (acc + (chunk % M) * wreg) % M;
                wreg <= (wreg * K) % M;
                idx  <= idx + 9'd1;
            end
        end
    end

    assign res  = acc[15:0];
    assign done = (idx == 9'd256);

    always @(posedge clk)
        if (armed && idx == 9'd256)
            assert (wreg == C);
endmodule

module docker_cfg_shadow (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire wr,
    input wire [5:0] waddr,
    input wire [7:0] wdata,
    input wire commit,
    input wire [5:0] raddr,
    output wire [7:0] rdata
);
    reg [7:0] shadow [0:63];
    reg [7:0] active [0:63];
    reg [7:0] wr_cnt;
    reg [7:0] act_gen;
    reg armed;
    reg pre_commit;
    integer i;

    initial begin
        wr_cnt = 8'h00;
        act_gen = 8'h00;
        armed = 1'b0;
        pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            shadow[i] = 8'h00;
            active[i] = 8'h00;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_cnt <= 8'h00;
            act_gen <= 8'h00;
            armed <= 1'b0;
            pre_commit <= 1'b1;
            for (i = 0; i < 64; i = i + 1) begin
                shadow[i] <= 8'h00;
                active[i] <= 8'h00;
            end
        end else if (en) begin
            if (wr) begin
                shadow[waddr] <= wdata;
                wr_cnt <= wr_cnt + 8'h01;
            end
            if (armed) begin
                for (i = 0; i < 64; i = i + 1)
                    active[i] <= shadow[i];
                act_gen <= act_gen + 8'h01;
            end
            armed <= commit;
            if (commit)
                pre_commit <= 1'b0;
        end
    end

    assign rdata = active[raddr];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && $past(rst_n) && pre_commit && $stable(wr_cnt))
            assert ($stable(act_gen));
endmodule

module polar_sc_result_dec (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire abort,
    input wire wr,
    input wire [2:0] wr_addr,
    input wire [127:0] llr_in,
    output wire [7:0] o_result,
    output wire o_done
);
    localparam [7:0] FROZEN = 8'b0001_0111;
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, DECODE = 2'd2, DONE = 2'd3;

    reg [127:0] llr_mem [0:7];
    reg [7:0] ps;
    reg [7:0] dec;
    reg [2:0] leaf_idx;
    reg [1:0] phase;
    reg armed_seen;
    reg started_seen;
    reg pre_abort;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) llr_mem[i] = 128'd0;
        ps = 8'd0;
        dec = 8'd0;
        leaf_idx = 3'd0;
        phase = IDLE;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        pre_abort = 1'b1;
    end

    wire [127:0] cur_word = llr_mem[leaf_idx];
    wire [7:0] la = cur_word[7:0];
    wire [7:0] lb = cur_word[15:8];
    wire [6:0] min_mag = (la[6:0] < lb[6:0]) ? la[6:0] : lb[6:0];
    wire [7:0] f_llr = {la[7] ^ lb[7], min_mag};
    wire [2:0] prev_idx = leaf_idx - 3'd1;
    wire u_prev = ps[prev_idx];
    wire [7:0] g_llr = u_prev ? (lb - la) : (lb + la);
    wire [7:0] leaf_llr = leaf_idx[0] ? g_llr : f_llr;
    wire bit_hat = FROZEN[leaf_idx] ? 1'b0 : leaf_llr[7];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_abort <= 1'b1;
            leaf_idx <= 3'd0;
            ps <= 8'd0;
            dec <= 8'd0;
        end else if (en) begin
            if (wr && phase != DECODE)
                llr_mem[wr_addr] <= llr_in;
            if (abort) begin
                phase <= IDLE;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            phase <= ARMED;
                            armed_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            phase <= DECODE;
                            started_seen <= 1'b1;
                            leaf_idx <= 3'd0;
                            ps <= 8'd0;
                        end
                    end
                    DECODE: begin
                        dec[leaf_idx] <= bit_hat;
                        ps[leaf_idx] <= bit_hat;
                        llr_mem[leaf_idx] <= {cur_word[127:16], f_llr, g_llr};
                        leaf_idx <= leaf_idx + 3'd1;
                        if (leaf_idx == 3'd7)
                            phase <= DONE;
                    end
                    DONE: begin
                        if (arm) begin
                            phase <= ARMED;
                            started_seen <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_result = dec;
    assign o_done = (phase == DONE);

    always @(posedge clk)
        if (pre_abort && phase == 2'd3)
            assert (started_seen && armed_seen);
endmodule

module jls_remap_lut (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_v,
    input wire [63:0] wdata,
    input wire new_frame,
    input wire pix_v,
    input wire [4:0] pix_idx,
    output reg [63:0] out_q
);
    localparam [63:0] DEPTH = 64'd24;
    localparam [63:0] LAST  = 64'd23;

    reg [63:0] mem [0:23];
    reg [63:0] wp;
    reg full_q, empty_q, load_own, map_own, armed;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 64'd0;
        wp = 64'd0;
        full_q = 1'b0;
        empty_q = 1'b1;
        load_own = 1'b1;
        map_own = 1'b0;
        armed = 1'b0;
        out_q = 64'd0;
    end

    wire [4:0] sidx = (pix_idx > 5'd23) ? 5'd23 : pix_idx;
    wire do_wr = wr_v && load_own && (wp < DEPTH);

    always @(posedge clk) begin
        if (rst) begin
            wp <= 64'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
            load_own <= 1'b1;
            map_own <= 1'b0;
            armed <= 1'b0;
            out_q <= 64'd0;
        end else if (en) begin
            if (new_frame) begin
                wp <= 64'd0;
                empty_q <= 1'b1;
                full_q <= 1'b0;
                load_own <= 1'b1;
                map_own <= 1'b0;
            end else if (do_wr) begin
                mem[wp[4:0]] <= wdata;
                wp <= wp + 64'd1;
                empty_q <= empty_q && (wp != 64'd0);
                full_q <= full_q || (wp == LAST);
                load_own <= load_own && (wp != LAST);
                map_own <= map_own || (wp == LAST);
                if (wp == LAST) armed <= 1'b1;
            end
            if (pix_v && map_own)
                out_q <= mem[sidx];
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!(full_q && empty_q));

    always @(posedge clk)
        if (armed)
            assert (!(load_own && map_own));
endmodule

module croc_wm_fifo (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        push,
    input  wire        pop,
    input  wire [63:0] wdata,
    input  wire        cfg_we,
    input  wire [63:0] cfg_af,
    input  wire [63:0] cfg_ae,
    input  wire        arm,
    input  wire        disarm,
    output wire [63:0] rdata,
    output wire        full,
    output wire        empty,
    output wire        afull,
    output wire        aempty
);
    reg [63:0] mem [0:15];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [63:0] count = 64'd0;
    reg [63:0] af_thr = 64'd14;
    reg [63:0] ae_thr = 64'd2;
    reg        full_q = 1'b0;
    reg        empty_q = 1'b1;
    reg        afull_q = 1'b0;
    reg        aempty_q = 1'b1;
    reg        win_q = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 64'd0;
    end

    wire do_push = push && !full_q;
    wire do_pop  = pop  && !empty_q;

    assign rdata  = mem[rptr];
    assign full   = full_q;
    assign empty  = empty_q;
    assign afull  = afull_q;
    assign aempty = aempty_q;

    always @(posedge clk) begin
        if (!rst_n) begin
            wptr     <= 4'd0;
            rptr     <= 4'd0;
            count    <= 64'd0;
            af_thr   <= 64'd14;
            ae_thr   <= 64'd2;
            full_q   <= 1'b0;
            empty_q  <= 1'b1;
            afull_q  <= 1'b0;
            aempty_q <= 1'b1;
            win_q    <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                af_thr <= cfg_af;
                ae_thr <= cfg_ae;
            end
            if (disarm)
                win_q <= 1'b0;
            else if (arm)
                win_q <= 1'b1;
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;
            if (do_push && !do_pop) begin
                count   <= count + 64'd1;
                empty_q <= 1'b0;
                if (count == 64'd15)
                    full_q <= 1'b1;
                if (count + 64'd1 == af_thr)
                    afull_q <= 1'b1;
                if (count == ae_thr)
                    aempty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 64'd1;
                if (count == 64'd1)
                    empty_q <= 1'b1;
                if (count == 64'd16)
                    full_q <= 1'b0;
                if (count == af_thr)
                    afull_q <= 1'b0;
                if (count - 64'd1 == ae_thr)
                    aempty_q <= 1'b1;
            end
        end
    end

    assert property (!(win_q && full_q && empty_q));
endmodule

module udp_keccak_tagger (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_valid,
    input  wire        in_last,
    input  wire [15:0] in_data,
    input  wire        go,
    input  wire        ack,
    output wire [15:0] tag,
    output reg         done,
    output wire        busy
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [255:0] st;
    reg [3:0]   absorb_ptr;
    reg [4:0]   rnd;
    reg [1:0]   phase;
    reg         armed_flg;
    reg         started_flg;
    reg         seen_q;
    reg         done_q;

    initial begin
        st = 256'd0;
        absorb_ptr = 4'd0;
        rnd = 5'd0;
        phase = P_IDLE;
        armed_flg = 1'b0;
        started_flg = 1'b0;
        seen_q = 1'b0;
        done = 1'b0;
        done_q = 1'b0;
    end

    function [15:0] rotl;
        input [15:0] a;
        input [3:0]  r;
        begin
            rotl = (a << r) | (a >> (5'd16 - {1'b0, r}));
        end
    endfunction

    wire [15:0] rc = (16'h1 << rnd[3:0]) ^ {11'd0, rnd} ^ 16'h8081;

    reg [63:0]  C, D;
    reg [255:0] A1, B, nxt;
    integer x, y, i;

    always @(*) begin
        C = 64'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                C[16*x +: 16] = C[16*x +: 16] ^ st[16*(x+4*y) +: 16];
        for (x = 0; x < 4; x = x + 1)
            D[16*x +: 16] = C[16*((x+3)%4) +: 16] ^ rotl(C[16*((x+1)%4) +: 16], 4'd1);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                A1[16*(x+4*y) +: 16] = st[16*(x+4*y) +: 16] ^ D[16*x +: 16];
        B = 256'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                B[16*(y+4*((x+3*y)%4)) +: 16] = rotl(A1[16*(x+4*y) +: 16], (((x+4*y)*(x+4*y+1))/2) % 16);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                nxt[16*(x+4*y) +: 16] = B[16*(x+4*y) +: 16] ^ ((~B[16*(((x+1)%4)+4*y) +: 16]) & B[16*(((x+2)%4)+4*y) +: 16]);
        nxt[15:0] = nxt[15:0] ^ rc;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            st <= 256'd0;
            absorb_ptr <= 4'd0;
            rnd <= 5'd0;
            phase <= P_IDLE;
            armed_flg <= 1'b0;
            started_flg <= 1'b0;
            seen_q <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                P_IDLE: begin
                    if (in_valid) begin
                        for (i = 0; i < 16; i = i + 1)
                            if (i == absorb_ptr)
                                st[16*i +: 16] <= st[16*i +: 16] ^ in_data;
                        if (in_last) begin
                            phase <= P_ARMED;
                            armed_flg <= 1'b1;
                            seen_q <= 1'b1;
                            absorb_ptr <= 4'd0;
                        end else begin
                            absorb_ptr <= absorb_ptr + 4'd1;
                        end
                    end
                end
                P_ARMED: begin
                    if (go) begin
                        phase <= P_RUN;
                        rnd <= 5'd0;
                        started_flg <= 1'b1;
                    end
                end
                P_RUN: begin
                    st <= nxt;
                    if (rnd == 5'd23) begin
                        phase <= P_DONE;
                        done <= 1'b1;
                    end else begin
                        rnd <= rnd + 5'd1;
                    end
                end
                P_DONE: begin
                    if (ack) begin
                        phase <= P_IDLE;
                        done <= 1'b0;
                        armed_flg <= 1'b0;
                        started_flg <= 1'b0;
                        st <= 256'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) done_q <= done;

    assign tag  = st[15:0];
    assign busy = (phase == P_RUN);

    reg pv;
    initial pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && seen_q && done && !done_q)
            assert (armed_flg && started_flg);
endmodule

module tlb32_ice40 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [51:0] lookup_vpn,
    input wire [7:0] lookup_asid,
    input wire fill,
    input wire [51:0] fill_vpn,
    input wire [7:0] fill_asid,
    input wire [51:0] fill_ppn,
    input wire [2:0] fill_perm,
    input wire flush_all,
    input wire flush_asid,
    input wire [7:0] asid_sel,
    output reg hit,
    output reg [51:0] ppn_out,
    output reg [2:0] perm_out
);
    reg [31:0] valid = 32'd0;
    reg [63:0] occ = 64'd0;
    reg [63:0] hits = 64'd0;
    reg [4:0] victim = 5'd0;

    reg [51:0] tag_vpn [0:31];
    reg [7:0] tag_asid [0:31];
    reg [51:0] data_ppn [0:31];
    reg [2:0] data_perm [0:31];

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            tag_vpn[i] = 52'd0;
            tag_asid[i] = 8'd0;
            data_ppn[i] = 52'd0;
            data_perm[i] = 3'd0;
        end
    end

    function [6:0] popcount32;
        input [31:0] v;
        integer k;
        begin
            popcount32 = 7'd0;
            for (k = 0; k < 32; k = k + 1)
                popcount32 = popcount32 + {6'd0, v[k]};
        end
    endfunction

    reg [31:0] asid_match;
    reg [4:0] free_idx;
    reg has_free;
    integer j;

    always @(*) begin
        asid_match = 32'd0;
        hit = 1'b0;
        ppn_out = 52'd0;
        perm_out = 3'd0;
        has_free = 1'b0;
        free_idx = 5'd0;
        for (j = 31; j >= 0; j = j - 1) begin
            if (!valid[j]) begin
                has_free = 1'b1;
                free_idx = j;
            end
        end
        for (j = 0; j < 32; j = j + 1) begin
            if (valid[j] && (tag_asid[j] == asid_sel))
                asid_match[j] = 1'b1;
            if (valid[j] && !hit && (tag_vpn[j] == lookup_vpn) && (tag_asid[j] == lookup_asid)) begin
                hit = 1'b1;
                ppn_out = data_ppn[j];
                perm_out = data_perm[j];
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= 32'd0;
            occ <= 64'd0;
            hits <= 64'd0;
            victim <= 5'd0;
        end else if (en) begin
            if (flush_all) begin
                valid <= 32'd0;
                occ <= 64'd0;
            end else if (flush_asid) begin
                valid <= valid & ~asid_match;
                occ <= occ - {57'd0, popcount32(asid_match)};
            end else if (fill) begin
                if (has_free) begin
                    tag_vpn[free_idx] <= fill_vpn;
                    tag_asid[free_idx] <= fill_asid;
                    data_ppn[free_idx] <= fill_ppn;
                    data_perm[free_idx] <= fill_perm;
                    valid <= valid | (32'd1 << free_idx);
                    occ <= occ + 64'd1;
                end else begin
                    tag_vpn[victim] <= fill_vpn;
                    tag_asid[victim] <= fill_asid;
                    data_ppn[victim] <= fill_ppn;
                    data_perm[victim] <= fill_perm;
                    victim <= victim + 5'd1;
                end
            end
            if (hit)
                hits <= hits + 64'd1;
        end
    end

    assert property (occ <= 64'd32);
endmodule

module spi_snoop_filter (
    input wire clk,
    input wire en,
    input wire sclk_rise,
    input wire mosi,
    output wire [4:0] o_occ
);
    reg [15:0] sr;
    reg [3:0]  bitcnt;
    reg [15:0] pvec [0:15];
    reg [4:0]  occ_cnt;
    reg        armed;

    integer k;
    initial begin
        sr = 16'd0;
        bitcnt = 4'd0;
        occ_cnt = 5'd0;
        armed = 1'b0;
        for (k = 0; k < 16; k = k + 1)
            pvec[k] = 16'd0;
    end

    wire [15:0] w   = {sr[14:0], mosi};
    wire [1:0]  op  = w[15:14];
    wire [3:0]  idx = w[13:10];
    wire [3:0]  cid = w[9:6];
    wire [15:0] cur = pvec[idx];
    wire [15:0] cmask = 16'd1 << cid;
    wire [15:0] set_v = cur | cmask;
    wire [15:0] clr_v = cur & ~cmask;

    always @(posedge clk) begin
        if (en && sclk_rise) begin
            sr <= w;
            bitcnt <= bitcnt + 4'd1;
            if (bitcnt == 4'd15) begin
                case (op)
                    2'b01: begin
                        pvec[idx] <= set_v;
                        if (cur == 16'd0)
                            occ_cnt <= occ_cnt + 5'd1;
                    end
                    2'b10: begin
                        pvec[idx] <= clr_v;
                        if (cur != 16'd0 && clr_v == 16'd0)
                            occ_cnt <= occ_cnt - 5'd1;
                    end
                    2'b11: begin
                        pvec[idx] <= 16'd0;
                        if (cur != 16'd0) begin
                            occ_cnt <= occ_cnt - 5'd1;
                            armed <= 1'b1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_occ = occ_cnt;

    always @(posedge clk)
        if (armed)
            assert (occ_cnt <= 5'd16);
endmodule

module stepper_seq (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_arm,
    input wire i_start,
    input wire [7:0] i_rate,
    input wire i_wr,
    input wire [2:0] i_waddr,
    input wire [127:0] i_wdata,
    output wire [127:0] o_coil,
    output wire o_done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0] fsm = S_IDLE;
    reg win = 1'b0;
    reg arm_seen = 1'b0;
    reg start_seen = 1'b0;
    reg [2:0] phase = 3'd0;
    reg [7:0] div = 8'd0;
    reg [7:0] rate = 8'd0;

    reg [127:0] pat [0:7];
    integer k;
    initial for (k = 0; k < 8; k = k + 1) pat[k] = 128'd1 << (k * 16);

    always @(posedge clk)
        if (i_ce && i_wr && !win)
            pat[i_waddr] <= i_wdata;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!win) begin
                if (i_open) begin
                    win <= 1'b1;
                    fsm <= S_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    phase <= 3'd0;
                    div <= 8'd0;
                end
            end else if (i_close) begin
                win <= 1'b0;
            end else begin
                case (fsm)
                    S_IDLE: if (i_arm) begin
                        fsm <= S_ARMED;
                        arm_seen <= 1'b1;
                        rate <= i_rate;
                    end
                    S_ARMED: if (i_start) begin
                        fsm <= S_RUN;
                        start_seen <= 1'b1;
                        div <= 8'd0;
                    end
                    S_RUN: begin
                        if (div == rate) begin
                            div <= 8'd0;
                            phase <= phase + 3'd1;
                            if (phase == 3'd7)
                                fsm <= S_DONE;
                        end else begin
                            div <= div + 8'd1;
                        end
                    end
                    default: if (i_arm) begin
                        fsm <= S_ARMED;
                        start_seen <= 1'b0;
                        rate <= i_rate;
                    end
                endcase
            end
        end
    end

    assign o_coil = pat[phase];
    assign o_done = (fsm == S_DONE);

    always @(*) if (win && fsm == S_DONE) assert (start_seen);
    always @(*) if (win && start_seen) assert (arm_seen);
endmodule

module range_mask_insert (
    input  wire        clk,
    input  wire        req,
    input  wire        ce,
    input  wire [4:0]  i_start,
    input  wire [4:0]  i_end,
    input  wire [31:0] i_src,
    output wire [31:0] mask,
    output reg  [31:0] dst,
    output reg         busy
);
    reg [4:0]  start_idx = 5'd0;
    reg [4:0]  end_idx   = 5'd0;
    reg [4:0]  cur       = 5'd0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] src       = 32'd0;
    reg        arm       = 1'b0;
    initial busy = 1'b0;
    initial dst  = 32'd0;

    // contiguous range mask decoder: bits start_idx..end_idx asserted
    assign mask = (32'hFFFFFFFF << start_idx) & (32'hFFFFFFFF >> (5'd31 - end_idx));

    wire [4:0] off = cur - start_idx;

    always @(posedge clk) begin
        if (!busy) begin
            if (req && (i_start <= i_end)) begin
                start_idx <= i_start;
                end_idx   <= i_end;
                cur       <= i_start;
                src       <= i_src;
                busy      <= 1'b1;
                timer     <= 32'd32;
                arm       <= 1'b1;
            end
        end else if (ce) begin
            dst[cur] <= src[off];
            timer    <= timer - 32'd1;
            if (cur == end_idx)
                busy <= 1'b0;
            else
                cur <= cur + 5'd1;
        end
    end

    always @(*) assert (!arm || !busy || (timer != 32'd0));
endmodule

module nan_canon_log (
    input wire clk,
    input wire i_ce,
    input wire [15:0] i_a,
    input wire [15:0] i_b,
    input wire i_canon,
    input wire i_pop,
    output wire [15:0] o_result,
    output wire o_invalid,
    output wire [15:0] o_log_head,
    output wire [15:0] o_occ
);
    localparam [15:0] QNAN_CANON = 16'h7E00;
    localparam [15:0] QUIET_BIT  = 16'h0200;

    // half-precision NaN classification
    wire a_nan  = (i_a[14:10] == 5'h1f) && (i_a[9:0] != 10'd0);
    wire b_nan  = (i_b[14:10] == 5'h1f) && (i_b[9:0] != 10'd0);
    wire a_snan = a_nan && !i_a[9];
    wire b_snan = b_nan && !i_b[9];
    wire any_nan = a_nan | b_nan;

    // NaN selection / quieting / canonicalization
    reg [15:0] sel;
    always @(*) begin
        if (i_canon)     sel = QNAN_CANON;
        else if (a_snan) sel = i_a | QUIET_BIT;
        else if (b_snan) sel = i_b | QUIET_BIT;
        else if (a_nan)  sel = i_a;
        else             sel = i_b;
    end
    wire [15:0] nxt = any_nan ? sel : i_a;

    reg [15:0] r_result = 16'd0;
    reg        r_invalid = 1'b0;
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [15:0] occ  = 16'd0;
    reg [15:0] log_mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) log_mem[i] = 16'd0;
    end

    wire [3:0] fill  = wptr - rptr;
    wire full  = (fill == 4'd8);
    wire empty = (fill == 4'd0);
    wire push_ok = i_ce && any_nan && !full;
    wire pop_ok  = i_pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            r_result  <= nxt;
            r_invalid <= a_snan | b_snan;
        end
        if (push_ok) begin
            log_mem[wptr[2:0]] <= sel;
            wptr <= wptr + 4'd1;
        end
        if (pop_ok)
            rptr <= rptr + 4'd1;
        case ({push_ok, pop_ok})
            2'b10: occ <= occ + 16'd1;
            2'b01: occ <= occ - 16'd1;
            default: ;
        endcase
    end

    assign o_result   = r_result;
    assign o_invalid  = r_invalid;
    assign o_log_head = log_mem[rptr[2:0]];
    assign o_occ      = occ;

    always @(posedge clk) assert (occ <= 16'd8);
endmodule

module trivium_core (
    input  wire        clk,
    input  wire        ce,
    input  wire        load,
    input  wire        zeroize,
    input  wire [79:0] key,
    input  wire [79:0] iv,
    output wire        ks_bit,
    output wire        ks_valid,
    output reg         ready
);
    reg [287:0] s = 288'd0;
    reg [63:0]  wcnt = 64'd0;
    reg         busy = 1'b0;
    reg         seen_load = 1'b0;
    reg         armed = 1'b1;
    reg         pv = 1'b0;
    initial ready = 1'b0;

    wire t1a = s[65]  ^ s[92];
    wire t2a = s[161] ^ s[176];
    wire t3a = s[242] ^ s[287];
    wire z   = t1a ^ t2a ^ t3a;
    wire t1  = t1a ^ (s[90]  & s[91])  ^ s[170];
    wire t2  = t2a ^ (s[174] & s[175]) ^ s[263];
    wire t3  = t3a ^ (s[285] & s[286]) ^ s[68];

    wire [287:0] nxt  = {s[286:177], t2, s[175:93], t1, s[91:0], t3};
    wire [287:0] init = {3'b111, 108'd0, 4'd0, iv, 13'd0, key};

    assign ks_bit   = z;
    assign ks_valid = ready && ce && !load && !zeroize;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (zeroize) begin
            s         <= 288'd0;
            wcnt      <= 64'd0;
            busy      <= 1'b0;
            ready     <= 1'b0;
            seen_load <= 1'b0;
            armed     <= 1'b0;
        end else if (ce) begin
            if (load) begin
                s         <= init;
                wcnt      <= 64'd0;
                busy      <= 1'b1;
                ready     <= 1'b0;
                seen_load <= 1'b1;
            end else if (busy) begin
                s <= nxt;
                if (wcnt == 64'd1151) begin
                    busy  <= 1'b0;
                    ready <= 1'b1;
                    wcnt  <= 64'd0;
                end else begin
                    wcnt <= wcnt + 64'd1;
                end
            end else if (ready) begin
                s <= nxt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(ready))
            assert (seen_load);
endmodule

module mutex_arb (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire req_a,
    input wire req_b,
    input wire rel,
    input wire w_open,
    input wire w_close,
    output wire o_own_a,
    output wire o_own_b,
    output wire [31:0] o_grants
);
    localparam [1:0] IDLE = 2'd0, ARM = 2'd1, START = 2'd2, FIN = 2'd3;

    reg [1:0] phase;
    reg latch_a, latch_b;
    reg sync_a, sync_b;
    reg own_a, own_b;
    reg win;
    reg [31:0] n_grants;

    initial phase = IDLE;
    initial latch_a = 1'b0;
    initial latch_b = 1'b0;
    initial sync_a = 1'b0;
    initial sync_b = 1'b0;
    initial own_a = 1'b0;
    initial own_b = 1'b0;
    initial win = 1'b0;
    initial n_grants = 32'd0;

    // cross-coupled set terms: each side inhibited by the other, A wins ties
    wire set_a = req_a & ~latch_b;
    wire set_b = req_b & ~latch_a & ~set_a;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            latch_a <= 1'b0;
            latch_b <= 1'b0;
            sync_a <= 1'b0;
            sync_b <= 1'b0;
            own_a <= 1'b0;
            own_b <= 1'b0;
            win <= 1'b0;
            n_grants <= 32'd0;
        end else if (i_ce) begin
            if (w_open)
                win <= 1'b1;
            else if (w_close)
                win <= 1'b0;
            case (phase)
                IDLE: begin
                    if (set_a | set_b) begin
                        latch_a <= latch_a | set_a;
                        latch_b <= latch_b | set_b;
                        phase <= ARM;
                    end
                end
                ARM: begin
                    sync_a <= latch_a;
                    sync_b <= latch_b;
                    phase <= START;
                end
                START: begin
                    own_a <= sync_a;
                    own_b <= sync_b;
                    n_grants <= n_grants + 32'd1;
                    phase <= FIN;
                end
                FIN: begin
                    if (rel) begin
                        latch_a <= 1'b0;
                        latch_b <= 1'b0;
                        sync_a <= 1'b0;
                        sync_b <= 1'b0;
                        own_a <= 1'b0;
                        own_b <= 1'b0;
                        phase <= IDLE;
                    end
                end
            endcase
        end
    end

    assign o_own_a = own_a;
    assign o_own_b = own_b;
    assign o_grants = n_grants;

    // Chain precedence inside the window: ownership (finish) only with filter (start) and latch (arm)
    assert property (!win || ((!own_a || (sync_a && latch_a)) && (!own_b || (sync_b && latch_b))));
endmodule

module ifu_align_buf (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_rvalid,
    input  wire [127:0] i_rdata,
    input  wire         i_pop,
    output wire         o_req,
    output wire [31:0]  o_fetch_addr,
    output wire         o_valid,
    output wire [127:0] o_line,
    output wire [31:0]  o_pc
);
    reg [127:0] abuf [0:7];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [3:0]  count = 4'd0;
    reg [31:0] fetch_ptr = 32'd0;
    reg [31:0] head_pc = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            abuf[i] = 128'd0;
    end

    wire [3:0] occ   = wptr - rptr;
    wire       full  = (occ == 4'd8);
    wire       empty = (occ == 4'd0);
    wire push_ok = i_ce && i_rvalid && !full;
    wire pop_ok  = i_ce && i_pop && !empty;

    always @(posedge clk) begin
        if (push_ok) begin
            abuf[wptr[2:0]] <= i_rdata;
            wptr            <= wptr + 4'd1;
            fetch_ptr       <= fetch_ptr + 32'd16;
        end
        if (pop_ok) begin
            rptr    <= rptr + 4'd1;
            head_pc <= head_pc + 32'd16;
        end
        case ({push_ok, pop_ok})
            2'b10:   count <= count + 4'd1;
            2'b01:   count <= count - 4'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (push_ok)
            armed <= 1'b1;

    always @(posedge clk)
        pv <= 1'b1;

    assign o_req        = !full;
    assign o_fetch_addr = fetch_ptr;
    assign o_valid      = !empty;
    assign o_line       = abuf[rptr[2:0]];
    assign o_pc         = head_pc;

    always @(posedge clk)
        if (armed && pv && $stable(rptr))
            assert ($stable(head_pc) && (count <= 4'd8));
endmodule

module doorbell_sweep (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        ring,
    input  wire [5:0]  ring_ch,
    input  wire        ext,
    output reg         busy,
    output reg  [7:0]  svc_cnt,
    output reg  [47:0] pending
);
    reg [5:0] idx;
    reg [7:0] deadline;
    reg       armed;
    reg       pv;
    initial begin
        pending  = 48'd0;
        busy     = 1'b0;
        idx      = 6'd0;
        deadline = 8'd0;
        armed    = 1'b1;
        svc_cnt  = 8'd0;
        pv       = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (ext) armed <= 1'b0;
            if (busy) begin
                if (pending[idx]) svc_cnt <= svc_cnt + 8'd1;
                pending[idx] <= 1'b0;
                deadline <= deadline - 8'd1 + (ext ? 8'd16 : 8'd0);
                if (idx == 6'd47) begin
                    busy <= 1'b0;
                    idx  <= 6'd0;
                end else begin
                    idx <= idx + 6'd1;
                end
            end else if (pending != 48'd0) begin
                busy     <= 1'b1;
                idx      <= 6'd0;
                deadline <= 8'd48;
            end
            if (ring && (ring_ch < 6'd48)) pending[ring_ch] <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (deadline != 8'd0);

    always @(posedge clk)
        if (pv && armed && $past(i_ce) && $past(busy) && !busy)
            assert ($past(deadline) == 8'd1);
endmodule

module backoff_ctrl (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire req,
    input wire col,
    input wire [63:0] rnd,
    output wire tx_active,
    output wire busy,
    output wire [63:0] o_attempts
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_WAIT = 2'd1;
    localparam [1:0] S_TX   = 2'd2;
    localparam [63:0] MAXA    = 64'd3;
    localparam [63:0] BUDGET0 = 64'd18;

    reg [1:0]  state;
    reg        pending;
    reg [63:0] attempts;
    reg [63:0] slot;
    reg [63:0] budget;

    initial begin
        state = S_IDLE;
        pending = 1'b0;
        attempts = 64'd0;
        slot = 64'd0;
        budget = 64'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            pending <= 1'b0;
            attempts <= 64'd0;
            slot <= 64'd0;
            budget <= 64'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state <= S_TX;
                        pending <= 1'b1;
                        attempts <= 64'd0;
                        slot <= 64'd0;
                        budget <= BUDGET0;
                    end
                end
                S_WAIT: begin
                    budget <= budget - 64'd1;
                    if (slot == 64'd0)
                        state <= S_TX;
                    else
                        slot <= slot - 64'd1;
                end
                S_TX: begin
                    budget <= budget - 64'd1;
                    if (!col) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else if (attempts >= MAXA) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else begin
                        attempts <= attempts + 64'd1;
                        slot <= rnd & ((64'd1 << (attempts + 64'd1)) - 64'd1);
                        state <= S_WAIT;
                    end
                end
                default: begin
                    state <= S_IDLE;
                    pending <= 1'b0;
                end
            endcase
        end
    end

    assign tx_active = (state == S_TX);
    assign busy = pending;
    assign o_attempts = attempts;

    always @(posedge clk)
        if (pending)
            assert (budget != 64'd0);
endmodule

module dirty_track_ram (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_we,
    input  wire [1:0]   i_addr,
    input  wire [127:0] i_wdata,
    input  wire         i_clr,
    input  wire         i_clr_blk,
    input  wire         i_clr_all,
    output wire [127:0] o_rdata,
    output wire [1:0]   o_dirty,
    output wire [1:0]   o_dirty_cnt,
    output wire         o_any_dirty
);
    // 4 x 128-bit data array, organised as 2 blocks of 2 words
    reg [127:0] mem [0:3];
    reg [1:0]   dirty     = 2'b00;
    reg [1:0]   dirty_cnt = 2'd0;
    reg         any_dirty = 1'b0;

    initial begin
        mem[0] = 128'd0;
        mem[1] = 128'd0;
        mem[2] = 128'd0;
        mem[3] = 128'd0;
    end

    wire wblk = i_addr[1];

    reg [1:0] dirty_nx;
    reg [1:0] cnt_nx;
    always @(*) begin
        dirty_nx = dirty;
        cnt_nx   = dirty_cnt;
        if (i_we) begin
            dirty_nx[wblk] = 1'b1;
            if (!dirty[wblk])
                cnt_nx = dirty_cnt + 2'd1;
        end else if (i_clr_all) begin
            dirty_nx = 2'b00;
            cnt_nx   = 2'd0;
        end else if (i_clr) begin
            dirty_nx[i_clr_blk] = 1'b0;
            if (dirty[i_clr_blk])
                cnt_nx = dirty_cnt - 2'd1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_we)
                mem[i_addr] <= i_wdata;
            dirty     <= dirty_nx;
            dirty_cnt <= cnt_nx;
            any_dirty <= |dirty_nx;
        end
    end

    assign o_rdata     = mem[i_addr];
    assign o_dirty     = dirty;
    assign o_dirty_cnt = dirty_cnt;
    assign o_any_dirty = any_dirty;

    always @(*)
        assert (any_dirty == (dirty_cnt != 2'd0));
endmodule

module lz77_match_finder (
    input wire clk,
    input wire i_push,
    input wire [63:0] i_data,
    input wire i_start,
    input wire [63:0] i_look0,
    input wire [63:0] i_look1,
    input wire i_ce,
    input wire i_ack,
    input wire i_flush,
    output wire o_searching,
    output wire o_match_valid,
    output wire [63:0] o_best_len,
    output wire [63:0] o_best_pos,
    output wire [63:0] o_match_len
);
    localparam [63:0] WIN  = 64'd256;
    localparam [63:0] LAST = 64'd255;

    reg [63:0] hist [0:255];
    reg [63:0] wr_ptr    = 64'd0;
    reg [63:0] look0     = 64'd0;
    reg [63:0] look1     = 64'd0;
    reg [63:0] scan_idx  = 64'd0;
    reg [63:0] scan_left = 64'd0;
    reg [63:0] cand_pos  = 64'd0;
    reg [63:0] match_len = 64'd0;
    reg [63:0] best_len  = 64'd0;
    reg [63:0] best_pos  = 64'd0;
    reg searching   = 1'b0;
    reg match_valid = 1'b0;
    reg armed       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) hist[i] = 64'd0;
    end

    wire [7:0] c0 = cand_pos[7:0];
    wire [7:0] c1 = c0 + 8'd1;
    wire [63:0] cand_len = (hist[c0] == look0) ? ((hist[c1] == look1) ? 64'd2 : 64'd1) : 64'd0;

    always @(posedge clk) begin
        if (i_push && !searching) begin
            hist[wr_ptr[7:0]] <= i_data;
            wr_ptr <= wr_ptr + 64'd1;
        end
        if (!searching && i_start) begin
            searching   <= 1'b1;
            match_valid <= 1'b0;
            scan_idx    <= 64'd0;
            scan_left   <= WIN;
            cand_pos    <= wr_ptr;
            look0       <= i_look0;
            look1       <= i_look1;
            best_len    <= 64'd0;
            best_pos    <= 64'd0;
            match_len   <= 64'd0;
        end else if (searching && i_ce) begin
            match_len <= cand_len;
            if (cand_len > best_len) begin
                best_len <= cand_len;
                best_pos <= cand_pos;
            end
            cand_pos  <= cand_pos + 64'd1;
            scan_idx  <= scan_idx + 64'd1;
            scan_left <= scan_left - 64'd1;
            if (scan_left == 64'd1) searching <= 1'b0;
            if (scan_idx == LAST) match_valid <= 1'b1;
        end else if (!searching && i_ack) begin
            match_valid <= 1'b0;
        end
    end

    // scope window: opened by the first accepted search, closed by flush
    always @(posedge clk) begin
        if (i_flush) armed <= 1'b0;
        else if (!searching && i_start) armed <= 1'b1;
    end

    assign o_searching   = searching;
    assign o_match_valid = match_valid;
    assign o_best_len    = best_len;
    assign o_best_pos    = best_pos;
    assign o_match_len   = match_len;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(searching) && $past(match_valid)));
endmodule

module async_mem_bus_ctrl (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         req,
    input  wire         req_wr,
    input  wire [4:0]   req_cs,
    input  wire [63:0]  req_addr,
    input  wire [63:0]  req_wdata,
    input  wire [63:0]  i_rdata,
    input  wire         cfg_we,
    input  wire [4:0]   cfg_cs,
    input  wire [63:0]  cfg_setup,
    input  wire [63:0]  cfg_access,
    input  wire [63:0]  cfg_hold,
    output wire [31:0]  cs_n,
    output wire         oe_n,
    output wire         we_n,
    output wire [63:0]  addr,
    output wire [63:0]  wdata,
    output wire [63:0]  rdata,
    output wire         busy
);
    localparam [1:0] P_IDLE = 2'd0, P_SETUP = 2'd1, P_ACCESS = 2'd2, P_HOLD = 2'd3;

    reg [1:0]    phase     = P_IDLE;
    reg [63:0]   cnt       = 64'd0;
    reg          wr_lat    = 1'b0;
    reg [4:0]    cs_lat    = 5'd0;
    reg [63:0]   addr_lat  = 64'd0;
    reg [63:0]   wdata_lat = 64'd0;
    reg [63:0]   rdata_lat = 64'd0;
    reg          oe        = 1'b0;
    reg          we        = 1'b0;
    reg          armed     = 1'b0;

    // per-chip-select timing registers: 32 entries x 64 bits each
    reg [2047:0] tsetup_flat  = {32{64'd1}};
    reg [2047:0] taccess_flat = {32{64'd2}};
    reg [2047:0] thold_flat   = {32{64'd1}};

    wire [63:0] t_setup  = tsetup_flat[cs_lat*64 +: 64];
    wire [63:0] t_access = taccess_flat[cs_lat*64 +: 64];
    wire [63:0] t_hold   = thold_flat[cs_lat*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            phase  <= P_IDLE;
            cnt    <= 64'd0;
            wr_lat <= 1'b0;
            oe     <= 1'b0;
            we     <= 1'b0;
        end else if (i_ce) begin
            if (cfg_we) begin
                tsetup_flat[cfg_cs*64 +: 64]  <= cfg_setup;
                taccess_flat[cfg_cs*64 +: 64] <= cfg_access;
                thold_flat[cfg_cs*64 +: 64]   <= cfg_hold;
            end
            case (phase)
                P_IDLE: begin
                    if (req) begin
                        phase     <= P_SETUP;
                        cnt       <= 64'd0;
                        wr_lat    <= req_wr;
                        cs_lat    <= req_cs;
                        addr_lat  <= req_addr;
                        wdata_lat <= req_wdata;
                        armed     <= 1'b1;
                    end
                end
                P_SETUP: begin
                    if (cnt >= t_setup) begin
                        phase <= P_ACCESS;
                        cnt   <= 64'd0;
                        if (wr_lat) we <= 1'b1;
                        else        oe <= 1'b1;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_ACCESS: begin
                    if (cnt >= t_access) begin
                        phase <= P_HOLD;
                        cnt   <= 64'd0;
                        if (!wr_lat) rdata_lat <= i_rdata;
                        oe    <= 1'b0;
                        we    <= 1'b0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_HOLD: begin
                    if (cnt >= t_hold) begin
                        phase <= P_IDLE;
                        cnt   <= 64'd0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
            endcase
        end
    end

    assign cs_n  = (phase == P_IDLE) ? 32'hFFFFFFFF : ~(32'd1 << cs_lat);
    assign oe_n  = ~oe;
    assign we_n  = ~we;
    assign addr  = addr_lat;
    assign wdata = wdata_lat;
    assign rdata = rdata_lat;
    assign busy  = (phase != P_IDLE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Absence after first accepted transaction: OE and WE strobes never both active
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(oe) && $past(we)));
endmodule

module stream_buffer (
    input wire clk,
    input wire ce,
    input wire flush,
    input wire [31:0] miss_addr,
    input wire fill,
    input wire [31:0] fill_data,
    input wire req,
    input wire [31:0] req_addr,
    output wire hit,
    output wire [31:0] hit_data,
    output wire [31:0] hit_tag
);
    reg [31:0] head = 32'd0;
    reg [31:0] tail = 32'd0;
    reg [6:0]  count = 7'd0;
    reg [5:0]  wptr = 6'd0;
    reg [5:0]  rptr = 6'd0;
    reg [63:0] valid = 64'd0;
    reg [31:0] tag_mem  [0:63];
    reg [31:0] data_mem [0:63];
    reg [31:0] fills = 32'd0;
    reg [31:0] hits  = 32'd0;
    reg armed = 1'b1;
    reg pv = 1'b0;
    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1) begin
            tag_mem[i]  = 32'd0;
            data_mem[i] = 32'd0;
        end
    end

    wire do_fill = ce && !flush && fill && (count != 7'd64);
    wire do_hit  = ce && !flush && req && (count != 7'd0) && (req_addr == head);

    assign hit      = do_hit;
    assign hit_data = data_mem[rptr];
    assign hit_tag  = tag_mem[rptr];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                head  <= miss_addr + 32'd1;
                tail  <= miss_addr + 32'd1;
                count <= 7'd0;
                wptr  <= 6'd0;
                rptr  <= 6'd0;
                valid <= 64'd0;
                armed <= 1'b0;
            end else begin
                if (do_fill) begin
                    tag_mem[wptr]  <= tail;
                    data_mem[wptr] <= fill_data;
                    tail  <= tail + 32'd1;
                    wptr  <= wptr + 6'd1;
                    fills <= fills + 32'd1;
                end
                if (do_hit) begin
                    rptr <= rptr + 6'd1;
                    head <= head + 32'd1;
                    hits <= hits + 32'd1;
                end
                valid <= (valid | (do_fill ? (64'd1 << wptr) : 64'd0))
                         & ~(do_hit ? (64'd1 << rptr) : 64'd0);
                case ({do_fill, do_hit})
                    2'b10:   count <= count + 7'd1;
                    2'b01:   count <= count - 7'd1;
                    default: count <= count;
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(fills) && $past(fills == hits))
            assert ($stable(hits));
endmodule

module welch_spectral_avg (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [7:0]  mag,
    input  wire        dump,
    input  wire [6:0]  rd_addr,
    output wire [23:0] rd_data,
    output wire        avg_done
);
    // per-bin accumulation RAM for squared magnitudes
    reg [23:0] acc [0:127];
    reg [7:0]  bin_idx      = 8'd0;
    reg [7:0]  frame_cnt    = 8'd0;
    reg [10:0] samples_left = 11'd1024;
    reg        armed        = 1'b1;   // high until the first dump event

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1)
            acc[i] = 24'd0;
    end

    wire [15:0] sq     = mag * mag;
    wire        accept = in_valid && (!armed || samples_left != 11'd0);

    always @(posedge clk) begin
        if (dump) begin
            armed        <= 1'b0;
            bin_idx      <= 8'd0;
            frame_cnt    <= 8'd0;
            samples_left <= 11'd0;
        end else if (accept) begin
            acc[bin_idx[6:0]] <= ((frame_cnt == 8'd0) ? 24'd0 : acc[bin_idx[6:0]]) + {8'd0, sq};
            if (bin_idx == 8'd127) begin
                bin_idx   <= 8'd0;
                frame_cnt <= frame_cnt + 8'd1;
            end else begin
                bin_idx <= bin_idx + 8'd1;
            end
            if (armed)
                samples_left <= samples_left - 11'd1;
        end
    end

    // 8-frame Welch average: divide accumulated power by 8
    assign rd_data  = acc[rd_addr] >> 3;
    assign avg_done = armed && (samples_left == 11'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Before the first dump, the frame count never exceeded 8
    always @(posedge clk)
        if (pv && armed)
            assert ($past(frame_cnt) <= 8'd8);
endmodule

module ptw_walker (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire [15:0] i_va,
    input  wire [15:0] i_root,
    input  wire        i_mem_valid,
    input  wire [15:0] i_mem_data,
    input  wire        i_ack,
    output wire        o_mem_req,
    output wire [15:0] o_mem_addr,
    output wire        o_done,
    output wire        o_fault,
    output wire [15:0] o_pa
);
    localparam [1:0]  S_IDLE = 2'd0;
    localparam [1:0]  S_WALK = 2'd1;
    localparam [1:0]  S_DONE = 2'd2;
    localparam [15:0] LAST_LVL = 16'd3;

    reg [1:0]  state   = S_IDLE;
    reg [15:0] lvl     = 16'd0;
    reg [15:0] reads   = 16'd0;
    reg [15:0] desc    = 16'd0;
    reg [15:0] va      = 16'd0;
    reg [15:0] walk_id = 16'd0;
    reg        fault   = 1'b0;
    reg        armed   = 1'b0;
    reg        pv      = 1'b0;

    wire [3:0] idx = (lvl == 16'd0) ? va[15:12] :
                     (lvl == 16'd1) ? va[11:8]  :
                     (lvl == 16'd2) ? va[7:4]   : va[3:0];

    assign o_mem_req  = (state == S_WALK);
    assign o_mem_addr = {desc[15:4], idx};
    assign o_done     = (state == S_DONE);
    assign o_fault    = fault;
    assign o_pa       = {desc[15:4], va[3:0]};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            fault <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state   <= S_WALK;
                        lvl     <= 16'd0;
                        reads   <= 16'd0;
                        desc    <= i_root;
                        va      <= i_va;
                        walk_id <= walk_id + 16'd1;
                        fault   <= 1'b0;
                        armed   <= 1'b1;
                    end
                end
                S_WALK: begin
                    if (i_mem_valid) begin
                        reads <= reads + 16'd1;
                        desc  <= i_mem_data;
                        if (!i_mem_data[0] || (!i_mem_data[1] && lvl == LAST_LVL)) begin
                            fault <= 1'b1;
                            state <= S_DONE;
                        end else if (i_mem_data[1]) begin
                            state <= S_DONE;
                        end else begin
                            lvl <= lvl + 16'd1;
                        end
                    end
                end
                S_DONE: begin
                    if (i_ack) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (armed && pv && $stable(walk_id) && $past(reads) >= 16'd4)
            assert ($stable(reads));
endmodule

module lza_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_ld,
    input  wire [31:0] i_a,
    input  wire [31:0] i_b,
    output reg  [31:0] o_sum,
    output wire        o_done
);
    function [31:0] clz32;
        input [31:0] v;
        integer i;
        reg found;
        begin
            clz32 = 32'd32;
            found = 1'b0;
            for (i = 31; i >= 0; i = i - 1) begin
                if (!found && v[i]) begin
                    clz32 = 31 - i;
                    found = 1'b1;
                end
            end
        end
    endfunction

    reg [31:0] ind = 32'd0;
    reg [31:0] rem = 32'd32;
    initial o_sum = 32'd0;

    wire [31:0] t_str = i_a ^ i_b;
    wire [31:0] g_str = i_a & i_b;
    wire [31:0] f_new = t_str | g_str;

    wire [31:0] lz_of_ind = clz32(ind);
    wire busy = (rem != 32'd0) && (rem != 32'd32);

    assign o_done = (rem == 32'd0);

    always @(posedge clk) begin
        if (rst) begin
            ind   <= 32'd0;
            rem   <= 32'd32;
            o_sum <= 32'd0;
        end else if (i_ce) begin
            if (i_ld) begin
                ind   <= f_new;
                rem   <= clz32(f_new);
                o_sum <= i_a + i_b;
            end else if (busy) begin
                ind   <= ind << 1;
                rem   <= rem - 32'd1;
                o_sum <= o_sum << 1;
            end
        end
    end

    always @(posedge clk)
        if (o_done) assert (ind[31]);
endmodule

module bfi_chain (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_load,
    input wire i_abort,
    input wire [63:0] i_dest,
    input wire [63:0] i_field,
    input wire [5:0] i_off,
    input wire [6:0] i_len,
    output wire [63:0] o_result,
    output wire o_done
);
    reg [1:0] phase = 2'd0;
    reg [63:0] dest = 64'd0;
    reg [63:0] field = 64'd0;
    reg [63:0] shifted = 64'd0;
    reg [63:0] mask = 64'd0;
    reg [63:0] result = 64'd0;
    reg [5:0] off = 6'd0;
    reg [6:0] len = 7'd0;
    reg armed_seen = 1'b0;
    reg start_seen = 1'b0;
    reg done_seen = 1'b0;
    reg pre_r = 1'b1;

    wire [63:0] lowmask = (len >= 7'd64) ? {64{1'b1}} : ((64'd1 << len) - 64'd1);

    always @(posedge clk) begin
        if (i_reset) begin
            phase <= 2'd0;
            armed_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_abort && (phase != 2'd0)) begin
                phase <= 2'd0;
                pre_r <= 1'b0;
            end else begin
                case (phase)
                    2'd0: if (i_load) begin
                        dest <= i_dest;
                        field <= i_field;
                        off <= i_off;
                        len <= (i_len > 7'd64) ? 7'd64 : i_len;
                        phase <= 2'd1;
                        armed_seen <= 1'b1;
                    end
                    2'd1: begin
                        shifted <= field << off;
                        mask <= lowmask << off;
                        phase <= 2'd2;
                        start_seen <= 1'b1;
                    end
                    2'd2: begin
                        result <= (dest & ~mask) | (shifted & mask);
                        phase <= 2'd3;
                        done_seen <= 1'b1;
                    end
                    default: phase <= 2'd0;
                endcase
            end
        end
    end

    assign o_result = result;
    assign o_done = (phase == 2'd3);

    always @(posedge clk)
        if (pre_r) assert (!done_seen || (start_seen && armed_seen));
endmodule

module block_parity_tally (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [15:0] din,
    output reg         par_q,
    output reg  [15:0] word_cnt,
    output reg  [15:0] odd_cnt,
    output reg         win
);
    // XOR parity tree: 16 -> 8 -> 4 -> 2 -> 1
    wire [7:0] l1;
    wire [3:0] l2;
    wire [1:0] l3;
    wire       par;
    assign l1[0] = din[0]  ^ din[1];
    assign l1[1] = din[2]  ^ din[3];
    assign l1[2] = din[4]  ^ din[5];
    assign l1[3] = din[6]  ^ din[7];
    assign l1[4] = din[8]  ^ din[9];
    assign l1[5] = din[10] ^ din[11];
    assign l1[6] = din[12] ^ din[13];
    assign l1[7] = din[14] ^ din[15];
    assign l2[0] = l1[0] ^ l1[1];
    assign l2[1] = l1[2] ^ l1[3];
    assign l2[2] = l1[4] ^ l1[5];
    assign l2[3] = l1[6] ^ l1[7];
    assign l3[0] = l2[0] ^ l2[1];
    assign l3[1] = l2[2] ^ l2[3];
    assign par   = l3[0] ^ l3[1];

    // 8-entry block buffer with per-word parity
    reg [15:0] mem  [0:7];
    reg        mpar [0:7];
    integer i;
    initial begin
        par_q    = 1'b0;
        word_cnt = 16'd0;
        odd_cnt  = 16'd0;
        win      = 1'b0;
        for (i = 0; i < 8; i = i + 1) begin
            mem[i]  = 16'd0;
            mpar[i] = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            par_q <= par;  // optional output register of the tree
            if (start) begin
                win      <= 1'b1;
                word_cnt <= 16'd0;
                odd_cnt  <= 16'd0;
            end else if (win) begin
                if (stop) begin
                    win <= 1'b0;
                end else if (word_cnt < 16'd8) begin
                    mem[word_cnt[2:0]]  <= din;
                    mpar[word_cnt[2:0]] <= par;
                    word_cnt <= word_cnt + 16'd1;
                    if (par) odd_cnt <= odd_cnt + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // after start until stop: at most 8 odd-parity words are tallied
    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(odd_cnt) <= 16'd8);
endmodule

module stream_demux16 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        in_valid,
    input  wire [3:0]  in_sel,
    input  wire [31:0] in_data,
    output wire        in_ready,
    output wire [15:0] out_valid,
    input  wire [15:0] out_ready,
    output wire [31:0] out_data
);
    reg [3:0]  sel_q   = 4'd0;
    reg [15:0] vld_q   = 16'd0;
    reg [31:0] data_q  = 32'd0;
    reg [31:0] acc_cnt = 32'd0;
    reg [31:0] dlv_cnt = 32'd0;
    reg        armed   = 1'b0;

    wire deliver = i_ce && vld_q[sel_q] && out_ready[sel_q];
    assign in_ready = (vld_q == 16'd0) || (vld_q[sel_q] && out_ready[sel_q]);
    wire accept  = i_ce && in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            sel_q   <= 4'd0;
            vld_q   <= 16'd0;
            data_q  <= 32'd0;
            acc_cnt <= 32'd0;
            dlv_cnt <= 32'd0;
        end else if (i_ce) begin
            if (deliver) begin
                vld_q   <= 16'd0;
                dlv_cnt <= dlv_cnt + 32'd1;
            end
            if (accept) begin
                sel_q   <= in_sel;
                data_q  <= in_data;
                vld_q   <= (16'd1 << in_sel);
                acc_cnt <= acc_cnt + 32'd1;
                armed   <= 1'b1;
            end
        end
    end

    assign out_valid = vld_q;
    assign out_data  = data_q;

    assert property (!armed || ((acc_cnt - dlv_cnt) <= 32'd1));
endmodule

module jk_bounded_resp (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    output reg         busy,
    output reg  [63:0] work,
    output reg  [63:0] timer
);
    localparam [63:0] LEN = 64'd12;

    initial busy  = 1'b0;
    initial work  = 64'd0;
    initial timer = 64'd0;

    // JK latch inputs: J accepts a request, K signals completion
    wire j = start && !busy;
    wire k = busy && (work == 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            work  <= 64'd0;
            timer <= 64'd0;
        end else if (ce) begin
            // gated JK latch: set / reset / invert while enabled, hold otherwise
            case ({j, k})
                2'b10:   busy <= 1'b1;
                2'b01:   busy <= 1'b0;
                2'b11:   busy <= ~busy;
                default: busy <= busy;
            endcase
            if (j) begin
                work  <= LEN;
                timer <= LEN + 64'd1;
            end else if (busy) begin
                if (work != 64'd0)
                    work <= work - 64'd1;
                timer <= timer - 64'd1;
            end
        end
    end

    // bounded response: countdown never expires while request outstanding
    always @(posedge clk)
        assert (!(busy && timer == 64'd0));
endmodule

module chipkill_decoder (
    input wire clk,
    input wire i_ce,
    input wire i_scrub,
    input wire [31:0] i_data,
    input wire [31:0] i_chk,
    output wire [31:0] o_data,
    output wire o_uncorr,
    output wire o_fail_valid,
    output wire [1:0] o_fail_id
);
    reg [31:0] syn;
    reg [31:0] dat;
    reg [3:0] fail_oh;
    reg [1:0] fail_id;
    reg fail_valid;
    reg uncorr;
    reg armed;
    initial begin
        syn = 32'h0; dat = 32'h0; fail_oh = 4'd0; fail_id = 2'd0;
        fail_valid = 1'b0; uncorr = 1'b0; armed = 1'b0;
    end

    wire [31:0] s = i_data ^ i_chk;
    wire e0 = |s[7:0];
    wire e1 = |s[15:8];
    wire e2 = |s[23:16];
    wire e3 = |s[31:24];
    wire [2:0] nerr = {2'b00, e0} + {2'b00, e1} + {2'b00, e2} + {2'b00, e3};
    wire [1:0] c = e3 ? 2'd3 : (e2 ? 2'd2 : (e1 ? 2'd1 : 2'd0));
    wire any_err = (nerr != 3'd0);
    wire mark = !fail_valid && (nerr == 3'd1);
    wire bad = (nerr > 3'd1) || (fail_valid && (nerr == 3'd1) && (c != fail_id));

    always @(posedge clk) begin
        if (i_scrub) begin
            syn <= 32'h0;
            fail_oh <= 4'd0;
            fail_id <= 2'd0;
            fail_valid <= 1'b0;
            uncorr <= 1'b0;
        end else if (i_ce) begin
            syn <= s;
            dat <= i_data;
            if (any_err) armed <= 1'b1;
            if (mark) begin
                fail_valid <= 1'b1;
                fail_id <= c;
                fail_oh <= fail_oh | (4'd1 << c);
            end
            if (bad) uncorr <= 1'b1;
        end
    end

    wire [31:0] chip_mask = fail_valid ? (32'h000000FF << {fail_id, 3'b000}) : 32'h0;
    assign o_data = dat ^ (syn & chip_mask);
    assign o_uncorr = uncorr;
    assign o_fail_valid = fail_valid;
    assign o_fail_id = fail_id;

    always @(posedge clk)
        if (armed)
            assert ((fail_oh & (fail_oh - 4'd1)) == 4'd0);
endmodule

module conv_interleaver (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_resync,
    input  wire [7:0] i_sym,
    output reg  [7:0] o_sym,
    output wire       o_fin
);
    // commutator branch counter and revolution counter
    reg [7:0] br  = 8'd0;
    reg [7:0] rev = 8'd0;
    // chain FSM: 0 IDLE, 1 ARMED (first symbol), 2 STARTED (first wrap), 3 FINISHED (second wrap)
    reg [1:0] phase = 2'd0;
    // scope latch: high until the first resync event
    reg before_r = 1'b1;
    reg pv = 1'b0;
    // per-branch delay memories: branch k delays by k symbols
    reg [7:0] d1_0 = 8'd0;
    reg [7:0] d2_0 = 8'd0, d2_1 = 8'd0;
    reg [7:0] d3_0 = 8'd0, d3_1 = 8'd0, d3_2 = 8'd0;
    initial o_sym = 8'd0;

    wire wrap = (br == 8'd3);
    wire fin  = (phase == 2'd3);
    assign o_fin = fin;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_resync) begin
            br       <= 8'd0;
            rev      <= 8'd0;
            phase    <= 2'd0;
            before_r <= 1'b0;
        end else if (i_ce) begin
            br <= wrap ? 8'd0 : br + 8'd1;
            if (wrap && rev != 8'd3) rev <= rev + 8'd1;
            case (phase)
                2'd0:    phase <= 2'd1;
                2'd1:    if (wrap) phase <= 2'd2;
                2'd2:    if (wrap) phase <= 2'd3;
                default: phase <= 2'd3;
            endcase
            case (br)
                8'd0: o_sym <= i_sym;
                8'd1: begin o_sym <= d1_0; d1_0 <= i_sym; end
                8'd2: begin o_sym <= d2_1; d2_1 <= d2_0; d2_0 <= i_sym; end
                default: begin o_sym <= d3_2; d3_2 <= d3_1; d3_1 <= d3_0; d3_0 <= i_sym; end
            endcase
        end
    end

    // finish may only be observed after arm and start: exactly two revolutions done
    always @(posedge clk)
        if (pv && before_r && $rose(fin))
            assert (rev == 8'd2);
endmodule

module misr_lockstep (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [63:0] din,
    output wire [63:0] signature,
    output wire        armed_o
);
    localparam [63:0] POLY = 64'h000000000000001B;
    localparam [63:0] SEED = 64'h0123456789ABCDEF;

    // Lane A holds the signature in true form, lane B in complemented form
    reg [63:0] sig_a;
    reg [63:0] sig_b;
    reg        armed;

    initial sig_a = SEED;
    initial sig_b = ~SEED;
    initial armed = 1'b0;

    function [63:0] misr_step;
        input [63:0] s;
        input [63:0] d;
        begin
            misr_step = {s[62:0], 1'b0} ^ (s[63] ? POLY : 64'd0) ^ d;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b0;
        end else if (start) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b1;
        end else begin
            if (stop)
                armed <= 1'b0;
            if (ce) begin
                sig_a <= misr_step(sig_a, din);
                sig_b <= ~misr_step(~sig_b, din);
            end
        end
    end

    assign signature = sig_a;
    assign armed_o   = armed;

    // After a capture starts, until it is stopped, the lockstep lanes agree on the low byte
    always @(*) assert (!armed || (sig_a[7:0] == ~sig_b[7:0]));
endmodule

module mcycle_epoch (
    input  wire        clk,
    input  wire        i_ce,
    output wire [63:0] o_cycle,
    output wire [63:0] o_epoch
);
    // 64-bit synchronous binary up counter (cycle CSR style) with a
    // pipelined lookahead carry out of the low 32-bit half that drives
    // an epoch counter tracking high-half advances.
    reg [63:0] cnt;
    reg        carry_q;
    reg [63:0] epoch;
    reg        armed;
    reg        pv;
    initial cnt     = 64'd0;
    initial carry_q = 1'b0;
    initial epoch   = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt     <= cnt + 64'd1;
            carry_q <= (cnt[31:0] == 32'hFFFFFFFE);
            if (carry_q)
                epoch <= epoch + 64'd1;
            armed   <= 1'b1;
        end
    end

    assign o_cycle = cnt;
    assign o_epoch = epoch;

    // after the first enabled cycle: if the high half of the counter did
    // not change, the epoch counter must not have changed either
    always @(posedge clk)
        if (pv && armed && $stable(cnt[63:32]))
            assert ($stable(epoch));
endmodule

module snoop_dup_tag_cache (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_fill,
    input  wire [31:0]  i_fill_addr,
    input  wire [127:0] i_fill_data,
    input  wire         i_snoop,
    input  wire [31:0]  i_snp_addr,
    input  wire         i_flush,
    input  wire [31:0]  i_cpu_addr,
    output reg          o_snp_valid,
    output reg  [127:0] o_snp_data,
    output wire         o_snp_hit,
    output wire         o_cpu_hit
);
    localparam TW = 24;

    reg [15:0]       valid     = 16'h0000;
    reg [16*TW-1:0]  tags      = {(16*TW){1'b0}};
    reg [2047:0]     data      = {2048{1'b0}};
    reg [15:0]       dup_valid = 16'h0000;
    reg [16*TW-1:0]  dup_tags  = {(16*TW){1'b0}};
    reg              snp_pend  = 1'b0;
    reg [3:0]        snp_idx   = 4'd0;
    reg              ever_filled = 1'b0;
    reg              armed     = 1'b1;
    initial o_snp_valid = 1'b0;
    initial o_snp_data  = 128'd0;

    wire [3:0]    f_idx = i_fill_addr[7:4];
    wire [TW-1:0] f_tag = i_fill_addr[31:8];
    wire [3:0]    s_idx = i_snp_addr[7:4];
    wire [TW-1:0] s_tag = i_snp_addr[31:8];
    wire [3:0]    c_idx = i_cpu_addr[7:4];
    wire [TW-1:0] c_tag = i_cpu_addr[31:8];

    wire dup_hit = dup_valid[s_idx] && (dup_tags[s_idx*TW +: TW] == s_tag);
    assign o_snp_hit = i_ce && !snp_pend && !i_fill && !i_flush && i_snoop && dup_hit;
    assign o_cpu_hit = valid[c_idx] && (tags[c_idx*TW +: TW] == c_tag);

    always @(posedge clk) begin
        if (i_ce) begin
            o_snp_valid <= 1'b0;
            if (snp_pend) begin
                valid[snp_idx]     <= 1'b0;
                dup_valid[snp_idx] <= 1'b0;
                o_snp_data  <= data[snp_idx*128 +: 128];
                o_snp_valid <= 1'b1;
                snp_pend    <= 1'b0;
            end else if (i_fill) begin
                valid[f_idx]     <= 1'b1;
                dup_valid[f_idx] <= 1'b1;
                tags[f_idx*TW +: TW]     <= f_tag;
                dup_tags[f_idx*TW +: TW] <= f_tag;
                data[f_idx*128 +: 128]   <= i_fill_data;
                ever_filled <= 1'b1;
            end else if (i_flush) begin
                valid     <= 16'h0000;
                dup_valid <= 16'h0000;
                armed     <= 1'b0;
            end else if (o_snp_hit) begin
                snp_pend <= 1'b1;
                snp_idx  <= s_idx;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!$past(o_snp_hit) || $past(ever_filled));
endmodule

module vcpu_minmax_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        open,
    input  wire        close,
    input  wire        arm,
    input  wire [15:0] a,
    input  wire [15:0] b,
    output reg  [15:0] min_out,
    output reg  [15:0] max_out,
    output reg         rdy
);
    localparam [1:0] S_IDLE     = 2'd0;
    localparam [1:0] S_ARMED    = 2'd1;
    localparam [1:0] S_STARTED  = 2'd2;
    localparam [1:0] S_FINISHED = 2'd3;

    reg [1:0]  st;
    reg        win, f_arm, f_start, f_done;
    reg [15:0] a_q, b_q, lo_q, hi_q;

    initial begin
        st = S_IDLE; win = 1'b0; f_arm = 1'b0; f_start = 1'b0; f_done = 1'b0;
        a_q = 16'd0; b_q = 16'd0; lo_q = 16'd0; hi_q = 16'd0;
        min_out = 16'd0; max_out = 16'd0; rdy = 1'b0;
    end

    // single magnitude decision drives both selections
    wire a_lt_b = (a_q < b_q);

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE; win <= 1'b0; f_arm <= 1'b0; f_start <= 1'b0; f_done <= 1'b0;
            a_q <= 16'd0; b_q <= 16'd0; lo_q <= 16'd0; hi_q <= 16'd0;
            min_out <= 16'd0; max_out <= 16'd0; rdy <= 1'b0;
        end else if (ce) begin
            rdy <= 1'b0;
            if (open && !win && st == S_IDLE) begin
                win     <= 1'b1;
                f_arm   <= 1'b0;
                f_start <= 1'b0;
                f_done  <= 1'b0;
            end else if (close) begin
                win <= 1'b0;
            end
            case (st)
                S_IDLE: if (arm) begin
                    a_q   <= a;
                    b_q   <= b;
                    f_arm <= 1'b1;
                    st    <= S_ARMED;
                end
                S_ARMED: begin
                    lo_q    <= a_lt_b ? a_q : b_q;
                    hi_q    <= a_lt_b ? b_q : a_q;
                    f_start <= 1'b1;
                    st      <= S_STARTED;
                end
                S_STARTED: begin
                    min_out <= lo_q;
                    max_out <= hi_q;
                    rdy     <= 1'b1;
                    f_done  <= 1'b1;
                    st      <= S_FINISHED;
                end
                default: st <= S_IDLE;
            endcase
        end
    end

    // after open until close: a finish is never seen without start and arm before it
    always @(*) assert (!(win && f_done) || (f_start && f_arm));
endmodule

module meta_sync_burst (
    input  wire        clk,
    input  wire        ce,
    input  wire [31:0] async_main,
    input  wire [31:0] async_shadow,
    input  wire        win_open,
    input  wire        win_close,
    output wire [31:0] sync_q,
    output wire        meta_err
);
    reg [31:0] main_q   = 32'd0;
    reg [31:0] shadow_q = 32'd0;
    reg        err_flag = 1'b0;
    reg        win      = 1'b0;
    reg [31:0] burst    = 32'd0;
    reg [31:0] budget   = 32'd16;

    assign sync_q   = main_q;
    assign meta_err = err_flag;

    always @(posedge clk) begin
        if (ce) begin
            main_q   <= async_main;
            shadow_q <= async_shadow;
            err_flag <= (main_q != shadow_q);
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (win_open) begin
                win    <= 1'b1;
                burst  <= 32'd0;
                budget <= 32'd16;
            end else if (win_close) begin
                win <= 1'b0;
            end else if (win && err_flag && (budget != 32'd0)) begin
                burst  <= burst + 32'd1;
                budget <= budget - 32'd1;
            end
        end
    end

    always @(posedge clk)
        assert (!win || burst <= 32'd16);
endmodule

module tb_drv_demux (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire         i_req,
    input  wire [3:0]   i_sel,
    input  wire [15:0]  i_data,
    output wire [255:0] o_bus,
    output wire         o_busy
);
    localparam [15:0] K = 16'd8;

    reg [3:0]   sel_r;
    reg [15:0]  data_r;
    reg [255:0] out_q;
    reg         pending;
    reg [15:0]  cnt;
    reg [15:0]  ph;

    initial sel_r   = 4'd0;
    initial data_r  = 16'd0;
    initial out_q   = 256'd0;
    initial pending = 1'b0;
    initial cnt     = 16'd0;
    initial ph      = 16'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            sel_r   <= 4'd0;
            data_r  <= 16'd0;
            out_q   <= 256'd0;
            pending <= 1'b0;
            cnt     <= 16'd0;
            ph      <= 16'd0;
        end else if (i_ce) begin
            if (!pending) begin
                if (i_req) begin
                    pending <= 1'b1;
                    sel_r   <= i_sel;
                    data_r  <= i_data;
                    cnt     <= K;
                    ph      <= 16'd0;
                end
            end else begin
                if (ph == K - 16'd1) begin
                    out_q[sel_r*16 +: 16] <= data_r;
                    pending <= 1'b0;
                    cnt     <= 16'd0;
                    ph      <= 16'd0;
                end else begin
                    ph  <= ph + 16'd1;
                    cnt <= cnt - 16'd1;
                end
            end
        end
    end

    assign o_bus  = out_q;
    assign o_busy = pending;

    assert property (!pending || cnt != 16'd0);
endmodule

module vend_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       coin_valid,
    input  wire [7:0] coin_val,
    input  wire       select,
    input  wire       cancel,
    output wire       vend,
    output wire       change_ret,
    output wire [7:0] change_out
);
    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_COLLECT = 2'd1;
    localparam [1:0] S_VEND    = 2'd2;
    localparam [1:0] S_CHANGE  = 2'd3;
    localparam [7:0] PRICE     = 8'd75;

    reg [1:0] state;
    reg [7:0] credit;
    reg [7:0] change_amt;
    reg       vend_r;
    reg       chg_r;
    reg       pv;
    initial begin
        state = S_IDLE; credit = 8'd0; change_amt = 8'd0;
        vend_r = 1'b0; chg_r = 1'b0; pv = 1'b0;
    end

    wire [8:0] sum     = {1'b0, credit} + {1'b0, coin_val};
    wire [7:0] sat_sum = sum[8] ? 8'd255 : sum[7:0];

    assign vend       = vend_r;
    assign change_ret = chg_r;
    assign change_out = change_amt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; credit <= 8'd0; change_amt <= 8'd0;
            vend_r <= 1'b0; chg_r <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (coin_valid) begin
                        credit <= sat_sum;
                        state  <= S_COLLECT;
                    end
                end
                S_COLLECT: begin
                    if (select && credit >= PRICE) begin
                        credit <= credit - PRICE;
                        state  <= S_VEND;
                        vend_r <= 1'b1;
                    end else if (cancel) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else if (coin_valid) begin
                        credit <= sat_sum;
                    end
                end
                S_VEND: begin
                    vend_r <= 1'b0;
                    if (credit != 8'd0) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_CHANGE: begin
                    chg_r      <= 1'b0;
                    change_amt <= 8'd0;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && $rose(vend_r))
            assert (!chg_r);
endmodule

module polyphase_resampler (
    input  wire         clk,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] in_data,
    output reg  [127:0] out_data,
    output reg          out_valid
);
    localparam [1:0] S_IDLE   = 2'd0;
    localparam [1:0] S_PRIMED = 2'd1;
    localparam [1:0] S_RUN    = 2'd2;
    localparam [1:0] S_DONE   = 2'd3;

    reg [127:0] hist [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) hist[i] = 128'd0;
    end

    reg [4:0] fill        = 5'd0;
    reg [4:0] phase       = 5'd0;
    reg [3:0] out_cnt     = 4'd0;
    reg [1:0] st          = S_IDLE;
    reg       q_seen      = 1'b0;
    reg       armed_seen  = 1'b0;
    reg       start_seen  = 1'b0;
    reg       finish_seen = 1'b0;
    initial out_data  = 128'd0;
    initial out_valid = 1'b0;

    wire [5:0] phase_sum = {1'b0, phase} + 6'd7;
    wire       wrap      = (phase_sum >= 6'd24);
    wire [4:0] phase_nxt = wrap ? (phase_sum[4:0] - 5'd24) : phase_sum[4:0];
    wire [4:0] tap       = 5'd23 - phase;

    always @(posedge clk) begin
        if (ce) begin
            if (in_valid) begin
                for (i = 23; i > 0; i = i - 1) hist[i] <= hist[i-1];
                hist[0] <= in_data;
                if (fill != 5'd24) fill <= fill + 5'd1;
                q_seen <= 1'b1;
            end
            phase     <= phase_nxt;
            out_valid <= 1'b0;
            case (st)
                S_IDLE: begin
                    if (fill == 5'd24) begin
                        st         <= S_PRIMED;
                        armed_seen <= 1'b1;
                    end
                end
                S_PRIMED: begin
                    if (wrap) begin
                        st         <= S_RUN;
                        start_seen <= 1'b1;
                        out_cnt    <= 4'd0;
                    end
                end
                S_RUN: begin
                    out_data  <= hist[phase] + hist[tap];
                    out_valid <= 1'b1;
                    if (out_cnt == 4'd11) begin
                        st          <= S_DONE;
                        finish_seen <= 1'b1;
                        out_cnt     <= 4'd0;
                    end else begin
                        out_cnt <= out_cnt + 4'd1;
                    end
                end
                S_DONE: begin
                    if (wrap) st <= S_RUN;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (q_seen && finish_seen)
            assert (start_seen && armed_seen);
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
endmodule

module fft_tdm_bus (
    input  wire        clk,
    input  wire        step,
    input  wire        wr_en,
    input  wire [2:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire [31:0] bus
);
    // 8-entry butterfly result store, time-shared onto one tri-state bus
    reg [31:0] mem [0:7];
    reg [31:0] phase = 32'd0;   // time-share slot counter
    reg [7:0]  oe    = 8'h01;   // one-hot slot output enable
    reg        armed = 1'b0;    // sticky: first bus drive by slot 0 has happened
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (wr_en)
            mem[wr_addr] <= wr_data;
        if (step) begin
            oe <= {oe[6:0], oe[7]};
            if (oe[7])
                phase <= 32'd0;
            else
                phase <= phase + 32'd1;
            if (oe[0])
                armed <= 1'b1;
        end
    end

    // tri-state buffer: drive the selected butterfly word only while stepping
    assign bus = step ? mem[phase[2:0]] : 32'bz;

    always @(posedge clk)
        if (armed) assert (phase <= 32'd7);
endmodule

module rms_power_meter (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [2:0] i_shift,
    input wire [31:0] i_sample,
    output wire o_busy,
    output wire o_valid,
    output wire [63:0] o_mean_sq
);
    reg busy;
    reg valid;
    reg [2:0] shift_r;
    reg [63:0] win_len, win_cnt, countdown, acc, result;
    reg pv;
    initial begin
        busy = 1'b0; valid = 1'b0; shift_r = 3'd0;
        win_len = 64'd1; win_cnt = 64'd0; countdown = 64'd0;
        acc = 64'd0; result = 64'd0; pv = 1'b0;
    end

    wire [63:0] sq = {32'd0, i_sample} * {32'd0, i_sample};
    wire [63:0] acc_nxt = acc + sq;
    wire last = (win_cnt + 64'd1 == win_len);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0; valid <= 1'b0; shift_r <= 3'd0;
            win_len <= 64'd1; win_cnt <= 64'd0; countdown <= 64'd0;
            acc <= 64'd0; result <= 64'd0;
        end else if (i_ce) begin
            valid <= 1'b0;
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                    shift_r <= i_shift;
                    win_len <= 64'd1 << i_shift;
                    countdown <= 64'd1 << i_shift;
                    win_cnt <= 64'd0;
                    acc <= 64'd0;
                end
            end else begin
                acc <= acc_nxt;
                win_cnt <= win_cnt + 64'd1;
                countdown <= countdown - 64'd1;
                if (last) begin
                    busy <= 1'b0;
                    result <= acc_nxt >> shift_r;
                    valid <= 1'b1;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_valid = valid;
    assign o_mean_sq = result;

    // after a measurement request is accepted (busy set) until the window completes:
    // the deadline countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (countdown != 64'd0);

    // and the window completes exactly when the countdown reaches zero
    always @(posedge clk)
        if (pv && $fell(busy))
            assert (countdown == 64'd0);
endmodule

module forth_rng_word (
    input  wire       clk,
    input  wire       ce,
    input  wire       go,
    output wire [7:0] rnd,
    output reg        busy
);
    reg [7:0] prng;
    reg [7:0] cd;
    reg [7:0] steps;
    initial begin prng = 8'h5A; cd = 8'd0; steps = 8'd0; busy = 1'b0; end

    // 8-bit xorshift (7,5,3)
    wire [7:0] x1 = prng ^ (prng << 7);
    wire [7:0] x2 = x1 ^ (x1 >> 5);
    wire [7:0] x3 = x2 ^ (x2 << 3);

    assign rnd = prng;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (go) begin
                    busy  <= 1'b1;
                    steps <= 8'd0;
                    cd    <= 8'd8;
                end
            end else begin
                prng <= x3;
                cd   <= cd - 8'd1;
                if (steps == 8'd7)
                    busy <= 1'b0;
                else
                    steps <= steps + 8'd1;
            end
        end
    end

    // countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (cd != 8'd0);

    // on the final shift round, exactly one tick of budget remains
    always @(posedge clk)
        if (busy && steps == 8'd7)
            assert (cd == 8'd1);
endmodule

module eth_sticky_align (
    input wire clk,
    input wire load,
    input wire shift,
    input wire [31:0] din,
    output wire [31:0] o_mant,
    output wire o_sticky,
    output wire [31:0] o_shamt
);
    localparam [31:0] PREAMBLE = 32'hD5555555;
    localparam [31:0] MAXSH = 32'd32;

    reg [31:0] mant;
    reg sticky;
    reg [31:0] shamt;
    reg [31:0] orig;
    reg armed;
    reg pv;

    initial begin
        mant = PREAMBLE;
        sticky = 1'b0;
        shamt = 32'd0;
        orig = PREAMBLE;
        armed = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load) begin
            mant <= din;
            orig <= din;
            sticky <= 1'b0;
            shamt <= 32'd0;
            armed <= 1'b0;
        end else if (shift) begin
            mant <= mant >> 1;
            sticky <= sticky | mant[0];
            if (shamt != MAXSH)
                shamt <= shamt + 32'd1;
        end
    end

    assign o_mant = mant;
    assign o_sticky = sticky;
    assign o_shamt = shamt;

    always @(posedge clk)
        if (pv && armed && $stable(shamt))
            assert ($stable(mant));
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
endmodule

module mem_stream_reader (
    input  wire        clk,
    input  wire        rst,
    input  wire        start,
    input  wire [31:0] i_len,
    input  wire [31:0] i_psize,
    input  wire        ce,
    input  wire        wr_en,
    input  wire [4:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_valid,
    output wire [31:0] o_data,
    output wire        o_start,
    output wire        o_last
);
    reg [31:0] mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) mem[i] = 32'd0;
    end
    always @(posedge clk)
        if (wr_en) mem[wr_addr] <= wr_data;

    reg [31:0] rd_ptr    = 32'd0;
    reg [31:0] remaining = 32'd0;
    reg [31:0] pkt_size  = 32'd8;
    reg [31:0] beat      = 32'd0;
    reg        busy      = 1'b0;
    reg        in_pkt    = 1'b0;

    wire fire = busy && ce;
    assign o_valid = busy;
    assign o_data  = mem[rd_ptr[4:0]];
    assign o_start = busy && (beat == 32'd0);
    assign o_last  = busy && ((beat == pkt_size - 32'd1) || (remaining == 32'd1));

    wire [31:0] len_c = (i_len > 32'd32) ? 32'd32 : i_len;
    wire [31:0] psz_c = ((i_psize == 32'd0) || (i_psize > 32'd8)) ? 32'd8 : i_psize;

    always @(posedge clk) begin
        if (rst) begin
            rd_ptr    <= 32'd0;
            remaining <= 32'd0;
            pkt_size  <= 32'd8;
            beat      <= 32'd0;
            busy      <= 1'b0;
            in_pkt    <= 1'b0;
        end else if (start && !busy) begin
            rd_ptr    <= 32'd0;
            remaining <= len_c;
            pkt_size  <= psz_c;
            beat      <= 32'd0;
            busy      <= (len_c != 32'd0);
            in_pkt    <= 1'b0;
        end else if (fire) begin
            rd_ptr    <= rd_ptr + 32'd1;
            remaining <= remaining - 32'd1;
            busy      <= (remaining != 32'd1);
            beat      <= o_last ? 32'd0 : beat + 32'd1;
            if (o_last)
                in_pkt <= 1'b0;
            else if (o_start)
                in_pkt <= 1'b1;
        end
    end

    always @(posedge clk)
        if (in_pkt) assert (beat <= 32'd7);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module vrf_lanes (
    input  wire        clk,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire        we,
    input  wire [6:0]  waddr,
    input  wire        wsel_alu,
    input  wire [63:0] wdata0,
    input  wire [63:0] wdata1,
    input  wire [6:0]  ra0,
    input  wire [6:0]  rb0,
    input  wire [6:0]  ra1,
    input  wire [6:0]  rb1,
    input  wire        cfg_we,
    input  wire [6:0]  cfg_addr,
    input  wire [1:0]  cfg_ew,
    output wire [63:0] out0,
    output wire [63:0] out1,
    output wire [63:0] o_wr_count
);
    reg [63:0] lane0_mem [0:127];
    reg [63:0] lane1_mem [0:127];
    reg [1:0]  ew_cfg    [0:127];
    reg [63:0] lane0_elems;
    reg [63:0] lane1_elems;
    reg [63:0] wr_count;
    reg        armed;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            lane0_mem[i] = 64'd0;
            lane1_mem[i] = 64'd0;
            ew_cfg[i]    = 2'd0;
        end
        lane0_elems = 64'd0;
        lane1_elems = 64'd0;
        wr_count    = 64'd0;
        armed       = 1'b0;
    end

    wire [63:0] alu0 = lane0_mem[ra0] + lane0_mem[rb0];
    wire [63:0] alu1 = lane1_mem[ra1] + lane1_mem[rb1];
    wire [63:0] elems = 64'd1 << ew_cfg[waddr];

    always @(posedge clk) begin
        if (ce) begin
            if (we) begin
                lane0_mem[waddr] <= wsel_alu ? alu0 : wdata0;
                lane1_mem[waddr] <= wsel_alu ? alu1 : wdata1;
                lane0_elems <= lane0_elems + elems;
                lane1_elems <= lane1_elems + elems;
                wr_count    <= wr_count + 64'd1;
            end
            if (cfg_we)
                ew_cfg[cfg_addr] <= cfg_ew;
            if (lock)
                armed <= 1'b1;
            else if (unlock)
                armed <= 1'b0;
        end
    end

    assign out0 = alu0;
    assign out1 = alu1;
    assign o_wr_count = wr_count;

    always @(*) assert (!armed || (lane0_elems == lane1_elems));
endmodule

module brmask_alloc (
    input  wire        clk,
    input  wire        rst,
    input  wire        alloc_req,
    input  wire        clr_req,
    input  wire        kill_req,
    input  wire        disp_valid,
    input  wire [5:0]  res_tag,
    input  wire [7:0]  disp_slot,
    input  wire [7:0]  rd_slot,
    output wire [63:0] o_free_vec,
    output wire [63:0] o_alloc_onehot,
    output wire [63:0] o_rd_mask,
    output wire [63:0] o_live,
    output wire        o_full
);
    reg [63:0] free_vec = ~64'd0;
    reg [63:0] live     = 64'd0;
    reg [63:0] n_free   = 64'd64;
    reg        no_kill  = 1'b1;

    wire [63:0] alloc_oh = free_vec & (~free_vec + 64'd1);
    wire [63:0] res_bit  = 64'd1 << res_tag;

    wire do_alloc = alloc_req && (n_free != 64'd0);
    wire do_clr   = !alloc_req && clr_req && (live != 64'd0) && ((free_vec & res_bit) == 64'd0);
    wire do_kill  = !alloc_req && !clr_req && kill_req && (live != 64'd0) && ((free_vec & res_bit) == 64'd0);
    wire do_disp  = !alloc_req && !clr_req && !kill_req && disp_valid;

    always @(posedge clk) begin
        if (rst) begin
            free_vec <= ~64'd0;
            live     <= 64'd0;
            n_free   <= 64'd64;
        end else if (do_alloc) begin
            free_vec <= free_vec & ~alloc_oh;
            live     <= live + 64'd1;
            n_free   <= n_free - 64'd1;
        end else if (do_clr) begin
            free_vec <= free_vec | res_bit;
            live     <= live - 64'd1;
            n_free   <= n_free + 64'd1;
        end else if (do_kill) begin
            free_vec <= free_vec | res_bit;
            live     <= live - 64'd1;
            n_free   <= n_free + 64'd1;
            no_kill  <= 1'b0;
        end
    end

    wire [256*64-1:0] mask_flat;
    genvar g;
    generate
        for (g = 0; g < 256; g = g + 1) begin : slot
            reg [63:0] m = 64'd0;
            always @(posedge clk) begin
                if (rst)
                    m <= 64'd0;
                else if (do_clr)
                    m <= m & ~res_bit;
                else if (do_kill && ((m & res_bit) != 64'd0))
                    m <= 64'd0;
                else if (do_disp && (disp_slot == g))
                    m <= ~free_vec;
            end
            assign mask_flat[g*64 +: 64] = m;
        end
    endgenerate

    assign o_free_vec     = free_vec;
    assign o_alloc_onehot = alloc_oh;
    assign o_rd_mask      = mask_flat[rd_slot*64 +: 64];
    assign o_live         = live;
    assign o_full         = (n_free == 64'd0);

    assert property (!no_kill || (live <= 64'd64));
endmodule

module dfe_ss_lms (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_mu_wr,
    input  wire [63:0] i_mu,
    input  wire        i_dec,
    input  wire        i_err_sgn,
    output wire [63:0] o_tap0,
    output wire [63:0] o_tap1,
    output wire        o_done
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_ADAPT = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;
    localparam [63:0] N_UPD  = 64'd4;

    reg [63:0] coef0 = 64'd0;
    reg [63:0] coef1 = 64'd0;
    reg [63:0] mu = 64'd1;
    reg [63:0] upd_cnt = 64'd0;
    reg [1:0]  hist = 2'b00;
    reg [1:0]  hist_cnt = 2'd0;
    reg [1:0]  phase = P_IDLE;
    reg        arm_seen = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen = 1'b0;

    // sign-sign LMS step: +mu when error sign matches decided bit sign, else -mu
    wire [63:0] d0 = (i_err_sgn ^ hist[0]) ? (~mu + 64'd1) : mu;
    wire [63:0] d1 = (i_err_sgn ^ hist[1]) ? (~mu + 64'd1) : mu;

    always @(posedge clk) begin
        if (rst) begin
            coef0 <= 64'd0;
            coef1 <= 64'd0;
            hist <= 2'b00;
            hist_cnt <= 2'd0;
            upd_cnt <= 64'd0;
            phase <= P_IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_mu_wr) begin
                mu <= i_mu;
                q_seen <= 1'b1;
            end
            hist <= {hist[0], i_dec};
            if (hist_cnt != 2'd2)
                hist_cnt <= hist_cnt + 2'd1;
            case (phase)
                P_IDLE: begin
                    if (hist_cnt == 2'd2) begin
                        phase <= P_ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                P_ARMED: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= 64'd1;
                    phase <= P_ADAPT;
                    start_seen <= 1'b1;
                end
                P_ADAPT: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= upd_cnt + 64'd1;
                    if (upd_cnt == N_UPD - 64'd1)
                        phase <= P_DONE;
                end
                default: ;
            endcase
        end
    end

    assign o_tap0 = coef0;
    assign o_tap1 = coef1;
    assign o_done = (phase == P_DONE);

    always @(posedge clk)
        if (q_seen && phase == P_DONE)
            assert (arm_seen && start_seen);
endmodule

module fb_scanout (
    input  wire        clk,
    input  wire        start,
    input  wire        ce,
    input  wire [31:0] base_in,
    output wire [31:0] o_addr,
    output wire        o_rd,
    output wire        o_eol,
    output wire        o_eof
);
    // 32 pixels per line, 32 lines per frame, raster-order scanout
    reg        armed    = 1'b0;
    reg [31:0] base     = 32'd0;
    reg [31:0] cur_addr = 32'd0;
    reg [31:0] line     = 32'd0;
    reg [31:0] px       = 32'd0;

    wire adv = armed && ce;
    wire eol = (px == 32'd31);
    wire eof = eol && (line == 32'd31);

    assign o_addr = cur_addr;
    assign o_rd   = adv;
    assign o_eol  = adv && eol;
    assign o_eof  = adv && eof;

    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        if (adv) begin
            if (eof) begin
                base     <= base_in;
                cur_addr <= base_in;
                line     <= 32'd0;
                px       <= 32'd0;
            end else if (eol) begin
                px       <= 32'd0;
                line     <= line + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end else begin
                px       <= px + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end
        end
    end

    // after scanout has been started, the fetch address stays inside the frame
    always @(posedge clk)
        if (armed)
            assert (cur_addr - base <= 32'd1023);
endmodule

module axis_scan_lockup (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_vld,
    input  wire [63:0] i_data,
    output wire        o_vld,
    output wire [63:0] o_data
);
    // Scan segment A (MAC-side domain): 4 beats of 64-bit stream data
    reg [3:0]   a_v;
    reg [255:0] a_d;
    // Lockup latch between segments: holds A's tail beat for a half cycle
    reg         lk_v;
    reg [63:0]  lk_d;
    // Scan segment B (UDP-side domain): 4 beats
    reg [3:0]   b_v;
    reg [255:0] b_d;
    // Occupancy of valid beats across the whole chain (8 entries + lockup)
    reg [63:0]  occ;
    // Packet window: opened by start-of-frame, closed by end-of-frame
    reg         armed;

    initial a_v   = 4'b0000;
    initial a_d   = 256'd0;
    initial lk_v  = 1'b0;
    initial lk_d  = 64'd0;
    initial b_v   = 4'b0000;
    initial b_d   = 256'd0;
    initial occ   = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            a_v   <= 4'b0000;
            a_d   <= 256'd0;
            lk_v  <= 1'b0;
            lk_d  <= 64'd0;
            b_v   <= 4'b0000;
            b_d   <= 256'd0;
            occ   <= 64'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            a_v   <= {a_v[2:0], i_vld};
            a_d   <= {a_d[191:0], i_data};
            lk_v  <= a_v[3];
            lk_d  <= a_d[255:192];
            b_v   <= {b_v[2:0], lk_v};
            b_d   <= {b_d[191:0], lk_d};
            occ   <= occ + {63'd0, i_vld} - {63'd0, b_v[3]};
            armed <= (armed | i_sof) & ~i_eof;
        end
    end

    assign o_vld  = b_v[3];
    assign o_data = b_d[255:192];

    always @(*)
        assert (!armed || occ <= 64'd9);
endmodule

module spi_master_face (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire cfg_wr,
    input wire [1:0] cfg_mode,
    input wire [7:0] tx_data,
    input wire miso,
    output reg cs_n,
    output reg sclk,
    output wire mosi,
    output reg [7:0] rx_data,
    output reg done
);
    reg busy;
    reg [7:0] shreg;
    reg [7:0] bitcnt;
    reg cpol;
    reg cpha;
    reg phase;
    reg samp;
    reg win;
    reg [1:0] mode_sh;
    reg pv;

    initial begin
        cs_n = 1'b1; sclk = 1'b0; rx_data = 8'd0; done = 1'b0;
        busy = 1'b0; shreg = 8'd0; bitcnt = 8'd0; cpol = 1'b0; cpha = 1'b0;
        phase = 1'b0; samp = 1'b0; win = 1'b0; mode_sh = 2'b00; pv = 1'b0;
    end

    assign mosi = shreg[7];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cs_n <= 1'b1; sclk <= 1'b0; done <= 1'b0; busy <= 1'b0;
            bitcnt <= 8'd0; cpol <= 1'b0; cpha <= 1'b0; phase <= 1'b0;
            win <= 1'b0; mode_sh <= 2'b00;
        end else if (ce) begin
            done <= 1'b0;
            if (!busy) begin
                if (cfg_wr) begin
                    cpol <= cfg_mode[1];
                    cpha <= cfg_mode[0];
                    sclk <= cfg_mode[1];
                end else if (start) begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    shreg <= tx_data;
                    bitcnt <= 8'd0;
                    phase <= 1'b0;
                    win <= 1'b1;
                    mode_sh <= {cpol, cpha};
                end
            end else begin
                sclk <= ~sclk;
                phase <= ~phase;
                if (!phase) begin
                    samp <= miso;
                end else begin
                    shreg <= {shreg[6:0], (cpha ? miso : samp)};
                    if (bitcnt == 8'd7) begin
                        bitcnt <= 8'd0;
                        busy <= 1'b0;
                        cs_n <= 1'b1;
                        win <= 1'b0;
                        done <= 1'b1;
                        rx_data <= {shreg[6:0], (cpha ? miso : samp)};
                    end else begin
                        bitcnt <= bitcnt + 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $stable(cs_n))
            assert ($stable({cpol, cpha}) && ({cpol, cpha} == mode_sh));
endmodule

module simd_serial_alu (
    input wire clk,
    input wire ce,
    input wire req,
    input wire [1:0] op,
    input wire [1:0] lsz,
    input wire [63:0] a_in,
    input wire [63:0] b_in,
    output wire busy_o,
    output wire [63:0] result,
    output wire [7:0] lane_flags
);
    localparam [63:0] K = 64'd8;
    reg busy = 1'b0;
    reg [63:0] cd = 64'd0;
    reg [63:0] pos = 64'd0;
    reg [63:0] a_r = 64'd0;
    reg [63:0] b_r = 64'd0;
    reg [63:0] res = 64'd0;
    reg [7:0] flg = 8'd0;
    reg [1:0] op_r = 2'd0;
    reg [1:0] lsz_r = 2'd0;
    reg carry = 1'b0;

    wire [2:0] p = pos[2:0];
    wire lane_lo = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & ~p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b00)) | (p == 3'd0);
    wire lane_hi = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b11)) | (p == 3'd7);
    wire [7:0] ab = a_r[{p, 3'b000} +: 8];
    wire [7:0] bb = b_r[{p, 3'b000} +: 8];
    wire sub = (op_r == 2'd1);
    wire arith = ~op_r[1];
    wire cin = lane_lo ? sub : carry;
    wire [8:0] sum = {1'b0, ab} + {1'b0, bb ^ {8{sub}}} + {8'd0, cin};
    reg [7:0] r8;
    always @(*) begin
        case (op_r)
            2'd0, 2'd1: r8 = sum[7:0];
            2'd2: r8 = ab & bb;
            default: r8 = ab ^ bb;
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                res[{p, 3'b000} +: 8] <= r8;
                flg[p] <= lane_hi & arith & sum[8];
                carry <= sum[8];
                cd <= cd - 64'd1;
                if (pos == 64'd7) begin
                    busy <= 1'b0;
                    pos <= 64'd0;
                end else begin
                    pos <= pos + 64'd1;
                end
            end else if (req) begin
                busy <= 1'b1;
                pos <= 64'd0;
                cd <= K;
                a_r <= a_in;
                b_r <= b_in;
                op_r <= op;
                lsz_r <= lsz;
                carry <= 1'b0;
            end
        end
    end

    assign busy_o = busy;
    assign result = res;
    assign lane_flags = flg;

    always @(*) if (busy) assert (cd != 64'd0);
    always @(*) if (!busy) assert (cd == 64'd0);
endmodule

module lin_master_tx (
    input wire clk,
    input wire rst,
    input wire i_tick,
    input wire i_start,
    input wire i_abort,
    input wire i_enhanced,
    input wire [5:0] i_id,
    input wire [3:0] i_len,
    input wire i_wr_en,
    input wire [3:0] i_wr_addr,
    input wire [31:0] i_wr_data,
    output wire o_busy,
    output wire o_bus_low,
    output wire [31:0] o_tx_byte
);
    // one-hot frame phase: 0 IDLE, 1 BREAK, 2 SYNC, 3 PID, 4 DATA, 5 CSUM
    reg [5:0] phase;
    initial phase = 6'b000001;
    reg [31:0] brk_cnt = 32'd0;
    reg [31:0] byte_idx = 32'd0;
    reg [31:0] bytes_left = 32'd0;
    reg [31:0] frame_len = 32'd1;
    reg [31:0] csum = 32'd0;
    reg [31:0] tx_byte = 32'd0;
    reg [7:0] pid_reg = 8'd0;
    reg [31:0] data_buf [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) data_buf[i] = 32'd0;
    end
    reg armed = 1'b1;
    reg pv = 1'b0;

    wire [7:0] cur_byte = data_buf[byte_idx[3:0]][7:0];
    wire [8:0] csum_sum = {1'b0, csum[7:0]} + {1'b0, cur_byte};
    wire [7:0] csum_next = csum_sum[8] ? (csum_sum[7:0] + 8'd1) : csum_sum[7:0];
    wire p0 = i_id[0] ^ i_id[1] ^ i_id[2] ^ i_id[4];
    wire p1 = ~(i_id[1] ^ i_id[3] ^ i_id[4] ^ i_id[5]);
    wire [7:0] pid_calc = {p1, p0, i_id};

    always @(posedge clk) begin
        pv <= 1'b1;
        if (i_abort) armed <= 1'b0;
    end

    always @(posedge clk) begin
        if (i_wr_en) data_buf[i_wr_addr] <= i_wr_data;
    end

    always @(posedge clk) begin
        if (rst || i_abort) begin
            phase <= 6'b000001;
            brk_cnt <= 32'd0;
            byte_idx <= 32'd0;
            bytes_left <= 32'd0;
        end else if (i_tick) begin
            if (phase[0] && i_start) begin
                phase[0] <= 1'b0;
                phase[1] <= 1'b1;
                brk_cnt <= 32'd0;
                frame_len <= {28'd0, i_len} + 32'd1;
                pid_reg <= pid_calc;
                csum <= i_enhanced ? {24'd0, pid_calc} : 32'd0;
            end
            if (phase[1]) begin
                if (brk_cnt == 32'd12) begin
                    phase[1] <= 1'b0;
                    phase[2] <= 1'b1;
                end
                brk_cnt <= brk_cnt + 32'd1;
            end
            if (phase[2]) begin
                tx_byte <= 32'h00000055;
                phase[2] <= 1'b0;
                phase[3] <= 1'b1;
            end
            if (phase[3]) begin
                tx_byte <= {24'd0, pid_reg};
                byte_idx <= 32'd0;
                bytes_left <= frame_len;
                phase[3] <= 1'b0;
                phase[4] <= 1'b1;
            end
            if (phase[4]) begin
                tx_byte <= {24'd0, cur_byte};
                csum <= {24'd0, csum_next};
                byte_idx <= byte_idx + 32'd1;
                bytes_left <= bytes_left - 32'd1;
                if (byte_idx == frame_len - 32'd1) phase[4] <= 1'b0;
                if (bytes_left == 32'd1) phase[5] <= 1'b1;
            end
            if (phase[5]) begin
                tx_byte <= {24'd0, ~csum[7:0]};
                phase[5] <= 1'b0;
                phase[0] <= 1'b1;
            end
        end
    end

    assign o_busy = !phase[0];
    assign o_bus_low = phase[1];
    assign o_tx_byte = tx_byte;

    // Absence, before first abort: checksum phase never begins while data phase is still active
    always @(posedge clk)
        if (pv && armed && $rose(phase[5]))
            assert (!phase[4]);
endmodule

module iq_imbalance_corr (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] i_in,
    input  wire [127:0] q_in,
    input  wire         coef_we,
    input  wire [7:0]   gain_in,
    input  wire [7:0]   phase_in,
    input  wire         cal_start,
    input  wire         cal_stop,
    output wire         out_valid,
    output wire [127:0] i_out,
    output wire [127:0] q_out,
    output wire [2:0]   inflight_o
);
    // programmable correction coefficients (Q1.7 fixed point)
    reg [7:0] gain;
    reg [7:0] phase;
    // pipeline valid bits
    reg v0, v1, v2, v3;
    // pipeline data
    reg [127:0] i0, q0, i1, i2, i3, q3;
    reg [135:0] p_i, p_q;
    reg [136:0] s2;
    // occupancy of the correction pipeline
    reg [2:0] inflight;
    // calibration observation window
    reg win;

    initial begin
        gain = 8'd128; phase = 8'd0;
        v0 = 1'b0; v1 = 1'b0; v2 = 1'b0; v3 = 1'b0;
        i0 = 128'd0; q0 = 128'd0; i1 = 128'd0; i2 = 128'd0; i3 = 128'd0; q3 = 128'd0;
        p_i = 136'd0; p_q = 136'd0; s2 = 137'd0;
        inflight = 3'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            gain <= 8'd128; phase <= 8'd0;
            v0 <= 1'b0; v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= 3'd0;
            win <= 1'b0;
        end else if (ce) begin
            if (coef_we) begin
                gain  <= gain_in;
                phase <= phase_in;
            end
            // stage 0: capture complex sample
            v0 <= in_valid;
            i0 <= i_in;
            q0 <= q_in;
            // stage 1: correction matrix products
            v1  <= v0;
            i1  <= i0;
            p_q <= q0 * gain;
            p_i <= i0 * phase;
            // stage 2: cross-branch sum
            v2 <= v1;
            i2 <= i1;
            s2 <= p_q + p_i;
            // stage 3: corrected output
            v3 <= v2;
            i3 <= i2;
            q3 <= s2[134:7];
            // occupancy bookkeeping
            inflight <= inflight + {2'b00, in_valid} - {2'b00, v3};
            // calibration window: opened by cal_start, closed by cal_stop
            if (cal_start)
                win <= 1'b1;
            else if (cal_stop)
                win <= 1'b0;
        end
    end

    assign out_valid  = v3;
    assign i_out      = i3;
    assign q_out      = q3;
    assign inflight_o = inflight;

    // within a calibration window, at most 4 samples are in flight
    always @(posedge clk)
        if (win)
            assert (inflight <= 3'd4);

    // within a calibration window, an empty pipeline presents no output
    always @(posedge clk)
        if (win && inflight == 3'd0)
            assert (!v3);
endmodule

module ro_entropy_harvester (
    input  wire        clk,
    input  wire        sample_en,
    input  wire [2:0]  ro_phase,
    output reg  [31:0] o_word,
    output reg         o_valid
);
    // collection shift register and sample counter
    reg [31:0] shreg      = 32'd0;
    reg [31:0] sample_cnt = 32'd0;
    // scope register: high until the first full word is harvested
    reg        armed      = 1'b1;
    initial o_word  = 32'd0;
    initial o_valid = 1'b0;

    // raw entropy bit: XOR of free-running oscillator phases
    wire raw_bit = ^ro_phase;

    always @(posedge clk) begin
        if (sample_en) begin
            shreg <= {shreg[30:0], raw_bit};
            if (sample_cnt == 32'd31) begin
                sample_cnt <= 32'd0;
                o_word     <= {shreg[30:0], raw_bit};
                o_valid    <= 1'b1;
                armed      <= 1'b0;
            end else begin
                sample_cnt <= sample_cnt + 32'd1;
                o_valid    <= 1'b0;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // before the first harvest, the top collection bit never changes
    always @(posedge clk)
        if (pv && armed) assert (shreg[31] == $past(shreg[31]));
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
    output reg  [31:0] o_pkt_cnt
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

module dvfs_ctrl (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire [31:0] i_load,
    input  wire        i_vr_ack,
    input  wire        i_win_close,
    output reg  [31:0] o_volt_mv,
    output reg  [31:0] o_freq_khz,
    output wire        o_pending,
    output wire [31:0] o_req_count
);
    localparam [31:0] HI_TH = 32'd800;
    localparam [31:0] LO_TH = 32'd200;

    reg [2:0]  cur_pt    = 3'd0;
    reg [2:0]  req_pt    = 3'd0;
    reg [2:0]  last_req  = 3'd0;
    reg        pending   = 1'b0;
    reg        win       = 1'b0;
    reg [31:0] req_count = 32'd0;

    wire       up    = (i_load > HI_TH) && (cur_pt != 3'd7);
    wire       dn    = (i_load < LO_TH) && (cur_pt != 3'd0);
    wire       issue = i_ce && !pending && (up || dn);
    wire [2:0] nxt   = up ? (cur_pt + 3'd1) : (cur_pt - 3'd1);
    wire       grant = i_ce && pending && i_vr_ack;

    always @(posedge clk) begin
        if (i_reset) begin
            cur_pt    <= 3'd0;
            req_pt    <= 3'd0;
            last_req  <= 3'd0;
            pending   <= 1'b0;
            win       <= 1'b0;
            req_count <= 32'd0;
        end else begin
            if (issue) begin
                req_pt    <= nxt;
                last_req  <= nxt;
                pending   <= 1'b1;
                req_count <= req_count + 32'd1;
            end else if (grant) begin
                cur_pt  <= req_pt;
                pending <= 1'b0;
            end
            if (issue)
                win <= 1'b1;
            else if (i_ce && i_win_close)
                win <= 1'b0;
        end
    end

    always @(*) begin
        case (cur_pt)
            3'd0: begin o_volt_mv = 32'd700;  o_freq_khz = 32'd100000;  end
            3'd1: begin o_volt_mv = 32'd750;  o_freq_khz = 32'd200000;  end
            3'd2: begin o_volt_mv = 32'd800;  o_freq_khz = 32'd400000;  end
            3'd3: begin o_volt_mv = 32'd850;  o_freq_khz = 32'd600000;  end
            3'd4: begin o_volt_mv = 32'd900;  o_freq_khz = 32'd800000;  end
            3'd5: begin o_volt_mv = 32'd950;  o_freq_khz = 32'd1000000; end
            3'd6: begin o_volt_mv = 32'd1000; o_freq_khz = 32'd1200000; end
            default: begin o_volt_mv = 32'd1100; o_freq_khz = 32'd1500000; end
        endcase
    end

    assign o_pending   = pending;
    assign o_req_count = req_count;

    always @(posedge clk)
        assert (!(win && !pending) || (cur_pt == last_req));
endmodule

module trace_buffer (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_trig,
    input  wire        i_flush,
    input  wire [63:0] i_sample,
    input  wire [5:0]  i_raddr,
    output wire [63:0] o_rdata,
    output wire        o_done,
    output wire [5:0]  o_trig_pos
);
    localparam [63:0] POST     = 64'd12;
    localparam [5:0]  DEPTH_M1 = 6'd47;

    reg [63:0] mem [0:47];
    reg [5:0]  wptr       = 6'd0;
    reg [5:0]  trig_pos   = 6'd0;
    reg        triggered  = 1'b0;
    reg        done       = 1'b0;
    reg [63:0] remaining  = 64'd0;
    reg [63:0] post_count = 64'd0;
    reg        no_abort   = 1'b1;
    reg        pv         = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) mem[i] = 64'd0;
    end

    wire [5:0] wptr_nxt = (wptr == DEPTH_M1) ? 6'd0 : wptr + 6'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                triggered  <= 1'b0;
                done       <= 1'b0;
                remaining  <= 64'd0;
                post_count <= 64'd0;
                no_abort   <= 1'b0;
            end else if (!done) begin
                mem[wptr] <= i_sample;
                wptr      <= wptr_nxt;
                if (!triggered) begin
                    if (i_trig) begin
                        triggered  <= 1'b1;
                        trig_pos   <= wptr;
                        remaining  <= POST;
                        post_count <= 64'd0;
                    end
                end else begin
                    remaining  <= remaining - 64'd1;
                    post_count <= post_count + 64'd1;
                    if (post_count == POST - 64'd1)
                        done <= 1'b1;
                end
            end
        end
    end

    assign o_rdata    = (i_raddr <= DEPTH_M1) ? mem[i_raddr] : 64'd0;
    assign o_done     = done;
    assign o_trig_pos = trig_pos;

    wire expired = (remaining == 64'd0);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_abort && $rose(expired))
            assert (done);
endmodule

module act_gate_counter (
    input wire clk,
    input wire ce,
    input wire gate,
    input wire evt,
    output reg [7:0] result
);
    reg       gate_q = 1'b0;
    reg       evt_q  = 1'b0;
    reg [7:0] cnt    = 8'd0;
    reg       win    = 1'b0;
    reg       seen   = 1'b0;
    initial result = 8'd0;

    wire edge_det = evt && !evt_q;

    always @(posedge clk) begin
        if (ce) begin
            gate_q <= gate;
            evt_q  <= evt;
            if (gate && !gate_q) begin
                win  <= 1'b1;
                seen <= 1'b0;
            end else if (gate && gate_q) begin
                if (edge_det) begin
                    seen <= 1'b1;
                    if (cnt != 8'hFF)
                        cnt <= cnt + 8'd1;
                end
            end else if (!gate && gate_q) begin
                result <= cnt;
                cnt    <= 8'd0;
                win    <= 1'b0;
            end
        end
    end

    assert property (!win || seen || cnt == 8'd0);
endmodule

module cplx_mixer (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire [63:0] s_i,
    input  wire [63:0] s_q,
    input  wire [63:0] lo_i,
    input  wire [63:0] lo_q,
    output reg  [63:0] y_i,
    output reg  [63:0] y_q
);
    // stage 1: four partial products of (s_i + j s_q) * (lo_i + j lo_q)
    reg [63:0] pp_ii, pp_qq, pp_iq, pp_qi;
    // shadow: the partial products that were summed into the current output
    reg [63:0] sp_ii, sp_qq, sp_iq, sp_qi;
    // observation window: opened by LO lock, closed by unlock (may never close)
    reg win;
    reg pv;

    initial begin
        pp_ii = 64'd0; pp_qq = 64'd0; pp_iq = 64'd0; pp_qi = 64'd0;
        sp_ii = 64'd0; sp_qq = 64'd0; sp_iq = 64'd0; sp_qi = 64'd0;
        y_i = 64'd0; y_q = 64'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            pp_ii <= 64'd0; pp_qq <= 64'd0; pp_iq <= 64'd0; pp_qi <= 64'd0;
            sp_ii <= 64'd0; sp_qq <= 64'd0; sp_iq <= 64'd0; sp_qi <= 64'd0;
            y_i <= 64'd0; y_q <= 64'd0;
        end else if (ce) begin
            pp_ii <= s_i * lo_i;
            pp_qq <= s_q * lo_q;
            pp_iq <= s_i * lo_q;
            pp_qi <= s_q * lo_i;
            sp_ii <= pp_ii;
            sp_qq <= pp_qq;
            sp_iq <= pp_iq;
            sp_qi <= pp_qi;
            y_i   <= pp_ii - pp_qq;
            y_q   <= pp_iq + pp_qi;
        end
    end

    always @(posedge clk) begin
        if (rst)         win <= 1'b0;
        else if (lock)   win <= 1'b1;
        else if (unlock) win <= 1'b0;
    end

    // precedence: within the lock window, an output change must be preceded by
    // a change in the partial products that feed the summer
    always @(posedge clk)
        if (pv && win && $stable(sp_ii) && $stable(sp_qq) && $stable(sp_iq) && $stable(sp_qi))
            assert ($stable(y_i) && $stable(y_q));
endmodule

module zz_reorder (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_in_valid,
    input  wire [31:0] i_coef,
    input  wire        i_out_ready,
    output reg         o_valid,
    output reg  [31:0] o_coef,
    output wire        o_full,
    output wire        o_empty
);
    // two 64-entry banks = 128-entry block memory (ping-pong)
    reg [31:0] mem [0:127];
    reg [1:0]  bank_valid = 2'b00;
    reg        w_bank = 1'b0;
    reg        r_bank = 1'b0;
    reg [31:0] w_idx = 32'd0;
    reg [31:0] r_idx = 32'd0;
    reg [31:0] nfull = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) mem[i] = 32'd0;
        o_valid = 1'b0;
        o_coef  = 32'd0;
    end

    // zigzag index-sequence ROM: zigzag position -> raster position
    function [5:0] zz;
        input [5:0] k;
        case (k)
            6'd0: zz=6'd0;   6'd1: zz=6'd1;   6'd2: zz=6'd8;   6'd3: zz=6'd16;
            6'd4: zz=6'd9;   6'd5: zz=6'd2;   6'd6: zz=6'd3;   6'd7: zz=6'd10;
            6'd8: zz=6'd17;  6'd9: zz=6'd24;  6'd10: zz=6'd32; 6'd11: zz=6'd25;
            6'd12: zz=6'd18; 6'd13: zz=6'd11; 6'd14: zz=6'd4;  6'd15: zz=6'd5;
            6'd16: zz=6'd12; 6'd17: zz=6'd19; 6'd18: zz=6'd26; 6'd19: zz=6'd33;
            6'd20: zz=6'd40; 6'd21: zz=6'd48; 6'd22: zz=6'd41; 6'd23: zz=6'd34;
            6'd24: zz=6'd27; 6'd25: zz=6'd20; 6'd26: zz=6'd13; 6'd27: zz=6'd6;
            6'd28: zz=6'd7;  6'd29: zz=6'd14; 6'd30: zz=6'd21; 6'd31: zz=6'd28;
            6'd32: zz=6'd35; 6'd33: zz=6'd42; 6'd34: zz=6'd49; 6'd35: zz=6'd56;
            6'd36: zz=6'd57; 6'd37: zz=6'd50; 6'd38: zz=6'd43; 6'd39: zz=6'd36;
            6'd40: zz=6'd29; 6'd41: zz=6'd22; 6'd42: zz=6'd15; 6'd43: zz=6'd23;
            6'd44: zz=6'd30; 6'd45: zz=6'd37; 6'd46: zz=6'd44; 6'd47: zz=6'd51;
            6'd48: zz=6'd58; 6'd49: zz=6'd59; 6'd50: zz=6'd52; 6'd51: zz=6'd45;
            6'd52: zz=6'd38; 6'd53: zz=6'd31; 6'd54: zz=6'd39; 6'd55: zz=6'd46;
            6'd56: zz=6'd53; 6'd57: zz=6'd60; 6'd58: zz=6'd61; 6'd59: zz=6'd54;
            6'd60: zz=6'd47; 6'd61: zz=6'd55; 6'd62: zz=6'd62; default: zz=6'd63;
        endcase
    endfunction

    wire wr_go   = i_in_valid && !bank_valid[w_bank];
    wire rd_go   = i_out_ready && bank_valid[r_bank];
    wire wr_done = wr_go && (w_idx == 32'd63);
    wire rd_done = rd_go && (r_idx == 32'd63);

    assign o_full  = (nfull == 32'd2);
    assign o_empty = !bank_valid[r_bank];

    // raster-order write into the current write bank
    always @(posedge i_clk)
        if (!i_reset && wr_go)
            mem[{w_bank, w_idx[5:0]}] <= i_coef;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bank_valid <= 2'b00;
            w_bank     <= 1'b0;
            r_bank     <= 1'b0;
            w_idx      <= 32'd0;
            r_idx      <= 32'd0;
            nfull      <= 32'd0;
            o_valid    <= 1'b0;
        end else begin
            if (wr_go)   w_idx  <= wr_done ? 32'd0 : w_idx + 32'd1;
            if (wr_done) w_bank <= ~w_bank;
            if (rd_go)   r_idx  <= rd_done ? 32'd0 : r_idx + 32'd1;
            if (rd_done) r_bank <= ~r_bank;
            if (wr_done) bank_valid[w_bank] <= 1'b1;
            if (rd_done) bank_valid[r_bank] <= 1'b0;
            case ({wr_done, rd_done})
                2'b10:   nfull <= nfull + 32'd1;
                2'b01:   nfull <= nfull - 32'd1;
                default: nfull <= nfull;
            endcase
            // zigzag-order read from the current read bank
            if (i_out_ready) begin
                o_valid <= bank_valid[r_bank];
                if (rd_go)
                    o_coef <= mem[{r_bank, zz(r_idx[5:0])}];
            end
        end
    end

    // absence: the buffer is never full and empty at the same time
    always @(posedge i_clk)
        if (o_full)
            assert (!o_empty);
endmodule

module usb_ep_buf (
    input  wire        clk,
    input  wire        ce,
    input  wire        cfg_set,
    input  wire        out_valid,
    input  wire [31:0] out_data,
    input  wire        in_ready,
    output wire [31:0] in_data,
    output wire        in_toggle,
    output wire        out_toggle,
    output wire [31:0] level_o
);
    reg [31:0] mem [0:15];
    reg [31:0] wptr     = 32'd0;
    reg [31:0] rptr     = 32'd0;
    reg [31:0] count    = 32'd0;
    reg        tog_out  = 1'b0;
    reg        tog_in   = 1'b0;
    reg        ep_cfg   = 1'b0;
    reg        armed    = 1'b0;
    reg        pkt_done = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 32'd0;
    end

    wire [31:0] level   = wptr - rptr;
    wire        do_push = ce && ep_cfg && out_valid && (level != 32'd16);
    wire        do_pop  = ce && in_ready && (level != 32'd0);

    assign in_data    = mem[rptr[3:0]];
    assign in_toggle  = tog_in;
    assign out_toggle = tog_out;
    assign level_o    = count;

    always @(posedge clk) begin
        if (ce) begin
            if (cfg_set) ep_cfg <= 1'b1;
            pkt_done <= do_push;
        end
        if (do_push) begin
            mem[wptr[3:0]] <= out_data;
            wptr    <= wptr + 32'd1;
            tog_out <= ~tog_out;
            armed   <= 1'b1;
        end
        if (do_pop) begin
            rptr   <= rptr + 32'd1;
            tog_in <= ~tog_in;
        end
        case ({do_push, do_pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (armed && $rose(pkt_done))
            assert (count <= 32'd16);
endmodule

module flow_hash_steer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        pkt_valid,
    input  wire [7:0]  src,
    input  wire [7:0]  dst,
    input  wire [7:0]  port,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [7:0]  cfg_data,
    output reg  [7:0]  hash_q,
    output reg  [7:0]  q_sel,
    output reg         out_valid
);
    // 32-entry indirection table, 8-bit words, entry i at bits [8i+7:8i]
    reg [255:0] tbl_flat;
    initial tbl_flat = {8{8'd3, 8'd2, 8'd1, 8'd0}};
    initial hash_q = 8'd0;
    initial q_sel = 8'd0;
    initial out_valid = 1'b0;

    // header hash
    wire [7:0] h = src ^ {dst[3:0], dst[7:4]} ^ {port[6:0], port[7]};
    wire [4:0] hidx = h[4:0];
    wire [255:0] sh = tbl_flat >> {hidx, 3'b000};
    wire [7:0] entry = sh[7:0];

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            tbl_flat  <= {8{8'd3, 8'd2, 8'd1, 8'd0}};
            hash_q    <= 8'd0;
            q_sel     <= 8'd0;
            out_valid <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 32; i = i + 1)
                if (cfg_we && cfg_addr == i[4:0])
                    tbl_flat[i*8 +: 8] <= {6'd0, cfg_data[1:0]};
            out_valid <= pkt_valid;
            if (pkt_valid) begin
                hash_q <= h;
                q_sel  <= entry;
            end
        end
    end

    always @(posedge clk)
        if (out_valid) assert (q_sel < 8'd4);
endmodule

module fracn_mash_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        clear,
    input  wire [31:0] int_in,
    input  wire [31:0] frac_in,
    input  wire [31:0] len_in,
    output reg  [31:0] div_ratio,
    output wire        busy
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_RUN   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    reg [1:0]  phase;
    reg        win;
    reg        seen_arm;
    reg        seen_start;
    reg [31:0] int_set;
    reg [31:0] frac_set;
    reg [31:0] len_set;
    reg [31:0] remaining;
    reg [31:0] acc1;
    reg [31:0] acc2;
    reg        c2_d;

    initial phase      = P_IDLE;
    initial win        = 1'b0;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial int_set    = 32'd0;
    initial frac_set   = 32'd0;
    initial len_set    = 32'd0;
    initial remaining  = 32'd0;
    initial acc1       = 32'd0;
    initial acc2       = 32'd0;
    initial c2_d       = 1'b0;
    initial div_ratio  = 32'd0;

    // two-stage MASH 1-1 sigma-delta modulator
    wire [32:0] sum1 = {1'b0, acc1} + {1'b0, frac_set};
    wire [32:0] sum2 = {1'b0, acc2} + {1'b0, sum1[31:0]};
    wire        c1   = sum1[32];
    wire        c2   = sum2[32];

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            win        <= 1'b0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            int_set    <= 32'd0;
            frac_set   <= 32'd0;
            len_set    <= 32'd0;
            remaining  <= 32'd0;
            acc1       <= 32'd0;
            acc2       <= 32'd0;
            c2_d       <= 1'b0;
            div_ratio  <= 32'd0;
        end else if (ce) begin
            case (phase)
                P_IDLE: if (arm) begin
                    int_set    <= int_in;
                    frac_set   <= frac_in;
                    len_set    <= len_in;
                    acc1       <= 32'd0;
                    acc2       <= 32'd0;
                    c2_d       <= 1'b0;
                    phase      <= P_ARMED;
                    win        <= 1'b1;
                    seen_arm   <= 1'b1;
                    seen_start <= 1'b0;
                end
                P_ARMED: if (start) begin
                    remaining  <= len_set;
                    phase      <= P_RUN;
                    seen_start <= 1'b1;
                end
                P_RUN: begin
                    acc1      <= sum1[31:0];
                    acc2      <= sum2[31:0];
                    c2_d      <= c2;
                    div_ratio <= int_set + {31'd0, c1} + {31'd0, c2} - {31'd0, c2_d};
                    if (remaining == 32'd0)
                        phase <= P_DONE;
                    else
                        remaining <= remaining - 32'd1;
                end
                P_DONE: if (clear) begin
                    phase      <= P_IDLE;
                    win        <= 1'b0;
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    assign busy = (phase == P_RUN);

    // chain precedence inside the arm..clear window: finish implies start and arm happened
    always @(posedge clk)
        if (win && phase == P_DONE)
            assert (seen_arm && seen_start);
endmodule

module autobaud_detect (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_rx,
    input  wire        i_arm,
    input  wire        i_clr,
    output wire [31:0] o_divisor,
    output wire        o_locked
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_ARMED = 2'd1;
    localparam [1:0] S_MEAS  = 2'd2;
    localparam [1:0] S_DONE  = 2'd3;

    reg [1:0]  stage     = S_IDLE;
    reg        measuring = 1'b0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] divisor   = 32'd0;
    reg        rx_q      = 1'b1;
    reg        win       = 1'b0;
    reg        pv        = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            rx_q <= i_rx;
            if (i_clr) begin
                stage     <= S_IDLE;
                measuring <= 1'b0;
                timer     <= 32'd0;
                win       <= 1'b0;
            end else begin
                if (i_arm) win <= 1'b1;
                // edge-capture timer: count start-bit width
                if (measuring) begin
                    if (i_rx) begin
                        divisor   <= timer + 32'd1;
                        measuring <= 1'b0;
                    end else begin
                        timer <= timer + 32'd1;
                    end
                end
                // measurement-state register: arm -> start -> finish
                case (stage)
                    S_IDLE:  if (i_arm) stage <= S_ARMED;
                    S_ARMED: if (rx_q && !i_rx) begin
                                 stage     <= S_MEAS;
                                 measuring <= 1'b1;
                                 timer     <= 32'd0;
                             end
                    S_MEAS:  if (i_rx) stage <= S_DONE;
                    default: ;
                endcase
            end
        end
    end

    assign o_divisor = divisor;
    assign o_locked  = (stage == S_DONE);

    always @(posedge clk)
        if (pv && win && $stable(stage))
            assert ($stable(divisor));
endmodule

module axi_addr_decoder (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire        cfg_sel,
    input  wire [63:0] cfg_base,
    input  wire [63:0] cfg_limit,
    input  wire        req_valid,
    input  wire [63:0] req_addr,
    input  wire        resp_valid,
    input  wire        resp_port,
    output wire        req_ready,
    output wire [1:0]  route,
    output wire        dec_err
);
    localparam [63:0] MAX_OUT = 64'd32;

    reg [63:0] base0  = 64'h0000000000000000;
    reg [63:0] limit0 = 64'h0000000000000FFF;
    reg [63:0] base1  = 64'h0000000000001000;
    reg [63:0] limit1 = 64'h0000000000001FFF;
    reg [63:0] cnt0   = 64'd0;
    reg [63:0] cnt1   = 64'd0;
    reg [63:0] total  = 64'd0;
    reg        armed  = 1'b0;

    wire hit0 = (req_addr >= base0) && (req_addr <= limit0);
    wire hit1 = !hit0 && (req_addr >= base1) && (req_addr <= limit1);

    assign route     = {hit1, hit0};
    assign dec_err   = req_valid && !hit0 && !hit1;
    assign req_ready = (total < MAX_OUT);

    wire do_resp  = resp_valid && (resp_port ? (cnt1 != 64'd0) : (cnt0 != 64'd0));
    wire do_issue = !do_resp && req_valid && (hit0 || hit1) && req_ready;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we) begin
                if (cfg_sel) begin
                    base1  <= cfg_base;
                    limit1 <= cfg_limit;
                end else begin
                    base0  <= cfg_base;
                    limit0 <= cfg_limit;
                end
            end
            if (do_resp) begin
                if (resp_port)
                    cnt1 <= cnt1 - 64'd1;
                else
                    cnt0 <= cnt0 - 64'd1;
                total <= total - 64'd1;
            end else if (do_issue) begin
                if (hit0)
                    cnt0 <= cnt0 + 64'd1;
                else
                    cnt1 <= cnt1 + 64'd1;
                total <= total + 64'd1;
                armed <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (cnt0 <= MAX_OUT);

    always @(posedge clk)
        if (armed) assert (cnt1 <= MAX_OUT);
endmodule

module swd_target_port (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        swdio_in,
    output wire        swdio_oe,
    output wire        swdio_out,
    output wire [31:0] o_wdata,
    output wire        o_busy
);
    localparam [2:0] PH_IDLE = 3'd0;
    localparam [2:0] PH_REQ  = 3'd1;
    localparam [2:0] PH_TRN1 = 3'd2;
    localparam [2:0] PH_ACK  = 3'd3;
    localparam [2:0] PH_DATA = 3'd4;
    localparam [2:0] PH_TRN2 = 3'd5;
    localparam [31:0] K = 32'd38;

    reg [2:0]  phase;
    reg [7:0]  req_sr;
    reg [31:0] bitcnt;
    reg [31:0] data_sr;
    reg        par_acc;
    reg        rnw_q;
    reg        outstanding;
    reg [31:0] countdown;
    reg        no_err;
    reg [31:0] wdata;

    initial begin
        phase = PH_IDLE;
        req_sr = 8'd0;
        bitcnt = 32'd0;
        data_sr = 32'd0;
        par_acc = 1'b0;
        rnw_q = 1'b0;
        outstanding = 1'b0;
        countdown = 32'd0;
        no_err = 1'b1;
        wdata = 32'd0;
    end

    wire [7:0] req_full = {swdio_in, req_sr[7:1]};
    wire req_ok = req_full[0] && !req_full[6] && req_full[7] &&
                  (req_full[5] == ^req_full[4:1]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE;
            req_sr <= 8'd0;
            bitcnt <= 32'd0;
            data_sr <= 32'd0;
            par_acc <= 1'b0;
            rnw_q <= 1'b0;
            outstanding <= 1'b0;
            countdown <= 32'd0;
            no_err <= 1'b1;
            wdata <= 32'd0;
        end else if (ce) begin
            case (phase)
                PH_IDLE: begin
                    if (swdio_in) begin
                        req_sr <= req_full;
                        bitcnt <= 32'd1;
                        phase <= PH_REQ;
                    end
                end
                PH_REQ: begin
                    req_sr <= req_full;
                    if (bitcnt == 32'd7) begin
                        bitcnt <= 32'd0;
                        if (req_ok) begin
                            phase <= PH_TRN1;
                            outstanding <= 1'b1;
                            countdown <= K;
                            rnw_q <= req_full[2];
                        end else begin
                            phase <= PH_IDLE;
                            no_err <= 1'b0;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_TRN1: begin
                    phase <= PH_ACK;
                    bitcnt <= 32'd0;
                    countdown <= countdown - 32'd1;
                    par_acc <= 1'b0;
                    if (rnw_q) data_sr <= wdata;
                    else data_sr <= 32'd0;
                end
                PH_ACK: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd2) begin
                        phase <= PH_DATA;
                        bitcnt <= 32'd0;
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_DATA: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd32) begin
                        phase <= PH_TRN2;
                        bitcnt <= 32'd0;
                        if (!rnw_q) begin
                            if (par_acc != swdio_in) no_err <= 1'b0;
                            else wdata <= data_sr;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                        if (rnw_q) begin
                            par_acc <= par_acc ^ data_sr[0];
                            data_sr <= {1'b0, data_sr[31:1]};
                        end else begin
                            par_acc <= par_acc ^ swdio_in;
                            data_sr <= {swdio_in, data_sr[31:1]};
                        end
                    end
                end
                PH_TRN2: begin
                    phase <= PH_IDLE;
                    outstanding <= 1'b0;
                    countdown <= 32'd0;
                end
                default: begin
                    phase <= PH_IDLE;
                end
            endcase
        end
    end

    assign swdio_oe  = (phase == PH_ACK) || (phase == PH_DATA && rnw_q);
    assign swdio_out = (phase == PH_ACK) ? (bitcnt == 32'd0) :
                       ((bitcnt == 32'd32) ? par_acc : data_sr[0]);
    assign o_wdata = wdata;
    assign o_busy  = outstanding;

    assert property (!no_err || !outstanding || countdown != 32'd0);
endmodule

module rns_alu (
    input wire clk,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] op_a,
    output wire [7:0] result,
    output wire rns_zero
);
    localparam OP_LOAD = 2'd0;
    localparam OP_ADD  = 2'd1;
    localparam OP_SUB  = 2'd2;
    localparam OP_MUL  = 2'd3;

    // residue registers, one per modulus channel (moduli 5 and 7)
    reg [2:0] r5;
    reg [2:0] r7;
    // binary mirror accumulator modulo 35 (= 5*7)
    reg [7:0] acc;
    // sticky scope register: set at the first LOAD
    reg armed;

    initial begin
        r5 = 3'd0;
        r7 = 3'd0;
        acc = 8'd0;
        armed = 1'b0;
    end

    // operand residues
    wire [15:0] opw = {8'd0, op_a};
    wire [15:0] a5  = opw % 16'd5;
    wire [15:0] a7  = opw % 16'd7;
    wire [15:0] a35 = opw % 16'd35;

    wire [15:0] r5w  = {13'd0, r5};
    wire [15:0] r7w  = {13'd0, r7};
    wire [15:0] accw = {8'd0, acc};

    // channel 5
    wire [15:0] n5_add = (r5w + a5) % 16'd5;
    wire [15:0] n5_sub = (r5w + 16'd5 - a5) % 16'd5;
    wire [15:0] n5_mul = (r5w * a5) % 16'd5;
    // channel 7
    wire [15:0] n7_add = (r7w + a7) % 16'd7;
    wire [15:0] n7_sub = (r7w + 16'd7 - a7) % 16'd7;
    wire [15:0] n7_mul = (r7w * a7) % 16'd7;
    // binary mirror mod 35
    wire [15:0] nb_add = (accw + a35) % 16'd35;
    wire [15:0] nb_sub = (accw + 16'd35 - a35) % 16'd35;
    wire [15:0] nb_mul = (accw * a35) % 16'd35;

    always @(posedge clk) begin
        if (en) begin
            case (op)
                OP_LOAD: begin
                    r5 <= a5[2:0];
                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
                end
                OP_SUB: begin
                    r5 <= n5_sub[2:0];
                    r7 <= n7_sub[2:0];
                    acc <= nb_sub[7:0];
                end
                default: begin
                    r5 <= n5_mul[2:0];
                    r7 <= n7_mul[2:0];
                    acc <= nb_mul[7:0];
                end
            endcase
        end
    end

    assign result = acc;
    assign rns_zero = (r5 == 3'd0) && (r7 == 3'd0);

    // Absence after first LOAD: RNS zero flag and nonzero binary mirror never together
    assert property (!armed || !((r5 == 3'd0) && (r7 == 3'd0) && (acc != 8'd0)));
endmodule

module delay_pulse_gen (
    input  wire        clk,
    input  wire        ce,
    input  wire        trig,
    input  wire        wr_cfg,
    input  wire [31:0] cfg_delay,
    input  wire [31:0] cfg_width,
    output wire        pulse,
    output wire        busy
);
    localparam [1:0] IDLE = 2'd0, DLY = 2'd1, WID = 2'd2;

    reg [31:0] delay_reg;
    reg [31:0] width_reg;
    reg [31:0] snap_delay;
    reg [31:0] snap_width;
    reg [31:0] cnt;
    reg [1:0]  phase;
    reg [33:0] since_trig;

    initial begin
        delay_reg  = 32'd0;
        width_reg  = 32'd0;
        snap_delay = 32'd0;
        snap_width = 32'd0;
        cnt        = 32'd0;
        phase      = IDLE;
        since_trig = 34'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (wr_cfg) begin
                delay_reg <= cfg_delay;
                width_reg <= cfg_width;
            end
            case (phase)
                IDLE: begin
                    if (trig) begin
                        phase      <= DLY;
                        cnt        <= 32'd0;
                        snap_delay <= delay_reg;
                        snap_width <= width_reg;
                        since_trig <= 34'd0;
                    end
                end
                DLY: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_delay) begin
                        phase <= WID;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                WID: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_width) begin
                        phase <= IDLE;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assign pulse = (phase == WID);
    assign busy  = (phase != IDLE);

    // Precedence: a pulse now implies the trigger came more than 'delay' cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig > {2'b00, snap_delay});

    // Precedence: a pulse now implies the trigger came no more than delay+width+1 cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig <= {2'b00, snap_delay} + {2'b00, snap_width} + 34'd1);
endmodule

module raw_hazard_wq (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire [63:0] wr_addr,
    input  wire [7:0]  wr_mask,
    input  wire        pop,
    input  wire        rd_valid,
    input  wire [63:0] rd_addr,
    input  wire [7:0]  rd_mask,
    output wire [31:0] o_match,
    output wire        o_fwd,
    output wire        o_stall,
    output wire        o_full,
    output wire        o_empty
);
    reg [63:0] q_addr [0:31];
    reg [7:0]  q_mask [0:31];
    reg [63:0] wptr, rptr, count;
    reg [31:0] match_vec;
    reg        fwd_r, stall_r;
    integer i;
    initial begin
        wptr = 64'd0; rptr = 64'd0; count = 64'd0;
        match_vec = 32'd0; fwd_r = 1'b0; stall_r = 1'b0;
        for (i = 0; i < 32; i = i + 1) begin
            q_addr[i] = 64'd0;
            q_mask[i] = 8'd0;
        end
    end

    wire full  = ((wptr - rptr) == 64'd32);
    wire empty = (count == 64'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;

    wire [31:0] hit;
    wire [31:0] cov_ok;
    genvar g;
    generate
        for (g = 0; g < 32; g = g + 1) begin : cmp
            localparam [4:0] IDX = g;
            wire [4:0] off = IDX - rptr[4:0];
            wire pend = ({59'd0, off} < count);
            assign hit[g]    = pend && (q_addr[g] == rd_addr) && ((q_mask[g] & rd_mask) != 8'd0);
            assign cov_ok[g] = ((q_mask[g] & rd_mask) == rd_mask);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 64'd0;
            rptr <= 64'd0;
            count <= 64'd0;
            match_vec <= 32'd0;
            fwd_r <= 1'b0;
            stall_r <= 1'b0;
        end else begin
            if (do_push) begin
                q_addr[wptr[4:0]] <= wr_addr;
                q_mask[wptr[4:0]] <= wr_mask;
                wptr <= wptr + 64'd1;
            end
            if (do_pop)
                rptr <= rptr + 64'd1;
            case ({do_push, do_pop})
                2'b10: count <= count + 64'd1;
                2'b01: count <= count - 64'd1;
                default: count <= count;
            endcase
            if (rd_valid) begin
                match_vec <= hit;
                fwd_r   <= (hit != 32'd0) && ((hit & cov_ok) == hit);
                stall_r <= (hit != 32'd0) && ((hit & cov_ok) != hit);
            end
        end
    end

    assign o_match = match_vec;
    assign o_fwd   = fwd_r;
    assign o_stall = stall_r;
    assign o_full  = full;
    assign o_empty = empty;

    assert property (!(full && empty));
endmodule

module ivt_dispatch (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        irq_valid,
    input  wire [3:0]  irq_id,
    input  wire        eoi,
    input  wire        tbl_we,
    input  wire [3:0]  tbl_idx,
    input  wire [31:0] tbl_wdata,
    output reg         active,
    output reg  [31:0] vec_addr,
    output reg  [3:0]  cur_id
);
    reg [31:0] vt [0:11];
    reg        nxt_valid;
    reg [3:0]  nxt_id;
    reg [31:0] nxt_addr;
    integer i;

    initial begin
        active    = 1'b0;
        vec_addr  = 32'd0;
        cur_id    = 4'd0;
        nxt_valid = 1'b0;
        nxt_id    = 4'd0;
        nxt_addr  = 32'd0;
        for (i = 0; i < 12; i = i + 1) vt[i] = 32'd0;
    end

    reg [31:0] cur_entry, nxt_entry, irq_entry;

    always @(*) begin
        case (cur_id)
            4'd0: cur_entry = vt[0];   4'd1: cur_entry = vt[1];
            4'd2: cur_entry = vt[2];   4'd3: cur_entry = vt[3];
            4'd4: cur_entry = vt[4];   4'd5: cur_entry = vt[5];
            4'd6: cur_entry = vt[6];   4'd7: cur_entry = vt[7];
            4'd8: cur_entry = vt[8];   4'd9: cur_entry = vt[9];
            4'd10: cur_entry = vt[10]; 4'd11: cur_entry = vt[11];
            default: cur_entry = 32'd0;
        endcase
    end

    always @(*) begin
        case (nxt_id)
            4'd0: nxt_entry = vt[0];   4'd1: nxt_entry = vt[1];
            4'd2: nxt_entry = vt[2];   4'd3: nxt_entry = vt[3];
            4'd4: nxt_entry = vt[4];   4'd5: nxt_entry = vt[5];
            4'd6: nxt_entry = vt[6];   4'd7: nxt_entry = vt[7];
            4'd8: nxt_entry = vt[8];   4'd9: nxt_entry = vt[9];
            4'd10: nxt_entry = vt[10]; 4'd11: nxt_entry = vt[11];
            default: nxt_entry = 32'd0;
        endcase
    end

    always @(*) begin
        case (irq_id)
            4'd0: irq_entry = vt[0];   4'd1: irq_entry = vt[1];
            4'd2: irq_entry = vt[2];   4'd3: irq_entry = vt[3];
            4'd4: irq_entry = vt[4];   4'd5: irq_entry = vt[5];
            4'd6: irq_entry = vt[6];   4'd7: irq_entry = vt[7];
            4'd8: irq_entry = vt[8];   4'd9: irq_entry = vt[9];
            4'd10: irq_entry = vt[10]; 4'd11: irq_entry = vt[11];
            default: irq_entry = 32'd0;
        endcase
    end

    wire        do_wr  = tbl_we && (tbl_idx < 4'd12);
    wire        do_irq = irq_valid && (irq_id < 4'd12);
    wire [31:0] wval   = {tbl_wdata[31:2], 2'b00};

    always @(posedge clk) begin
        if (rst) begin
            active    <= 1'b0;
            nxt_valid <= 1'b0;
        end else if (ce) begin
            if (do_wr) begin
                vt[tbl_idx] <= wval;
                if (active && tbl_idx == cur_id)
                    vec_addr <= wval;
                if (nxt_valid && tbl_idx == nxt_id)
                    nxt_addr <= wval;
            end else if (eoi) begin
                if (active) begin
                    if (nxt_valid) begin
                        cur_id    <= nxt_id;
                        vec_addr  <= nxt_addr;
                        nxt_valid <= 1'b0;
                    end else begin
                        active <= 1'b0;
                    end
                end
            end else if (do_irq) begin
                if (!active) begin
                    active   <= 1'b1;
                    cur_id   <= irq_id;
                    vec_addr <= irq_entry;
                end else if (!nxt_valid) begin
                    nxt_valid <= 1'b1;
                    nxt_id    <= irq_id;
                    nxt_addr  <= irq_entry;
                end
            end
        end
    end

    always @(posedge clk)
        assert (!active || vec_addr == cur_entry);
endmodule

module csa_token_checksum (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_close,
    input  wire [7:0] i_byte,
    output wire       o_csa_zero,
    output wire       o_ref_busy
);
    // carry-save accumulator of a token byte stream
    reg [7:0] sum_r   = 8'd0;
    reg [7:0] carry_r = 8'd0;
    // binary reference accumulator (shadow checksum)
    reg [7:0] acc     = 8'd0;
    // scope register: high until the first record-close event
    reg       armed   = 1'b1;

    // 3:2 reduction of (sum, carry<<1, incoming byte)
    wire [7:0] csa_a = sum_r;
    wire [7:0] csa_b = {carry_r[6:0], 1'b0};
    wire [7:0] csa_c = i_byte;
    wire [7:0] sum_n   = csa_a ^ csa_b ^ csa_c;
    wire [7:0] carry_n = (csa_a & csa_b) | (csa_a & csa_c) | (csa_b & csa_c);

    wire [7:0] csa_val = sum_r + {carry_r[6:0], 1'b0};

    assign o_csa_zero = (csa_val == 8'd0);
    assign o_ref_busy = (acc != 8'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            sum_r   <= sum_n;
            carry_r <= carry_n;
            acc     <= acc + i_byte;
            if (i_close)
                armed <= 1'b0;
        end
    end

    // Absence, before first close: CSA-zero and reference-busy never together
    assert property (!armed || !(o_csa_zero && o_ref_busy));
endmodule

module ws2812_encoder (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [23:0] color,
    output reg         dout,
    output wire        busy_o,
    output wire        ready
);
    localparam [31:0] T_BIT   = 32'd4;
    localparam [31:0] T_HI0   = 32'd1;
    localparam [31:0] T_HI1   = 32'd3;
    localparam [31:0] T_RESET = 32'd8;
    localparam [31:0] N_BITS  = 32'd24;
    localparam [31:0] K       = 32'd104;

    reg        busy        = 1'b0;
    reg        in_reset    = 1'b0;
    reg [31:0] shift       = 32'd0;
    reg [31:0] bit_cnt     = 32'd0;
    reg [31:0] pulse_timer = 32'd0;
    reg [31:0] gap_cnt     = 32'd0;
    reg [31:0] deadline    = 32'd0;

    assign busy_o = busy;
    assign ready  = !busy;

    always @(*) begin
        dout = busy && !in_reset && (pulse_timer < (shift[23] ? T_HI1 : T_HI0));
    end

    always @(posedge clk) begin
        if (rst) begin
            busy        <= 1'b0;
            in_reset    <= 1'b0;
            shift       <= 32'd0;
            bit_cnt     <= 32'd0;
            pulse_timer <= 32'd0;
            gap_cnt     <= 32'd0;
            deadline    <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (start) begin
                    busy        <= 1'b1;
                    in_reset    <= 1'b0;
                    shift       <= {8'd0, color};
                    bit_cnt     <= N_BITS;
                    pulse_timer <= 32'd0;
                    gap_cnt     <= 32'd0;
                    deadline    <= K;
                end
            end else begin
                deadline <= deadline - 32'd1;
                if (!in_reset) begin
                    if (pulse_timer == T_BIT - 32'd1) begin
                        pulse_timer <= 32'd0;
                        shift       <= shift << 1;
                        if (bit_cnt == 32'd1) begin
                            bit_cnt  <= 32'd0;
                            in_reset <= 1'b1;
                            gap_cnt  <= T_RESET;
                        end else begin
                            bit_cnt <= bit_cnt - 32'd1;
                        end
                    end else begin
                        pulse_timer <= pulse_timer + 32'd1;
                    end
                end else begin
                    if (gap_cnt == 32'd1) begin
                        gap_cnt  <= 32'd0;
                        in_reset <= 1'b0;
                        busy     <= 1'b0;
                    end else begin
                        gap_cnt <= gap_cnt - 32'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert (deadline != 32'd0);
endmodule

module tapeout_i2f (
    input wire clk,
    input wire en,
    input wire arm,
    input wire start,
    input wire [7:0] din,
    input wire q_sess,
    input wire r_sess,
    output reg [7:0] fout,
    output reg fin
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, NORM = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_f, start_f;
    reg [7:0] mant;
    reg [3:0] exp;
    reg win;

    initial begin
        phase = IDLE; arm_f = 1'b0; start_f = 1'b0;
        mant = 8'd0; exp = 4'd0; fout = 8'd0; fin = 1'b0; win = 1'b0;
    end

    wire guard_b = mant[3];
    wire sticky_b = |mant[2:0];
    wire rup = guard_b && (sticky_b || mant[4]);
    wire [2:0] mfrac = mant[6:4];
    wire [2:0] mr = (rup && mfrac != 3'b111) ? (mfrac + 3'd1) : mfrac;
    wire [7:0] rounded = (mant == 8'd0) ? 8'd0 : {1'b0, exp, mr};

    always @(posedge clk) begin
        if (en) begin
            if (q_sess) begin
                win <= 1'b1;
                arm_f <= 1'b0;
                start_f <= 1'b0;
                phase <= IDLE;
                fin <= 1'b0;
            end else begin
                if (r_sess) win <= 1'b0;
                fin <= 1'b0;
                case (phase)
                    IDLE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                    ARMED: if (start) begin
                        start_f <= 1'b1; phase <= NORM;
                    end
                    NORM: begin
                        if (mant != 8'd0 && !mant[7]) begin
                            mant <= mant << 1;
                            exp <= exp - 4'd1;
                        end else begin
                            phase <= DONE;
                            fin <= 1'b1;
                            fout <= rounded;
                        end
                    end
                    DONE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win) && fin)
            assert ($past(arm_f) && $past(start_f));
endmodule

module wl_map_scan (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [4:0] lblk,
    output reg busy,
    output reg done
);
    reg [4:0]  map_mem   [0:31];
    reg [15:0] erase_cnt [0:31];
    reg [5:0]  scan_idx;
    reg [5:0]  countdown;
    reg [4:0]  best_idx;
    reg [15:0] best_cnt;
    reg [4:0]  tgt;
    integer i;

    initial busy = 1'b0;
    initial done = 1'b0;
    initial scan_idx = 6'd0;
    initial countdown = 6'd0;
    initial best_idx = 5'd0;
    initial best_cnt = 16'hFFFF;
    initial tgt = 5'd0;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            map_mem[i] = i;
            erase_cnt[i] = 16'd0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            scan_idx <= 6'd0;
            countdown <= 6'd0;
            best_idx <= 5'd0;
            best_cnt <= 16'hFFFF;
            tgt <= 5'd0;
            for (i = 0; i < 32; i = i + 1) begin
                map_mem[i] <= i;
                erase_cnt[i] <= 16'd0;
            end
        end else if (en) begin
            done <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    tgt <= lblk;
                    scan_idx <= 6'd0;
                    countdown <= 6'd33;
                    best_cnt <= 16'hFFFF;
                end
            end else if (scan_idx < 6'd32) begin
                if (erase_cnt[scan_idx[4:0]] < best_cnt) begin
                    best_idx <= scan_idx[4:0];
                    best_cnt <= erase_cnt[scan_idx[4:0]];
                end
                scan_idx <= scan_idx + 6'd1;
                countdown <= countdown - 6'd1;
            end else if (scan_idx == 6'd32) begin
                map_mem[tgt] <= best_idx;
                if (erase_cnt[best_idx] != 16'hFFFF)
                    erase_cnt[best_idx] <= erase_cnt[best_idx] + 16'd1;
                busy <= 1'b0;
                countdown <= countdown - 6'd1;
                done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 6'd0);
endmodule

module mempool_bank_rdata_mux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req_valid,
    input wire [3:0] req_bank,
    input wire [255:0] bank_rdata,
    output reg [15:0] rdata,
    output wire rvalid,
    output wire [15:0] o_rsp_cnt
);
    reg v_q0, v_q1, v_q2;
    reg [3:0] idx_q0, idx_q1, idx_q2;
    reg [15:0] sel_q0, sel_q1, sel_q2;
    reg [15:0] rsp_cnt;

    initial begin
        v_q0 = 1'b0; v_q1 = 1'b0; v_q2 = 1'b0;
        idx_q0 = 4'd0; idx_q1 = 4'd0; idx_q2 = 4'd0;
        sel_q0 = 16'h0000; sel_q1 = 16'h0000; sel_q2 = 16'h0000;
        rsp_cnt = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v_q0 <= 1'b0; v_q1 <= 1'b0; v_q2 <= 1'b0;
            idx_q0 <= 4'd0; idx_q1 <= 4'd0; idx_q2 <= 4'd0;
            sel_q0 <= 16'h0000; sel_q1 <= 16'h0000; sel_q2 <= 16'h0000;
            rsp_cnt <= 16'd0;
        end else if (en) begin
            v_q0 <= req_valid;
            idx_q0 <= req_bank;
            sel_q0 <= req_valid ? (16'h0001 << req_bank) : 16'h0000;
            v_q1 <= v_q0;
            idx_q1 <= idx_q0;
            sel_q1 <= sel_q0;
            v_q2 <= v_q1;
            idx_q2 <= idx_q1;
            sel_q2 <= sel_q1;
            if (v_q2)
                rsp_cnt <= rsp_cnt + 16'd1;
        end
    end

    integer b;
    always @(*) begin
        rdata = 16'h0000;
        for (b = 0; b < 16; b = b + 1)
            if (sel_q2[b])
                rdata = rdata | bank_rdata[b*16 +: 16];
    end

    assign rvalid = v_q2;
    assign o_rsp_cnt = rsp_cnt;

    always @(posedge clk)
        assert ((sel_q2 & (sel_q2 - 16'h0001)) == 16'h0000);
endmodule

module anl_dsp_simd_mul (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [1:0]  cfg_mode,
    input  wire        ld,
    input  wire [31:0] a_in,
    input  wire [31:0] b_in,
    input  wire        push,
    input  wire        pop,
    input  wire        start,
    input  wire        stop,
    output wire [63:0] o_head,
    output wire [31:0] o_occ,
    output wire        o_full,
    output wire        o_win
);
    reg [1:0]  mode_q;
    reg [31:0] a_q, b_q;
    reg [63:0] res_q;
    reg [63:0] buf_q0, buf_q1, buf_q2, buf_q3;
    reg [3:0]  valid_q;
    reg [31:0] occ_q;
    reg        win_q;

    initial begin
        mode_q  = 2'd0;
        a_q     = 32'd0;
        b_q     = 32'd0;
        res_q   = 64'd0;
        buf_q0  = 64'd0;
        buf_q1  = 64'd0;
        buf_q2  = 64'd0;
        buf_q3  = 64'd0;
        valid_q = 4'b0000;
        occ_q   = 32'd0;
        win_q   = 1'b0;
    end

    // lane-cut SIMD multiplier
    wire [63:0] p32   = {32'd0, a_q} * {32'd0, b_q};
    wire [31:0] p16_0 = {16'd0, a_q[15:0]}  * {16'd0, b_q[15:0]};
    wire [31:0] p16_1 = {16'd0, a_q[31:16]} * {16'd0, b_q[31:16]};
    wire [15:0] p8_0  = {8'd0, a_q[7:0]}   * {8'd0, b_q[7:0]};
    wire [15:0] p8_1  = {8'd0, a_q[15:8]}  * {8'd0, b_q[15:8]};
    wire [15:0] p8_2  = {8'd0, a_q[23:16]} * {8'd0, b_q[23:16]};
    wire [15:0] p8_3  = {8'd0, a_q[31:24]} * {8'd0, b_q[31:24]};

    reg [63:0] prod;
    always @(*) begin
        case (mode_q)
            2'd1:    prod = {p16_1, p16_0};
            2'd2:    prod = {p8_3, p8_2, p8_1, p8_0};
            default: prod = p32;
        endcase
    end

    // buffer slot selection
    reg [3:0] push_mask;
    always @(*) begin
        if (!valid_q[0])      push_mask = 4'b0001;
        else if (!valid_q[1]) push_mask = 4'b0010;
        else if (!valid_q[2]) push_mask = 4'b0100;
        else if (!valid_q[3]) push_mask = 4'b1000;
        else                  push_mask = 4'b0000;
    end
    wire [3:0] pop_mask = valid_q & (~valid_q + 4'd1);

    wire push_acc = push && !(&valid_q);
    wire pop_acc  = pop && (|valid_q);

    always @(posedge clk) begin
        if (rst) begin
            mode_q  <= 2'd0;
            a_q     <= 32'd0;
            b_q     <= 32'd0;
            res_q   <= 64'd0;
            buf_q0  <= 64'd0;
            buf_q1  <= 64'd0;
            buf_q2  <= 64'd0;
            buf_q3  <= 64'd0;
            valid_q <= 4'b0000;
            occ_q   <= 32'd0;
            win_q   <= 1'b0;
        end else if (en) begin
            if (ld) begin
                mode_q <= cfg_mode;
                a_q    <= a_in;
                b_q    <= b_in;
            end
            res_q <= prod;
            if (push_acc && push_mask[0]) buf_q0 <= res_q;
            if (push_acc && push_mask[1]) buf_q1 <= res_q;
            if (push_acc && push_mask[2]) buf_q2 <= res_q;
            if (push_acc && push_mask[3]) buf_q3 <= res_q;
            valid_q <= (valid_q | (push_acc ? push_mask : 4'b0000))
                       & ~(pop_acc ? pop_mask : 4'b0000);
            if (push_acc && !pop_acc)
                occ_q <= occ_q + 32'd1;
            else if (pop_acc && !push_acc)
                occ_q <= occ_q - 32'd1;
            if (start)
                win_q <= 1'b1;
            else if (stop)
                win_q <= 1'b0;
        end
    end

    assign o_head = valid_q[0] ? buf_q0 :
                    valid_q[1] ? buf_q1 :
                    valid_q[2] ? buf_q2 :
                    valid_q[3] ? buf_q3 : 64'd0;
    assign o_occ  = occ_q;
    assign o_full = &valid_q;
    assign o_win  = win_q;

    // Bounded existence: at most 4 results inside the observation window
    always @(*) assert (!win_q || occ_q <= 32'd4);
endmodule

module axis_luma_compressor (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
);
    localparam [63:0] UNITY = 64'h0000_0001_0000_0000;
    localparam [63:0] SLEW_LEN = 64'd8;

    reg [63:0] env;
    reg [63:0] gain;
    reg [63:0] tgt;
    reg        pend;
    reg [63:0] cd;
    reg [63:0] step;
    reg [63:0] hist [0:7];
    reg        win;

    integer i;
    initial begin
        env  = 64'd0;
        gain = UNITY;
        tgt  = UNITY;
        pend = 1'b0;
        cd   = 64'd0;
        step = 64'd0;
        win  = 1'b0;
        for (i = 0; i < 8; i = i + 1) hist[i] = UNITY;
    end

    assign s_tready = en;
    wire acc = en && s_tvalid;

    wire [63:0] reduction = (env > thr) ? ((env - thr) >> ratio_sh) : 64'd0;
    wire [63:0] new_tgt   = (reduction >= gain) ? 64'd0 : (gain - reduction);
    wire [63:0] gain_next = (tgt < gain) ? (gain - ((gain - tgt) >> 3))
                                         : (gain + ((tgt - gain) >> 3));
    wire [63:0] env_next  = (s_luma > env) ? (env + ((s_luma - env) >> 2))
                                           : (env - ((env - s_luma) >> 5));

    always @(posedge clk) begin
        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
        end else if (en) begin
            if (acc)
                env <= env_next;
            if (!pend) begin
                if (acc && (env > thr)) begin
                    tgt  <= new_tgt;
                    pend <= 1'b1;
                    cd   <= SLEW_LEN;
                    step <= 64'd0;
                end
            end else begin
                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

    wire [127:0] prod = s_luma * gain;
    assign m_luma   = prod[95:32];
    assign m_tvalid = s_tvalid;
    assign m_tuser  = s_tuser;
    assign m_tlast  = s_tlast;
    assign o_gain   = gain;
    assign o_hist0  = hist[0];
    assign o_win    = win;

    always @(*) assert (!(win && pend) || cd != 64'd0);
endmodule

module tf2_wrle (
    input wire clk,
    input wire rst,
    input wire en,
    input wire in_valid,
    input wire [15:0] in_data,
    input wire drain,
    output reg out_valid,
    output reg [15:0] out_val,
    output reg [15:0] out_cnt
);
    localparam [15:0] MAX = 16'd24;

    reg [15:0] cur;
    reg [15:0] cnt;
    reg [15:0] dl;
    reg busy;
    reg pre_drain;
    reg pv;

    initial begin
        cur = 16'd0;
        cnt = 16'd0;
        dl = 16'd0;
        busy = 1'b0;
        pre_drain = 1'b1;
        pv = 1'b0;
        out_valid = 1'b0;
        out_val = 16'd0;
        out_cnt = 16'd0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cur <= 16'd0;
            cnt <= 16'd0;
            dl <= 16'd0;
            busy <= 1'b0;
            pre_drain <= 1'b1;
            out_valid <= 1'b0;
            out_val <= 16'd0;
            out_cnt <= 16'd0;
        end else if (en) begin
            out_valid <= 1'b0;
            if (drain) begin
                pre_drain <= 1'b0;
                if (busy) begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    busy <= 1'b0;
                    cnt <= 16'd0;
                    dl <= 16'd0;
                end
            end else if (in_valid) begin
                if (!busy) begin
                    cur <= in_data;
                    cnt <= 16'd1;
                    dl <= MAX;
                    busy <= 1'b1;
                end else if (in_data == cur && cnt < MAX) begin
                    cnt <= cnt + 16'd1;
                    dl <= dl - 16'd1;
                end else begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    cur <= in_data;
                    cnt <= 16'd1;
                    dl <= MAX;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(pre_drain) && $past(busy))
            assert ($past(dl) != 16'd0);
endmodule

module hbpf_breathe (
    input  wire clk,
    input  wire en,
    output wire led
);
    localparam [63:0] STEP      = 64'h0000000100000000;
    localparam [63:0] NSTEPS    = 64'h0000000080000000;
    localparam [63:0] MAX       = 64'h8000000000000000;
    localparam [63:0] PRESC_MAX = 64'd999;

    reg [63:0] pwm_cnt  = 64'd0;
    reg [63:0] presc    = 64'd0;
    reg [63:0] pos      = 64'd0;
    reg [63:0] duty     = 64'd0;
    reg [63:0] headroom = 64'h8000000000000000;
    reg        dir        = 1'b1;
    reg        first_rise = 1'b1;

    assign led = (pwm_cnt < duty);

    wire tick = en && (presc == PRESC_MAX);

    always @(posedge clk) begin
        if (en) begin
            pwm_cnt <= pwm_cnt + 64'd1;
            if (presc == PRESC_MAX)
                presc <= 64'd0;
            else
                presc <= presc + 64'd1;
        end
        if (tick) begin
            if (dir) begin
                if (pos < NSTEPS) begin
                    pos      <= pos + 64'd1;
                    duty     <= duty + STEP;
                    headroom <= headroom - STEP;
                end else begin
                    dir        <= 1'b0;
                    first_rise <= 1'b0;
                end
            end else begin
                if (pos > 64'd0) begin
                    pos      <= pos - 64'd1;
                    duty     <= duty - STEP;
                    headroom <= headroom + STEP;
                end else begin
                    dir <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (first_rise)
            assert (duty <= MAX);

    always @(posedge clk)
        if (first_rise)
            assert (headroom <= MAX);
endmodule

module degate_trng_health (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [127:0] sample
);
    reg [127:0] last_smp = 128'd0;
    reg [127:0] ref_smp  = 128'd0;
    reg [127:0] hist [0:7];
    reg [2:0]   rep_cnt  = 3'd0;
    reg [2:0]   win_cnt  = 3'd0;
    reg [3:0]   apt_cnt  = 4'd0;
    reg         alarm    = 1'b0;
    reg         armed    = 1'b0;
    reg         pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            hist[i] = 128'd0;
    end

    wire       rep_match = (sample == last_smp);
    wire [2:0] rep_nxt   = rep_match ? ((rep_cnt == 3'd7) ? 3'd7 : rep_cnt + 3'd1) : 3'd0;

    reg [3:0] apt_nxt;
    reg [2:0] win_nxt;
    always @(*) begin
        if (win_cnt == 3'd0) begin
            apt_nxt = 4'd1;
            win_nxt = 3'd1;
        end else if (win_cnt == 3'd7) begin
            apt_nxt = 4'd0;
            win_nxt = 3'd0;
        end else begin
            apt_nxt = apt_cnt + ((sample == ref_smp) ? 4'd1 : 4'd0);
            win_nxt = win_cnt + 3'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            last_smp <= 128'd0;
            ref_smp  <= 128'd0;
            rep_cnt  <= 3'd0;
            win_cnt  <= 3'd0;
            apt_cnt  <= 4'd0;
            alarm    <= 1'b0;
            armed    <= 1'b0;
        end else if (en) begin
            hist[win_cnt] <= sample;
            last_smp <= sample;
            rep_cnt  <= rep_nxt;
            if (win_cnt == 3'd0)
                ref_smp <= sample;
            apt_cnt  <= apt_nxt;
            win_cnt  <= win_nxt;
            if (rep_nxt >= 3'd5 || apt_nxt >= 4'd6)
                alarm <= 1'b1;
            if (win_cnt == 3'd7)
                armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (pv && !rst && armed && $stable(alarm))
            assert (!(apt_cnt[3] && win_cnt != 3'd0));
    end
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
endmodule

module stream_trap (
    input wire clk,
    input wire rst,
    input wire en,
    input wire fault_valid,
    input wire [63:0] fault_cause,
    input wire [63:0] frame_addr,
    input wire mret,
    input wire resume,
    input wire host_arm,
    input wire host_disarm,
    output reg in_trap,
    output reg stream_active
);
    localparam [63:0] DEPTH_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] cause;
    reg [63:0] epc;
    reg [63:0] status;
    reg [63:0] trap_depth;
    reg [63:0] log_mem [0:31];
    reg [4:0]  log_ptr;
    reg        win;
    reg        pv;
    integer i;

    initial begin
        cause = 64'd0;
        epc = 64'd0;
        status = 64'd0;
        trap_depth = 64'd0;
        in_trap = 1'b0;
        stream_active = 1'b0;
        log_ptr = 5'd0;
        win = 1'b0;
        pv = 1'b0;
        for (i = 0; i < 32; i = i + 1) log_mem[i] = 64'd0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cause <= 64'd0;
            epc <= 64'd0;
            status <= 64'd0;
            trap_depth <= 64'd0;
            in_trap <= 1'b0;
            stream_active <= 1'b0;
            log_ptr <= 5'd0;
            win <= 1'b0;
            for (i = 0; i < 32; i = i + 1) log_mem[i] <= 64'd0;
        end else if (en) begin
            if (host_disarm) win <= 1'b0;
            else if (host_arm) win <= 1'b1;

            if (fault_valid) begin
                cause <= fault_cause;
                epc <= frame_addr;
                status <= {status[63:1], stream_active};
                log_mem[log_ptr] <= fault_cause;
                log_ptr <= log_ptr + 5'd1;
                if (trap_depth != DEPTH_MAX) trap_depth <= trap_depth + 64'd1;
                in_trap <= 1'b1;
                stream_active <= 1'b0;
            end else if (mret && trap_depth != 64'd0) begin
                trap_depth <= trap_depth - 64'd1;
                if (trap_depth == 64'd1) begin
                    in_trap <= 1'b0;
                    stream_active <= status[0];
                end
            end else if (resume && trap_depth == 64'd0) begin
                stream_active <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && stream_active && !$past(stream_active))
            assert (!in_trap);
endmodule

module yat_phase_ring (
    input  wire        clk,
    input  wire        rst,
    input  wire        advance,
    output wire [31:0] fetch_phase,
    output wire [31:0] exec_phase
);
    reg [31:0] fetch_ring;
    reg [31:0] exec_ring;

    initial fetch_ring = 32'h00000000;
    initial exec_ring  = 32'h00000000;

    // Fetch-side Johnson phase token
    always @(posedge clk) begin
        if (rst)
            fetch_ring <= 32'h00000000;
        else if (advance)
            fetch_ring <= {fetch_ring[30:0], ~fetch_ring[31]};
    end

    // Execute-side shadow ring checked by the hazard unit
    always @(posedge clk) begin
        if (rst)
            exec_ring <= 32'h00000000;
        else if (advance)
            exec_ring <= {exec_ring[30:0], ~exec_ring[31]};
    end

    assign fetch_phase = fetch_ring;
    assign exec_phase  = exec_ring;

    assert property (fetch_ring[31] == exec_ring[31]);
endmodule

module tx_pace_tq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         wr,
    input  wire         wr_idx,
    input  wire [127:0] wr_data,
    input  wire         ack,
    input  wire         clr,
    output reg          fire,
    output reg          done
);
    reg [127:0] now;
    reg [127:0] dl0, dl1;
    reg [1:0]   vld;
    reg         eidx;
    reg [1:0]   phase;
    reg         started, finished, win;

    initial begin
        now = 128'd0; dl0 = 128'd0; dl1 = 128'd0; vld = 2'b00; eidx = 1'b0;
        phase = 2'd0; started = 1'b0; finished = 1'b0; win = 1'b0;
        fire = 1'b0; done = 1'b0;
    end

    wire [127:0] dl_e     = eidx ? dl1 : dl0;
    wire         start_ok = (phase == 2'd1) && vld[eidx] && (now >= dl_e);
    wire         fin_ok   = (phase == 2'd2) && ack;
    wire [1:0]   vld_clr  = (fin_ok && !clr) ? (vld & ~(2'b01 << eidx)) : vld;
    wire [1:0]   vld_n    = wr ? (vld_clr | (2'b01 << wr_idx)) : vld_clr;
    wire         eidx_n   = (vld == 2'b10) ? 1'b1 :
                            (vld == 2'b11) ? (dl1 < dl0) : 1'b0;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                now <= 128'd0; vld <= 2'b00; eidx <= 1'b0;
                phase <= 2'd0; started <= 1'b0; finished <= 1'b0; win <= 1'b0;
                fire <= 1'b0; done <= 1'b0;
            end else begin
                now  <= now + 128'd1;
                fire <= 1'b0;
                done <= 1'b0;
                eidx <= eidx_n;
                vld  <= vld_n;
                if (wr) begin
                    if (wr_idx) dl1 <= wr_data;
                    else        dl0 <= wr_data;
                end
                if (clr) begin
                    phase <= 2'd0; started <= 1'b0; finished <= 1'b0; win <= 1'b0;
                end else begin
                    case (phase)
                        2'd0: if (wr) begin phase <= 2'd1; win <= 1'b1; end
                        2'd1: if (start_ok) begin phase <= 2'd2; started <= 1'b1; fire <= 1'b1; end
                        2'd2: if (fin_ok) begin phase <= 2'd3; finished <= 1'b1; done <= 1'b1; end
                        default: ;
                    endcase
                end
            end
        end
    end

    always @(posedge clk)
        if (win && finished)
            assert (started);
endmodule

module hadesv_mie_jk (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire j,
    input wire k,
    input wire trap_enter,
    input wire mret,
    output reg q,
    output reg [31:0] tcnt,
    output reg in_trap
);
    initial q = 1'b0;
    initial tcnt = 32'h00000000;
    initial in_trap = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire q_next = (j & ~k) ? 1'b1 :
                  (~j & k) ? 1'b0 :
                  (j & k)  ? ~q   : q;

    always @(posedge clk) begin
        if (!rst_n) begin
            q <= 1'b0;
            tcnt <= 32'h00000000;
            in_trap <= 1'b0;
        end else if (en) begin
            q <= q_next;
            if (q_next != q)
                tcnt <= tcnt + 32'h00000001;
            if (mret)
                in_trap <= 1'b0;
            else if (trap_enter)
                in_trap <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (pv && rst_n && in_trap && $rose(q))
            assert (tcnt[0] == 1'b1);
    end
endmodule

module rgmii_relay_fifo (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [3:0]  rxd_rise,
    input  wire [3:0]  rxd_fall,
    input  wire        ctl_rise,
    input  wire        ctl_fall,
    input  wire        rd_en,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ
);
    reg [4:0]  cap_rise;
    reg [4:0]  cap_fall;
    reg [1:0]  byte_ph;
    reg [23:0] shift;
    reg [31:0] mem [0:3];
    reg [31:0] wr_cnt;
    reg [31:0] rd_cnt;
    reg [31:0] occ;
    reg        armed;

    initial begin
        cap_rise = 5'd0;
        cap_fall = 5'd0;
        byte_ph  = 2'd0;
        shift    = 24'd0;
        mem[0]   = 32'd0;
        mem[1]   = 32'd0;
        mem[2]   = 32'd0;
        mem[3]   = 32'd0;
        wr_cnt   = 32'd0;
        rd_cnt   = 32'd0;
        occ      = 32'd0;
        armed    = 1'b0;
    end

    wire       rx_dv   = cap_rise[4];
    wire [7:0] rx_byte = {cap_fall[3:0], cap_rise[3:0]};
    wire [31:0] diff   = wr_cnt - rd_cnt;
    wire       full    = (diff == 32'd4);
    wire       push    = en && rx_dv && (byte_ph == 2'd3) && !full;
    wire       pop     = en && rd_en && (wr_cnt != rd_cnt);

    always @(posedge clk) begin
        if (rst) begin
            cap_rise <= 5'd0;
            cap_fall <= 5'd0;
            byte_ph  <= 2'd0;
            shift    <= 24'd0;
            mem[0]   <= 32'd0;
            mem[1]   <= 32'd0;
            mem[2]   <= 32'd0;
            mem[3]   <= 32'd0;
            wr_cnt   <= 32'd0;
            rd_cnt   <= 32'd0;
            occ      <= 32'd0;
            armed    <= 1'b0;
        end else if (en) begin
            cap_rise <= {ctl_rise, rxd_rise};
            cap_fall <= {ctl_fall, rxd_fall};
            armed    <= armed | rx_dv;
            if (rx_dv) begin
                byte_ph <= byte_ph + 2'd1;
                case (byte_ph)
                    2'd0: shift[7:0]   <= rx_byte;
                    2'd1: shift[15:8]  <= rx_byte;
                    2'd2: shift[23:16] <= rx_byte;
                    default: ;
                endcase
            end
            if (push) begin
                mem[wr_cnt[1:0]] <= {rx_byte, shift};
                wr_cnt <= wr_cnt + 32'd1;
            end
            if (pop)
                rd_cnt <= rd_cnt + 32'd1;
            occ <= occ + (push ? 32'd1 : 32'd0) - (pop ? 32'd1 : 32'd0);
        end
    end

    assign dout  = mem[rd_cnt[1:0]];
    assign empty = (wr_cnt == rd_cnt);
    assign o_occ = occ;

    always @(posedge clk)
        if (armed)
            assert (occ <= 32'd4);
endmodule

module gf180_tapline_cal (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire [63:0] din,
    input  wire        cal_start,
    input  wire        cal_done,
    output wire [63:0] dout,
    output wire [7:0]  tok_o,
    output wire [63:0] cal_cnt_o,
    output wire        win_o
);
    reg [63:0] tap  [0:7];
    reg [63:0] samp [0:7];
    reg [7:0]  tok;
    reg        win;
    reg [63:0] cal_cnt;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 64'd0;
            samp[i] = 64'd0;
        end
        tok     = 8'd0;
        win     = 1'b0;
        cal_cnt = 64'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) begin
                tap[i]  <= 64'd0;
                samp[i] <= 64'd0;
            end
            tok     <= 8'd0;
            win     <= 1'b0;
            cal_cnt <= 64'd0;
        end else if (en) begin
            tap[0] <= din;
            for (i = 1; i < 8; i = i + 1)
                tap[i] <= tap[i-1];
            for (i = 0; i < 8; i = i + 1)
                samp[i] <= tap[i];
            if (cal_start) begin
                win     <= 1'b1;
                tok     <= 8'b0000_0001;
                cal_cnt <= 64'd0;
            end else if (cal_done) begin
                win <= 1'b0;
                tok <= 8'd0;
            end else if (win) begin
                tok <= tok << 1;
                if (cal_cnt != 64'hFFFF_FFFF_FFFF_FFFF)
                    cal_cnt <= cal_cnt + 64'd1;
            end else begin
                tok <= 8'd0;
            end
        end
    end

    assign dout      = samp[7];
    assign tok_o     = tok;
    assign cal_cnt_o = cal_cnt;
    assign win_o     = win;

    always @(*)
        if (win)
            assert (!(tok[6] && tok[7]));
endmodule

module tc_trace_cache (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [1:0]   op,
    input  wire [3:0]   idx,
    input  wire [31:0]  fill_start,
    input  wire [3:0]   fill_flags,
    input  wire [127:0] fill_instr,
    input  wire [31:0]  fill_next,
    input  wire         trace_begin,
    input  wire         trace_end,
    input  wire [31:0]  fetch_pc,
    output reg          hit,
    output reg  [3:0]   hit_idx,
    output reg  [3:0]   hit_flags,
    output reg  [127:0] hit_instr,
    output reg  [31:0]  hit_next
);
    reg [15:0] valid = 16'h0000;
    reg [31:0] occ   = 32'd0;
    reg        win   = 1'b0;

    reg [31:0] start_addr [0:15];
    reg [3:0]  br_flags   [0:15];
    reg [31:0] slot       [0:63];
    reg [31:0] next_fa    [0:15];

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            start_addr[i] = 32'd0;
            br_flags[i]   = 4'd0;
            next_fa[i]    = 32'd0;
        end
        for (i = 0; i < 64; i = i + 1)
            slot[i] = 32'd0;
    end

    // control state: valid, occupancy, window
    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 16'h0000;
            occ   <= 32'd0;
            win   <= 1'b0;
        end else if (en) begin
            case (op)
                2'd1: begin
                    valid[idx] <= 1'b1;
                    if (!valid[idx]) occ <= occ + 32'd1;
                end
                2'd2: begin
                    valid[idx] <= 1'b0;
                    if (valid[idx]) occ <= occ - 32'd1;
                end
                2'd3: begin
                    valid <= 16'h0000;
                    occ   <= 32'd0;
                end
                default: ;
            endcase
            if (trace_begin)
                win <= 1'b1;
            else if (trace_end || op == 2'd3)
                win <= 1'b0;
        end
    end

    // data storage
    always @(posedge clk) begin
        if (rst_n && en && op == 2'd1) begin
            start_addr[idx]        <= fill_start;
            br_flags[idx]          <= fill_flags;
            next_fa[idx]           <= fill_next;
            slot[{idx, 2'd0}]      <= fill_instr[31:0];
            slot[{idx, 2'd1}]      <= fill_instr[63:32];
            slot[{idx, 2'd2}]      <= fill_instr[95:64];
            slot[{idx, 2'd3}]      <= fill_instr[127:96];
        end
    end

    // combinational lookup
    integer j;
    always @(*) begin
        hit     = 1'b0;
        hit_idx = 4'd0;
        for (j = 15; j >= 0; j = j - 1) begin
            if (valid[j] && start_addr[j] == fetch_pc) begin
                hit     = 1'b1;
                hit_idx = j[3:0];
            end
        end
        hit_flags = br_flags[hit_idx];
        hit_next  = next_fa[hit_idx];
        hit_instr = {slot[{hit_idx, 2'd3}], slot[{hit_idx, 2'd2}],
                     slot[{hit_idx, 2'd1}], slot[{hit_idx, 2'd0}]};
    end

    // properties
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(valid))
            assert ($stable(occ));

    always @(posedge clk)
        if (win)
            assert (occ <= 32'd16);
endmodule

module zynq_pwr_dom (
    input  wire       clk,
    input  wire       en,
    input  wire       req_on,
    input  wire       req_off,
    input  wire [6:0] idx,
    output wire       root_ready,
    output wire       busy
);
    reg [127:0] dom_on;
    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

    wire do_on  = req_on && !req_off;
    wire do_off = req_off && !req_on && !pend;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (pend) begin
                prog <= prog + 8'd1;
                cd   <= cd - 8'd1;
                if (prog == 8'd19) begin
                    pend    <= 1'b0;
                    root_on <= 1'b1;
                end
            end
            if (do_on && !dom_on[idx]) begin
                dom_on[idx] <= 1'b1;
                refcnt      <= refcnt + 8'd1;
                if (refcnt == 8'd0 && !root_on && !pend) begin
                    pend <= 1'b1;
                    prog <= 8'd0;
                    cd   <= 8'd24;
                end
            end else if (do_off && dom_on[idx]) begin
                dom_on[idx] <= 1'b0;
                refcnt      <= refcnt - 8'd1;
                if (refcnt == 8'd1 && root_on) begin
                    root_on <= 1'b0;
                    first_n <= 1'b0;
                end
            end
        end
    end

    assign root_ready = root_on;
    assign busy       = pend;

    always @(posedge clk)
        if (pv && first_n && pend && $stable(pend))
            assert ($stable(cd == 8'd0) && cd != 8'd0);
endmodule

module mmio_router_tmo (
    input wire clk,
    input wire en,
    input wire cfg_we,
    input wire [5:0] cfg_idx,
    input wire [63:0] cfg_base,
    input wire [63:0] cfg_limit,
    input wire req,
    input wire [63:0] req_addr,
    input wire win_clr,
    output wire o_busy,
    output wire o_win,
    output wire [5:0] o_sel
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base  [0:63];
    reg [63:0] limit [0:63];
    reg        busy;
    reg        win;
    reg [5:0]  sel;
    reg [63:0] cnt;
    reg [63:0] age;

    integer i;
    initial begin
        busy = 1'b0;
        win  = 1'b0;
        sel  = 6'd0;
        cnt  = 64'd0;
        age  = 64'd0;
        for (i = 0; i < 64; i = i + 1) begin
            base[i]  = 64'd0;
            limit[i] = 64'd0;
        end
    end

    reg       hit;
    reg [5:0] hidx;
    integer j;
    always @(*) begin
        hit  = 1'b0;
        hidx = 6'd0;
        for (j = 63; j >= 0; j = j - 1) begin
            if ((base[j] <= req_addr) && (req_addr <= limit[j])) begin
                hit  = 1'b1;
                hidx = j[5:0];
            end
        end
    end

    wire accept = req && hit && !busy;

    always @(posedge clk) begin
        if (en) begin
            if (cfg_we) begin
                base[cfg_idx]  <= cfg_base;
                limit[cfg_idx] <= cfg_limit;
            end
            if (win_clr)
                win <= 1'b0;
            else if (accept)
                win <= 1'b1;
            if (busy) begin
                if (age == K - 64'd1) begin
                    busy <= 1'b0;
                    cnt  <= 64'd0;
                    age  <= 64'd0;
                end else begin
                    cnt <= cnt - 64'd1;
                    age <= age + 64'd1;
                end
            end else if (accept) begin
                busy <= 1'b1;
                sel  <= hidx;
                cnt  <= K;
                age  <= 64'd0;
            end
        end
    end

    assign o_busy = busy;
    assign o_win  = win;
    assign o_sel  = sel;

    always @(posedge clk)
        if (win && busy)
            assert (cnt != 64'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cnt <= K);
endmodule

module hft_feed_switch (
    input  wire         clk,
    input  wire         en,
    input  wire [3:0]   s_tvalid,
    input  wire [511:0] s_tdata,
    input  wire [7:0]   s_tdest,
    input  wire [3:0]   s_tlast,
    output wire [3:0]   s_tready,
    output wire [3:0]   m_tvalid,
    output wire [511:0] m_tdata,
    output wire [3:0]   m_tlast,
    input  wire [3:0]   m_tready
);
    reg [7:0] sel_o  = 8'd0;
    reg [3:0] lock_o = 4'd0;
    reg [3:0] busy_i = 4'd0;
    reg [7:0] dst_i  = 8'd0;
    reg       win    = 1'b0;

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            wire [1:0] s = sel_o[2*g +: 2];
            assign m_tvalid[g] = lock_o[g] && s_tvalid[s];
            assign m_tdata[128*g +: 128] = s_tdata[{s, 7'd0} +: 128];
            assign m_tlast[g] = s_tlast[s];
        end
        for (g = 0; g < 4; g = g + 1) begin : g_in
            wire [1:0] d = dst_i[2*g +: 2];
            assign s_tready[g] = en && busy_i[g] && m_tready[d];
        end
    endgenerate

    wire [3:0] rel = {4{en}} & lock_o & m_tvalid & m_tready & m_tlast;

    reg [3:0] gnt_v;
    reg [7:0] gnt_i;
    integer i, j;
    always @(*) begin
        gnt_v = 4'd0;
        gnt_i = 8'd0;
        for (j = 0; j < 4; j = j + 1) begin
            if (!lock_o[j]) begin
                for (i = 3; i >= 0; i = i - 1) begin
                    if (s_tvalid[i] && s_tdest[2*i +: 2] == j && !busy_i[i]) begin
                        gnt_v[j] = 1'b1;
                        gnt_i[2*j +: 2] = i;
                    end
                end
            end
        end
    end

    reg [3:0] lock_n, busy_n;
    reg [7:0] sel_n, dst_n;
    reg       win_n;
    always @(*) begin
        lock_n = lock_o;
        busy_n = busy_i;
        sel_n  = sel_o;
        dst_n  = dst_i;
        win_n  = win;
        for (j = 0; j < 4; j = j + 1) begin
            if (rel[j]) begin
                lock_n[j] = 1'b0;
                for (i = 0; i < 4; i = i + 1)
                    if (sel_o[2*j +: 2] == i) busy_n[i] = 1'b0;
            end
        end
        for (j = 0; j < 4; j = j + 1) begin
            if (gnt_v[j]) begin
                lock_n[j] = 1'b1;
                sel_n[2*j +: 2] = gnt_i[2*j +: 2];
                for (i = 0; i < 4; i = i + 1) begin
                    if (gnt_i[2*j +: 2] == i) begin
                        busy_n[i] = 1'b1;
                        dst_n[2*i +: 2] = j;
                    end
                end
            end
        end
        if (gnt_v[0]) win_n = 1'b1;
        else if (rel[0]) win_n = 1'b0;
    end

    always @(posedge clk) begin
        if (en) begin
            lock_o <= lock_n;
            busy_i <= busy_n;
            sel_o  <= sel_n;
            dst_i  <= dst_n;
            win    <= win_n;
        end
    end

    assert property (!(win && lock_o[0]) || ((!lock_o[1] || sel_o[3:2] != sel_o[1:0]) && (!lock_o[2] || sel_o[5:4] != sel_o[1:0]) && (!lock_o[3] || sel_o[7:6] != sel_o[1:0])));
endmodule

module tile_rf_led (
    input wire clk,
    input wire rst,
    input wire en,
    input wire ld,
    input wire [63:0] ld_data,
    input wire consume,
    input wire reshape,
    input wire [4:0] new_rows,
    output wire o_full,
    output wire [63:0] o_row0,
    output wire [63:0] o_fill
);
    localparam [4:0] DEF_ROWS = 5'd12;
    localparam [4:0] MAX_ROWS = 5'd16;

    reg [63:0] mem [0:15];
    reg [4:0] wptr;
    reg [63:0] fill_cnt;
    reg [4:0] shape_rows;
    reg pristine;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 64'd0;
        wptr = 5'd0;
        fill_cnt = 64'd0;
        shape_rows = DEF_ROWS;
        pristine = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            fill_cnt <= 64'd0;
            shape_rows <= DEF_ROWS;
            pristine <= 1'b1;
        end else if (en) begin
            if (consume) begin
                wptr <= 5'd0;
                fill_cnt <= 64'd0;
            end else if (ld && (wptr != shape_rows)) begin
                mem[wptr[3:0]] <= ld_data;
                wptr <= wptr + 5'd1;
                fill_cnt <= fill_cnt + 64'd1;
            end else if (reshape && (wptr == 5'd0)) begin
                shape_rows <= (new_rows > MAX_ROWS) ? MAX_ROWS : new_rows;
                pristine <= 1'b0;
            end
        end
    end

    assign o_full = (wptr == shape_rows);
    assign o_row0 = mem[0];
    assign o_fill = fill_cnt;

    always @(posedge clk)
        if (pristine)
            assert (fill_cnt <= 64'd12);
endmodule

module da_fir4 (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire [31:0] d0,
    input  wire [31:0] d1,
    input  wire [31:0] d2,
    input  wire [31:0] d3,
    output wire [63:0] y,
    output wire        done
);
    // fixed coefficients C0..C3 = 3, 5, 7, 11
    function [31:0] rom;
        input [3:0] a;
        begin
            case (a)
                4'd0:  rom = 32'd0;
                4'd1:  rom = 32'd3;
                4'd2:  rom = 32'd5;
                4'd3:  rom = 32'd8;
                4'd4:  rom = 32'd7;
                4'd5:  rom = 32'd10;
                4'd6:  rom = 32'd12;
                4'd7:  rom = 32'd15;
                4'd8:  rom = 32'd11;
                4'd9:  rom = 32'd14;
                4'd10: rom = 32'd16;
                4'd11: rom = 32'd19;
                4'd12: rom = 32'd18;
                4'd13: rom = 32'd21;
                4'd14: rom = 32'd23;
                default: rom = 32'd26;
            endcase
        end
    endfunction

    reg [31:0] x0, x1, x2, x3;
    reg [63:0] acc;
    reg [31:0] cnt;
    reg [31:0] rem;
    reg        busy;
    reg        win;

    initial x0 = 32'd0;
    initial x1 = 32'd0;
    initial x2 = 32'd0;
    initial x3 = 32'd0;
    initial acc = 64'd0;
    initial cnt = 32'd0;
    initial rem = 32'd32;
    initial busy = 1'b0;
    initial win = 1'b0;

    wire [3:0]  addr  = {x3[0], x2[0], x1[0], x0[0]};
    wire [63:0] slice = {32'd0, rom(addr)} << cnt;

    always @(posedge clk) begin
        if (rst) begin
            x0   <= 32'd0;
            x1   <= 32'd0;
            x2   <= 32'd0;
            x3   <= 32'd0;
            acc  <= 64'd0;
            cnt  <= 32'd0;
            rem  <= 32'd32;
            busy <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (!busy) begin
                if (start) begin
                    x0   <= d0;
                    x1   <= d1;
                    x2   <= d2;
                    x3   <= d3;
                    acc  <= 64'd0;
                    cnt  <= 32'd0;
                    rem  <= 32'd32;
                    busy <= 1'b1;
                    win  <= 1'b1;
                end
            end else begin
                acc <= acc + slice;
                x0  <= {1'b0, x0[31:1]};
                x1  <= {1'b0, x1[31:1]};
                x2  <= {1'b0, x2[31:1]};
                x3  <= {1'b0, x3[31:1]};
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
                if (cnt == 32'd31) begin
                    busy <= 1'b0;
                    win  <= 1'b0;
                end
            end
        end
    end

    assign y    = acc;
    assign done = busy && en && (cnt == 32'd31);

    // A1 / A2: bounded counts inside the window
    always @(*) if (win) assert (cnt <= 32'd32);
    always @(*) if (win) assert (rem <= 32'd32);
endmodule

module therm_totalizer (
    input  wire        clk,
    input  wire        en,
    input  wire [63:0] therm,
    output wire [63:0] out
);
    // popcount encoder
    reg [6:0] cnt;
    integer k;
    always @(*) begin
        cnt = 7'd0;
        for (k = 0; k < 64; k = k + 1)
            cnt = cnt + {6'd0, therm[k]};
    end

    wire [63:0] addend = {57'd0, cnt};

    reg [63:0] rca_sum;
    reg [63:0] cla_sum;
    reg        armed;
    reg        pv;
    initial rca_sum = 64'd0;
    initial cla_sum = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    // ripple-carry adder
    wire [64:0] rc;
    wire [63:0] rca_next;
    assign rc[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 64; i = i + 1) begin : g_rca
            assign rca_next[i] = rca_sum[i] ^ addend[i] ^ rc[i];
            assign rc[i+1] = (rca_sum[i] & addend[i]) | (rc[i] & (rca_sum[i] ^ addend[i]));
        end
    endgenerate

    // carry-lookahead adder, 4-bit groups
    wire [63:0] cg = cla_sum & addend;
    wire [63:0] cp = cla_sum ^ addend;
    wire [63:0] cc;
    wire [16:0] gcarry;
    wire [63:0] cla_next;
    assign gcarry[0] = 1'b0;
    genvar j;
    generate
        for (j = 0; j < 16; j = j + 1) begin : g_cla
            wire g0 = cg[4*j];   wire p0 = cp[4*j];
            wire g1 = cg[4*j+1]; wire p1 = cp[4*j+1];
            wire g2 = cg[4*j+2]; wire p2 = cp[4*j+2];
            wire g3 = cg[4*j+3]; wire p3 = cp[4*j+3];
            wire c0 = gcarry[j];
            assign cc[4*j]   = c0;
            assign cc[4*j+1] = g0 | (p0 & c0);
            assign cc[4*j+2] = g1 | (p1 & g0) | (p1 & p0 & c0);
            assign cc[4*j+3] = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);
            wire GG = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            wire PP = p3 & p2 & p1 & p0;
            assign gcarry[j+1] = GG | (PP & c0);
        end
    endgenerate
    assign cla_next = cp ^ cc;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            rca_sum <= rca_next;
            cla_sum <= cla_next;
            armed   <= armed | therm[63];
        end
    end

    assign out = rca_sum;

    always @(posedge clk)
        if (pv && armed && $past(en))
            assert (rca_sum == $past(cla_sum) + {57'd0, $past(cnt)});
endmodule

module dbg_failover_mux (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [7:0] pri_data,
    input  wire [7:0] bak_data,
    input  wire       pri_fault,
    input  wire       pri_ok,
    output wire [7:0] out_data
);
    reg [7:0] health     = 8'd0;
    reg       arm_f      = 1'b0;
    reg       start_f    = 1'b0;
    reg       fin_f      = 1'b0;
    reg       active_src = 1'b0;
    reg       pv         = 1'b0;

    assign out_data = active_src ? bak_data : pri_data;

    always @(posedge clk) begin
        if (!rst_n) begin
            health     <= 8'd0;
            arm_f      <= 1'b0;
            start_f    <= 1'b0;
            fin_f      <= 1'b0;
            active_src <= 1'b0;
        end else if (en) begin
            if (pri_ok && fin_f && active_src) begin
                health     <= 8'd0;
                arm_f      <= 1'b0;
                start_f    <= 1'b0;
                fin_f      <= 1'b0;
                active_src <= 1'b0;
            end else begin
                if (pri_fault && health != 8'hFF)
                    health <= health + 8'd1;
                if (health >= 8'd3 && !arm_f)
                    arm_f <= 1'b1;
                if (arm_f && pri_fault && !start_f)
                    start_f <= 1'b1;
                if (start_f && !fin_f)
                    fin_f <= 1'b1;
                if (start_f && arm_f && !active_src)
                    active_src <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(fin_f))
            assert ($stable(active_src));
endmodule

module orbit_mrs_unit (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        req_valid,
    input  wire [2:0]  req_idx,
    input  wire [15:0] req_data,
    input  wire        cfg_lock,
    output wire        busy,
    output reg         mrs_cmd_valid,
    output reg  [18:0] mrs_cmd
);
    reg [15:0] shadow [0:7];
    reg [7:0]  pend;
    reg [2:0]  cur_idx;
    reg [15:0] cur_data;
    reg [15:0] cnt;
    reg        win;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) shadow[i] = 16'd0;
        pend = 8'd0;
        cur_idx = 3'd0;
        cur_data = 16'd0;
        cnt = 16'd0;
        win = 1'b0;
        mrs_cmd_valid = 1'b0;
        mrs_cmd = 19'd0;
    end

    assign busy = |pend;

    wire accept   = req_valid && !busy;
    wire countdn  = busy && (cnt > 16'd1);
    wire complete = busy && (cnt == 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) shadow[i] <= 16'd0;
            pend <= 8'd0;
            cur_idx <= 3'd0;
            cur_data <= 16'd0;
            cnt <= 16'd0;
            win <= 1'b0;
            mrs_cmd_valid <= 1'b0;
            mrs_cmd <= 19'd0;
        end else if (en) begin
            mrs_cmd_valid <= 1'b0;
            if (accept) begin
                pend[req_idx] <= 1'b1;
                cur_idx <= req_idx;
                cur_data <= req_data;
                cnt <= 16'd8;
                mrs_cmd_valid <= 1'b1;
                mrs_cmd <= {req_idx, req_data};
            end else if (countdn) begin
                cnt <= cnt - 16'd1;
            end else if (complete) begin
                for (i = 0; i < 8; i = i + 1)
                    if (cur_idx == i[2:0]) shadow[i] <= cur_data;
                pend[cur_idx] <= 1'b0;
                cnt <= 16'd0;
            end
            if (accept)
                win <= 1'b1;
            else if (cfg_lock)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy) assert (cnt != 16'd0);
endmodule

module dram_ret_est (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [3:0] x,
    output wire [7:0] est
);
    reg [7:0] tiv0, tiv1, tiv2, tiv3;
    reg [7:0] to0, to1, to2, to3;
    reg [3:0] idx1, idx2;
    reg [7:0] tiv_r, to_r, sum_q;
    reg       arm;

    initial begin
        tiv0 = 8'd200; tiv1 = 8'd150; tiv2 = 8'd100; tiv3 = 8'd60;
        to0  = 8'd0;   to1  = 8'd12;  to2  = 8'd24;  to3  = 8'd36;
        idx1 = 4'd0; tiv_r = 8'd200; to_r = 8'd0;
        idx2 = 4'd0; sum_q = 8'd200; arm = 1'b0;
    end

    wire [7:0] tiv_sel = (x[3:2] == 2'd0) ? tiv0 :
                         (x[3:2] == 2'd1) ? tiv1 :
                         (x[3:2] == 2'd2) ? tiv2 : tiv3;
    wire [7:0] to_sel  = (x[1:0] == 2'd0) ? to0 :
                         (x[1:0] == 2'd1) ? to1 :
                         (x[1:0] == 2'd2) ? to2 : to3;

    always @(posedge clk) begin
        if (rst) begin
            tiv0 <= 8'd200; tiv1 <= 8'd150; tiv2 <= 8'd100; tiv3 <= 8'd60;
            to0  <= 8'd0;   to1  <= 8'd12;  to2  <= 8'd24;  to3  <= 8'd36;
            idx1 <= 4'd0; tiv_r <= 8'd200; to_r <= 8'd0;
            idx2 <= 4'd0; sum_q <= 8'd200; arm <= 1'b0;
        end else if (en) begin
            idx1  <= x;
            tiv_r <= tiv_sel;
            to_r  <= to_sel;
            idx2  <= idx1;
            sum_q <= tiv_r + to_r;
            arm   <= 1'b1;
        end
    end

    assign est = sum_q;

    wire [7:0] exp_tiv2 = (idx2[3:2] == 2'd0) ? 8'd200 :
                          (idx2[3:2] == 2'd1) ? 8'd150 :
                          (idx2[3:2] == 2'd2) ? 8'd100 : 8'd60;
    wire [7:0] exp_to2  = (idx2[1:0] == 2'd0) ? 8'd0 :
                          (idx2[1:0] == 2'd1) ? 8'd12 :
                          (idx2[1:0] == 2'd2) ? 8'd24 : 8'd36;
    wire [7:0] exp_sum2 = exp_tiv2 + exp_to2;

    always @(posedge clk)
        if (arm)
            assert (sum_q == exp_sum2);
endmodule

module sd_line_fill_uart #(
    parameter [15:0] CLKS_PER_BIT = 16'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rx,
    input  wire        flush,
    output wire [15:0] o_occ,
    output wire        o_full,
    output wire        o_ferr,
    output wire [15:0] o_word0
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_START = 2'd1;
    localparam [1:0] S_DATA  = 2'd2;
    localparam [1:0] S_STOP  = 2'd3;

    reg [1:0]  st;
    reg [15:0] baud_cnt;
    reg [15:0] bit_cnt;
    reg [15:0] shreg;
    reg [15:0] line [0:7];
    reg [2:0]  wr_ptr;
    reg [15:0] occ;
    reg        line_full;
    reg        frame_err;
    reg        armed;
    reg        rx_prev;

    integer i;
    initial begin
        st = S_IDLE;
        baud_cnt = 16'd0;
        bit_cnt = 16'd0;
        shreg = 16'd0;
        wr_ptr = 3'd0;
        occ = 16'd0;
        line_full = 1'b0;
        frame_err = 1'b0;
        armed = 1'b0;
        rx_prev = 1'b1;
        for (i = 0; i < 8; i = i + 1) line[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            baud_cnt <= 16'd0;
            bit_cnt <= 16'd0;
            shreg <= 16'd0;
            wr_ptr <= 3'd0;
            occ <= 16'd0;
            line_full <= 1'b0;
            frame_err <= 1'b0;
            armed <= 1'b0;
            rx_prev <= 1'b1;
        end else if (en) begin
            rx_prev <= rx;
            case (st)
                S_IDLE: begin
                    baud_cnt <= 16'd0;
                    bit_cnt <= 16'd0;
                    if (rx_prev && !rx) st <= S_START;
                end
                S_START: begin
                    if (baud_cnt == (CLKS_PER_BIT >> 1) - 16'd1) begin
                        baud_cnt <= 16'd0;
                        if (!rx) st <= S_DATA;
                        else st <= S_IDLE;
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_DATA: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        shreg <= {rx, shreg[15:1]};
                        if (bit_cnt == 16'd15) begin
                            bit_cnt <= 16'd0;
                            st <= S_STOP;
                        end else begin
                            bit_cnt <= bit_cnt + 16'd1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_STOP: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        st <= S_IDLE;
                        if (!rx) begin
                            frame_err <= 1'b1;
                        end else if (!line_full) begin
                            line[wr_ptr] <= shreg;
                            wr_ptr <= wr_ptr + 3'd1;
                            occ <= occ + 16'd1;
                            line_full <= ((occ + 16'd1) == 16'd8);
                            armed <= 1'b1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
            endcase
            if (flush) begin
                occ <= 16'd0;
                wr_ptr <= 3'd0;
                line_full <= 1'b0;
                frame_err <= 1'b0;
            end
        end
    end

    assign o_occ = occ;
    assign o_full = line_full;
    assign o_ferr = frame_err;
    assign o_word0 = line[0];

    always @(posedge clk)
        if (armed)
            assert (occ <= 16'd8);
endmodule

module perfect_id_rom (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    output wire [31:0] rdata,
    output wire        last
);
    localparam [31:0] ROM_VENDOR    = 32'h49424D00;
    localparam [31:0] ROM_PART      = 32'h50455246;
    localparam [31:0] ROM_REVISION  = 32'h00000003;
    localparam [31:0] ROM_FEAT0     = 32'h0000C3A5;
    localparam [31:0] ROM_FEAT1     = 32'h00000011;
    localparam [31:0] ROM_SIGNATURE = 32'h43484933;
    localparam [31:0] LAST_IDX      = 32'd5;

    reg [31:0] ptr;
    reg [31:0] remaining;
    reg [31:0] rdata_q;
    initial begin
        ptr       = 32'd0;
        remaining = LAST_IDX;
        rdata_q   = 32'd0;
    end

    reg [31:0] rom_word;
    always @(*) begin
        case (ptr)
            32'd0:   rom_word = ROM_VENDOR;
            32'd1:   rom_word = ROM_PART;
            32'd2:   rom_word = ROM_REVISION;
            32'd3:   rom_word = ROM_FEAT0;
            32'd4:   rom_word = ROM_FEAT1;
            32'd5:   rom_word = ROM_SIGNATURE;
            default: rom_word = 32'd0;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            ptr       <= 32'd0;
            remaining <= LAST_IDX;
            rdata_q   <= 32'd0;
        end else if (en) begin
            rdata_q   <= rom_word;
            ptr       <= (remaining == 32'd0) ? 32'd0 : ptr + 32'd1;
            remaining <= (ptr == LAST_IDX) ? LAST_IDX : remaining - 32'd1;
        end
    end

    assign rdata = rdata_q;
    assign last  = (remaining == 32'd0);

    assert property (ptr <= 32'd5);
    assert property (remaining <= 32'd5);
endmodule

module json_key_fuzzy_match (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] key_in,
    input wire [7:0] query,
    input wire ld_tol,
    input wire [3:0] tol_in,
    input wire q_open,
    input wire q_close,
    output reg near,
    output reg far,
    output reg win
);
    reg [3:0] tol;
    reg pv;
    initial tol = 4'd0;
    initial near = 1'b0;
    initial far = 1'b1;
    initial win = 1'b0;
    initial pv = 1'b0;

    wire [7:0] diff = key_in ^ query;
    wire [3:0] dist = {3'd0, diff[0]} + {3'd0, diff[1]} + {3'd0, diff[2]} + {3'd0, diff[3]}
                    + {3'd0, diff[4]} + {3'd0, diff[5]} + {3'd0, diff[6]} + {3'd0, diff[7]};
    wire near_nxt = (dist <= tol);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            tol  <= 4'd0;
            near <= 1'b0;
            far  <= 1'b1;
            win  <= 1'b0;
        end else if (en) begin
            if (ld_tol) tol <= tol_in;
            near <= near_nxt;
            far  <= far ^ (near ^ near_nxt);
            win  <= q_open ? 1'b1 : (q_close ? 1'b0 : win);
        end
    end

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(near) && $past(far)));
endmodule

module monocle_bscan (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        capture,
    input  wire        update,
    input  wire        shift,
    input  wire        tdi,
    input  wire [23:0] pins_in,
    output wire        tdo,
    output wire [23:0] pins_out
);
    reg [23:0] shift_reg   = 24'd0;
    reg [23:0] update_reg  = 24'd0;
    reg [15:0] shifted_cnt = 16'd0;
    reg [15:0] remain_cnt  = 16'd24;
    reg        armed       = 1'b0;

    assign tdo      = shift_reg[0];
    assign pins_out = update_reg;

    wire frame_full  = (remain_cnt == 16'd0);
    wire frame_empty = (shifted_cnt == 16'd0);

    always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg   <= 24'd0;
            update_reg  <= 24'd0;
            shifted_cnt <= 16'd0;
            remain_cnt  <= 16'd24;
            armed       <= 1'b0;
        end else if (en) begin
            if (capture) begin
                shift_reg   <= pins_in;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
                armed       <= 1'b1;
            end else if (update) begin
                update_reg  <= shift_reg;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
            end else if (shift && (remain_cnt != 16'd0)) begin
                shift_reg   <= {tdi, shift_reg[23:1]};
                shifted_cnt <= shifted_cnt + 16'd1;
                remain_cnt  <= remain_cnt - 16'd1;
            end
        end
    end

    always @(*)
        if (armed)
            assert (!(frame_full && frame_empty));
endmodule

module friscv_hart_rst_sync (
    input wire clk,
    input wire arst_n,
    input wire en,
    input wire soft_req,
    output wire hart_rst_n
);
    reg [3:0]  sync = 4'b0000;
    reg [63:0] cnt  = 64'd0;
    reg        pend = 1'b0;
    reg        win  = 1'b0;

    always @(posedge clk or negedge arst_n) begin
        if (!arst_n) begin
            sync <= 4'b0000;
            cnt  <= 64'd0;
            pend <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (soft_req && !pend) begin
                sync <= 4'b0000;
                cnt  <= 64'd6;
                pend <= 1'b1;
                win  <= 1'b1;
            end else if (pend && sync != 4'b1111) begin
                sync <= {sync[2:0], 1'b1};
                cnt  <= cnt - 64'd1;
            end else if (pend) begin
                pend <= 1'b0;
                win  <= 1'b0;
            end
        end
    end

    assign hart_rst_n = sync[3];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(sync[3]))
            assert (cnt != 64'd0);
endmodule

module hack_rowfix (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [63:0] row_addr,
    input wire fuse_load,
    input wire [3:0] fuse_idx,
    input wire [63:0] fuse_val,
    input wire fuse_reload,
    output reg [4:0] spare_sel,
    output reg [63:0] row_out
);
    reg [63:0] fuse_addr [0:15];
    reg [15:0] fuse_en;
    reg [63:0] lat_addr;
    reg busy;
    reg [4:0] idx;
    reg [63:0] cnt;
    reg hit;
    reg [3:0] hit_slot;
    reg pre_ev;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fuse_addr[i] = 64'd0;
    end
    initial fuse_en = 16'd0;
    initial lat_addr = 64'd0;
    initial busy = 1'b0;
    initial idx = 5'd0;
    initial cnt = 64'd0;
    initial hit = 1'b0;
    initial hit_slot = 4'd0;
    initial pre_ev = 1'b1;
    initial spare_sel = 5'd0;
    initial row_out = 64'd0;

    // combinational compare of the current 4-entry window
    reg win_hit;
    reg [3:0] win_slot;
    reg [3:0] s;
    integer k;
    always @(*) begin
        win_hit = 1'b0;
        win_slot = 4'd0;
        s = 4'd0;
        for (k = 3; k >= 0; k = k - 1) begin
            s = idx[3:0] + k;
            if (fuse_en[s] && (fuse_addr[s] == lat_addr)) begin
                win_hit = 1'b1;
                win_slot = s;
            end
        end
    end

    wire fin_hit = hit | win_hit;
    wire [3:0] fin_slot = hit ? hit_slot : win_slot;

    always @(posedge clk) begin
        if (rst) begin
            fuse_en <= 16'd0;
            lat_addr <= 64'd0;
            busy <= 1'b0;
            idx <= 5'd0;
            cnt <= 64'd0;
            hit <= 1'b0;
            hit_slot <= 4'd0;
            pre_ev <= 1'b1;
            spare_sel <= 5'd0;
            row_out <= 64'd0;
        end else if (en) begin
            if (fuse_load) begin
                fuse_addr[fuse_idx] <= fuse_val;
                fuse_en[fuse_idx] <= 1'b1;
            end
            if (fuse_reload) begin
                idx <= 5'd0;
                pre_ev <= 1'b0;
            end else if (busy) begin
                if (win_hit && !hit) begin
                    hit <= 1'b1;
                    hit_slot <= win_slot;
                end
                if (idx == 5'd12) begin
                    busy <= 1'b0;
                    if (fin_hit) begin
                        spare_sel <= {1'b1, fin_slot};
                        row_out <= 64'hFFFF_FFFF_FFFF_FFF0 | {60'd0, fin_slot};
                    end else begin
                        spare_sel <= 5'd0;
                        row_out <= lat_addr;
                    end
                end else begin
                    idx <= idx + 5'd4;
                    cnt <= cnt - 64'd1;
                end
            end else if (req) begin
                lat_addr <= row_addr;
                busy <= 1'b1;
                idx <= 5'd0;
                cnt <= 64'd4;
                hit <= 1'b0;
            end
        end
    end

    always @(*)
        if (pre_ev && busy)
            assert ((cnt != 64'd0) && (idx < 5'd16));
endmodule

module golay_scrub (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [3:0]  wr_addr,
    input  wire [11:0] wr_data,
    input  wire        inj,
    input  wire [3:0]  inj_addr,
    input  wire [23:0] inj_mask,
    input  wire        scrub_start,
    input  wire        scrub_done,
    output wire [31:0] o_corr_cnt,
    output wire [31:0] o_inj_cnt,
    output wire [11:0] o_syn,
    output wire        o_win
);
    function [11:0] brow;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:  brow = 12'hDC5;
                4'd1:  brow = 12'hB8B;
                4'd2:  brow = 12'h717;
                4'd3:  brow = 12'hE2D;
                4'd4:  brow = 12'hC5B;
                4'd5:  brow = 12'h8B7;
                4'd6:  brow = 12'h16F;
                4'd7:  brow = 12'h2DD;
                4'd8:  brow = 12'h5B9;
                4'd9:  brow = 12'hB71;
                4'd10: brow = 12'h6E3;
                default: brow = 12'hFFE;
            endcase
        end
    endfunction

    function [11:0] mulB;
        input [11:0] v;
        integer j;
        begin
            mulB = 12'h000;
            for (j = 0; j < 12; j = j + 1)
                if (v[j]) mulB = mulB ^ brow(j);
        end
    endfunction

    function [3:0] wt12;
        input [11:0] v;
        integer j;
        begin
            wt12 = 4'd0;
            for (j = 0; j < 12; j = j + 1)
                wt12 = wt12 + {3'b000, v[j]};
        end
    endfunction

    function [23:0] encode;
        input [11:0] d;
        begin
            encode = {d, mulB(d)};
        end
    endfunction

    function [11:0] syndrome;
        input [23:0] r;
        begin
            syndrome = mulB(r[23:12]) ^ r[11:0];
        end
    endfunction

    function [23:0] golay_err;
        input [11:0] s;
        reg [11:0] s2;
        reg found;
        integer j;
        begin
            golay_err = 24'h000000;
            found = 1'b0;
            if (wt12(s) <= 4'd3) begin
                golay_err = {12'h000, s};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(12'h001 << j), (s ^ brow(j))};
                    found = 1'b1;
                end
            s2 = mulB(s);
            if (!found && (wt12(s2) <= 4'd3)) begin
                golay_err = {s2, 12'h000};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s2 ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(s2 ^ brow(j)), (12'h001 << j)};
                    found = 1'b1;
                end
        end
    endfunction

    reg [23:0] mem [0:15];
    reg [15:0] err_flag;
    reg [11:0] syn_reg;
    reg [3:0]  scan_ptr;
    reg [31:0] inj_cnt;
    reg [31:0] corr_cnt;
    reg        inj_seen;
    reg        win;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1)
            mem[k] = 24'h000000;
        err_flag = 16'h0000;
        syn_reg  = 12'h000;
        scan_ptr = 4'd0;
        inj_cnt  = 32'd0;
        corr_cnt = 32'd0;
        inj_seen = 1'b0;
        win      = 1'b0;
    end

    wire [23:0] cur     = mem[scan_ptr];
    wire [11:0] cur_syn = syndrome(cur);
    wire [23:0] cur_err = golay_err(cur_syn);

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1)
                mem[k] <= 24'h000000;
            err_flag <= 16'h0000;
            syn_reg  <= 12'h000;
            scan_ptr <= 4'd0;
            inj_cnt  <= 32'd0;
            corr_cnt <= 32'd0;
            inj_seen <= 1'b0;
            win      <= 1'b0;
        end else if (en) begin
            if (scrub_start)
                win <= 1'b1;
            else if (scrub_done)
                win <= 1'b0;
            if (win) begin
                syn_reg <= cur_syn;
                if (err_flag[scan_ptr]) begin
                    mem[scan_ptr]      <= cur ^ cur_err;
                    err_flag[scan_ptr] <= 1'b0;
                    corr_cnt           <= corr_cnt + 32'd1;
                end
                scan_ptr <= scan_ptr + 4'd1;
            end
            if (inj) begin
                mem[inj_addr]      <= mem[inj_addr] ^ inj_mask;
                err_flag[inj_addr] <= 1'b1;
                inj_cnt            <= inj_cnt + 32'd1;
                inj_seen           <= 1'b1;
            end
            if (wr) begin
                mem[wr_addr]      <= encode(wr_data);
                err_flag[wr_addr] <= 1'b0;
            end
        end
    end

    assign o_corr_cnt = corr_cnt;
    assign o_inj_cnt  = inj_cnt;
    assign o_syn      = syn_reg;
    assign o_win      = win;

    assert property (!(win && corr_cnt != 32'd0) || inj_seen);
endmodule

module hdmi_line_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        line_start,
    input  wire        line_stop,
    input  wire [31:0] sample_in,
    output reg  [31:0] y
);
    reg [31:0] win_rom [0:255];
    reg [31:0] idx;
    reg [31:0] dn;
    reg        win;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            if (i < 128)
                win_rom[i] = i * i * 4;
            else
                win_rom[i] = (255 - i) * (255 - i) * 4;
        end
    end

    initial begin
        idx = 32'd0;
        dn  = 32'd255;
        win = 1'b0;
        y   = 32'd0;
    end

    wire [32:0] coef_sum = {1'b0, win_rom[idx[7:0]]} + {1'b0, win_rom[dn[7:0]]};
    wire [31:0] coef     = coef_sum[32:1];
    wire [63:0] prod     = sample_in * coef;

    always @(posedge clk) begin
        if (rst) begin
            idx <= 32'd0;
            dn  <= 32'd255;
            win <= 1'b0;
            y   <= 32'd0;
        end else if (en) begin
            if (dn == 32'd0) begin
                idx <= 32'd0;
                dn  <= 32'd255;
            end else begin
                idx <= idx + 32'd1;
                dn  <= dn - 32'd1;
            end
            win <= line_start ? 1'b1 : (line_stop ? 1'b0 : win);
            y   <= prod[31:0];
        end
    end

    assert property (!win || idx <= 32'd255);
endmodule

module jls_pausible_clkctl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire areq,
    input wire mutex_gnt,
    input wire [31:0] din,
    input wire sof,
    input wire eof,
    input wire [7:0] raddr,
    output wire [31:0] dout,
    output wire ring_clk_en
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2;

    reg [1:0] phase = 2'd0;
    reg hs_latch = 1'b0;
    reg clk_en = 1'b1;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    reg [7:0] wptr = 8'd0;
    reg win = 1'b0;
    reg [31:0] linebuf [0:255];

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            linebuf[i] = 32'd0;
    end

    assign dout = linebuf[raddr];
    assign ring_clk_en = clk_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            hs_latch <= 1'b0;
            clk_en <= 1'b1;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
            wptr <= 8'd0;
            win <= 1'b0;
        end else if (en) begin
            if (eof)
                win <= 1'b0;
            else if (sof)
                win <= 1'b1;
            case (phase)
                IDLE: begin
                    if (areq) begin
                        hs_latch <= 1'b1;
                        phase <= ARMED;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
                end
                default: begin
                    phase <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst_n && en && phase == STARTED)
            linebuf[wptr] <= din;
    end

    always @(posedge clk)
        if (win && phase == 2'd2)
            assert (arm_cnt == start_cnt && start_cnt == fin_cnt + 32'd1 && !clk_en);
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
    wire pop       = nonempty && free_slot;
    wire push_ok   = push && (q_count < 5'd16);
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
endmodule

module hfrisc_ctx_save_mux (
    input  wire          clk,
    input  wire          rst,
    input  wire          en,
    input  wire [1023:0] rf_flat,
    output reg  [31:0]   dout
);
    reg [31:0] sel;
    reg [4:0]  idx;
    initial begin
        sel = 32'h00000001;
        idx = 5'd0;
    end

    wire [4:0] idx_n = idx + 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            sel <= 32'h00000001;
            idx <= 5'd0;
        end else if (en) begin
            sel <= sel ^ (32'h00000001 << idx) ^ (32'h00000001 << idx_n);
            idx <= idx_n;
        end
    end

    integer i;
    always @(*) begin
        dout = 32'h00000000;
        for (i = 0; i < 32; i = i + 1)
            dout = dout | (rf_flat[i*32 +: 32] & {32{sel[i]}});
    end

    always @(*) assert ((sel != 32'h00000000) && ((sel & (sel - 32'h00000001)) == 32'h00000000));
endmodule

module babysoc_padmux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr,
    input wire [2:0] wr_idx,
    input wire [2:0] wr_func,
    input wire lock_req,
    input wire [7:0] gpio_out,
    input wire pll_clk,
    input wire dac_bit,
    input wire uart_tx,
    output wire [7:0] pad_out,
    output wire o_err,
    output wire o_locked
);
    reg [23:0] func_sel;
    reg [31:0] wr_cnt;
    reg [31:0] cm_cnt;
    reg err;
    reg locked;
    reg pre_lock;
    integer k;

    initial begin
        func_sel = 24'd0;
        wr_cnt = 32'd0;
        cm_cnt = 32'd0;
        err = 1'b0;
        locked = 1'b0;
        pre_lock = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            func_sel <= 24'd0;
            wr_cnt <= 32'd0;
            cm_cnt <= 32'd0;
            err <= 1'b0;
            locked <= 1'b0;
            pre_lock <= 1'b1;
        end else if (en) begin
            if (wr && !locked) begin
                for (k = 0; k < 8; k = k + 1)
                    if (wr_idx == k) func_sel[k*3 +: 3] <= wr_func;
                wr_cnt <= wr_cnt + 32'd1;
                cm_cnt <= cm_cnt + 32'd1;
            end
            err <= err | (wr_cnt != cm_cnt);
            if (lock_req) begin
                locked <= 1'b1;
                pre_lock <= 1'b0;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : pads
            wire [2:0] fs = func_sel[g*3 +: 3];
            assign pad_out[g] = (fs == 3'd0) ? gpio_out[g] :
                                (fs == 3'd1) ? pll_clk :
                                (fs == 3'd2) ? dac_bit :
                                (fs == 3'd3) ? uart_tx : 1'b0;
        end
    endgenerate

    assign o_err = err;
    assign o_locked = locked;

    always @(posedge clk)
        if (pre_lock)
            assert (!err);
endmodule

module hdlbits_cam (
    input wire clk,
    input wire rst,
    input wire en,
    input wire lookup,
    input wire [63:0] lookup_key,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] wr_key,
    output wire hit,
    output wire [1:0] hit_vec
);
    reg [63:0] key_mem [0:1];
    reg [1:0] valid;
    reg s1_vld;
    reg [31:0] s1_key_hi;
    reg [1:0] s1_pm;
    reg s2_vld;
    reg [1:0] s2_match;
    reg [63:0] inflight;
    reg armed;

    initial key_mem[0] = 64'd0;
    initial key_mem[1] = 64'd0;
    initial valid = 2'b00;
    initial s1_vld = 1'b0;
    initial s1_key_hi = 32'd0;
    initial s1_pm = 2'b00;
    initial s2_vld = 1'b0;
    initial s2_match = 2'b00;
    initial inflight = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            key_mem[0] <= 64'd0;
            key_mem[1] <= 64'd0;
            valid <= 2'b00;
            s1_vld <= 1'b0;
            s1_key_hi <= 32'd0;
            s1_pm <= 2'b00;
            s2_vld <= 1'b0;
            s2_match <= 2'b00;
            inflight <= 64'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (wr_en) begin
                key_mem[wr_idx] <= wr_key;
                valid[wr_idx] <= 1'b1;
            end
            s1_vld <= lookup;
            s1_key_hi <= lookup_key[63:32];
            s1_pm[0] <= valid[0] & (key_mem[0][31:0] == lookup_key[31:0]);
            s1_pm[1] <= valid[1] & (key_mem[1][31:0] == lookup_key[31:0]);
            s2_vld <= s1_vld;
            s2_match[0] <= s1_pm[0] & (key_mem[0][63:32] == s1_key_hi);
            s2_match[1] <= s1_pm[1] & (key_mem[1][63:32] == s1_key_hi);
            inflight <= inflight + {63'd0, lookup} - {63'd0, s2_vld};
            armed <= armed | lookup;
        end
    end

    assign hit_vec = s2_vld ? s2_match : 2'b00;
    assign hit = |hit_vec;

    always @(*) assert (!armed || inflight <= 64'd2);
endmodule

module doomsday_cdr (
    input wire clk,
    input wire rst,
    input wire en,
    input wire rx,
    output reg finished
);
    reg [3:0]  samp;
    reg [1:0]  phase_sel;
    reg [2:0]  vote;
    reg [1:0]  os_cnt;
    reg [15:0] bit_cnt;
    reg        armed;
    reg        started;
    reg        no_slip;
    reg        prev_bit;

    initial begin
        samp = 4'b1111; phase_sel = 2'd0; vote = 3'b111; os_cnt = 2'd0;
        bit_cnt = 16'd0; armed = 1'b0; started = 1'b0; finished = 1'b0;
        no_slip = 1'b1; prev_bit = 1'b1;
    end

    wire [1:0] ph_m     = phase_sel - 2'd1;
    wire [1:0] ph_p     = phase_sel + 2'd1;
    wire [1:0] exp_edge = phase_sel + 2'd2;
    wire [1:0] dist     = os_cnt - exp_edge;
    wire edge_det  = samp[0] ^ rx;
    wire slip      = edge_det && (os_cnt != exp_edge);
    wire bit_valid = (os_cnt == 2'd3);
    wire rec_bit   = (vote[0] & vote[1]) | (vote[0] & vote[2]) | (vote[1] & vote[2]);
    wire idle_edge = (samp == 4'b1111) && !rx;

    always @(posedge clk) begin
        if (rst) begin
            samp <= 4'b1111; phase_sel <= 2'd0; vote <= 3'b111; os_cnt <= 2'd0;
            bit_cnt <= 16'd0; armed <= 1'b0; started <= 1'b0; finished <= 1'b0;
            no_slip <= 1'b1; prev_bit <= 1'b1;
        end else if (en) begin
            samp   <= {samp[2:0], rx};
            os_cnt <= os_cnt + 2'd1;
            vote   <= {samp[ph_p], samp[phase_sel], samp[ph_m]};
            if (slip) begin
                no_slip <= 1'b0;
                if (dist[1] == 1'b0) phase_sel <= phase_sel + 2'd1;
                else                 phase_sel <= phase_sel - 2'd1;
            end
            if (bit_valid) prev_bit <= rec_bit;
            if (idle_edge) armed <= 1'b1;
            if (armed && bit_valid && prev_bit && !rec_bit) started <= 1'b1;
            if (started && !finished && bit_valid && bit_cnt != 16'd383)
                bit_cnt <= bit_cnt + 16'd1;
            if (started && bit_cnt == 16'd383) finished <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_slip)
            assert (!finished || $past(armed));
endmodule

module metro_led_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr_en,
    input  wire [5:0]  wr_addr,
    input  wire [63:0] wr_data,
    output wire [63:0] row_drv,
    output wire [63:0] col_drv
);
    reg [63:0] frame_mem_r [0:63];
    reg [63:0] row_idx_r = 64'd0;
    reg [63:0] row_sel_r = 64'h0000_0000_0000_0001;
    reg [63:0] col_r     = 64'd0;
    reg        armed_r   = 1'b0;
    reg        pv_r      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1)
            frame_mem_r[i] = 64'd0;
    end

    assign row_drv = row_sel_r;
    assign col_drv = col_r;

    always_ff @(posedge clk) begin
        if (wr_en)
            frame_mem_r[wr_addr] <= wr_data;
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_idx_r <= 64'd0;
        else if (en)
            row_idx_r <= (row_idx_r == 64'd63) ? 64'd0 : (row_idx_r + 64'd1);
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_sel_r <= 64'h0000_0000_0000_0001;
        else if (en)
            row_sel_r <= {row_sel_r[62:0], row_sel_r[63]};
    end

    always_ff @(posedge clk) begin
        if (rst)
            col_r <= 64'd0;
        else if (en)
            col_r <= frame_mem_r[row_idx_r[5:0]];
    end

    always_ff @(posedge clk) begin
        if (rst)
            armed_r <= 1'b0;
        else if (en && (row_idx_r == 64'd63))
            armed_r <= 1'b1;
    end

    always_ff @(posedge clk) begin
        pv_r <= 1'b1;
    end

    always @(posedge clk) begin
        if (pv_r && $past(armed_r))
            assert (!($past(row_sel_r[0]) && $past(row_sel_r[63])));
    end
endmodule

module isp_fb_sema (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [31:0] req_id,
    input wire [5:0] cell_sel,
    input wire arm_req,
    input wire start_req,
    input wire fin_req,
    output wire [1:0] o_phase,
    output wire [47:0] o_locked,
    output wire [31:0] o_cur_owner
);
    reg [47:0] locked = 48'd0;
    reg [31:0] owner [0:47];
    reg [5:0] cur_cell = 6'd0;
    reg [1:0] phase = 2'd0;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) owner[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            locked <= 48'd0;
            cur_cell <= 6'd0;
            phase <= 2'd0;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
        end else if (en) begin
            case (phase)
                2'd0: begin
                    if (arm_req && (cell_sel < 6'd48) && !locked[cell_sel]) begin
                        locked[cell_sel] <= 1'b1;
                        owner[cell_sel] <= req_id;
                        cur_cell <= cell_sel;
                        phase <= 2'd1;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                2'd1: begin
                    if (start_req) begin
                        phase <= 2'd2;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                2'd2: begin
                    if (fin_req) begin
                        locked[cur_cell] <= 1'b0;
                        phase <= 2'd0;
                        fin_cnt <= fin_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_locked = locked;
    assign o_cur_owner = owner[cur_cell];

    always @(*) assert (((arm_cnt - start_cnt) <= 32'd1) && ((start_cnt - fin_cnt) <= 32'd1));
endmodule

module vid_gearbox_128b130b (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         sof,
    input  wire         eof,
    input  wire         in_v,
    input  wire [127:0] in_data,
    input  wire         in_ctl,
    output reg          out_v,
    output reg  [127:0] out_word
);
    reg [255:0] gbuf     = 256'd0;
    reg [7:0]   occ      = 8'd0;
    reg [6:0]   ph       = 7'd0;
    reg         win      = 1'b0;
    reg         acc_seen = 1'b0;

    initial out_v    = 1'b0;
    initial out_word = 128'd0;

    wire [1:0]   hdr  = in_ctl ? 2'b10 : 2'b01;
    wire [255:0] ins  = {126'd0, hdr, in_data} << occ;
    wire [255:0] mix  = gbuf | ins;
    wire         stall = (ph == 7'd64);

    always @(posedge clk) begin
        if (rst) begin
            gbuf     <= 256'd0;
            occ      <= 8'd0;
            ph       <= 7'd0;
            win      <= 1'b0;
            acc_seen <= 1'b0;
            out_v    <= 1'b0;
            out_word <= 128'd0;
        end else if (en) begin
            if (sof) begin
                gbuf     <= 256'd0;
                occ      <= 8'd0;
                ph       <= 7'd0;
                win      <= 1'b1;
                acc_seen <= 1'b0;
                out_v    <= 1'b0;
            end else begin
                if (eof)
                    win <= 1'b0;
                if (stall) begin
                    out_v    <= 1'b1;
                    out_word <= gbuf[127:0];
                    gbuf     <= {128'd0, gbuf[255:128]};
                    occ      <= occ - 8'd128;
                    ph       <= 7'd0;
                end else if (in_v) begin
                    out_v    <= 1'b1;
                    out_word <= mix[127:0];
                    gbuf     <= {128'd0, mix[255:128]};
                    occ      <= occ + 8'd2;
                    ph       <= ph + 7'd1;
                    acc_seen <= 1'b1;
                end else begin
                    out_v    <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (win && !acc_seen)
            assert (occ == 8'd0);
        if (win && acc_seen && ph != 7'd0)
            assert (occ != 8'd0);
    end
endmodule

module manch_h16_rx (
    input  wire        clk,
    input  wire        en,
    input  wire        sof,
    input  wire        abort,
    input  wire        rx,
    output wire        done,
    output wire [15:0] word,
    output wire        err_o,
    output wire        mid_strobe
);
    reg [31:0] phase;
    reg        last_lvl;
    reg [31:0] shreg;
    reg [31:0] bits_left;
    reg [31:0] deadline;
    reg        busy;
    reg        err;
    reg        win;
    reg        pv;

    initial begin
        phase = 32'd0;
        last_lvl = 1'b0;
        shreg = 32'd0;
        bits_left = 32'd0;
        deadline = 32'd0;
        busy = 1'b0;
        err = 1'b0;
        win = 1'b0;
        pv = 1'b0;
    end

    assign mid_strobe = busy && (phase == 32'd8);
    assign done  = en && busy && !abort && (phase == 32'd15) && (bits_left == 32'd1);
    assign word  = shreg[15:0];
    assign err_o = err;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (abort) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (sof && !busy) begin
                busy      <= 1'b1;
                win       <= 1'b1;
                bits_left <= 32'd16;
                phase     <= 32'd0;
                deadline  <= 32'd256;
                err       <= 1'b0;
            end else if (busy) begin
                deadline <= (deadline != 32'd0) ? (deadline - 32'd1) : 32'd0;
                if (phase == 32'd15) begin
                    phase     <= 32'd0;
                    bits_left <= bits_left - 32'd1;
                    if (bits_left == 32'd1) begin
                        busy <= 1'b0;
                        win  <= 1'b0;
                    end
                end else begin
                    phase <= phase + 32'd1;
                end
                if (phase == 32'd4)
                    last_lvl <= rx;
                if (phase == 32'd12) begin
                    if (last_lvl != rx)
                        shreg <= {shreg[30:0], last_lvl};
                    else begin
                        shreg <= {shreg[30:0], 1'b0};
                        err   <= 1'b1;
                    end
                    last_lvl <= rx;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $rose(mid_strobe))
            assert (deadline != 32'd0);
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
endmodule

module wl_decim48 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire flush,
    input wire [63:0] din,
    output wire [63:0] o_dout,
    output wire o_tick
);
    localparam [5:0]  LAST = 6'd47;
    localparam [63:0] WIN  = 64'd48;

    reg [5:0]  phase;
    reg [63:0] acc;
    reg [63:0] dout;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;
    reg        tick;
    reg        pre_flush;
    reg        pv;

    initial begin
        phase = 6'd0;
        acc = 64'd0;
        dout = 64'd0;
        in_cnt = 64'd0;
        out_cnt = 64'd0;
        tick = 1'b0;
        pre_flush = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 6'd0;
            acc <= 64'd0;
            dout <= 64'd0;
            in_cnt <= 64'd0;
            out_cnt <= 64'd0;
            tick <= 1'b0;
            pre_flush <= 1'b1;
        end else if (en) begin
            if (flush) begin
                phase <= 6'd0;
                acc <= 64'd0;
                tick <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                in_cnt <= in_cnt + 64'd1;
                if (phase == LAST) begin
                    phase <= 6'd0;
                    dout <= acc + din;
                    acc <= 64'd0;
                    out_cnt <= out_cnt + 64'd1;
                    tick <= 1'b1;
                end else begin
                    phase <= phase + 6'd1;
                    acc <= acc + din;
                    tick <= 1'b0;
                end
            end
        end
    end

    assign o_dout = dout;
    assign o_tick = tick;

    always @(posedge clk)
        if (pv && !rst && pre_flush && $rose(tick))
            assert (in_cnt == WIN * out_cnt);
endmodule

module SsiFir8 (
    input  wire        clk,
    input  wire        en,
    input  wire        load_req,
    input  wire [31:0] coef_in,
    input  wire        s_valid,
    input  wire [31:0] s_data,
    input  wire        frame_end,
    output wire [31:0] y,
    output wire        y_valid
);
    reg [31:0] tap  [0:7];
    reg [31:0] coef [0:7];
    reg [31:0] fill_cnt = 32'd0;
    reg        primed   = 1'b0;
    reg        loading  = 1'b0;
    reg [31:0] load_ptr = 32'd0;
    reg        win      = 1'b0;
    reg        pv       = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 32'd0;
            coef[i] = 32'd0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (load_req) begin
                loading  <= 1'b1;
                load_ptr <= 32'd0;
                fill_cnt <= 32'd0;
                primed   <= 1'b0;
            end else begin
                primed <= (fill_cnt >= 32'd8);
                if (loading) begin
                    coef[load_ptr[2:0]] <= coef_in;
                    if (load_ptr == 32'd7) begin
                        loading  <= 1'b0;
                        load_ptr <= 32'd0;
                    end else begin
                        load_ptr <= load_ptr + 32'd1;
                    end
                end else if (s_valid) begin
                    for (i = 7; i > 0; i = i - 1)
                        tap[i] <= tap[i-1];
                    tap[0]   <= s_data;
                    fill_cnt <= (fill_cnt < 32'd8) ? (fill_cnt + 32'd1) : 32'd8;
                end
            end
            if (load_req)
                win <= 1'b1;
            else if (frame_end)
                win <= 1'b0;
        end
    end

    assign y = tap[0]*coef[0] + tap[1]*coef[1] + tap[2]*coef[2] + tap[3]*coef[3]
             + tap[4]*coef[4] + tap[5]*coef[5] + tap[6]*coef[6] + tap[7]*coef[7];
    assign y_valid = primed;

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(primed) && $past(loading)));
endmodule

module ecc_err_logger (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sw_arm,
    input wire err_valid,
    input wire err_ue,
    input wire [31:0] err_syn,
    input wire [31:0] err_addr,
    input wire sw_ack
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, CAPT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] syn_q, addr_q;
    reg        type_q;
    reg [31:0] ce_cnt, ue_cnt;
    reg [31:0] log_mem [0:127];
    reg [6:0]  wp;
    reg        arm_seen, start_seen, fin_seen;

    integer i;
    initial begin
        phase = IDLE;
        syn_q = 32'd0;
        addr_q = 32'd0;
        type_q = 1'b0;
        ce_cnt = 32'd0;
        ue_cnt = 32'd0;
        wp = 7'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        fin_seen = 1'b0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            syn_q <= 32'd0;
            addr_q <= 32'd0;
            type_q <= 1'b0;
            ce_cnt <= 32'd0;
            ue_cnt <= 32'd0;
            wp <= 7'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            fin_seen <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE, DONE: begin
                    if (sw_arm) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (err_valid) begin
                        phase <= CAPT;
                        start_seen <= 1'b1;
                        syn_q <= err_syn;
                        addr_q <= err_addr;
                        type_q <= err_ue;
                        if (err_ue) begin
                            if (ue_cnt != 32'hFFFFFFFF) ue_cnt <= ue_cnt + 32'd1;
                        end else begin
                            if (ce_cnt != 32'hFFFFFFFF) ce_cnt <= ce_cnt + 32'd1;
                        end
                        log_mem[wp] <= err_addr;
                        wp <= wp + 7'd1;
                    end
                end
                CAPT: begin
                    if (sw_ack) begin
                        phase <= DONE;
                        fin_seen <= 1'b1;
                    end
                end
                default: phase <= phase;
            endcase
        end
    end

    assert property (!fin_seen || (start_seen && arm_seen));
endmodule

module norm32 (
    input wire clk,
    input wire en,
    input wire arm,
    input wire load,
    input wire start,
    input wire ack,
    input wire [31:0] din,
    input wire [31:0] ein,
    output wire done,
    output wire [31:0] mant_o,
    output wire [31:0] exp_o
);
    reg [1:0] phase = 2'd0;
    reg [31:0] mant = 32'd0;
    reg [31:0] exp_r = 32'd0;
    reg [5:0] shamt = 6'd0;
    reg armed_f = 1'b0;
    reg started_f = 1'b0;
    reg q_seen = 1'b0;
    reg pv = 1'b0;

    assign done = (phase == 2'd3);
    assign mant_o = mant;
    assign exp_o = exp_r;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            q_seen <= q_seen | load;
            case (phase)
                2'd0: begin
                    if (arm) begin
                        mant <= din;
                        exp_r <= ein;
                        shamt <= 6'd0;
                        armed_f <= 1'b1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    if (start) begin
                        started_f <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    if (mant[31] || (mant == 32'd0) || (shamt >= 6'd32)) begin
                        exp_r <= exp_r - {26'd0, shamt};
                        phase <= 2'd3;
                    end else begin
                        mant <= {mant[30:0], 1'b0};
                        shamt <= shamt + 6'd1;
                    end
                end
                2'd3: begin
                    if (ack) begin
                        armed_f <= 1'b0;
                        started_f <= 1'b0;
                        phase <= 2'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && q_seen && $past(q_seen) && $past(phase) == 2'd3)
            assert ($past(armed_f) && $past(started_f));
endmodule

module dfx_quiesce (
    input wire clk,
    input wire rst,
    input wire en,
    input wire issue,
    input wire ret,
    output wire bus_quiet
);
    reg [15:0] out_cnt;
    reg [15:0] iss_cnt;
    reg [15:0] ret_cnt;
    reg        armed;
    initial out_cnt = 16'd0;
    initial iss_cnt = 16'd0;
    initial ret_cnt = 16'd0;
    initial armed   = 1'b0;

    wire iss_ok = issue && (out_cnt != 16'hFFFF);
    wire ret_ok = ret && (out_cnt != 16'd0);

    always @(posedge clk) begin
        if (rst) begin
            out_cnt <= 16'd0;
            iss_cnt <= 16'd0;
            ret_cnt <= 16'd0;
            armed   <= 1'b0;
        end else if (en) begin
            out_cnt <= out_cnt + {15'd0, iss_ok} - {15'd0, ret_ok};
            iss_cnt <= iss_cnt + {15'd0, iss_ok};
            ret_cnt <= ret_cnt + {15'd0, ret_ok};
            armed   <= armed | iss_ok;
        end
    end

    assign bus_quiet = ~(out_cnt[0] | out_cnt[1] | out_cnt[2] | out_cnt[3] |
                         out_cnt[4] | out_cnt[5] | out_cnt[6] | out_cnt[7] |
                         out_cnt[8] | out_cnt[9] | out_cnt[10] | out_cnt[11] |
                         out_cnt[12] | out_cnt[13] | out_cnt[14] | out_cnt[15]);

    always @(posedge clk)
        if (armed && bus_quiet)
            assert (ret_cnt == iss_cnt);
endmodule

module ppu_clkfail_ctl (
    input  wire clk,
    input  wire rst_n,
    input  wire en,
    input  wire prim_fail,
    output wire use_backup,
    output wire busy,
    output wire fail_flag
);
    localparam [7:0] SETTLE = 8'd200;

    reg       sel_src     = 1'b0;
    reg       switching   = 1'b0;
    reg [7:0] settle_cnt  = 8'd0;
    reg       sticky_fail = 1'b0;
    reg [7:0] fail_cnt    = 8'd0;
    reg       fail_seen   = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            sel_src     <= 1'b0;
            switching   <= 1'b0;
            settle_cnt  <= 8'd0;
            sticky_fail <= 1'b0;
            fail_cnt    <= 8'd0;
            fail_seen   <= 1'b0;
        end else if (en) begin
            if (prim_fail) begin
                fail_seen   <= 1'b1;
                sticky_fail <= 1'b1;
                if (fail_cnt != 8'd255)
                    fail_cnt <= fail_cnt + 8'd1;
            end
            if (prim_fail && !sel_src && !switching) begin
                switching  <= 1'b1;
                settle_cnt <= SETTLE;
            end else if (switching) begin
                settle_cnt <= settle_cnt - 8'd1;
                if (settle_cnt == 8'd1) begin
                    sel_src   <= 1'b1;
                    switching <= 1'b0;
                end
            end
        end
    end

    assign use_backup = sel_src;
    assign busy       = switching;
    assign fail_flag  = sticky_fail;

    always @(posedge clk)
        if (sel_src)
            assert (fail_seen);
endmodule

module caribou_cuckoo_barrett (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        req,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        rehash,
    input  wire [31:0] new_mod,
    output reg  [32:0] res_r,
    output reg         done,
    output reg         busy,
    output reg         expired
);
    reg [31:0] mod_r;
    reg [32:0] mu_r;
    reg [63:0] prod_r;
    reg [31:0] q_r;
    reg [2:0]  stage;
    reg [31:0] cnt;
    reg        pre_rehash;

    initial begin
        mod_r      = 32'hFFFF_FFFF;
        mu_r       = 33'h1_0000_0001;
        prod_r     = 64'd0;
        q_r        = 32'd0;
        res_r      = 33'd0;
        stage      = 3'd0;
        cnt        = 32'd0;
        busy       = 1'b0;
        done       = 1'b0;
        expired    = 1'b0;
        pre_rehash = 1'b1;
    end

    wire [64:0] two64   = {1'b1, 64'd0};
    wire [64:0] mu_full = (new_mod == 32'd0) ? 65'd0 : (two64 / {33'd0, new_mod});
    wire [96:0] pm      = prod_r * mu_r;
    wire [63:0] qm      = q_r * mod_r;
    wire [63:0] diff    = prod_r - qm;
    wire [32:0] mod_ext = {1'b0, mod_r};

    always @(posedge clk) begin
        if (rst) begin
            mod_r      <= 32'hFFFF_FFFF;
            mu_r       <= 33'h1_0000_0001;
            prod_r     <= 64'd0;
            q_r        <= 32'd0;
            res_r      <= 33'd0;
            stage      <= 3'd0;
            cnt        <= 32'd0;
            busy       <= 1'b0;
            done       <= 1'b0;
            expired    <= 1'b0;
            pre_rehash <= 1'b1;
        end else if (en) begin
            if (rehash) pre_rehash <= 1'b0;
            if (!busy) begin
                if (req) begin
                    prod_r <= a * b;
                    busy   <= 1'b1;
                    stage  <= 3'd0;
                    cnt    <= 32'd5;
                    done   <= 1'b0;
                end else if (rehash) begin
                    mod_r <= new_mod;
                    mu_r  <= mu_full[32:0];
                    done  <= 1'b0;
                end
            end else begin
                cnt     <= cnt - 32'd1;
                expired <= expired | ((cnt == 32'd1) && (stage != 3'd4));
                case (stage)
                    3'd0: begin
                        q_r   <= pm[95:64];
                        stage <= 3'd1;
                    end
                    3'd1: begin
                        res_r <= diff[32:0];
                        stage <= 3'd2;
                    end
                    3'd2: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd3;
                    end
                    3'd3: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd4;
                    end
                    3'd4: begin
                        done <= 1'b1;
                        busy <= 1'b0;
                    end
                    default: begin
                        stage <= stage;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (pv && pre_rehash && en && $stable(done))
            assert ($stable(expired));
    end
endmodule

module gardner_ted_lxp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] sample_in,
    output wire [15:0] o_err,
    output wire o_strobe
);
    reg phase;
    reg [7:0] prev_sym, mid, cur_sym;
    reg [7:0] sym_cnt;
    reg [7:0] half_cnt;
    reg [15:0] err_out;
    reg [15:0] err_mem [0:31];
    integer i;

    initial begin
        phase = 1'b0;
        prev_sym = 8'd0;
        mid = 8'd0;
        cur_sym = 8'd0;
        sym_cnt = 8'd0;
        half_cnt = 8'd0;
        err_out = 16'd0;
        for (i = 0; i < 32; i = i + 1) err_mem[i] = 16'd0;
    end

    wire signed [8:0] diff = $signed({sample_in[7], sample_in}) - $signed({cur_sym[7], cur_sym});
    wire signed [16:0] prod = diff * $signed({mid[7], mid});
    wire [15:0] err = prod[15:0];

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            prev_sym <= 8'd0;
            mid <= 8'd0;
            cur_sym <= 8'd0;
            sym_cnt <= 8'd0;
            half_cnt <= 8'd0;
            err_out <= 16'd0;
            for (i = 0; i < 32; i = i + 1) err_mem[i] <= 16'd0;
        end else if (en) begin
            phase <= ~phase;
            if (!phase) begin
                mid <= sample_in;
            end else begin
                prev_sym <= cur_sym;
                cur_sym <= sample_in;
                err_out <= err;
                err_mem[sym_cnt[4:0]] <= err;
            end
            if (half_cnt == 8'd63) begin
                half_cnt <= 8'd0;
                sym_cnt <= 8'd0;
            end else begin
                half_cnt <= half_cnt + 8'd1;
                if (phase)
                    sym_cnt <= sym_cnt + 8'd1;
            end
        end
    end

    assign o_err = err_out;
    assign o_strobe = phase;

    always @(*) assert (sym_cnt <= 8'd31);
endmodule

module ft60x_axi_default_slave (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire       arvalid,
    input  wire [7:0] arid,
    input  wire [7:0] arlen,
    input  wire       rready,
    input  wire       awvalid,
    input  wire [7:0] awid,
    input  wire       wvalid,
    input  wire       wlast,
    input  wire       bready,
    output wire       arready,
    output wire       rvalid,
    output wire [1:0] rresp,
    output wire       rlast,
    output wire [7:0] rid,
    output wire       awready,
    output wire       wready,
    output wire       bvalid,
    output wire [1:0] bresp,
    output wire [7:0] bid
);
    reg [7:0] rid_q   = 8'd0;
    reg [7:0] len_q   = 8'd0;
    reg [7:0] sent_q  = 8'd0;
    reg       busy    = 1'b0;
    reg       rbeat_q = 1'b0;
    reg       win     = 1'b0;
    reg [7:0] bid_q   = 8'd0;
    reg       wact    = 1'b0;
    reg       bpend   = 1'b0;

    assign arready = en & ~busy;
    assign rvalid  = en & busy;
    assign rresp   = 2'b11;
    assign rlast   = ((sent_q + 8'd1) == len_q);
    assign rid     = rid_q;
    assign awready = en & ~bpend & ~wact;
    assign wready  = en & wact;
    assign bvalid  = en & bpend;
    assign bresp   = 2'b11;
    assign bid     = bid_q;

    wire ar_hs = arvalid & arready;
    wire r_hs  = rvalid & rready;
    wire aw_hs = awvalid & awready;
    wire w_hs  = wvalid & wready;
    wire b_hs  = bvalid & bready;

    always @(posedge clk) begin
        if (!rst_n) begin
            rid_q   <= 8'd0;
            len_q   <= 8'd0;
            sent_q  <= 8'd0;
            busy    <= 1'b0;
            rbeat_q <= 1'b0;
            win     <= 1'b0;
            bid_q   <= 8'd0;
            wact    <= 1'b0;
            bpend   <= 1'b0;
        end else if (en) begin
            rbeat_q <= r_hs;
            if (ar_hs) begin
                rid_q  <= arid;
                len_q  <= ((arlen > 8'd15) ? 8'd15 : arlen) + 8'd1;
                sent_q <= 8'd0;
                busy   <= 1'b1;
                win    <= 1'b1;
            end else if (r_hs) begin
                if (rlast) begin
                    busy   <= 1'b0;
                    sent_q <= 8'd0;
                    win    <= 1'b0;
                end else begin
                    sent_q <= sent_q + 8'd1;
                end
            end
            if (aw_hs) begin
                bid_q <= awid;
                wact  <= 1'b1;
            end
            if (w_hs && wlast) begin
                wact  <= 1'b0;
                bpend <= 1'b1;
            end
            if (b_hs)
                bpend <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && $rose(rbeat_q))
            assert (sent_q <= 8'd16);
endmodule

module nyuzi_scan_demux (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         ir_load,
    input  wire [7:0]   ir_data,
    input  wire         shift,
    input  wire         scan_in,
    output wire [255:0] chain_si,
    output reg          frame_done
);
    reg [7:0]  chain_sel;
    reg [15:0] shift_cnt;
    reg [15:0] remaining;
    reg        armed;

    initial chain_sel  = 8'd0;
    initial shift_cnt  = 16'd0;
    initial remaining  = 16'd999;
    initial armed      = 1'b0;
    initial frame_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            chain_sel  <= 8'd0;
            shift_cnt  <= 16'd0;
            remaining  <= 16'd999;
            armed      <= 1'b0;
            frame_done <= 1'b0;
        end else if (en) begin
            frame_done <= 1'b0;
            if (ir_load) begin
                chain_sel <= ir_data;
                shift_cnt <= 16'd0;
                remaining <= 16'd999;
                armed     <= 1'b1;
            end else if (shift) begin
                if (remaining == 16'd0) begin
                    shift_cnt  <= 16'd0;
                    remaining  <= 16'd999;
                    frame_done <= 1'b1;
                end else begin
                    shift_cnt <= shift_cnt + 16'd1;
                    remaining <= remaining - 16'd1;
                end
            end
        end
    end

    wire si_bit = scan_in & shift & en;
    assign chain_si = {255'd0, si_bit} << chain_sel;

    always @(posedge clk)
        if (armed) assert (shift_cnt <= 16'd999);
endmodule

module sv2v_hdr_parser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire sop,
    input wire eop,
    input wire [15:0] din,
    output reg [15:0] kind,
    output reg [15:0] len,
    output reg [15:0] csum
);
    reg [15:0] off;
    reg [15:0] hdr_mem [0:31];
    reg hdr_done;
    reg win;
    integer i;

    initial begin
        off = 16'd0;
        kind = 16'd0;
        len = 16'd0;
        csum = 16'd0;
        hdr_done = 1'b0;
        win = 1'b0;
        for (i = 0; i < 32; i = i + 1) hdr_mem[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            off <= 16'd0;
            kind <= 16'd0;
            len <= 16'd0;
            csum <= 16'd0;
            hdr_done <= 1'b0;
            win <= 1'b0;
            for (i = 0; i < 32; i = i + 1) hdr_mem[i] <= 16'd0;
        end else if (en) begin
            if (sop) begin
                off <= 16'd1;
                kind <= din;
                hdr_mem[0] <= din;
                hdr_done <= 1'b0;
                win <= 1'b1;
            end else if (win) begin
                if (off < 16'd32) hdr_mem[off[4:0]] <= din;
                if (off == 16'd1) len <= din;
                if (off == 16'd2) begin
                    csum <= din;
                    hdr_done <= 1'b1;
                end
                if (off != 16'hFFFF) off <= off + 16'd1;
                if (eop) win <= 1'b0;
            end
        end
    end

    assert property (!(win && (off > 16'd3)) || hdr_done);
endmodule

module fp8_reduce_minmax (
    input wire clk,
    input wire rst,
    input wire en,
    input wire valid,
    input wire op,
    input wire [7:0] x,
    output reg [7:0] mx,
    output reg [7:0] mn,
    output reg [7:0] res,
    output reg inv,
    output reg armed
);
    initial mx = 8'hFC;
    initial mn = 8'h7C;
    initial res = 8'h00;
    initial inv = 1'b0;
    initial armed = 1'b0;

    function isnan;
        input [7:0] a;
        isnan = (a[6:2] == 5'h1F) && (a[1:0] != 2'b00);
    endfunction

    function [7:0] key;
        input [7:0] a;
        key = a[7] ? ~a : (a | 8'h80);
    endfunction

    function [7:0] fmax;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmax = 8'h7E;
            else if (isnan(a)) fmax = b;
            else if (isnan(b)) fmax = a;
            else if (key(a) >= key(b)) fmax = a;
            else fmax = b;
        end
    endfunction

    function [7:0] fmin;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmin = 8'h7E;
            else if (isnan(a)) fmin = b;
            else if (isnan(b)) fmin = a;
            else if (key(a) <= key(b)) fmin = a;
            else fmin = b;
        end
    endfunction

    function fle;
        input [7:0] a;
        input [7:0] b;
        fle = !isnan(a) && !isnan(b) && (key(a) <= key(b));
    endfunction

    wire [7:0] nmax = fmax(mx, x);
    wire [7:0] nmin = fmin(mn, x);

    always @(posedge clk) begin
        if (rst) begin
            mx <= 8'hFC;
            mn <= 8'h7C;
            res <= 8'h00;
            inv <= 1'b0;
            armed <= 1'b0;
        end else if (en && valid) begin
            mx <= nmax;
            mn <= nmin;
            res <= op ? nmin : nmax;
            inv <= isnan(x) && !x[1];
            armed <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!isnan(mx) && !isnan(mn) && (fle(mn, mx) || (mx == 8'hFC && mn == 8'h7C)));
endmodule

module tbdr_tile_dir (
    input  wire         clk,
    input  wire         en,
    input  wire         rd_req,
    input  wire         wr_req,
    input  wire [3:0]   req_line,
    input  wire [2:0]   req_id,
    input  wire [127:0] wdata,
    input  wire         inv_ack,
    input  wire         tile_begin,
    input  wire         tile_end,
    output reg          gnt_s,
    output reg          gnt_x,
    output reg          win,
    output reg          busy,
    output reg  [3:0]   ack_cnt
);
    reg [31:0]   st_f;
    reg [127:0]  shr_f;
    reg [47:0]   own_f;
    reg [2047:0] data_f;
    reg [3:0]    tline;
    reg [2:0]    treq;
    reg [127:0]  tdata;

    initial begin
        st_f    = 32'd0;
        shr_f   = 128'd0;
        own_f   = 48'd0;
        data_f  = 2048'd0;
        tline   = 4'd0;
        treq    = 3'd0;
        tdata   = 128'd0;
        busy    = 1'b0;
        ack_cnt = 4'd0;
        gnt_s   = 1'b0;
        gnt_x   = 1'b0;
        win     = 1'b0;
    end

    wire [7:0] shr_cur  = shr_f[req_line*8 +: 8];
    wire [7:0] id_mask  = 8'd1 << req_id;
    wire [7:0] others   = shr_cur & ~id_mask;
    wire [3:0] pop      = {3'd0, others[0]} + {3'd0, others[1]} + {3'd0, others[2]} + {3'd0, others[3]}
                        + {3'd0, others[4]} + {3'd0, others[5]} + {3'd0, others[6]} + {3'd0, others[7]};
    wire       no_other = (others == 8'd0);
    wire       wr_go    = wr_req && !busy;
    wire       rd_go    = rd_req && !wr_req && !busy;
    wire       ack_go   = inv_ack && (ack_cnt != 4'd0);
    wire       ack_last = ack_go && (ack_cnt == 4'd1);

    always @(posedge clk) begin
        if (en) begin
            gnt_s <= rd_go;
            gnt_x <= (wr_go && no_other) || ack_last;
            win   <= tile_begin ? 1'b1 : (tile_end ? 1'b0 : win);

            if (wr_go) begin
                if (!no_other) begin
                    busy    <= 1'b1;
                    ack_cnt <= pop;
                    tline   <= req_line;
                    treq    <= req_id;
                    tdata   <= wdata;
                    st_f[req_line*2 +: 2] <= 2'd3;
                end else begin
                    data_f[req_line*128 +: 128] <= wdata;
                    st_f[req_line*2 +: 2]       <= 2'd2;
                    own_f[req_line*3 +: 3]      <= req_id;
                    shr_f[req_line*8 +: 8]      <= 8'd0;
                end
            end else if (rd_go) begin
                shr_f[req_line*8 + req_id] <= 1'b1;
                st_f[req_line*2 +: 2]      <= 2'd1;
            end

            if (ack_go) begin
                ack_cnt <= ack_cnt - 4'd1;
                if (ack_cnt == 4'd1) begin
                    busy <= 1'b0;
                    st_f[tline*2 +: 2]       <= 2'd2;
                    own_f[tline*3 +: 3]      <= treq;
                    shr_f[tline*8 +: 8]      <= 8'd0;
                    data_f[tline*128 +: 128] <= tdata;
                end
            end
        end
    end

    always @(*) if (win) assert (!(gnt_s && gnt_x));
endmodule

module chacha_qr_lockstep (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire load,
    input wire [3:0] ld_idx,
    input wire [31:0] ld_word,
    input wire start,
    input wire abort,
    output wire o_mismatch,
    output wire [31:0] o_word0,
    output wire [31:0] o_rnd
);
    // 16 x 32-bit state words, flattened: word i at bits [i*32 +: 32]
    reg [511:0] st_a;
    reg [511:0] st_b;
    reg [31:0]  rnd;
    reg         win;

    initial begin
        st_a = 512'd0;
        st_b = 512'd0;
        rnd  = 32'd0;
        win  = 1'b0;
    end

    function [511:0] qr_step;
        input [511:0] s;
        input [2:0] sel;
        reg [3:0] ia, ib, ic, id;
        reg [31:0] a, b, c, d;
        reg [511:0] r;
        begin
            case (sel)
                3'd0: begin ia = 4'd0; ib = 4'd4; ic = 4'd8;  id = 4'd12; end
                3'd1: begin ia = 4'd1; ib = 4'd5; ic = 4'd9;  id = 4'd13; end
                3'd2: begin ia = 4'd2; ib = 4'd6; ic = 4'd10; id = 4'd14; end
                3'd3: begin ia = 4'd3; ib = 4'd7; ic = 4'd11; id = 4'd15; end
                3'd4: begin ia = 4'd0; ib = 4'd5; ic = 4'd10; id = 4'd15; end
                3'd5: begin ia = 4'd1; ib = 4'd6; ic = 4'd11; id = 4'd12; end
                3'd6: begin ia = 4'd2; ib = 4'd7; ic = 4'd8;  id = 4'd13; end
                default: begin ia = 4'd3; ib = 4'd4; ic = 4'd9; id = 4'd14; end
            endcase
            a = s[{ia, 5'b0} +: 32];
            b = s[{ib, 5'b0} +: 32];
            c = s[{ic, 5'b0} +: 32];
            d = s[{id, 5'b0} +: 32];
            a = a + b; d = d ^ a; d = {d[15:0], d[31:16]};
            c = c + d; b = b ^ c; b = {b[19:0], b[31:20]};
            a = a + b; d = d ^ a; d = {d[23:0], d[31:24]};
            c = c + d; b = b ^ c; b = {b[24:0], b[31:25]};
            r = s;
            r[{ia, 5'b0} +: 32] = a;
            r[{ib, 5'b0} +: 32] = b;
            r[{ic, 5'b0} +: 32] = c;
            r[{id, 5'b0} +: 32] = d;
            qr_step = r;
        end
    endfunction

    wire [511:0] nxt_a = qr_step(st_a, rnd[2:0]);
    wire [511:0] nxt_b = qr_step(st_b, rnd[2:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            st_a <= 512'd0;
            st_b <= 512'd0;
            rnd  <= 32'd0;
            win  <= 1'b0;
        end else if (en) begin
            if (load) begin
                st_a[{ld_idx, 5'b0} +: 32] <= ld_word;
                st_b[{ld_idx, 5'b0} +: 32] <= ld_word;
                rnd <= 32'd0;
            end else begin
                st_a <= nxt_a;
                st_b <= nxt_b;
                rnd  <= rnd + 32'd1;
            end
            if (abort)
                win <= 1'b0;
            else if (start)
                win <= 1'b1;
        end
    end

    assign o_mismatch = (st_a != st_b);
    assign o_word0    = st_a[31:0];
    assign o_rnd      = rnd;

    always @(*) assert (!win || (st_a[31:0] == st_b[31:0]));
endmodule

module lego_slot_alloc (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire alloc_req,
    input wire free_req,
    input wire [0:0] free_idx,
    input wire sess_open,
    input wire sess_close,
    output wire full,
    output wire empty,
    output wire grant_valid,
    output wire [0:0] grant_idx
);
    reg [1:0] bitmap;
    reg [15:0] used_cnt;
    reg [15:0] free_cnt;
    reg win;
    initial begin
        bitmap = 2'b00;
        used_cnt = 16'd0;
        free_cnt = 16'd2;
        win = 1'b0;
    end

    assign grant_valid = alloc_req && (bitmap != 2'b11);
    assign grant_idx = bitmap[0] ? 1'b1 : 1'b0;
    wire do_free = !grant_valid && free_req && bitmap[free_idx];

    always @(posedge clk) begin
        if (!rst_n) begin
            bitmap <= 2'b00;
            used_cnt <= 16'd0;
            free_cnt <= 16'd2;
            win <= 1'b0;
        end else if (en) begin
            if (grant_valid) begin
                bitmap[grant_idx] <= 1'b1;
                used_cnt <= used_cnt + 16'd1;
                free_cnt <= free_cnt - 16'd1;
            end else if (do_free) begin
                bitmap[free_idx] <= 1'b0;
                used_cnt <= used_cnt - 16'd1;
                free_cnt <= free_cnt + 16'd1;
            end
            win <= sess_open ? 1'b1 : (sess_close ? 1'b0 : win);
        end
    end

    assign full = (free_cnt == 16'd0);
    assign empty = (used_cnt == 16'd0);

    always @(*) if (win) assert (!(free_cnt == 16'd0 && used_cnt == 16'd0));
endmodule

module tile_polarity_lock (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         retrain,
    input  wire [127:0] rx_data,
    output wire [127:0] data_out,
    output reg          locked
);
    localparam [7:0] TS     = 8'hBC;
    localparam [7:0] TS_INV = 8'h43;

    reg [15:0] inv_flag;
    reg [15:0] det_mask;
    reg [4:0]  det_cnt;
    reg        pre_rt;
    reg        pv;

    initial inv_flag = 16'd0;
    initial det_mask = 16'd0;
    initial det_cnt  = 5'd0;
    initial locked   = 1'b0;
    initial pre_rt   = 1'b1;
    initial pv       = 1'b0;

    reg [15:0] new_mask;
    reg [15:0] nxt_inv;
    reg [4:0]  new_cnt;
    integer i;

    always @(*) begin
        new_mask = 16'd0;
        nxt_inv  = inv_flag;
        new_cnt  = 5'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (!det_mask[i]) begin
                if (rx_data[8*i +: 8] == TS) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b0;
                end else if (rx_data[8*i +: 8] == TS_INV) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b1;
                end
            end
            new_cnt = new_cnt + {4'd0, new_mask[i]};
        end
    end

    wire [4:0] sum_cnt = det_cnt + new_cnt;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_lane
            assign data_out[8*g +: 8] = rx_data[8*g +: 8] ^ {8{inv_flag[g]}};
        end
    endgenerate

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            inv_flag <= 16'd0;
            det_mask <= 16'd0;
            det_cnt  <= 5'd0;
            locked   <= 1'b0;
            pre_rt   <= 1'b1;
        end else if (en) begin
            if (retrain) begin
                inv_flag <= 16'd0;
                det_mask <= 16'd0;
                det_cnt  <= 5'd0;
                locked   <= 1'b0;
                pre_rt   <= 1'b0;
            end else begin
                inv_flag <= nxt_inv;
                det_mask <= det_mask | new_mask;
                det_cnt  <= sum_cnt;
                locked   <= locked | (sum_cnt == 5'd16);
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && pre_rt && $rose(locked))
            assert (&det_mask);
endmodule

module uart_nco (
    input wire i_clk,
    input wire i_rst,
    input wire i_en,
    input wire [7:0] i_fword,
    input wire i_start,
    input wire i_stop,
    output wire [7:0] o_sin,
    output wire [7:0] o_ticks,
    output wire o_win
);
    localparam [63:0] SIN_TAB = {8'd37, 8'd1, 8'd37, 8'd128, 8'd218, 8'd255, 8'd218, 8'd128};

    reg [7:0] phase = 8'd0;
    reg [7:0] tick_cnt = 8'd0;
    reg [2:0] last_idx = 3'd0;
    reg [7:0] sin_q = 8'd128;
    reg       win = 1'b0;

    wire [8:0] sum = {1'b0, phase} + {1'b0, i_fword};
    wire [7:0] nphase = sum[7:0];
    wire       carry = sum[8];
    wire [2:0] nidx = nphase[7:5];
    wire [5:0] nbase = {nidx, 3'b000};
    wire [7:0] n_sin = SIN_TAB[nbase +: 8];
    wire [5:0] lbase = {last_idx, 3'b000};
    wire [7:0] sin_of_last = SIN_TAB[lbase +: 8];

    always @(posedge i_clk) begin
        if (i_rst) begin
            phase <= 8'd0;
            tick_cnt <= 8'd0;
            last_idx <= 3'd0;
            sin_q <= 8'd128;
            win <= 1'b0;
        end else if (i_en) begin
            phase <= nphase;
            if (carry)
                tick_cnt <= tick_cnt + 8'd1;
            last_idx <= nidx;
            sin_q <= n_sin;
            if (i_start)
                win <= 1'b1;
            else if (i_stop)
                win <= 1'b0;
        end
    end

    assign o_sin = sin_q;
    assign o_ticks = tick_cnt;
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge i_clk) pv <= 1'b1;

    always @(posedge i_clk)
        if (pv && !$past(i_rst) && win && $stable(phase))
            assert ($stable(sin_q));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
    output wire o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module bank_steer_demux (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire        resp,
    input  wire [15:0] addr,
    output reg  [3:0]  pending,
    output reg  [1:0]  phase,
    output reg  [15:0] done_cnt
);
    // phase: 0 = IDLE, 1 = ARMED (bank decoded), 2 = STARTED (bank pending), 3 = FINISHED
    reg [1:0]  bank_idx;
    reg [15:0] addr_q;

    initial phase    = 2'd0;
    initial pending  = 4'd0;
    initial bank_idx = 2'd0;
    initial addr_q   = 16'd0;
    initial done_cnt = 16'd0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            pending  <= 4'd0;
            bank_idx <= 2'd0;
            addr_q   <= 16'd0;
            done_cnt <= 16'd0;
        end else if (ce) begin
            case (phase)
                2'd0: if (req) begin
                    addr_q   <= addr;
                    bank_idx <= addr[1:0];
                    phase    <= 2'd1;
                end
                2'd1: begin
                    pending <= pending | (4'd1 << bank_idx);
                    phase   <= 2'd2;
                end
                2'd2: if (resp) begin
                    pending  <= pending & ~(4'd1 << bank_idx);
                    phase    <= 2'd3;
                    done_cnt <= done_cnt + 16'd1;
                end
                default: phase <= 2'd0;
            endcase
        end
    end

    // A finish can only be observed once the started bank request has been retired
    always @(*) assert (phase != 2'd3 || pending == 4'd0);
endmodule

module wwdg_window (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       stop,
    input  wire       kick,
    input  wire [7:0] cfg_reload,
    input  wire [7:0] cfg_win,
    output wire [1:0] o_fault,
    output wire       o_armed,
    output wire [7:0] o_cnt
);
    reg       pv       = 1'b0;
    reg       armed    = 1'b0;
    reg [7:0] cnt      = 8'd64;
    reg [7:0] reload   = 8'd64;
    reg [7:0] win_thr  = 8'd0;
    reg [1:0] fault    = 2'b00;
    reg       win_open = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (start) begin
            armed    <= 1'b1;
            reload   <= cfg_reload | 8'h40;
            win_thr  <= cfg_win & 8'h3F;
            cnt      <= cfg_reload | 8'h40;
            fault    <= 2'b00;
            win_open <= 1'b0;
        end else if (stop) begin
            armed <= 1'b0;
        end else if (armed && ce && fault == 2'b00) begin
            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
endmodule

module huff_decoder64 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire step,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] bits_in,
    input wire [63:0] wr_code,
    input wire [63:0] wr_len,
    output wire busy,
    output wire [63:0] o_sym,
    output wire [63:0] o_nsym
);
    localparam [63:0] MAXLEN = 64'd8;

    // decode window / request outstanding
    reg win = 1'b0;
    // bit accumulator, consumed-code shift register, bit position, completion countdown
    reg [63:0] acc = 64'd0;
    reg [63:0] code_acc = 64'd0;
    reg [63:0] bitpos = 64'd0;
    reg [63:0] cnt = 64'd0;
    reg [63:0] sym = 64'd0;
    reg [63:0] nsym = 64'd0;
    // two-entry code table (code word + length)
    reg [63:0] code0 = 64'd0;
    reg [63:0] len0 = 64'd1;
    reg [63:0] code1 = 64'd2;
    reg [63:0] len1 = 64'd2;

    wire [63:0] nbits = bitpos + 64'd1;
    wire [63:0] ncode = {code_acc[62:0], acc[63]};
    wire hit0 = (nbits == len0) && (ncode == code0);
    wire hit1 = (nbits == len1) && (ncode == code1);
    wire esc  = (nbits == MAXLEN);

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            acc <= 64'd0;
            code_acc <= 64'd0;
            bitpos <= 64'd0;
            cnt <= 64'd0;
            nsym <= 64'd0;
        end else begin
            if (wr_en) begin
                if (wr_idx) begin
                    code1 <= wr_code;
                    len1 <= wr_len;
                end else begin
                    code0 <= wr_code;
                    len0 <= wr_len;
                end
            end
            if (win) begin
                if (step) begin
                    acc <= acc << 1;
                    code_acc <= ncode;
                    bitpos <= nbits;
                    cnt <= cnt - 64'd1;
                    if (hit0 || hit1 || esc) begin
                        win <= 1'b0;
                        nsym <= nsym + 64'd1;
                        sym <= hit0 ? 64'd0 : (hit1 ? 64'd1 : 64'd2);
                    end
                end
            end else if (start) begin
                win <= 1'b1;
                acc <= bits_in;
                code_acc <= 64'd0;
                bitpos <= 64'd0;
                cnt <= MAXLEN;
            end
        end
    end

    assign busy = win;
    assign o_sym = sym;
    assign o_nsym = nsym;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(cnt) != 64'd0);
endmodule

module bfx_unit (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [2:0] i_op,
    input  wire       i_lock,
    input  wire       i_unlock,
    input  wire [7:0] i_src,
    input  wire [7:0] i_dst,
    output wire [7:0] o_res
);
    // field control: start position, width, and remaining headroom above the field
    reg [7:0] pos;
    reg [7:0] wid;
    reg [7:0] rem;
    reg [7:0] res;
    reg       win;
    initial pos = 8'd0;
    initial wid = 8'd0;
    initial rem = 8'd8;
    initial res = 8'd0;
    initial win = 1'b0;

    localparam OP_GROW = 3'd0, OP_SHRINK = 3'd1, OP_ADV = 3'd2, OP_RET = 3'd3,
               OP_EXTZ = 3'd4, OP_EXTS = 3'd5, OP_INS = 3'd6, OP_NOP = 3'd7;

    wire [7:0] mask = (wid >= 8'd8) ? 8'hFF : ((8'd1 << wid) - 8'd1);
    wire [7:0] ext  = (i_src >> pos) & mask;
    wire       sbit = ((wid != 8'd0) && (wid < 8'd8)) ? ext[wid[2:0] - 3'd1] : 1'b0;
    wire [7:0] exts = sbit ? (ext | ~mask) : ext;
    wire [7:0] ins  = (i_dst & ~(mask << pos)) | ((i_src & mask) << pos);

    always @(posedge clk) begin
        if (i_reset) begin
            pos <= 8'd0;
            wid <= 8'd0;
            rem <= 8'd8;
            res <= 8'd0;
            win <= 1'b0;
        end else if (i_ce) begin
            if (i_unlock)
                win <= 1'b0;
            else if (i_lock)
                win <= 1'b1;
            case (i_op)
                OP_GROW:   if (rem != 8'd0) begin wid <= wid + 8'd1; rem <= rem - 8'd1; end
                OP_SHRINK: if (wid != 8'd0) begin wid <= wid - 8'd1; rem <= rem + 8'd1; end
                OP_ADV:    if (rem != 8'd0) begin pos <= pos + 8'd1; rem <= rem - 8'd1; end
                OP_RET:    if (pos != 8'd0) begin pos <= pos - 8'd1; rem <= rem + 8'd1; end
                OP_EXTZ:   res <= ext;
                OP_EXTS:   res <= exts;
                OP_INS:    res <= ins;
                default:   ;
            endcase
        end
    end

    assign o_res = res;

    // between lock and unlock: field width never exceeds the word size
    always @(posedge clk)
        if (win) assert (wid <= 8'd8);
endmodule

module wb_port_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       issue,
    input  wire [7:0] lat,
    input  wire       oreq,
    input  wire [7:0] olat,
    output wire       acc,
    output wire       oacc,
    output wire       wb_fire,
    output wire       wb_trk
);
    // result-bus reservation shift register: bit i = write port booked i steps ahead
    reg [47:0] resv = 48'd0;
    // slot booked by the tracked (watched) functional unit request
    reg [47:0] trk  = 48'd0;
    // window register: set when tracked request accepted, cleared on its writeback
    reg        pend = 1'b0;
    // bounded-response countdown
    reg [7:0]  cnt  = 8'd0;

    wire [47:0] rsh = resv >> 1;
    wire lat_ok  = (lat  < 8'd48) && ((rsh & (48'd1 << lat))  == 48'd0);
    wire olat_ok = (olat < 8'd48) && ((rsh & (48'd1 << olat)) == 48'd0);

    assign acc  = step && issue && !pend && lat_ok;
    assign oacc = step && oreq && olat_ok && !(acc && (olat == lat));
    assign wb_fire = step && resv[0];
    assign wb_trk  = step && pend && trk[0];

    always @(posedge clk) begin
        if (rst) begin
            resv <= 48'd0;
            trk  <= 48'd0;
            pend <= 1'b0;
            cnt  <= 8'd0;
        end else if (step) begin
            resv <= rsh | (acc ? (48'd1 << lat) : 48'd0) | (oacc ? (48'd1 << olat) : 48'd0);
            trk  <= (trk >> 1) | (acc ? (48'd1 << lat) : 48'd0);
            if (pend) begin
                if (trk[0]) begin
                    pend <= 1'b0;
                    cnt  <= 8'd0;
                end else begin
                    cnt  <= cnt - 8'd1;
                end
            end else if (acc) begin
                pend <= 1'b1;
                cnt  <= lat + 8'd1;
            end
        end
    end

    // after accept (pend set) until writeback (pend cleared): countdown never expires
    assert property (!pend || cnt != 8'd0);
endmodule

module lpm_engine (
    input  wire        clk,
    input  wire        insert,
    input  wire        flush,
    input  wire [63:0] ins_prefix,
    input  wire [6:0]  ins_len,
    input  wire [63:0] key,
    output reg         hit,
    output reg  [4:0]  match_addr,
    output reg  [6:0]  match_len,
    output wire [63:0] o_count
);
    reg [63:0] prefix_mem [0:31];
    reg [6:0]  len_mem    [0:31];
    reg [31:0] valid;
    reg [5:0]  wr_ptr;
    reg [63:0] count;
    reg        armed;

    integer k;
    initial begin
        valid  = 32'd0;
        wr_ptr = 6'd0;
        count  = 64'd0;
        armed  = 1'b1;
        for (k = 0; k < 32; k = k + 1) begin
            prefix_mem[k] = 64'd0;
            len_mem[k]    = 7'd0;
        end
    end

    function [63:0] pmask;
        input [6:0] l;
        begin
            if (l >= 7'd64) pmask = ~64'd0;
            else            pmask = ~(~64'd0 >> l);
        end
    endfunction

    wire [6:0] ins_len_sat = (ins_len > 7'd64) ? 7'd64 : ins_len;

    always @(posedge clk) begin
        if (flush) begin
            valid  <= 32'd0;
            wr_ptr <= 6'd0;
            armed  <= 1'b0;
        end else if (insert && wr_ptr < 6'd32) begin
            prefix_mem[wr_ptr[4:0]] <= ins_prefix & pmask(ins_len_sat);
            len_mem[wr_ptr[4:0]]    <= ins_len_sat;
            valid[wr_ptr[4:0]]      <= 1'b1;
            wr_ptr <= wr_ptr + 6'd1;
            count  <= count + 64'd1;
        end
    end

    integer i;
    always @(*) begin
        hit        = 1'b0;
        match_addr = 5'd0;
        match_len  = 7'd0;
        for (i = 0; i < 32; i = i + 1) begin
            if (valid[i] && (((key ^ prefix_mem[i]) & pmask(len_mem[i])) == 64'd0)
                && (!hit || len_mem[i] > match_len)) begin
                hit        = 1'b1;
                match_addr = i[4:0];
                match_len  = len_mem[i];
            end
        end
    end

    assign o_count = count;

    always @(*)
        if (armed)
            assert (count <= 64'd32);
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module eink_cic_decim (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire [127:0] din,
    output wire [127:0] o_pix,
    output wire         o_valid
);
    // 2-stage CIC decimator (R=4) smoothing grayscale waveform drive levels
    reg [127:0] integ1, integ2;
    reg [127:0] comb1_dly, comb2_dly;
    reg [127:0] dout;
    reg [1:0]   phase;
    reg         seen_nz;   // shadow: a nonzero sample has been accepted
    reg         vld;
    initial integ1 = 128'd0;
    initial integ2 = 128'd0;
    initial comb1_dly = 128'd0;
    initial comb2_dly = 128'd0;
    initial dout = 128'd0;
    initial phase = 2'd0;
    initial seen_nz = 1'b0;
    initial vld = 1'b0;

    wire [127:0] c1 = integ2 - comb1_dly;
    wire [127:0] c2 = c1 - comb2_dly;

    always @(posedge clk) begin
        if (rst) begin
            integ1 <= 128'd0;
            integ2 <= 128'd0;
            comb1_dly <= 128'd0;
            comb2_dly <= 128'd0;
            dout <= 128'd0;
            phase <= 2'd0;
            seen_nz <= 1'b0;
            vld <= 1'b0;
        end else if (i_ce) begin
            integ1 <= integ1 + din;
            integ2 <= integ2 + integ1;
            phase <= phase + 2'd1;
            if (din != 128'd0)
                seen_nz <= 1'b1;
            if (phase == 2'd3) begin
                comb1_dly <= integ2;
                comb2_dly <= c1;
                dout <= c2;
                vld <= 1'b1;
            end else begin
                vld <= 1'b0;
            end
        end
    end

    assign o_pix = dout;
    assign o_valid = vld;

    // Precedence: a nonzero output requires a nonzero input accepted earlier
    always @(posedge clk)
        if (dout != 128'd0) assert (seen_nz);
endmodule

module mcast_demux (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire [7:0] i_mask,
    input  wire [7:0] i_data,
    input  wire [7:0] i_ready,
    output wire [7:0] o_valid,
    output wire [7:0] o_data,
    output wire       o_done,
    output wire       o_busy
);
    localparam IDLE  = 2'd0;
    localparam ARMED = 2'd1;
    localparam SEND  = 2'd2;
    localparam FIN   = 2'd3;

    reg [1:0] phase;
    reg [7:0] mask;
    reg [7:0] delivered;
    reg [7:0] data;
    initial phase = IDLE;
    initial mask = 8'd0;
    initial delivered = 8'd0;
    initial data = 8'd0;

    assign o_valid = (phase == SEND) ? (mask & ~delivered) : 8'd0;
    assign o_data  = data;
    assign o_done  = (phase == FIN);
    assign o_busy  = (phase != IDLE);

    wire [7:0] accepted = o_valid & i_ready;
    wire [7:0] next_del = delivered | accepted;

    always @(posedge clk) begin
        if (i_reset) begin
            phase     <= IDLE;
            mask      <= 8'd0;
            delivered <= 8'd0;
            data      <= 8'd0;
        end else if (i_ce) begin
            case (phase)
                IDLE: begin
                    if (i_arm && (i_mask != 8'd0)) begin
                        mask      <= i_mask;
                        data      <= i_data;
                        delivered <= 8'd0;
                        phase     <= ARMED;
                    end
                end
                ARMED: begin
                    phase <= SEND;
                end
                SEND: begin
                    delivered <= next_del;
                    if (next_del == mask)
                        phase <= FIN;
                end
                FIN: begin
                    phase     <= IDLE;
                    mask      <= 8'd0;
                    delivered <= 8'd0;
                end
            endcase
        end
    end

    // finish implies a copy was started (at least one delivery)
    always @(*)
        if (phase == FIN) assert (delivered != 8'd0);

    // finish implies an arm with a non-empty destination mask happened
    always @(*)
        if (phase == FIN) assert (mask != 8'd0);
endmodule

module remap_unit (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_seq_go,
    input  wire        i_unlock,
    input  wire        i_cfg_we,
    input  wire        i_cfg_sel,
    input  wire        i_cfg_en,
    input  wire [63:0] i_cfg_src,
    input  wire [63:0] i_cfg_size,
    input  wire [63:0] i_cfg_tgt,
    input  wire [63:0] i_addr,
    output wire [63:0] o_addr,
    output wire        o_hit
);
    localparam [63:0] ROM_BASE  = 64'h0000_0000_2000_0000;
    localparam [63:0] ROM_SIZE  = 64'h0000_0000_0001_0000;
    localparam [63:0] DRAM_BASE = 64'h0000_0000_8000_0000;
    localparam [63:0] DRAM_SIZE = 64'h0000_0000_4000_0000;

    // scope register: high until software unlocks the remap table
    reg        boot_phase = 1'b1;
    // boot handoff sequencer: 0 alias, 1 copy, 2 drain, 3 ram at zero
    reg [63:0] seq        = 64'd0;
    // window 0: boot ROM aliased to address zero
    reg        alias_en   = 1'b1;
    reg [63:0] src0       = 64'd0;
    reg [63:0] size0      = ROM_SIZE;
    reg [63:0] tgt0       = ROM_BASE;
    // window 1: DRAM mapped at address zero
    reg        ram_en     = 1'b0;
    reg [63:0] src1       = 64'd0;
    reg [63:0] size1      = DRAM_SIZE;
    reg [63:0] tgt1       = DRAM_BASE;

    always @(posedge clk) begin
        if (i_reset) begin
            boot_phase <= 1'b1;
            seq        <= 64'd0;
            alias_en   <= 1'b1;
            src0       <= 64'd0;
            size0      <= ROM_SIZE;
            tgt0       <= ROM_BASE;
            ram_en     <= 1'b0;
            src1       <= 64'd0;
            size1      <= DRAM_SIZE;
            tgt1       <= DRAM_BASE;
        end else if (i_ce) begin
            if (i_unlock)
                boot_phase <= 1'b0;
            if (i_seq_go && (seq != 64'd3))
                seq <= seq + 64'd1;
            if (i_seq_go && (seq == 64'd1))
                alias_en <= 1'b0;
            if (i_seq_go && (seq == 64'd2))
                ram_en <= 1'b1;
            if (i_cfg_we && !boot_phase) begin
                if (i_cfg_sel) begin
                    src1   <= i_cfg_src;
                    size1  <= i_cfg_size;
                    tgt1   <= i_cfg_tgt;
                    ram_en <= i_cfg_en;
                end else begin
                    src0     <= i_cfg_src;
                    size0    <= i_cfg_size;
                    tgt0     <= i_cfg_tgt;
                    alias_en <= i_cfg_en;
                end
            end
        end
    end

    wire [63:0] off0 = i_addr - src0;
    wire [63:0] off1 = i_addr - src1;
    wire hit0 = alias_en && (i_addr >= src0) && (off0 < size0);
    wire hit1 = ram_en   && (i_addr >= src1) && (off1 < size1);

    assign o_hit  = hit0 || hit1;
    assign o_addr = hit0 ? (tgt0 + off0) : (hit1 ? (tgt1 + off1) : i_addr);

    // Absence, before unlock: address zero never has two owners
    always @(posedge clk)
        if (boot_phase)
            assert (!(alias_en && ram_en));
endmodule

module dram_init_seq (
    input wire clk,
    input wire rst,
    input wire step,
    input wire rel,
    output reg [2:0] cmd,
    output reg cke,
    output reg init_done
);
    reg [3:0]  cmd_idx  = 4'd0;
    reg [63:0] wait_cnt = 64'd0;
    reg        zq_done  = 1'b0;
    reg        armed    = 1'b0;

    initial cmd = 3'd0;
    initial cke = 1'b0;
    initial init_done = 1'b0;

    function [63:0] cmd_delay;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:    cmd_delay = 64'd4;
                4'd1:    cmd_delay = 64'd3;
                4'd14:   cmd_delay = 64'd4;
                default: cmd_delay = 64'd1;
            endcase
        end
    endfunction

    function [2:0] cmd_code;
        input [3:0] idx;
        begin
            if (idx == 4'd0)       cmd_code = 3'd1;
            else if (idx == 4'd1)  cmd_code = 3'd2;
            else if (idx == 4'd14) cmd_code = 3'd4;
            else if (idx == 4'd15) cmd_code = 3'd0;
            else                   cmd_code = 3'd3;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            cmd_idx   <= 4'd0;
            wait_cnt  <= 64'd0;
            zq_done   <= 1'b0;
            armed     <= 1'b0;
            init_done <= 1'b0;
            cmd       <= 3'd0;
            cke       <= 1'b0;
        end else if (step) begin
            cmd <= 3'd0;
            if (rel) armed <= 1'b0;
            if (wait_cnt != 64'd0) begin
                wait_cnt <= wait_cnt - 64'd1;
            end else if (cmd_idx != 4'd15) begin
                cmd      <= cmd_code(cmd_idx);
                wait_cnt <= cmd_delay(cmd_idx);
                cmd_idx  <= cmd_idx + 4'd1;
                if (cmd_idx == 4'd1) begin
                    cke <= 1'b1;
                    if (!rel) armed <= 1'b1;
                end
                if (cmd_idx == 4'd14) zq_done <= 1'b1;
            end else begin
                init_done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed && init_done)
            assert (zq_done);
endmodule

module const_slicer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       req,
    input  wire       cfg_we,
    input  wire [1:0] cfg_order,
    input  wire [7:0] in_i,
    input  wire [7:0] in_q,
    output reg  [3:0] dec_bits,
    output reg  [7:0] err_i,
    output reg  [7:0] err_q,
    output reg        done,
    output wire       busy_o
);
    reg [1:0] mod_order;
    reg [7:0] sym_i, sym_q;
    reg       busy;
    reg [7:0] cd;
    reg [7:0] phase;
    reg       pre_cfg;
    reg       pv;

    initial begin
        mod_order = 2'd1; sym_i = 8'd0; sym_q = 8'd0;
        busy = 1'b0; cd = 8'd0; phase = 8'd0;
        dec_bits = 4'd0; err_i = 8'd0; err_q = 8'd0; done = 1'b0;
        pre_cfg = 1'b1; pv = 1'b0;
    end

    assign busy_o = busy;

    wire si = sym_i[7];
    wire sq = sym_q[7];
    wire mi = sym_i[7] ^ sym_i[6];
    wire mq = sym_q[7] ^ sym_q[6];
    wire qam = mod_order[1];

    wire [7:0] qam_pt_i = si ? (mi ? 8'hA0 : 8'hE0) : (mi ? 8'h60 : 8'h20);
    wire [7:0] qam_pt_q = sq ? (mq ? 8'hA0 : 8'hE0) : (mq ? 8'h60 : 8'h20);
    wire [7:0] psk_pt_i = si ? 8'hC0 : 8'h40;
    wire [7:0] psk_pt_q = sq ? 8'hC0 : 8'h40;

    wire [7:0] pt_i = qam ? qam_pt_i : psk_pt_i;
    wire [7:0] pt_q = qam ? qam_pt_q : ((mod_order == 2'd0) ? 8'h00 : psk_pt_q);
    wire [3:0] bits = qam ? {mq, sq, mi, si}
                    : ((mod_order == 2'd0) ? {3'b000, si} : {2'b00, sq, si});

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            cd    <= 8'd0;
            phase <= 8'd0;
            done  <= 1'b0;
        end else if (ce) begin
            done <= 1'b0;
            if (cfg_we && !busy)
                mod_order <= cfg_order;
            if (!busy) begin
                if (req) begin
                    sym_i <= in_i;
                    sym_q <= in_q;
                    busy  <= 1'b1;
                    cd    <= 8'd4;
                    phase <= 8'd0;
                end
            end else begin
                cd <= cd - 8'd1;
                if (phase == 8'd3) begin
                    busy     <= 1'b0;
                    phase    <= 8'd0;
                    dec_bits <= bits;
                    err_i    <= sym_i - pt_i;
                    err_q    <= sym_q - pt_q;
                    done     <= 1'b1;
                end else begin
                    phase <= phase + 8'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (!rst && ce && cfg_we && !busy)
            pre_cfg <= 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_cfg && $past(busy))
            assert ($past(cd) != 8'd0);
endmodule

module r2sdf_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    output reg  [63:0] y_out,
    output reg         y_valid
);
    // single-delay-feedback memory: N/2 = 64 entries
    reg [63:0] dly [0:63];
    reg [63:0] ptr;       // stage control counter (0..63)
    reg        phase;     // 0 = fill, 1 = compute (butterfly)
    reg [63:0] bfly_cnt;  // butterflies issued
    reg        armed;     // high until the first frame's compute pass completes
    integer i;

    initial begin
        ptr = 64'd0; phase = 1'b0; bfly_cnt = 64'd0; armed = 1'b1;
        y_out = 64'd0; y_valid = 1'b0;
        for (i = 0; i < 64; i = i + 1) dly[i] = 64'd0;
    end

    wire [5:0]  idx    = ptr[5:0];
    wire [63:0] fb     = dly[idx];
    wire [63:0] bf_sum = fb + x_in;
    wire [63:0] bf_dif = fb - x_in;
    wire        last   = (ptr == 64'd63);

    always @(posedge clk) begin
        if (rst) begin
            ptr <= 64'd0; phase <= 1'b0; bfly_cnt <= 64'd0; armed <= 1'b1;
            y_out <= 64'd0; y_valid <= 1'b0;
        end else if (en) begin
            if (phase) begin
                // compute: butterfly between delayed sample and new sample
                dly[idx] <= bf_dif;
                y_out    <= bf_sum;
                bfly_cnt <= bfly_cnt + 64'd1;
                if (last) armed <= 1'b0;
            end else begin
                // fill: push new sample into delay line, drain previous differences
                dly[idx] <= x_in;
                y_out    <= fb;
            end
            y_valid <= 1'b1;
            if (last) begin
                ptr   <= 64'd0;
                phase <= ~phase;
            end else begin
                ptr <= ptr + 64'd1;
            end
        end
    end

    // before the first frame completes, at most 63 butterflies have been issued
    always @(posedge clk) if (armed) assert (bfly_cnt <= 64'd63);
endmodule

module mtile_od_loader (
    input  wire         clk,
    input  wire         step,
    input  wire         req,
    input  wire         ext_hold,
    input  wire [127:0] din,
    input  wire [3:0]   raddr,
    output wire [127:0] rdata,
    output wire         bus_line,
    output wire         busy_o
);
    // tile register: 16 rows of 128-bit data
    reg [127:0] tile [0:15];
    reg         busy;
    reg [4:0]   cnt;    // completion countdown
    reg [3:0]   beats;  // rows loaded so far
    reg         armed;  // sticky: set at first accepted request
    reg         pv;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) tile[i] = 128'd0;
        busy  = 1'b0;
        cnt   = 5'd0;
        beats = 4'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    // open-drain drivers on a wired-AND ready line with external pull-up:
    // each driver pulls the line low while its input is asserted, otherwise releases it
    wire [1:0] od_pull = {ext_hold, busy};
    wire [1:0] od_rel  = ~od_pull;
    assign bus_line = &od_rel;

    always @(posedge clk) begin
        if (step) begin
            if (busy) begin
                tile[beats] <= din;
                if (beats == 4'd15) begin
                    busy  <= 1'b0;
                    cnt   <= 5'd0;
                    beats <= 4'd0;
                end else begin
                    beats <= beats + 4'd1;
                    cnt   <= cnt - 5'd1;
                end
            end else if (req && bus_line) begin
                busy  <= 1'b1;
                cnt   <= 5'd16;
                beats <= 4'd0;
                armed <= 1'b1;
            end
        end
    end

    assign rdata  = tile[raddr];
    assign busy_o = busy;

    always @(posedge clk) pv <= 1'b1;

    // bounded response: countdown never expired while the load was still outstanding
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(busy) || $past(cnt) != 5'd0);
endmodule

module razor_shadow_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [63:0] d_main,
    input  wire [63:0] d_late,
    output reg  [63:0] main_q,
    output reg  [63:0] shadow_q,
    output reg  [63:0] err_cnt,
    output reg         razor_err
);
    localparam [1:0] IDLE    = 2'd0;
    localparam [1:0] ARMED   = 2'd1;
    localparam [1:0] STARTED = 2'd2;
    localparam [1:0] DONE    = 2'd3;

    reg [1:0] phase = IDLE;
    reg armed = 1'b0;
    reg started = 1'b0;
    reg finished = 1'b0;

    initial begin
        main_q    = 64'd0;
        shadow_q  = 64'd0;
        err_cnt   = 64'd0;
        razor_err = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= IDLE;
            armed     <= 1'b0;
            started   <= 1'b0;
            finished  <= 1'b0;
            main_q    <= 64'd0;
            shadow_q  <= 64'd0;
            err_cnt   <= 64'd0;
            razor_err <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    main_q   <= d_main;
                    armed    <= 1'b1;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= ARMED;
                end
                ARMED: begin
                    shadow_q <= d_late;
                    started  <= 1'b1;
                    phase    <= STARTED;
                end
                STARTED: begin
                    razor_err <= (main_q != shadow_q);
                    if (main_q != shadow_q) begin
                        main_q  <= shadow_q;
                        err_cnt <= err_cnt + 64'd1;
                    end
                    finished <= 1'b1;
                    phase    <= DONE;
                end
                default: begin
                    armed    <= 1'b0;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (finished) assert (started && armed);
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
    reg [7:0] bitcnt = 8'd0;   // bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
    wire       last     = busy && ce && (bitcnt == 8'd15);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
            bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
            if (bitcnt == 8'd15) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
                    remain  <= LEN - 64'd1;
                    held    <= 64'd1;
                end
            end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module conv_enc_win (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    input wire start,
    input wire stop,
    output reg c0,
    output reg c1,
    output reg win,
    output reg [15:0] nbits
);
    // constraint-length-4 shift register of past input bits (4 entries)
    reg [3:0] sr;
    initial sr = 4'b0000;
    initial c0 = 1'b0;
    initial c1 = 1'b0;
    initial win = 1'b0;
    initial nbits = 16'd0;

    wire [3:0] sr_n = {sr[2:0], din};

    // G0 = 1111 computed incrementally as a sliding-window parity,
    // G1 = 1011 computed directly from the next shift-register contents
    always @(posedge clk) begin
        if (rst) begin
            sr    <= 4'b0000;
            c0    <= 1'b0;
            c1    <= 1'b0;
            nbits <= 16'd0;
        end else if (ce) begin
            sr    <= sr_n;
            c0    <= c0 ^ din ^ sr[3];
            c1    <= sr_n[3] ^ sr_n[1] ^ sr_n[0];
            nbits <= nbits + 16'd1;
        end
    end

    // observation window: opened by start, closed by stop
    always @(posedge clk) begin
        if (rst)
            win <= 1'b0;
        else if (start)
            win <= 1'b1;
        else if (stop)
            win <= 1'b0;
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    // inside the window, the XOR of the two code bits equals the input bit
    // that sat in tap position 1 before the shift
    always @(posedge clk)
        if (pv && win && $past(ce) && !$past(rst))
            assert ((c0 ^ c1) == $past(sr[1]));
endmodule

module cordic_rot64 (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        ack,
    input  wire [63:0] x_in,
    input  wire [63:0] y_in,
    input  wire [63:0] z_in,
    output wire [63:0] x_out,
    output wire [63:0] y_out,
    output wire [63:0] z_out,
    output wire        busy_o,
    output wire        done_o
);
    localparam [63:0] N_ITER = 64'd32;

    reg signed [63:0] x, y, z;
    reg [63:0] iter, remaining;
    reg busy, done, armed;

    initial begin
        x = 64'd0; y = 64'd0; z = 64'd0;
        iter = 64'd0; remaining = N_ITER;
        busy = 1'b0; done = 1'b0; armed = 1'b0;
    end

    // 32-entry arctangent ROM, angle in Q32 radians held in 64 bits
    function [63:0] atan_lut;
        input [4:0] i;
        begin
            case (i)
                5'd0: atan_lut = 64'h00000000C90FDAA2;
                5'd1: atan_lut = 64'h0000000076B19C16;
                5'd2: atan_lut = 64'h000000003EB6EBF2;
                5'd3: atan_lut = 64'h000000001FD5BA9B;
                5'd4: atan_lut = 64'h000000000FFAADDC;
                5'd5: atan_lut = 64'h0000000007FF556F;
                5'd6: atan_lut = 64'h0000000003FFEAAB;
                5'd7: atan_lut = 64'h0000000001FFFD55;
                default: atan_lut = 64'd1 << (6'd32 - {1'b0, i});
            endcase
        end
    endfunction

    wire [4:0] sh = iter[4:0];

    always @(posedge clk) begin
        if (rst) begin
            x <= 64'd0; y <= 64'd0; z <= 64'd0;
            iter <= 64'd0; remaining <= N_ITER;
            busy <= 1'b0; done <= 1'b0; armed <= 1'b0;
        end else if (ce) begin
            if (start && !busy) begin
                x <= x_in; y <= y_in; z <= z_in;
                iter <= 64'd0;
                remaining <= N_ITER;
                busy <= 1'b1;
                done <= 1'b0;
                armed <= 1'b1;
            end else begin
                if (ack) armed <= 1'b0;
                if (busy) begin
                    if (z[63] == 1'b0) begin
                        x <= x - (y >>> sh);
                        y <= y + (x >>> sh);
                        z <= z - atan_lut(sh);
                    end else begin
                        x <= x + (y >>> sh);
                        y <= y - (x >>> sh);
                        z <= z + atan_lut(sh);
                    end
                    iter <= iter + 64'd1;
                    remaining <= remaining - 64'd1;
                    if (iter == N_ITER - 64'd1) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                    end
                end
            end
        end
    end

    assign x_out = x;
    assign y_out = y;
    assign z_out = z;
    assign busy_o = busy;
    assign done_o = done;

    // After a start (armed) until ack: never busy with the iteration budget exhausted
    always @(posedge clk)
        if (armed)
            assert (!(busy && remaining == 64'd0));
endmodule

module gray_tally (
    input  wire        clk,
    input  wire        start,
    input  wire        stop,
    input  wire        step,
    output reg  [63:0] bin,
    output reg  [63:0] gray,
    output reg         armed
);
    initial bin   = 64'd0;
    initial gray  = 64'd0;
    initial armed = 1'b0;

    // next binary count and the bits that change on increment
    wire [63:0] bin_nx = bin + 64'd1;
    wire [63:0] diff   = bin ^ bin_nx;
    // binary-to-Gray conversion of the change mask: XOR each bit with its upper neighbour
    wire [63:0] flip   = diff ^ (diff >> 1);

    // tally counters: binary count plus an incrementally maintained Gray image
    always @(posedge clk) begin
        if (start) begin
            bin  <= 64'd0;
            gray <= 64'd0;
        end else if (step) begin
            bin  <= bin_nx;
            gray <= gray ^ flip;
        end
    end

    // observation window: opened by start, closed by stop (stop may never come)
    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        else if (stop)
            armed <= 1'b0;
    end

    // inside the window the Gray image is zero exactly when the binary count is zero
    assert property (!armed || ((gray == 64'd0) == (bin == 64'd0)));
endmodule

module bitslip_align (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_slip,
    input  wire        i_lock,
    input  wire [31:0] i_word,
    output wire [31:0] o_word,
    output wire        o_armed
);
    // two-word window of the incoming serial stream
    reg [63:0] window  = 64'd0;
    // slip offset (up counter) and its redundant remaining-slips counter (down counter)
    reg [31:0] slip    = 32'd0;
    reg [31:0] slip_dn = 32'd31;
    // sticky: set the first time word lock is reported
    reg        armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            window <= {window[31:0], i_word};
            if (i_lock)
                armed <= 1'b1;
            if (i_slip) begin
                // up counter wraps when the down counter is exhausted
                slip    <= (slip_dn == 32'd0)  ? 32'd0  : slip + 32'd1;
                // down counter reloads when the up counter hits the last offset
                slip_dn <= (slip == 32'd31)    ? 32'd31 : slip_dn - 32'd1;
            end
        end
    end

    wire [63:0] shifted = window << slip[4:0];
    assign o_word  = shifted[63:32];
    assign o_armed = armed;

    // after lock: the slip offset never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip <= 32'd31);

    // after lock: the remaining-slip counter never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip_dn <= 32'd31);
endmodule

module mdio_master64 (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        op_rd,
    input  wire [4:0]  phy_ad,
    input  wire [4:0]  reg_ad,
    input  wire [15:0] wr_data,
    input  wire        mdio_i,
    output wire        mdio_o,
    output wire        mdio_oe,
    output wire        busy,
    output wire [63:0] o_rd_data
);
    localparam [2:0] IDLE = 3'd0, PRE = 3'd1, CMD = 3'd2, TA = 3'd3, DATA = 3'd4;

    reg [2:0]  phase      = IDLE;
    reg [63:0] pre_cnt    = 64'd0;
    reg [31:0] frame_sr   = 32'd0;
    reg [63:0] bit_cnt    = 64'd0;
    reg        ta         = 1'b0;
    reg        op_read    = 1'b0;
    reg [15:0] rx_sh      = 16'd0;
    reg [63:0] rd_data    = 64'd0;
    reg        ta_pending = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            case (phase)
                IDLE: begin
                    if (start) begin
                        op_read  <= op_rd;
                        frame_sr <= {2'b01, (op_rd ? 2'b10 : 2'b01), phy_ad, reg_ad, 2'b10, wr_data};
                        pre_cnt  <= 64'd0;
                        bit_cnt  <= 64'd0;
                        phase    <= PRE;
                    end
                end
                PRE: begin
                    if (pre_cnt == 64'd31) begin
                        pre_cnt <= 64'd0;
                        bit_cnt <= 64'd0;
                        phase   <= CMD;
                    end else begin
                        pre_cnt <= pre_cnt + 64'd1;
                    end
                end
                CMD: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd13) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b1;
                        phase   <= TA;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                TA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd1) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b0;
                        phase   <= DATA;
                        if (op_read) ta_pending <= 1'b1;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                DATA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (op_read) rx_sh <= {rx_sh[14:0], mdio_i};
                    if (bit_cnt == 64'd15) begin
                        bit_cnt <= 64'd0;
                        phase   <= IDLE;
                        if (op_read) begin
                            rd_data    <= {48'd0, rx_sh[14:0], mdio_i};
                            ta_pending <= 1'b0;
                        end
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    ta    <= 1'b0;
                end
            endcase
        end
    end

    assign mdio_oe   = (phase == PRE) || (phase == CMD) || ((phase == TA || phase == DATA) && !op_read);
    assign mdio_o    = (phase == PRE) ? 1'b1 : frame_sr[31];
    assign busy      = (phase != IDLE);
    assign o_rd_data = rd_data;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(ta_pending))
            assert ($stable(rd_data));
endmodule

module phase_clkgen (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cfg_we,
    input  wire [2:0]  cfg_sel,
    input  wire [15:0] cfg_div,
    input  wire [15:0] cfg_off,
    input  wire        win_open,
    input  wire        win_close,
    output wire [7:0]  clk_out,
    output wire [7:0]  align_pulse
);
    localparam [15:0] LAP = 16'd240;

    reg [15:0]  cyc        = 16'd0;
    reg [15:0]  lap        = 16'd0;
    reg [127:0] div_sh     = {8{16'd2}};
    reg [127:0] off_sh     = 128'd0;
    reg [127:0] div_act    = {8{16'd2}};
    reg [127:0] off_act    = 128'd0;
    reg [127:0] ph         = 128'd0;
    reg [15:0]  align_cnt0 = 16'd0;
    reg         win        = 1'b0;
    reg         pv         = 1'b0;

    wire        wrap = (cyc == LAP - 16'd1);
    wire [15:0] off0 = off_act[15:0];

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : outs
            assign clk_out[g]     = ph[g*16 +: 16] < (div_act[g*16 +: 16] >> 1);
            assign align_pulse[g] = ce && (cyc == off_act[g*16 +: 16]);
        end
    endgenerate

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            cyc        <= 16'd0;
            lap        <= 16'd0;
            align_cnt0 <= 16'd0;
            win        <= 1'b0;
            ph         <= 128'd0;
            div_act    <= {8{16'd2}};
            off_act    <= 128'd0;
            div_sh     <= {8{16'd2}};
            off_sh     <= 128'd0;
        end else begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;
            if (cfg_we) begin
                div_sh[cfg_sel*16 +: 16] <= cfg_div;
                off_sh[cfg_sel*16 +: 16] <= cfg_off;
            end
            if (ce) begin
                if (wrap) begin
                    cyc        <= 16'd0;
                    lap        <= lap + 16'd1;
                    align_cnt0 <= 16'd0;
                end else begin
                    cyc <= cyc + 16'd1;
                    if (cyc == off0) align_cnt0 <= align_cnt0 + 16'd1;
                end
                for (i = 0; i < 8; i = i + 1) begin
                    if (wrap) begin
                        div_act[i*16 +: 16] <= (div_sh[i*16 +: 16] < 16'd2) ? 16'd2 : div_sh[i*16 +: 16];
                        off_act[i*16 +: 16] <= (off_sh[i*16 +: 16] >= LAP) ? (LAP - 16'd1) : off_sh[i*16 +: 16];
                    end
                    if (cyc == off_act[i*16 +: 16])
                        ph[i*16 +: 16] <= 16'd0;
                    else if (ph[i*16 +: 16] >= div_act[i*16 +: 16] - 16'd1)
                        ph[i*16 +: 16] <= 16'd0;
                    else
                        ph[i*16 +: 16] <= ph[i*16 +: 16] + 16'd1;
                end
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(lap) && $past(align_cnt0) >= 16'd1)
            assert ($stable(align_cnt0));
endmodule

module bitserial_alu (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       arm,
    input  wire       start,
    input  wire       ack,
    input  wire [1:0] op,
    input  wire [7:0] a_in,
    input  wire [7:0] b_in,
    output wire [7:0] result,
    output wire       done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase      = 2'd0;
    reg [7:0] cnt        = 8'd0;
    reg       seen_arm   = 1'b0;
    reg       seen_start = 1'b0;
    reg [1:0] op_r       = 2'd0;
    reg [7:0] opa        = 8'd0;
    reg [7:0] opb        = 8'd0;
    reg [7:0] res        = 8'd0;
    reg       carry      = 1'b0;

    wire abit = opa[0];
    wire bbit = (op_r == 2'd1) ? ~opb[0] : opb[0];
    wire sbit = abit ^ bbit ^ carry;
    wire cout = (abit & bbit) | (abit & carry) | (bbit & carry);
    wire fbit = (op_r == 2'd2) ? (abit & opb[0]) :
                (op_r == 2'd3) ? (abit ^ opb[0]) : sbit;

    assign result = res;
    assign done   = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            cnt        <= 8'd0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            carry      <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase      <= ARMED;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        op_r       <= op;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase      <= RUN;
                        seen_start <= 1'b1;
                        cnt        <= 8'd0;
                        opa        <= a_in;
                        opb        <= b_in;
                        res        <= 8'd0;
                        carry      <= (op_r == 2'd1);
                    end
                end
                RUN: begin
                    res   <= {fbit, res[7:1]};
                    opa   <= {1'b0, opa[7:1]};
                    opb   <= {1'b0, opb[7:1]};
                    carry <= (op_r[1] == 1'b0) ? cout : 1'b0;
                    if (cnt == 8'd7) begin
                        phase <= DONE;
                        cnt   <= 8'd8;
                    end else begin
                        cnt <= cnt + 8'd1;
                    end
                end
                DONE: begin
                    if (ack) begin
                        phase      <= IDLE;
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assert property (phase != 2'd3 || (seen_arm && seen_start));
endmodule

module wfq_sched16 (
    input  wire        clk,
    input  wire        step,
    input  wire        enq_valid,
    input  wire [3:0]  enq_q,
    input  wire        cfg_we,
    input  wire [3:0]  cfg_q,
    input  wire [15:0] cfg_weight,
    output wire        enq_ready,
    output wire        backlogged,
    output wire [3:0]  grant_q,
    output wire        sched_idle
);
    // scheduling state array: 16 queues x 16-bit virtual time / weight / backlog
    reg [255:0] vtime;
    reg [255:0] weight;
    reg [255:0] backlog;
    reg [15:0]  active;
    reg [4:0]   active_cnt;
    reg [15:0]  gvt;
    reg         armed;

    initial begin
        vtime      = 256'd0;
        weight     = {16{16'd1}};
        backlog    = 256'd0;
        active     = 16'd0;
        active_cnt = 5'd0;
        gvt        = 16'd0;
        armed      = 1'b0;
    end

    // weighted fair selection: active queue with smallest virtual time
    reg [3:0]  sel;
    reg [15:0] best_vt;
    reg        found;
    integer j;
    always @(*) begin
        found = 1'b0;
        sel = 4'd0;
        best_vt = 16'd0;
        for (j = 0; j < 16; j = j + 1)
            if (active[j] && (!found || vtime[j*16 +: 16] < best_vt)) begin
                found = 1'b1;
                sel = j[3:0];
                best_vt = vtime[j*16 +: 16];
            end
    end

    wire [15:0] sel_backlog = backlog[sel*16 +: 16];
    wire [15:0] sel_weight  = weight[sel*16 +: 16];
    wire [15:0] enq_backlog = backlog[enq_q*16 +: 16];
    wire [15:0] enq_vt      = vtime[enq_q*16 +: 16];

    wire dispatch = step && (active != 16'd0);
    wire do_enq   = enq_valid && !step && (enq_backlog != 16'hFFFF);

    always @(posedge clk) begin
        if (cfg_we)
            weight[cfg_q*16 +: 16] <= cfg_weight;
        if (dispatch) begin
            armed <= 1'b1;
            gvt <= best_vt;
            vtime[sel*16 +: 16] <= best_vt + sel_weight;
            backlog[sel*16 +: 16] <= sel_backlog - 16'd1;
            if (sel_backlog == 16'd1) begin
                active[sel] <= 1'b0;
                active_cnt <= active_cnt - 5'd1;
            end
        end else if (do_enq) begin
            backlog[enq_q*16 +: 16] <= enq_backlog + 16'd1;
            if (!active[enq_q]) begin
                active[enq_q] <= 1'b1;
                active_cnt <= active_cnt + 5'd1;
                if (enq_vt < gvt)
                    vtime[enq_q*16 +: 16] <= gvt;
            end
        end
    end

    assign enq_ready  = !step;
    assign grant_q    = sel;
    assign sched_idle = (active_cnt == 5'd0);
    assign backlogged = (active != 16'd0);

    // after the first dispatch: idle flag and backlogged flag never both set
    always @(*) if (armed) assert (!(sched_idle && backlogged));
endmodule

module axi_burst_to_lite (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_awvalid,
    input  wire [3:0]   i_awid,
    input  wire [31:0]  i_awaddr,
    input  wire [2:0]   i_awlen,
    input  wire         i_wr_en,
    input  wire [2:0]   i_wr_idx,
    input  wire [127:0] i_wr_data,
    input  wire [1:0]   i_lite_bresp,
    input  wire         i_bready,
    output wire         o_awready,
    output wire         o_lite_valid,
    output wire [31:0]  o_lite_awaddr,
    output wire [127:0] o_lite_wdata,
    output wire         o_bvalid,
    output wire [3:0]   o_bid,
    output wire [1:0]   o_bresp
);
    reg         busy = 1'b0;
    reg         bvalid = 1'b0;
    reg         win = 1'b0;
    reg [3:0]   beats_left = 4'd0;
    reg [3:0]   deadline = 4'd0;
    reg [31:0]  addr = 32'd0;
    reg [3:0]   id = 4'd0;
    reg [1:0]   resp_acc = 2'd0;
    reg [2:0]   bidx = 3'd0;
    reg [127:0] wbuf [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            wbuf[i] = 128'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            bvalid <= 1'b0;
            win <= 1'b0;
            beats_left <= 4'd0;
            deadline <= 4'd0;
            addr <= 32'd0;
            id <= 4'd0;
            resp_acc <= 2'd0;
            bidx <= 3'd0;
        end else if (i_ce) begin
            if (!busy && !bvalid && i_awvalid) begin
                busy <= 1'b1;
                win <= 1'b1;
                id <= i_awid;
                addr <= i_awaddr;
                beats_left <= {1'b0, i_awlen} + 4'd1;
                deadline <= {1'b0, i_awlen} + 4'd1;
                resp_acc <= 2'd0;
                bidx <= 3'd0;
            end else if (busy) begin
                beats_left <= beats_left - 4'd1;
                deadline <= deadline - 4'd1;
                addr <= addr + 32'd16;
                bidx <= bidx + 3'd1;
                if (i_lite_bresp > resp_acc)
                    resp_acc <= i_lite_bresp;
                if (beats_left == 4'd1) begin
                    busy <= 1'b0;
                    bvalid <= 1'b1;
                end
            end else if (bvalid && i_bready) begin
                bvalid <= 1'b0;
                win <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (!rst && i_ce && i_wr_en)
            wbuf[i_wr_idx] <= i_wr_data;

    assign o_awready     = !busy && !bvalid;
    assign o_lite_valid  = busy;
    assign o_lite_awaddr = addr;
    assign o_lite_wdata  = wbuf[bidx];
    assign o_bvalid      = bvalid;
    assign o_bid         = id;
    assign o_bresp       = resp_acc;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(beats_left) == 4'd0 || $past(deadline) != 4'd0);
endmodule

module qspi_xip_ctrl (
    input  wire        clk,
    input  wire        ce,
    input  wire        req,
    input  wire [23:0] addr,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_wdata,
    input  wire [3:0]  io_in,
    output wire [3:0]  io_out,
    output wire        cs_n,
    output reg         busy,
    output reg         pf_valid,
    output reg  [31:0] pf_data
);
    reg        cs_active  = 1'b0;
    reg [31:0] cnt        = 32'd0;
    reg [31:0] nib        = 32'd0;
    reg [31:0] sh_out     = 32'd0;
    reg [7:0]  cfg_opcode = 8'hEB;
    reg        armed      = 1'b0;

    initial busy     = 1'b0;
    initial pf_valid = 1'b0;
    initial pf_data  = 32'd0;

    assign cs_n   = !cs_active;
    assign io_out = sh_out[31:28];

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                    cnt       <= 32'd20;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
                if (cnt <= 32'd8) begin
                    pf_data <= {pf_data[27:0], io_in};
                    if (nib == 32'd7) begin
                        pf_valid  <= 1'b1;
                        cs_active <= 1'b0;
                        nib       <= 32'd0;
                    end else begin
                        nib <= nib + 32'd1;
                    end
                end
                if (cnt == 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(busy && pf_valid));

    always @(posedge clk)
        if (armed) assert (!(cs_active && !busy));
endmodule

module pretrig_capture (
    input  wire        clk,
    input  wire        ce,
    input  wire        rearm,
    input  wire        trig,
    input  wire [63:0] sample,
    input  wire [5:0]  rd_idx,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured
);
    localparam [63:0] DEPTH = 64'd48;
    reg [63:0] chain [0:47];
    reg [47:0] valid;
    reg [63:0] count;
    reg        frozen;
    reg        pv;
    integer i;

    initial begin
        for (i = 0; i < 48; i = i + 1) chain[i] = 64'd0;
        valid  = 48'd0;
        count  = 64'd0;
        frozen = 1'b0;
        pv     = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rearm) begin
            frozen <= 1'b0;
            count  <= 64'd0;
            valid  <= 48'd0;
        end else if (ce && !frozen) begin
            if (trig && count == DEPTH) begin
                frozen <= 1'b1;
            end else begin
                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
    output wire        out_fire
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module pwm_fault_trip (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       fault_in,
    input  wire       cfg_we,
    input  wire [3:0] cfg_hi,
    input  wire [3:0] cfg_lo,
    input  wire       clr_req,
    input  wire       duty_we,
    input  wire [7:0] duty_in,
    output reg  [3:0] out_hi,
    output reg  [3:0] out_lo
);
    reg [7:0] cnt;
    reg [7:0] duty;
    reg       fault_lat;
    reg [3:0] safe_hi;
    reg [3:0] safe_lo;
    reg       clr_arm;
    reg       no_clear_yet;

    initial cnt = 8'd0;
    initial duty = 8'd128;
    initial fault_lat = 1'b0;
    initial safe_hi = 4'b0000;
    initial safe_lo = 4'b1111;
    initial clr_arm = 1'b0;
    initial no_clear_yet = 1'b1;
    initial out_hi = 4'b0000;
    initial out_lo = 4'b1111;

    wire pwm_on = (cnt < duty);

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= 8'd0;
            duty      <= 8'd128;
            fault_lat <= 1'b0;
            safe_hi   <= 4'b0000;
            safe_lo   <= 4'b1111;
            clr_arm   <= 1'b0;
            out_hi    <= 4'b0000;
            out_lo    <= 4'b1111;
        end else if (ce) begin
            cnt <= cnt + 8'd1;
            if (duty_we)
                duty <= duty_in;
            if (cfg_we) begin
                safe_hi <= cfg_hi;
                safe_lo <= cfg_lo & ~cfg_hi;
            end
            if (clr_req)
                clr_arm <= 1'b1;
            if (fault_in)
                fault_lat <= 1'b1;
            else if (clr_arm && fault_lat) begin
                fault_lat    <= 1'b0;
                clr_arm      <= 1'b0;
                no_clear_yet <= 1'b0;
            end
            if (fault_in || fault_lat) begin
                out_hi <= safe_hi;
                out_lo <= safe_lo;
            end else begin
                out_hi <= {4{pwm_on}};
                out_lo <= {4{~pwm_on}};
            end
        end
    end

    always @(posedge clk)
        if (no_clear_yet)
            assert ((out_hi & out_lo) == 4'd0);
endmodule

module tag_array_precedence (
    input wire clk,
    input wire ce,
    input wire fill,
    input wire [6:0] fill_set,
    input wire [7:0] fill_tag,
    input wire flush,
    input wire lookup,
    input wire [6:0] lookup_set,
    input wire [7:0] lookup_tag,
    output wire hit
);
    localparam [6:0] NSETS = 7'd96;

    reg [7:0] tag_mem [0:95];
    reg [95:0] valid;
    reg filled_any;
    reg [7:0] fill_cnt;
    reg hit_q;
    reg armed;

    integer i;
    initial begin
        for (i = 0; i < 96; i = i + 1) tag_mem[i] = 8'd0;
        valid = 96'd0;
        filled_any = 1'b0;
        fill_cnt = 8'd0;
        hit_q = 1'b0;
        armed = 1'b0;
    end

    wire fill_ok = fill && (fill_set < NSETS);
    wire look_ok = lookup && (lookup_set < NSETS);
    wire raw_hit = look_ok && valid[lookup_set] && (tag_mem[lookup_set] == lookup_tag);

    always @(posedge clk) begin
        if (ce && !flush && fill_ok)
            tag_mem[fill_set] <= fill_tag;
    end

    always @(posedge clk) begin
        if (ce) begin
            hit_q <= !flush && raw_hit;
            if (flush) begin
                valid <= 96'd0;
                filled_any <= 1'b0;
                fill_cnt <= 8'd0;
            end else if (fill_ok) begin
                valid[fill_set] <= 1'b1;
                filled_any <= 1'b1;
                if (fill_cnt != 8'hFF) fill_cnt <= fill_cnt + 8'd1;
                armed <= 1'b1;
            end
        end
    end

    assign hit = hit_q;

    always @(posedge clk)
        if (armed && hit_q)
            assert (filled_any);

    always @(posedge clk)
        if (armed && hit_q)
            assert (fill_cnt != 8'd0);
endmodule

module ecc_dbg_mem (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cmd_valid,
    input  wire        cmd_wr,
    input  wire [5:0]  cmd_addr,
    input  wire [31:0] cmd_wdata,
    input  wire [38:0] cmd_inject,
    input  wire        rsp_ack,
    output wire        rsp_valid,
    output reg  [31:0] rsp_rdata,
    output reg  [6:0]  rsp_syndrome,
    output reg         rsp_sbe,
    output reg         rsp_dbe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, START = 2'd2, DONE = 2'd3;

    function [38:0] secded_enc(input [31:0] d);
        integer i, j, p, k;
        reg [38:0] c;
        reg par;
        begin
            c = 39'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    c[i] = d[j];
                    j = j + 1;
                end
            end
            for (p = 0; p < 6; p = p + 1) begin
                par = 1'b0;
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) par = par ^ c[k];
                c[1 << p] = par;
            end
            c[0] = ^c[38:1];
            secded_enc = c;
        end
    endfunction

    function [5:0] secded_syn(input [38:0] c);
        integer p, k;
        reg [5:0] s;
        begin
            s = 6'd0;
            for (p = 0; p < 6; p = p + 1)
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) s[p] = s[p] ^ c[k];
            secded_syn = s;
        end
    endfunction

    function [31:0] secded_data(input [38:0] c);
        integer i, j;
        reg [31:0] d;
        begin
            d = 32'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    d[j] = c[i];
                    j = j + 1;
                end
            end
            secded_data = d;
        end
    endfunction

    reg [1:0]  phase      = IDLE;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen     = 1'b0;
    reg        wr_q       = 1'b0;
    reg [5:0]  addr_q     = 6'd0;
    reg [31:0] wdata_q    = 32'd0;
    reg [38:0] inj_q      = 39'd0;
    reg [38:0] rd_cw_q    = 39'd0;
    reg [38:0] mem [0:63];

    integer n;
    initial begin
        for (n = 0; n < 64; n = n + 1) mem[n] = 39'd0;
        rsp_rdata    = 32'd0;
        rsp_syndrome = 7'd0;
        rsp_sbe      = 1'b0;
        rsp_dbe      = 1'b0;
    end

    wire [38:0] wr_cw = secded_enc(wdata_q) ^ inj_q;
    wire [5:0]  syn   = secded_syn(rd_cw_q);
    wire        ovp   = ^rd_cw_q;
    wire        sbe   = ovp;
    wire        dbe   = !ovp && (syn != 6'd0);
    wire [38:0] fixed = sbe ? (rd_cw_q ^ (39'd1 << syn)) : rd_cw_q;

    assign rsp_valid = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: if (cmd_valid) begin
                    phase      <= ARMED;
                    arm_seen   <= 1'b1;
                    start_seen <= 1'b0;
                    wr_q       <= cmd_wr;
                    addr_q     <= cmd_addr;
                    wdata_q    <= cmd_wdata;
                    inj_q      <= cmd_inject;
                    if (cmd_wr) q_seen <= 1'b1;
                end
                ARMED: begin
                    if (wr_q) mem[addr_q] <= wr_cw;
                    rd_cw_q    <= wr_q ? wr_cw : mem[addr_q];
                    start_seen <= 1'b1;
                    phase      <= START;
                end
                START: begin
                    rsp_rdata    <= secded_data(fixed);
                    rsp_syndrome <= {ovp, syn};
                    rsp_sbe      <= sbe;
                    rsp_dbe      <= dbe;
                    phase        <= DONE;
                end
                DONE: if (rsp_ack) begin
                    phase      <= IDLE;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    assert property (!q_seen || !rsp_valid || (arm_seen && start_seen));
endmodule

module mpop_fifo (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire [31:0] din,
    input wire [2:0] npop_req,
    input wire open,
    input wire close,
    output reg [31:0] dout0,
    output reg [31:0] dout1,
    output reg [31:0] dout2,
    output reg [31:0] dout3,
    output wire [2:0] npop_o,
    output wire [31:0] count_o
);
    reg [31:0] bank0 [0:3];
    reg [31:0] bank1 [0:3];
    reg [31:0] bank2 [0:3];
    reg [31:0] bank3 [0:3];
    integer k;
    initial begin
        for (k = 0; k < 4; k = k + 1) begin
            bank0[k] = 32'd0; bank1[k] = 32'd0; bank2[k] = 32'd0; bank3[k] = 32'd0;
        end
    end

    reg [4:0] wptr = 5'd0;
    reg [4:0] rptr = 5'd0;
    reg [31:0] count = 32'd0;
    reg win = 1'b0;
    reg push_ack = 1'b0;

    wire [4:0] occ = wptr - rptr;
    wire full = (occ >= 5'd16);
    wire do_push = push && !full;
    wire [2:0] req = (npop_req > 3'd4) ? 3'd4 : npop_req;
    wire [2:0] npop = ({2'b00, req} > occ) ? occ[2:0] : req;
    assign npop_o = npop;
    assign count_o = count;

    wire [3:0] i0 = rptr[3:0];
    wire [3:0] i1 = rptr[3:0] + 4'd1;
    wire [3:0] i2 = rptr[3:0] + 4'd2;
    wire [3:0] i3 = rptr[3:0] + 4'd3;

    always @(*) begin
        case (i0[1:0])
            2'd0: dout0 = bank0[i0[3:2]];
            2'd1: dout0 = bank1[i0[3:2]];
            2'd2: dout0 = bank2[i0[3:2]];
            default: dout0 = bank3[i0[3:2]];
        endcase
        case (i1[1:0])
            2'd0: dout1 = bank0[i1[3:2]];
            2'd1: dout1 = bank1[i1[3:2]];
            2'd2: dout1 = bank2[i1[3:2]];
            default: dout1 = bank3[i1[3:2]];
        endcase
        case (i2[1:0])
            2'd0: dout2 = bank0[i2[3:2]];
            2'd1: dout2 = bank1[i2[3:2]];
            2'd2: dout2 = bank2[i2[3:2]];
            default: dout2 = bank3[i2[3:2]];
        endcase
        case (i3[1:0])
            2'd0: dout3 = bank0[i3[3:2]];
            2'd1: dout3 = bank1[i3[3:2]];
            2'd2: dout3 = bank2[i3[3:2]];
            default: dout3 = bank3[i3[3:2]];
        endcase
    end

    always @(posedge clk) begin
        if (ce && do_push) begin
            case (wptr[1:0])
                2'd0: bank0[wptr[3:2]] <= din;
                2'd1: bank1[wptr[3:2]] <= din;
                2'd2: bank2[wptr[3:2]] <= din;
                default: bank3[wptr[3:2]] <= din;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            rptr <= 5'd0;
            count <= 32'd0;
            win <= 1'b0;
            push_ack <= 1'b0;
        end else if (ce) begin
            wptr <= wptr + {4'd0, do_push};
            rptr <= rptr + {2'd0, npop};
            count <= count + {31'd0, do_push} - {29'd0, npop};
            push_ack <= do_push;
            if (open) win <= 1'b1;
            else if (close) win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && $rose(push_ack))
            assert (count <= 32'd16);
endmodule

module gshare_streak (
    input  wire        clk,
    input  wire        upd,
    input  wire        taken,
    input  wire [63:0] upd_pc,
    input  wire [63:0] fetch_pc,
    input  wire        restore,
    input  wire [63:0] restore_ghr,
    output wire        pred_taken
);
    reg [63:0] ghr      = 64'd0;
    reg [63:0] streak_t = 64'd0;
    reg [63:0] streak_n = 64'd0;
    reg        armed    = 1'b1;
    reg [1:0]  pht [0:255];
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            pht[i] = 2'b01;
    end

    wire [7:0] fidx = fetch_pc[9:2] ^ ghr[7:0];
    wire [7:0] uidx = upd_pc[9:2] ^ ghr[7:0];
    assign pred_taken = pht[fidx][1];

    wire [63:0] t_inc = (streak_t == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_t : streak_t + 64'd1;
    wire [63:0] n_inc = (streak_n == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_n : streak_n + 64'd1;

    always @(posedge clk) begin
        if (restore) begin
            ghr   <= restore_ghr;
            armed <= 1'b0;
        end else if (upd) begin
            ghr <= {ghr[62:0], taken};
            if (taken) begin
                pht[uidx] <= (pht[uidx] == 2'b11) ? 2'b11 : pht[uidx] + 2'b01;
                if (!ghr[0]) begin
                    streak_t <= 64'd1;
                    streak_n <= 64'd0;
                end else begin
                    streak_t <= t_inc;
                end
            end else begin
                pht[uidx] <= (pht[uidx] == 2'b00) ? 2'b00 : pht[uidx] - 2'b01;
                if (ghr[0]) begin
                    streak_n <= 64'd1;
                    streak_t <= 64'd0;
                end else begin
                    streak_n <= n_inc;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(streak_t) != 64'd0 && $past(streak_n) != 64'd0));
endmodule

module rst_seq24 (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_cfg_we,
    input  wire [127:0] i_cfg_order,
    input  wire [127:0] i_cfg_delay,
    input  wire         i_start,
    output wire [23:0]  o_dom_rst,
    output wire         o_busy
);
    localparam [4:0] LAST   = 5'd23;
    localparam [9:0] BUDGET = 10'd768;

    // programmed release order (24 x 5-bit domain ids) and per-step delays (24 x 5-bit)
    reg [127:0] cfg_order = 128'd0;
    reg [127:0] cfg_delay = 128'd0;
    reg [4:0]   step_idx  = 5'd0;
    reg [4:0]   dly_cnt   = 5'd0;
    reg [23:0]  dom_rst   = 24'hFFFFFF;
    reg         busy      = 1'b0;
    reg [9:0]   budget    = 10'd0;

    wire [4:0] cur_dom = cfg_order[step_idx*5 +: 5];
    wire [4:0] nxt_dly = cfg_delay[(step_idx + 5'd1)*5 +: 5];

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                if (i_cfg_we) begin
                    cfg_order <= i_cfg_order;
                    cfg_delay <= i_cfg_delay;
                end else if (i_start) begin
                    busy     <= 1'b1;
                    step_idx <= 5'd0;
                    dly_cnt  <= cfg_delay[4:0];
                    budget   <= BUDGET;
                    dom_rst  <= 24'hFFFFFF;
                end
            end else begin
                budget <= budget - 10'd1;
                if (dly_cnt != 5'd0) begin
                    dly_cnt <= dly_cnt - 5'd1;
                end else begin
                    if (cur_dom < 5'd24)
                        dom_rst[cur_dom] <= 1'b0;
                    if (step_idx == LAST) begin
                        busy     <= 1'b0;
                        step_idx <= 5'd0;
                    end else begin
                        step_idx <= step_idx + 5'd1;
                        dly_cnt  <= nxt_dly;
                    end
                end
            end
        end
    end

    assign o_dom_rst = dom_rst;
    assign o_busy    = busy;

    // after start accepted until sequence done: watchdog countdown never expires
    always @(*)
        assert (!busy || budget != 10'd0);
endmodule

module bus_timeout_mon (
    input  wire        clk,
    input  wire        i_clr,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire [31:0] i_thresh,
    input  wire        i_req,
    input  wire        i_resp,
    output wire        o_err_resp,
    output wire        o_timeout,
    output wire [31:0] o_txn_count
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_BUSY  = 2'd2;

    reg [1:0]  phase;
    reg [31:0] thresh;
    reg [31:0] wait_cnt;
    reg [31:0] txn_count;
    reg        to_err;
    reg        seen_arm;
    reg        seen_start;

    initial begin
        phase = P_IDLE;
        thresh = 32'd0;
        wait_cnt = 32'd0;
        txn_count = 32'd0;
        to_err = 1'b0;
        seen_arm = 1'b0;
        seen_start = 1'b0;
    end

    always @(posedge clk) begin
        if (i_clr) begin
            phase <= P_IDLE;
            thresh <= 32'd0;
            wait_cnt <= 32'd0;
            txn_count <= 32'd0;
            to_err <= 1'b0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_arm) begin
                        thresh <= i_thresh;
                        seen_arm <= 1'b1;
                        phase <= P_ARMED;
                    end
                end
                P_ARMED: begin
                    if (i_req) begin
                        seen_start <= 1'b1;
                        wait_cnt <= 32'd0;
                        txn_count <= txn_count + 32'd1;
                        phase <= P_BUSY;
                    end
                end
                P_BUSY: begin
                    if (i_resp) begin
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else if (wait_cnt >= thresh) begin
                        to_err <= 1'b1;
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else begin
                        wait_cnt <= wait_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_err_resp  = (phase == P_BUSY) && !i_resp && (wait_cnt >= thresh);
    assign o_timeout   = to_err;
    assign o_txn_count = txn_count;

    assert property (!to_err || (seen_arm && seen_start));
endmodule

module pdm_cic_precedence (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_pdm,
    output wire [31:0] o_pcm
);
    localparam [31:0] DEC = 32'd64;

    reg [31:0] integ1;
    reg [31:0] integ2;
    reg [31:0] dly1;
    reg [31:0] dly2;
    reg [31:0] pcm;
    reg [31:0] phase;
    reg        seen_one;
    reg        armed;

    initial integ1   = 32'd0;
    initial integ2   = 32'd0;
    initial dly1     = 32'd0;
    initial dly2     = 32'd0;
    initial pcm      = 32'd0;
    initial phase    = 32'd0;
    initial seen_one = 1'b0;
    initial armed    = 1'b0;

    wire [31:0] integ1_n = integ1 + {31'd0, i_pdm};
    wire [31:0] integ2_n = integ2 + integ1;
    wire [31:0] comb1    = integ2 - dly1;
    wire [31:0] comb2    = comb1 - dly2;
    wire        tick     = (phase == DEC - 32'd1);

    always @(posedge clk) begin
        if (i_ce) begin
            integ1 <= integ1_n;
            integ2 <= integ2_n;
            if (i_pdm)
                seen_one <= 1'b1;
            if (tick) begin
                phase <= 32'd0;
                dly1  <= integ2;
                dly2  <= comb1;
                pcm   <= comb2;
                armed <= 1'b1;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    assign o_pcm = pcm;

    always @(posedge clk) assert (!armed || pcm == 32'd0 || seen_one);
endmodule

module scan_unload_chain (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire [31:0] scan_in,
    input  wire [31:0] func_d,
    output wire [31:0] scan_out,
    output wire        busy_o
);
    // 32-entry scan chain of 32-bit scan flip-flops
    reg [31:0] chain [0:31];
    reg        busy     = 1'b0;
    reg [31:0] shifted  = 32'd0;
    reg [31:0] deadline = 32'd0;
    integer i;
    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) chain[k] = 32'd0;
    end

    assign scan_out = chain[31];
    assign busy_o   = busy;

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            shifted  <= 32'd0;
            deadline <= 32'd0;
        end else if (ce) begin
            if (busy) begin
                // test mode: scan mux selects the previous flop
                for (i = 31; i > 0; i = i - 1)
                    chain[i] <= chain[i-1];
                chain[0] <= scan_in;
                shifted  <= shifted + 32'd1;
                deadline <= deadline - 32'd1;
                if (shifted == 32'd31)
                    busy <= 1'b0;
            end else if (req) begin
                // accept unload request: countdown guarantees completion in 32 shifts
                busy     <= 1'b1;
                shifted  <= 32'd0;
                deadline <= 32'd32;
            end else begin
                // functional mode: scan mux selects functional data
                for (i = 0; i < 32; i = i + 1)
                    chain[i] <= chain[i] ^ func_d;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy))
            assert ($past(deadline) != 32'd0);
endmodule

module median_tick_filter (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        in_valid,
    input  wire [15:0] in_px,
    input  wire        sess_open,
    input  wire        sess_close,
    output wire [15:0] med_px,
    output wire        med_valid,
    output wire [15:0] fill_out
);
    // 8-entry sliding window of 16-bit price samples (packed)
    reg [127:0] win   = 128'd0;
    // thermometer occupancy mask: one bit per filled slot
    reg [7:0]   mask  = 8'h00;
    // occupancy counter, saturates at 8
    reg [15:0]  fill  = 16'd0;
    // trading-session window register (scope: open .. close)
    reg         armed = 1'b0;

    // odd-even transposition sorting network over 8 entries
    function [127:0] sort8;
        input [127:0] v;
        integer st, j;
        reg [127:0] t;
        reg [15:0] a, b;
        begin
            t = v;
            for (st = 0; st < 8; st = st + 1) begin
                for (j = (st % 2); j < 7; j = j + 2) begin
                    a = t[16*j +: 16];
                    b = t[16*(j+1) +: 16];
                    if (a > b) begin
                        t[16*j +: 16]     = b;
                        t[16*(j+1) +: 16] = a;
                    end
                end
            end
            sort8 = t;
        end
    endfunction

    wire [127:0] sorted = sort8(win);
    assign med_px    = sorted[16*3 +: 16];
    assign med_valid = mask[7];
    assign fill_out  = fill;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 128'd0;
            mask  <= 8'h00;
            fill  <= 16'd0;
            armed <= 1'b0;
        end else if (ce) begin
            if (sess_close) begin
                armed <= 1'b0;
                mask  <= 8'h00;
                fill  <= 16'd0;
            end else begin
                if (sess_open)
                    armed <= 1'b1;
                if (in_valid) begin
                    win  <= {win[111:0], in_px};
                    mask <= {mask[6:0], 1'b1};
                    if (!mask[7])
                        fill <= fill + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside a session, whenever the clock-enable burst ends, occupancy is at most 8
    always @(posedge clk)
        if (pv && armed && $fell(ce))
            assert (fill <= 16'd8);
endmodule

module aes_round_seq64 (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire arm,
    input wire start,
    input wire ack,
    input wire [63:0] pt,
    input wire [63:0] key_in,
    output wire done,
    output wire [63:0] ct
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;
    localparam [63:0] NR = 64'd10;

    reg [1:0] phase;
    reg arm_seen, start_seen;
    reg [63:0] rnd;
    reg [63:0] st;
    reg [63:0] rk;
    initial begin
        phase = IDLE; arm_seen = 1'b0; start_seen = 1'b0;
        rnd = 64'd0; st = 64'd0; rk = 64'd0;
    end

    function [3:0] sbox4(input [3:0] x);
        case (x)
            4'h0: sbox4 = 4'hC; 4'h1: sbox4 = 4'h5; 4'h2: sbox4 = 4'h6; 4'h3: sbox4 = 4'hB;
            4'h4: sbox4 = 4'h9; 4'h5: sbox4 = 4'h0; 4'h6: sbox4 = 4'hA; 4'h7: sbox4 = 4'hD;
            4'h8: sbox4 = 4'h3; 4'h9: sbox4 = 4'hE; 4'hA: sbox4 = 4'hF; 4'hB: sbox4 = 4'h8;
            4'hC: sbox4 = 4'h4; 4'hD: sbox4 = 4'h7; 4'hE: sbox4 = 4'h1; default: sbox4 = 4'h2;
        endcase
    endfunction

    function [63:0] sub64(input [63:0] x);
        integer i;
        begin
            sub64 = 64'd0;
            for (i = 0; i < 16; i = i + 1)
                sub64[i*4 +: 4] = sbox4(x[i*4 +: 4]);
        end
    endfunction

    function [63:0] shift64(input [63:0] x);
        integer r, c;
        begin
            shift64 = 64'd0;
            for (c = 0; c < 4; c = c + 1)
                for (r = 0; r < 4; r = r + 1)
                    shift64[(4*c+r)*4 +: 4] = x[(4*((c+r)%4)+r)*4 +: 4];
        end
    endfunction

    function [63:0] mix64(input [63:0] x);
        integer c;
        reg [15:0] col;
        begin
            mix64 = 64'd0;
            for (c = 0; c < 4; c = c + 1) begin
                col = x[c*16 +: 16];
                mix64[c*16 +: 16] = col ^ {col[11:0], col[15:12]} ^ {col[7:0], col[15:8]};
            end
        end
    endfunction

    wire last_round = (rnd == NR - 64'd1);
    wire [63:0] after_shift = shift64(sub64(st));
    wire [63:0] round_out = (last_round ? after_shift : mix64(after_shift)) ^ rk;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
            rnd <= 64'd0; st <= 64'd0; rk <= 64'd0;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    phase <= ARMED; arm_seen <= 1'b1; start_seen <= 1'b0;
                    st <= pt ^ key_in; rk <= key_in;
                end
                ARMED: if (start) begin
                    phase <= RUN; start_seen <= 1'b1; rnd <= 64'd0;
                end
                RUN: begin
                    st <= round_out;
                    rk <= {rk[62:0], rk[63]} ^ rnd;
                    rnd <= rnd + 64'd1;
                    if (last_round) phase <= DONE;
                end
                default: if (ack) begin
                    phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
                end
            endcase
        end
    end

    assign done = (phase == DONE);
    assign ct = st;

    always @(posedge clk)
        if (phase == DONE)
            assert (arm_seen && start_seen);
endmodule

module stream_realigner (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire sop,
    input wire eop,
    input wire [2:0] sop_off,
    input wire [63:0] in_data,
    output reg [63:0] out_data,
    output reg [63:0] out_tail,
    output reg out_valid,
    output reg tail_valid
);
    reg [2:0]  off;
    reg [63:0] residue;
    reg        win;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;

    initial begin
        off = 3'd0; residue = 64'd0; win = 1'b0;
        in_cnt = 64'd0; out_cnt = 64'd0;
        out_data = 64'd0; out_tail = 64'd0;
        out_valid = 1'b0; tail_valid = 1'b0;
    end

    wire [5:0]  sh     = {off, 3'b000};
    wire [5:0]  sop_sh = {sop_off, 3'b000};
    wire [6:0]  lsh    = 7'd64 - {1'b0, sh};
    wire [63:0] merged = residue | (in_data << lsh);

    always @(posedge clk) begin
        if (rst) begin
            off <= 3'd0; residue <= 64'd0; win <= 1'b0;
            in_cnt <= 64'd0; out_cnt <= 64'd0;
            out_data <= 64'd0; out_tail <= 64'd0;
            out_valid <= 1'b0; tail_valid <= 1'b0;
        end else if (in_valid) begin
            out_valid  <= 1'b0;
            tail_valid <= 1'b0;
            if (!win) begin
                if (sop) begin
                    off     <= sop_off;
                    residue <= in_data >> sop_sh;
                    win     <= 1'b1;
                    in_cnt  <= in_cnt + 64'd1;
                end
            end else begin
                out_data  <= merged;
                out_valid <= 1'b1;
                in_cnt    <= in_cnt + 64'd1;
                if (eop) begin
                    out_tail   <= in_data >> sh;
                    tail_valid <= 1'b1;
                    out_cnt    <= out_cnt + 64'd2;
                    residue    <= 64'd0;
                    win        <= 1'b0;
                end else begin
                    residue <= in_data >> sh;
                    out_cnt <= out_cnt + 64'd1;
                end
            end
        end
    end

    assert property (!win || (in_cnt != out_cnt));
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

module fp_align_shifter (
    input  wire        clk,
    input  wire        rst,
    input  wire        load,
    input  wire        i_ce,
    input  wire [63:0] a_exp,
    input  wire [63:0] a_sig,
    input  wire [63:0] b_exp,
    input  wire [63:0] b_sig,
    output reg  [63:0] sig,
    output reg  [63:0] exp_out,
    output reg  [63:0] cnt,
    output reg         g,
    output reg         r,
    output reg         s,
    output wire        busy
);
    // shadow: some nonzero bit has been shifted out of the significand
    reg lost  = 1'b0;
    // sticky scope register: set at the first accepted alignment request
    reg armed = 1'b0;

    initial sig     = 64'd0;
    initial exp_out = 64'd0;
    initial cnt     = 64'd0;
    initial g       = 1'b0;
    initial r       = 1'b0;
    initial s       = 1'b0;

    assign busy = (cnt != 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            sig     <= 64'd0;
            exp_out <= 64'd0;
            cnt     <= 64'd0;
            g       <= 1'b0;
            r       <= 1'b0;
            s       <= 1'b0;
            lost    <= 1'b0;
        end else if (load) begin
            armed <= 1'b1;
            if (a_exp >= b_exp) begin
                exp_out <= a_exp;
                sig     <= b_sig;
                cnt     <= a_exp - b_exp;
            end else begin
                exp_out <= b_exp;
                sig     <= a_sig;
                cnt     <= b_exp - a_exp;
            end
            g    <= 1'b0;
            r    <= 1'b0;
            s    <= 1'b0;
            lost <= 1'b0;
        end else if (i_ce && cnt != 64'd0) begin
            sig  <= {1'b0, sig[63:1]};
            g    <= sig[0];
            r    <= g;
            s    <= s | r;
            lost <= lost | sig[0];
            cnt  <= cnt - 64'd1;
        end
    end

    // precedence, after first load: sticky set now => a nonzero bit was shifted out earlier
    always @(*) assert (!armed || !s || lost);
endmodule

module dadda4x4 (
    input  wire [3:0] a,
    input  wire [3:0] b,
    output wire [7:0] p
);
    // partial products pij = a[i] & b[j], weight i+j
    wire p00 = a[0] & b[0];
    wire p01 = a[0] & b[1];
    wire p02 = a[0] & b[2];
    wire p03 = a[0] & b[3];
    wire p10 = a[1] & b[0];
    wire p11 = a[1] & b[1];
    wire p12 = a[1] & b[2];
    wire p13 = a[1] & b[3];
    wire p20 = a[2] & b[0];
    wire p21 = a[2] & b[1];
    wire p22 = a[2] & b[2];
    wire p23 = a[2] & b[3];
    wire p30 = a[3] & b[0];
    wire p31 = a[3] & b[1];
    wire p32 = a[3] & b[2];
    wire p33 = a[3] & b[3];
    // Dadda stage 1: reduce max column height 4 -> 3 (two half adders)
    wire s1 = p03 ^ p12;
    wire c1 = p03 & p12;
    wire s2 = p13 ^ p22;
    wire c2 = p13 & p22;
    // Dadda stage 2: reduce height 3 -> 2 (one half adder, three full adders)
    wire s3 = p02 ^ p11;
    wire c3 = p02 & p11;
    wire s4 = s1 ^ p21 ^ p30;
    wire c4 = (s1 & p21) | (s1 & p30) | (p21 & p30);
    wire s5 = s2 ^ p31 ^ c1;
    wire c5 = (s2 & p31) | (s2 & c1) | (p31 & c1);
    wire s6 = p23 ^ p32 ^ c2;
    wire c6 = (p23 & p32) | (p23 & c2) | (p32 & c2);
    // final carry-propagate adder over columns 1..6
    wire [5:0] row_x = {p33, s6, s5, s4, s3, p01};
    wire [5:0] row_y = {c6, c5, c4, c3, p20, p10};
    wire [6:0] cpa = {1'b0, row_x} + {1'b0, row_y};
    assign p = {cpa, p00};
endmodule

module dadda_simd_mul (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire         i_flush,
    input  wire [127:0] i_data,
    output wire [127:0] o_prod
);
    reg [127:0] op_r;
    reg [127:0] prod_r;
    reg         v1;
    reg [1:0]   op_gen;
    reg [1:0]   p_gen;
    reg         armed;
    reg         pv;
    initial op_r   = 128'h0;
    initial prod_r = 128'h0;
    initial v1     = 1'b0;
    initial op_gen = 2'd0;
    initial p_gen  = 2'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    // 16 lanes, each lane packs {a[3:0], b[3:0]} in 8 bits of the operand word
    wire [127:0] tree_p;
    genvar k;
    generate
        for (k = 0; k < 16; k = k + 1) begin : lane
            dadda4x4 u_mul (
                .a(op_r[8*k+7:8*k+4]),
                .b(op_r[8*k+3:8*k]),
                .p(tree_p[8*k+7:8*k])
            );
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            if (v1) begin
                prod_r <= tree_p;
                p_gen  <= op_gen;
            end
            if (i_load) begin
                op_r   <= i_data;
                op_gen <= op_gen + 2'd1;
                v1     <= 1'b1;
            end else if (v1) begin
                v1 <= 1'b0;
            end
            if (i_flush)
                armed <= 1'b0;
            else if (i_load)
                armed <= 1'b1;
        end
    end

    assign o_prod = prod_r;

    always @(posedge clk) pv <= 1'b1;

    // after first load until flush: never (product tag unchanged AND product changed)
    always @(posedge clk)
        if (pv && armed && $stable(p_gen))
            assert ($stable(prod_r));
endmodule

module tap_delay_chain (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire [31:0] cfg_tap,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    // 12-stage x 32-bit data chain plus a parallel marker chain
    reg [383:0] chain;
    reg [11:0]  mark;
    reg [31:0]  tap;
    reg [1:0]   phase;
    reg         started;
    reg         q_seen;

    initial chain   = 384'd0;
    initial mark    = 12'h000;
    initial tap     = 32'd0;
    initial phase   = IDLE;
    initial started = 1'b0;
    initial q_seen  = 1'b0;

    wire tap_ok   = (tap < 32'd12);
    wire tap_mark = tap_ok ? mark[tap[3:0]] : 1'b0;
    assign dout   = tap_ok ? chain[{tap[3:0], 5'b00000} +: 32] : 32'd0;
    assign done   = (phase == DONE);

    wire go_arm    = ce && (phase == IDLE) && arm;
    wire go_finish = ce && ((phase == ARMED) || (phase == RUN)) && tap_mark;
    wire go_start  = ce && (phase == ARMED) && start && !tap_mark;

    always @(posedge clk) begin
        if (ce) begin
            chain <= {chain[351:0], din};
            mark  <= {mark[10:0], go_start};
        end
        if (go_arm) begin
            phase  <= ARMED;
            q_seen <= 1'b1;
            tap    <= (cfg_tap < 32'd12) ? cfg_tap : 32'd11;
        end else if (go_finish) begin
            phase <= DONE;
        end else if (go_start) begin
            phase   <= RUN;
            started <= 1'b1;
        end
    end

    // after the first arm: finish is never observed unless start happened
    always @(posedge clk)
        if (q_seen) assert (phase != DONE || started);
endmodule

module mesi_pair (
    input wire clk,
    input wire rst,
    input wire step,
    input wire who,
    input wire wr,
    output reg [1:0] st_a,
    output reg [1:0] st_b,
    output reg bus_req,
    output reg [31:0] bus_cnt,
    output reg [31:0] wb_cnt
);
    localparam [1:0] ST_I = 2'b00;
    localparam [1:0] ST_S = 2'b01;
    localparam [1:0] ST_E = 2'b10;
    localparam [1:0] ST_M = 2'b11;

    initial st_a = ST_I;
    initial st_b = ST_I;
    initial bus_req = 1'b0;
    initial bus_cnt = 32'd0;
    initial wb_cnt = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            st_a <= ST_I;
            st_b <= ST_I;
            bus_req <= 1'b0;
            bus_cnt <= 32'd0;
            wb_cnt <= 32'd0;
        end else if (step) begin
            bus_req <= 1'b0;
            if (!who) begin
                if (wr) begin
                    if (st_a == ST_E) begin
                        st_a <= ST_M;
                    end else if (st_a != ST_M) begin
                        st_a <= ST_M;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_a == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_b == ST_I) begin
                        st_a <= ST_E;
                    end else begin
                        st_a <= ST_S;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_S;
                    end
                end
            end else begin
                if (wr) begin
                    if (st_b == ST_E) begin
                        st_b <= ST_M;
                    end else if (st_b != ST_M) begin
                        st_b <= ST_M;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_b == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_a == ST_I) begin
                        st_b <= ST_E;
                    end else begin
                        st_b <= ST_S;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_S;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!(st_a == ST_M && st_b == ST_M));
endmodule

module therm_dac_seg (
    input wire clk,
    input wire i_ce,
    input wire i_mute,
    input wire i_load,
    input wire [3:0] i_val,
    input wire i_up,
    input wire i_down,
    output wire [15:0] o_seg
);
    reg [3:0]  val;
    reg [15:0] therm;
    reg        pre_mute;
    initial val = 4'd0;
    initial therm = 16'h0001;
    initial pre_mute = 1'b1;

    // binary-to-thermometer decoder: lines 0..i_val asserted
    wire [15:0] dec_in = (16'd2 << i_val) - 16'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!pre_mute) begin
                // muted: segments frozen off
            end else if (i_mute) begin
                pre_mute <= 1'b0;
                val      <= 4'd0;
                therm    <= 16'd0;
            end else if (i_load) begin
                val   <= i_val;
                therm <= dec_in;
            end else if (i_up && !i_down) begin
                if (val != 4'd15) begin
                    val   <= val + 4'd1;
                    therm <= {therm[14:0], 1'b1};
                end
            end else if (i_down && !i_up) begin
                if (val != 4'd0) begin
                    val   <= val - 4'd1;
                    therm <= {1'b0, therm[15:1]};
                end
            end
        end
    end

    // registered thermometer output driving unary DAC segments
    assign o_seg = therm;

    // before mute: output is always a valid, non-empty thermometer code
    always @(*)
        assert (!pre_mute || (therm[0] && ((therm & (therm + 16'd1)) == 16'd0)));
endmodule

module traffic_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       preempt,
    output wire       ns_green,
    output wire       ew_green,
    output wire [2:0] phase_o
);
    // phases: 0 NS_GREEN, 1 NS_YELLOW, 2 ALL_RED_A, 3 EW_GREEN, 4 EW_YELLOW, 5 ALL_RED_B
    reg [2:0]  phase     = 3'd0;
    reg [15:0] timer     = 16'd39;
    reg [15:0] green_cnt = 16'd0;
    reg        armed     = 1'b1;
    reg        pv        = 1'b0;

    assign ns_green = (phase == 3'd0);
    assign ew_green = (phase == 3'd3);
    assign phase_o  = phase;

    function [15:0] dur;
        input [2:0] p;
        begin
            case (p)
                3'd0:    dur = 16'd39;
                3'd1:    dur = 16'd4;
                3'd2:    dur = 16'd1;
                3'd3:    dur = 16'd29;
                3'd4:    dur = 16'd4;
                default: dur = 16'd1;
            endcase
        end
    endfunction

    wire [2:0] nxt = (phase >= 3'd5) ? 3'd0 : phase + 3'd1;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            phase     <= 3'd0;
            timer     <= 16'd39;
            green_cnt <= 16'd0;
            armed     <= 1'b1;
        end else if (step) begin
            if (phase == 3'd0)
                green_cnt <= green_cnt + 16'd1;
            if (phase == 3'd0 && preempt) begin
                timer <= 16'd200;
                armed <= 1'b0;
            end else if (timer == 16'd0) begin
                phase <= nxt;
                timer <= dur(nxt);
                if (nxt == 3'd0)
                    green_cnt <= 16'd0;
            end else begin
                timer <= timer - 16'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(ns_green))
            assert (green_cnt <= 16'd40);
endmodule

module vtg_frame_sync #(
    parameter [31:0] H_ACTIVE = 32'd4,
    parameter [31:0] H_FP     = 32'd1,
    parameter [31:0] H_SYNC   = 32'd2,
    parameter [31:0] H_BP     = 32'd1,
    parameter [31:0] V_ACTIVE = 32'd2,
    parameter [31:0] V_FP     = 32'd1,
    parameter [31:0] V_SYNC   = 32'd2,
    parameter [31:0] V_BP     = 32'd1
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    output wire        hsync,
    output wire        vsync,
    output wire        hblank,
    output wire        vblank,
    output wire        active,
    output wire [31:0] o_x,
    output wire [31:0] o_y,
    output wire        o_win
);
    localparam [31:0] H_TOTAL    = H_ACTIVE + H_FP + H_SYNC + H_BP;
    localparam [31:0] HS_START   = H_ACTIVE + H_FP;
    localparam [31:0] HS_END     = H_ACTIVE + H_FP + H_SYNC;
    localparam [31:0] V_TOTAL    = V_ACTIVE + V_FP + V_SYNC + V_BP;
    localparam [31:0] VS_START   = V_ACTIVE + V_FP;
    localparam [31:0] VS_END     = V_ACTIVE + V_FP + V_SYNC;

    reg [31:0] h_cnt;
    reg [31:0] v_cnt;
    reg [31:0] lines_done;
    reg        win;
    reg        pv;
    initial begin
        h_cnt = 32'd0;
        v_cnt = 32'd0;
        lines_done = 32'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    wire line_end = (h_cnt == H_TOTAL - 32'd1);
    wire last_line = (v_cnt == V_TOTAL - 32'd1);
    wire vs_close = line_end && (v_cnt == VS_END - 32'd1);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (line_end) begin
                h_cnt <= 32'd0;
                if (last_line) begin
                    v_cnt <= 32'd0;
                    lines_done <= 32'd0;
                end else begin
                    v_cnt <= v_cnt + 32'd1;
                    lines_done <= lines_done + 32'd1;
                end
            end else begin
                h_cnt <= h_cnt + 32'd1;
            end
            if (vs_close)
                win <= 1'b0;
            else if (arm)
                win <= 1'b1;
        end
    end

    assign hsync  = (h_cnt >= HS_START) && (h_cnt < HS_END);
    assign vsync  = (v_cnt >= VS_START) && (v_cnt < VS_END);
    assign hblank = (h_cnt >= H_ACTIVE);
    assign vblank = (v_cnt >= V_ACTIVE);
    assign active = !hblank && !vblank;
    assign o_x = h_cnt;
    assign o_y = v_cnt;
    assign o_win = win;

    always @(posedge clk)
        if (pv && win && $rose(vsync))
            assert (lines_done == VS_START);
endmodule

module xs3_cell_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         arm,
    input  wire         go,
    input  wire         clr,
    input  wire [127:0] a_in,
    input  wire [127:0] b_in,
    output reg  [127:0] result,
    output reg          carry_out
);
    reg [127:0] opa;
    reg [127:0] opb;
    reg [1:0]   phase;
    reg         armed_seen;
    reg         start_seen;
    reg         done;

    initial begin
        opa = 128'd0; opb = 128'd0; result = 128'd0; carry_out = 1'b0;
        phase = 2'd0; armed_seen = 1'b0; start_seen = 1'b0; done = 1'b0;
    end

    // Combinational excess-3 adder: 32 digits, binary add then +3/-3 correction
    wire [32:0]  c;
    wire [127:0] xs3_sum;
    assign c[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : g_dig
            wire [4:0] raw = {1'b0, opa[4*i +: 4]} + {1'b0, opb[4*i +: 4]} + {4'd0, c[i]};
            assign c[i+1] = raw[4];
            assign xs3_sum[4*i +: 4] = raw[4] ? (raw[3:0] + 4'd3) : (raw[3:0] - 4'd3);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            phase <= 2'd0; armed_seen <= 1'b0; start_seen <= 1'b0; done <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (arm) begin
                    opa <= a_in;
                    armed_seen <= 1'b1;
                    phase <= 2'd1;
                end
                2'd1: if (go) begin
                    opb <= b_in;
                    start_seen <= 1'b1;
                    phase <= 2'd2;
                end
                2'd2: begin
                    result <= xs3_sum;
                    carry_out <= c[32];
                    done <= 1'b1;
                    phase <= 2'd3;
                end
                default: if (clr) begin
                    armed_seen <= 1'b0;
                    start_seen <= 1'b0;
                    done <= 1'b0;
                    phase <= 2'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (done)
            assert (start_seen && armed_seen);
endmodule

module irq_prio_budget (
    input wire clk,
    input wire rst,
    input wire step,
    input wire [3:0] req,
    input wire [7:0] d0,
    input wire [7:0] d1,
    input wire [7:0] d2,
    input wire [7:0] d3,
    input wire dbg_wr,
    input wire [7:0] dbg_val,
    output reg [7:0] sel_data,
    output reg [1:0] sel_idx,
    output reg sel_vld,
    output reg [7:0] cnt
);
    reg armed;
    initial sel_data = 8'd0;
    initial sel_idx = 2'd0;
    initial sel_vld = 1'b0;
    initial cnt = 8'd0;
    initial armed = 1'b1;

    wire [7:0] c0 = (d0 > 8'd8)  ? 8'd8  : d0;
    wire [7:0] c1 = (d1 > 8'd12) ? 8'd12 : d1;
    wire [7:0] c2 = (d2 > 8'd16) ? 8'd16 : d2;
    wire [7:0] c3 = (d3 > 8'd20) ? 8'd20 : d3;

    reg [7:0] nxt_data;
    reg [1:0] nxt_idx;
    reg nxt_vld;
    always @(*) begin
        if (req[0]) begin
            nxt_data = c0; nxt_idx = 2'd0; nxt_vld = 1'b1;
        end else if (req[1]) begin
            nxt_data = c1; nxt_idx = 2'd1; nxt_vld = 1'b1;
        end else if (req[2]) begin
            nxt_data = c2; nxt_idx = 2'd2; nxt_vld = 1'b1;
        end else if (req[3]) begin
            nxt_data = c3; nxt_idx = 2'd3; nxt_vld = 1'b1;
        end else begin
            nxt_data = 8'd0; nxt_idx = 2'd0; nxt_vld = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 8'd0;
            sel_data <= 8'd0;
            sel_idx <= 2'd0;
            sel_vld <= 1'b0;
        end else if (dbg_wr) begin
            cnt <= dbg_val;
            armed <= 1'b0;
        end else if (step) begin
            if (cnt == sel_data) begin
                cnt <= 8'd0;
                sel_data <= nxt_data;
                sel_idx <= nxt_idx;
                sel_vld <= nxt_vld;
            end else begin
                cnt <= cnt + 8'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;
    always @(posedge clk)
        if (pv && $past(armed)) assert ($past(cnt) <= 8'd20);
endmodule

module frame_scrambler32 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire [31:0] i_data,
    output wire [31:0] o_scr,
    output wire [31:0] o_desc
);
    localparam [31:0] SEED = 32'h1D2C3B4A;
    localparam [31:0] POLY = 32'hEDB88320;
    localparam [31:0] LAST = 32'd11;

    reg [31:0] lfsr_tx, lfsr_rx;
    reg [31:0] tx_cnt, rx_cnt;
    reg        armed;
    initial begin
        lfsr_tx = SEED; lfsr_rx = SEED;
        tx_cnt = 32'd0; rx_cnt = 32'd0;
        armed = 1'b0;
    end

    function [31:0] lfsr_step;
        input [31:0] s;
        begin
            lfsr_step = s[0] ? ((s >> 1) ^ POLY) : (s >> 1);
        end
    endfunction

    // scrambler (tx) and descrambler (rx) run in lockstep, reseeding every 12 words
    always @(posedge clk) begin
        if (rst) begin
            lfsr_tx <= SEED; lfsr_rx <= SEED;
            tx_cnt <= 32'd0; rx_cnt <= 32'd0;
        end else if (i_ce) begin
            if (tx_cnt == LAST) begin
                tx_cnt  <= 32'd0;
                lfsr_tx <= SEED;
            end else begin
                tx_cnt  <= tx_cnt + 32'd1;
                lfsr_tx <= lfsr_step(lfsr_tx);
            end
            if (rx_cnt == LAST) begin
                rx_cnt  <= 32'd0;
                lfsr_rx <= SEED;
            end else begin
                rx_cnt  <= rx_cnt + 32'd1;
                lfsr_rx <= lfsr_step(lfsr_rx);
            end
        end
    end

    // sticky scope register: set at the first scrambled word, never cleared
    always @(posedge clk)
        if (i_ce) armed <= 1'b1;

    assign o_scr  = i_data ^ lfsr_tx;
    assign o_desc = o_scr ^ lfsr_rx;

    wire tx_sof = (tx_cnt == 32'd0);
    wire tx_eof = (tx_cnt == LAST);
    wire rx_sof = (rx_cnt == 32'd0);
    wire rx_eof = (rx_cnt == LAST);

    always @(posedge clk) begin
        if (armed) begin
            assert (!(tx_sof && rx_eof));
            assert (!(tx_eof && rx_sof));
        end
    end
endmodule

module wstrobe_demux_bank (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_we,
    input  wire [4:0]  i_addr,
    input  wire [63:0] i_data,
    input  wire        i_ce,
    output wire [31:0] o_strobe,
    output wire        o_busy,
    output wire [63:0] o_num_valid
);
    reg        pending;
    reg [4:0]  addr_q;
    reg [63:0] data_q;
    reg [31:0] valid;
    reg [63:0] num_valid;
    reg        armed;
    reg [63:0] bank [0:31];
    integer i;
    initial begin
        pending = 1'b0;
        addr_q = 5'd0;
        data_q = 64'd0;
        valid = 32'd0;
        num_valid = 64'd0;
        armed = 1'b0;
        for (i = 0; i < 32; i = i + 1) bank[i] = 64'd0;
    end

    wire fire = pending && i_ce;
    wire [31:0] strobe = fire ? (32'd1 << addr_q) : 32'd0;
    wire newly_valid = |(strobe & ~valid);

    reg [63:0] valid_pop;
    integer k;
    always @(*) begin
        valid_pop = 64'd0;
        for (k = 0; k < 32; k = k + 1)
            valid_pop = valid_pop + {63'd0, valid[k]};
    end

    always @(posedge clk) begin
        if (rst) begin
            pending <= 1'b0;
            valid <= 32'd0;
            num_valid <= 64'd0;
        end else begin
            if (fire) begin
                pending <= 1'b0;
                valid <= valid | strobe;
                if (newly_valid)
                    num_valid <= num_valid + 64'd1;
                armed <= 1'b1;
            end else if (i_we && !pending) begin
                pending <= 1'b1;
                addr_q <= i_addr;
                data_q <= i_data;
            end
        end
    end

    always @(posedge clk) begin
        for (i = 0; i < 32; i = i + 1)
            if (!rst && strobe[i]) bank[i] <= data_q;
    end

    assign o_strobe = strobe;
    assign o_busy = pending;
    assign o_num_valid = num_valid;

    assert property (!armed || (num_valid <= 64'd32));
endmodule

module ctr_drbg_engine (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] cmd,
    input wire [31:0] entropy,
    output reg busy,
    output reg [31:0] out_data,
    output reg [31:0] reseed_ctr
);
    // cmd: 2'b01 instantiate, 2'b10 reseed, 2'b11 generate
    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
endmodule

module sevenseg_scan_mux (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_wr,
    input  wire [4:0]  i_waddr,
    input  wire [31:0] i_wdata,
    output reg  [6:0]  o_seg,
    output wire [31:0] o_anode
);
    // digit-index counter and one-hot digit drive (anode) register
    reg [31:0] dig_idx = 32'd0;
    reg [31:0] anode   = 32'h00000001;
    // shadow: digit 16 has been driven during this (first) frame
    reg        visited_hi = 1'b0;
    // scope register: high until the scan first wraps from digit 31 to 0
    reg        armed = 1'b1;
    // per-digit value registers
    reg [31:0] digit_val [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            digit_val[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (i_reset) begin
            dig_idx    <= 32'd0;
            anode      <= 32'h00000001;
            visited_hi <= 1'b0;
            armed      <= 1'b1;
        end else if (i_ce) begin
            if (dig_idx == 32'd31) begin
                dig_idx <= 32'd0;
                armed   <= 1'b0;
            end else begin
                dig_idx <= dig_idx + 32'd1;
            end
            anode <= {anode[30:0], anode[31]};
            if (anode[16])
                visited_hi <= 1'b1;
        end
    end

    always @(posedge clk)
        if (i_wr)
            digit_val[i_waddr] <= i_wdata;

    wire [31:0] cur_val = digit_val[dig_idx[4:0]];
    wire [3:0]  nib     = cur_val[3:0];

    always @(*) begin
        case (nib)
            4'h0: o_seg = 7'b1000000;
            4'h1: o_seg = 7'b1111001;
            4'h2: o_seg = 7'b0100100;
            4'h3: o_seg = 7'b0110000;
            4'h4: o_seg = 7'b0011001;
            4'h5: o_seg = 7'b0010010;
            4'h6: o_seg = 7'b0000010;
            4'h7: o_seg = 7'b1111000;
            4'h8: o_seg = 7'b0000000;
            4'h9: o_seg = 7'b0010000;
            4'hA: o_seg = 7'b0001000;
            4'hB: o_seg = 7'b0000011;
            4'hC: o_seg = 7'b1000110;
            4'hD: o_seg = 7'b0100001;
            4'hE: o_seg = 7'b0000110;
            default: o_seg = 7'b0001110;
        endcase
    end

    assign o_anode = ~anode;

    // Precedence, before first wrap: driving the last digit requires digit 16 to have been driven earlier
    always @(*)
        assert (!(armed && anode[31]) || visited_hi);
endmodule

module palette_lut (
    input wire clk,
    input wire rst,
    input wire wr_en,
    input wire [1:0] wr_idx,
    input wire [31:0] wr_data,
    input wire pix_valid,
    input wire [1:0] pix_idx,
    input wire lock_cmd,
    input wire unlock_cmd,
    output reg [31:0] color_q,
    output reg [1:0] idx_q,
    output reg locked,
    output reg [31:0] lookups
);
    reg [31:0] pal0, pal1, pal2, pal3;
    initial begin
        pal0 = 32'd0; pal1 = 32'd0; pal2 = 32'd0; pal3 = 32'd0;
        color_q = 32'd0; idx_q = 2'd0; locked = 1'b0; lookups = 32'd0;
    end

    wire do_wr = wr_en && !locked;
    wire [31:0] pal_rd = (pix_idx == 2'd0) ? pal0 : (pix_idx == 2'd1) ? pal1 : (pix_idx == 2'd2) ? pal2 : pal3;
    wire [31:0] new_rd = (do_wr && (wr_idx == pix_idx)) ? wr_data : pal_rd;
    wire [31:0] cur_entry = (idx_q == 2'd0) ? pal0 : (idx_q == 2'd1) ? pal1 : (idx_q == 2'd2) ? pal2 : pal3;

    always @(posedge clk) begin
        if (rst) begin
            pal0 <= 32'd0; pal1 <= 32'd0; pal2 <= 32'd0; pal3 <= 32'd0;
            color_q <= 32'd0; idx_q <= 2'd0; locked <= 1'b0; lookups <= 32'd0;
        end else begin
            if (do_wr) begin
                case (wr_idx)
                    2'd0: pal0 <= wr_data;
                    2'd1: pal1 <= wr_data;
                    2'd2: pal2 <= wr_data;
                    default: pal3 <= wr_data;
                endcase
            end
            if (pix_valid) begin
                idx_q <= pix_idx;
                color_q <= new_rd;
                lookups <= lookups + 32'd1;
            end else if (do_wr && (wr_idx == idx_q)) begin
                color_q <= wr_data;
            end
            if (lock_cmd) locked <= 1'b1;
            else if (unlock_cmd) locked <= 1'b0;
        end
    end

    always @(posedge clk)
        if (locked)
            assert (color_q == cur_entry);
endmodule

module bypass_xact_reg (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        finish,
    input  wire        open_w,
    input  wire        close_w,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        bypass_en
);
    // phase: 0 idle, 1 armed (word captured), 2 started (bypass engaged), 3 finished
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        win;
    reg [31:0] stored;
    reg [31:0] xact_cnt;
    reg        pv;

    initial begin
        phase = 2'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        win = 1'b0;
        stored = 32'd0;
        xact_cnt = 32'd0;
        pv = 1'b0;
    end

    // bypass multiplexer: steer input straight through while started,
    // the stored copy is left untouched
    assign bypass_en = (phase == 2'd2);
    assign dout = bypass_en ? din : stored;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (open_w)       win <= 1'b1;
            else if (close_w) win <= 1'b0;

            case (phase)
                2'd0: if (arm) begin
                    phase    <= 2'd1;
                    arm_seen <= 1'b1;
                    stored   <= din;
                end
                2'd1: if (start) begin
                    phase      <= 2'd2;
                    start_seen <= 1'b1;
                end
                2'd2: if (finish) begin
                    phase    <= 2'd3;
                    xact_cnt <= xact_cnt + 32'd1;
                end
                default: begin
                    phase      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence inside the window: a finish is only observed if
    // arm and start had both happened in the previous cycle's record
    always @(posedge clk)
        if (pv && win && phase == 2'd3)
            assert ($past(start_seen) && $past(arm_seen));
endmodule

module pipe_ao22_track (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        in_valid,
    input  wire [31:0] din,
    input  wire        open_win,
    input  wire        close_win,
    output wire [31:0] dout,
    output wire        dout_valid
);
    reg        v1;
    reg [31:0] s1;
    reg        v2;
    reg [31:0] s2;
    reg        seen_in;
    reg [31:0] in_cnt;
    reg        armed;

    initial v1 = 1'b0;
    initial s1 = 32'd0;
    initial v2 = 1'b0;
    initial s2 = 32'd0;
    initial seen_in = 1'b0;
    initial in_cnt = 32'd0;
    initial armed = 1'b0;

    wire [31:0] s1_next;
    wire [31:0] s2_next;

    ao22 #(.W(32)) u_s1 (
        .a({32{in_valid}}), .b(din),
        .c({32{~in_valid}}), .d(s1),
        .y(s1_next)
    );

    ao22 #(.W(32)) u_s2 (
        .a({32{v1}}), .b(s1),
        .c({32{~v1}}), .d(s2),
        .y(s2_next)
    );

    assign dout = s2;
    assign dout_valid = v2;

    always @(posedge clk) begin
        if (rst) begin
            v1 <= 1'b0;
            s1 <= 32'd0;
            v2 <= 1'b0;
            s2 <= 32'd0;
            seen_in <= 1'b0;
            in_cnt <= 32'd0;
            armed <= 1'b0;
        end else if (step) begin
            v1 <= in_valid;
            s1 <= s1_next;
            v2 <= v1;
            s2 <= s2_next;
            seen_in <= seen_in | in_valid;
            if (in_valid && (in_cnt != 32'hFFFFFFFF))
                in_cnt <= in_cnt + 32'd1;
            if (open_win)
                armed <= 1'b1;
            else if (close_win)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed && v2) assert (seen_in);

    always @(posedge clk)
        if (armed && v2) assert (in_cnt != 32'd0);
endmodule

module ao22 #(parameter W = 32) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire [W-1:0] c,
    input  wire [W-1:0] d,
    output wire [W-1:0] y
);
    assign y = (a & b) | (c & d);
endmodule

module age_matrix_iq (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_alloc,
    input  wire        i_alloc_ready,
    input  wire [31:0] i_alloc_tag,
    input  wire        i_issue,
    input  wire [3:0]  i_wake,
    output reg  [31:0] o_issue_tag,
    output wire        o_issue_valid,
    output wire [31:0] o_issue_cnt
);
    // age[i*4+j] == 1 means entry i is older than entry j
    reg [3:0]   valid = 4'b0000;
    reg [3:0]   ready = 4'b0000;
    reg [15:0]  age = 16'h0000;
    reg [127:0] tags = 128'd0;
    reg [31:0]  issue_cnt = 32'd0;
    reg         armed = 1'b0;
    reg         pv = 1'b0;

    reg [3:0] grant;
    reg [3:0] free_sel;
    integer i, j, k;

    wire [3:0] rv = valid & ready;
    wire issue_fire = i_ce & i_issue & (|rv);
    wire alloc_fire = i_ce & i_alloc & ~(&valid);

    // oldest-ready select: an entry wins if no other ready entry is older
    always @(*) begin
        for (i = 0; i < 4; i = i + 1) begin
            grant[i] = rv[i];
            for (j = 0; j < 4; j = j + 1)
                if (j != i && rv[j] && age[j*4+i]) grant[i] = 1'b0;
        end
        if (!valid[0])      free_sel = 4'b0001;
        else if (!valid[1]) free_sel = 4'b0010;
        else if (!valid[2]) free_sel = 4'b0100;
        else if (!valid[3]) free_sel = 4'b1000;
        else                free_sel = 4'b0000;
        o_issue_tag = 32'd0;
        for (k = 0; k < 4; k = k + 1)
            if (grant[k]) o_issue_tag = o_issue_tag | tags[k*32 +: 32];
    end

    assign o_issue_valid = issue_fire;
    assign o_issue_cnt = issue_cnt;

    always @(posedge clk) begin
        if (issue_fire) begin
            issue_cnt <= issue_cnt + 32'd1;
            armed <= 1'b1;
        end
        for (i = 0; i < 4; i = i + 1) begin
            if (alloc_fire && free_sel[i]) begin
                valid[i] <= 1'b1;
                ready[i] <= i_alloc_ready;
                tags[i*32 +: 32] <= i_alloc_tag;
                for (j = 0; j < 4; j = j + 1)
                    if (j != i) begin
                        age[i*4+j] <= 1'b0;
                        age[j*4+i] <= valid[j];
                    end
            end else begin
                if (issue_fire && grant[i]) valid[i] <= 1'b0;
                if (i_ce && valid[i] && i_wake[i]) ready[i] <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // after the first issue: if the valid set did not change, no issue was counted
    always @(posedge clk)
        if (pv && armed && $stable(valid))
            assert ($stable(issue_cnt));
endmodule

module sd_dac_lockstep (
    input wire clk,
    input wire ce,
    input wire mute,
    input wire [15:0] din,
    output reg dout,
    output reg dchk
);
    // main first-order sigma-delta error accumulator
    reg [15:0] acc = 16'h0000;
    // lockstep reference accumulator (does not see mute)
    reg [15:0] acc_chk = 16'h0000;
    // scope register: high until the first mute event
    reg before_mute = 1'b1;
    reg pv = 1'b0;

    initial dout = 1'b0;
    initial dchk = 1'b0;

    wire [16:0] sum     = {1'b0, acc}     + {1'b0, din};
    wire [16:0] sum_chk = {1'b0, acc_chk} + {1'b0, din};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (mute) begin
            acc  <= 16'h0000;
            dout <= 1'b0;
        end else if (ce) begin
            acc  <= sum[15:0];
            dout <= sum[16];
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            acc_chk <= sum_chk[15:0];
            dchk    <= sum_chk[16];
        end
    end

    always @(posedge clk) begin
        if (mute)
            before_mute <= 1'b0;
    end

    // Absence, before first mute: never (reference bit held) and (main bit toggled)
    always @(posedge clk)
        if (pv && before_mute)
            assert (!($stable(dchk) && !$stable(dout)));
endmodule
